INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_54', '54', 'Python', 'OOP', 'Easy', 'mcq', 'What is the first parameter of an instance method in Python?', 'self', 'this', 'cls', 'instance', 'A', 0, 'By convention, the first parameter of instance methods is ''self'', referring to the instance itself.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_55', '55', 'Python', 'OOP', 'Medium', 'mcq', 'What is the purpose of __init__ in a Python class?', 'It initializes a new instance of the class', 'It destroys an instance', 'It creates a class variable', 'It defines the class name', 'A', 0, '__init__ is the constructor method called automatically when creating a new instance, used to initialize attributes.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_56', '56', 'Python', 'OOP', 'Medium', 'mcq', 'What is encapsulation in OOP?', 'Bundling data and methods together and restricting direct access', 'Inheriting from multiple classes', 'Creating abstract classes', 'Using global variables', 'A', 0, 'Encapsulation bundles data (attributes) and methods within a class, using access control to protect internal state.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_57', '57', 'Python', 'OOP', 'Hard', 'mcq', 'What is the difference between __str__ and __repr__ in Python?', '__str__ is for end-user display; __repr__ is for developers and debugging', 'They are identical', '__repr__ is for display; __str__ is for debugging', '__str__ cannot be overridden', 'A', 0, '__str__ returns a human-readable string, while __repr__ returns an unambiguous developer-oriented representation.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_58', '58', 'Python', 'OOP', 'Hard', 'mcq', 'What are Python descriptors?', 'Objects that define __get__, __set__, or __delete__ to customize attribute access', 'Functions that describe a class', 'Docstrings attached to methods', 'Type annotations', 'A', 0, 'Descriptors implement the descriptor protocol (__get__, __set__, __delete__) to customize attribute access on classes.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_59', '59', 'Python', 'OOP', 'Medium', 'mcq', 'What does the @classmethod decorator do?', 'Binds the method to the class, receiving cls as first argument', 'Makes the method private', 'Makes the method static', 'Prevents method overriding', 'A', 0, '@classmethod binds the method to the class rather than the instance. It receives the class (cls) as its first argument.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_60', '60', 'Python', 'OOP', 'Medium', 'mcq', 'What does the @staticmethod decorator do?', 'Defines a method that does not receive self or cls', 'Makes the method unchangeable', 'Binds the method to the class', 'Creates a class variable', 'A', 0, '@staticmethod defines a method that belongs to the class namespace but does not receive self or cls automatically.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_61', '61', 'Python', 'Inheritance', 'Easy', 'mcq', 'How does a class Dog inherit from a class Animal in Python?', 'class Dog(Animal):', 'class Dog extends Animal:', 'class Dog inherits Animal:', 'class Dog <- Animal:', 'A', 0, 'In Python, inheritance is specified by putting the parent class in parentheses after the class name.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_62', '62', 'Python', 'Inheritance', 'Medium', 'mcq', 'What is the MRO in Python?', 'Method Resolution Order - the order in which base classes are searched', 'Multiple Return Objects', 'Module Reference Order', 'Method Repeat Override', 'A', 0, 'MRO determines the order in which methods are looked up in the class hierarchy, using the C3 linearization algorithm.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_63', '63', 'Python', 'Inheritance', 'Medium', 'mcq', 'What does super() do in Python?', 'Returns a proxy object that delegates method calls to a parent class', 'Creates a superclass', 'Overrides all parent methods', 'Prevents inheritance', 'A', 0, 'super() returns a proxy object that delegates method calls to the parent class, following the MRO.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_64', '64', 'Python', 'Inheritance', 'Hard', 'mcq', 'What is the diamond problem in multiple inheritance?', 'Ambiguity when a class inherits from two classes that share a common base', 'A class inheriting from itself', 'Circular imports', 'A class with four parents', 'A', 0, 'The diamond problem occurs when two parent classes share a common ancestor, creating ambiguity. Python solves this with C3 linearization.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_65', '65', 'Python', 'Inheritance', 'Easy', 'mcq', 'Can a Python class inherit from multiple parent classes?', 'Yes, Python supports multiple inheritance', 'No, only single inheritance is allowed', 'Only with a special keyword', 'Only abstract classes can', 'A', 0, 'Python supports multiple inheritance. A class can list multiple parent classes separated by commas.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_66', '66', 'Python', 'Inheritance', 'Hard', 'mcq', 'What is an Abstract Base Class (ABC) in Python?', 'A class that cannot be instantiated and may have abstract methods', 'A class with no methods', 'A compiled C class', 'A class that only has static methods', 'A', 0, 'ABCs from the abc module define interfaces. They cannot be instantiated directly and force subclasses to implement abstract methods.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_67', '67', 'Python', 'Decorators', 'Medium', 'mcq', 'What is a decorator in Python?', 'A function that modifies the behavior of another function', 'A comment style', 'A type annotation', 'A class attribute', 'A', 0, 'Decorators are functions that take a function as input and return a modified version, applied with @decorator syntax.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_68', '68', 'Python', 'Decorators', 'Medium', 'mcq', 'What does @property do in Python?', 'Defines a method that can be accessed like an attribute', 'Makes an attribute private', 'Creates a class property file', 'Locks an attribute value', 'A', 0, '@property turns a method into a getter, allowing attribute-like access while running code behind the scenes.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_69', '69', 'Python', 'Decorators', 'Hard', 'mcq', 'What does functools.wraps do when writing a decorator?', 'Preserves the original function''s metadata (name, docstring, etc.)', 'Wraps the function in a try-except', 'Makes the decorator reusable', 'Converts the function to a generator', 'A', 0, 'functools.wraps copies the wrapped function''s __name__, __doc__, and other attributes to the wrapper function.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_70', '70', 'Python', 'Decorators', 'Hard', 'mcq', 'How can a decorator accept arguments?', 'By using a decorator factory: a function that returns the actual decorator', 'Decorators cannot accept arguments', 'By using global variables', 'By modifying sys.argv', 'A', 0, 'A decorator factory is a function that takes arguments and returns a decorator. Example: @repeat(3) uses repeat as a factory.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_71', '71', 'Python', 'Decorators', 'Medium', 'mcq', 'Which of the following is equivalent to @decorator on a function f?', 'f = decorator(f)', 'f = f(decorator)', 'decorator = f', 'f.decorator()', 'A', 0, '@decorator above a function definition is syntactic sugar for f = decorator(f) after the function is defined.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_72', '72', 'Python', 'Generators', 'Medium', 'mcq', 'What keyword makes a function a generator function?', 'yield', 'return', 'generate', 'next', 'A', 0, 'The presence of yield in a function body makes it a generator function. Calling it returns a generator iterator.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_73', '73', 'Python', 'Generators', 'Medium', 'mcq', 'What is the main advantage of generators over lists?', 'They produce values lazily, saving memory', 'They are faster to iterate', 'They support indexing', 'They are thread-safe', 'A', 0, 'Generators produce values one at a time on demand, avoiding storing the entire sequence in memory.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_74', '74', 'Python', 'Generators', 'Hard', 'mcq', 'What does the send() method do on a generator?', 'Sends a value into the generator, resuming it and providing the value to yield', 'Sends the generator to another thread', 'Closes the generator', 'Resets the generator', 'A', 0, 'gen.send(value) resumes the generator and the yield expression evaluates to value, enabling two-way communication.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_75', '75', 'Python', 'Generators', 'Hard', 'mcq', 'What does ''yield from'' do in Python?', 'Delegates to a sub-generator, forwarding sent values and exceptions', 'Yields a value from a list', 'Creates a generator from a file', 'Imports a generator from a module', 'A', 0, '''yield from iterable'' delegates iteration to the sub-iterable, transparently forwarding send() and throw() calls.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_76', '76', 'Python', 'Generators', 'Easy', 'mcq', 'What does next() do when called on a generator?', 'Retrieves the next yielded value', 'Skips to the end', 'Resets the generator', 'Returns all remaining values', 'A', 0, 'next(gen) resumes the generator until the next yield, returning the yielded value. Raises StopIteration when exhausted.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_77', '77', 'Python', 'Iterators', 'Medium', 'mcq', 'Which two methods must an iterator implement?', '__iter__ and __next__', '__init__ and __del__', '__get__ and __set__', '__enter__ and __exit__', 'A', 0, 'The iterator protocol requires __iter__ (returning self) and __next__ (returning the next value or raising StopIteration).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_78', '78', 'Python', 'Iterators', 'Easy', 'mcq', 'What built-in function creates an iterator from an iterable?', 'iter()', 'next()', 'list()', 'range()', 'A', 0, 'iter(iterable) returns an iterator object. You can then use next() to get successive elements.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_79', '79', 'Python', 'Iterators', 'Medium', 'mcq', 'What exception signals the end of an iterator?', 'StopIteration', 'EndOfIterator', 'IteratorError', 'IndexError', 'A', 0, 'When an iterator is exhausted, __next__() raises StopIteration to signal there are no more elements.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_80', '80', 'Python', 'Iterators', 'Hard', 'mcq', 'What is the difference between an iterable and an iterator?', 'An iterable has __iter__ returning an iterator; an iterator also has __next__', 'They are the same thing', 'Iterables are faster', 'Iterators support indexing', 'A', 0, 'An iterable implements __iter__() which returns an iterator. An iterator implements both __iter__() and __next__().', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_81', '81', 'Python', 'Comprehensions', 'Easy', 'mcq', 'What is a list comprehension in Python?', 'A concise way to create lists using [expr for item in iterable]', 'A method to understand lists', 'A way to compress lists', 'A list sorting technique', 'A', 0, 'List comprehensions provide a compact syntax for creating lists from existing iterables with optional filtering.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_82', '82', 'Python', 'Comprehensions', 'Easy', 'mcq', 'Which of the following is a valid dict comprehension?', '{k: v for k, v in pairs}', '[k: v for k, v in pairs]', '(k: v for k, v in pairs)', '<k: v for k, v in pairs>', 'A', 0, 'Dict comprehensions use curly braces with key: value syntax inside the comprehension expression.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_83', '83', 'Python', 'Comprehensions', 'Medium', 'mcq', 'What does (x**2 for x in range(5)) create?', 'A generator expression', 'A tuple', 'A list', 'A set', 'A', 0, 'Parentheses around a comprehension-like expression create a generator expression, not a tuple.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_84', '84', 'Python', 'Comprehensions', 'Medium', 'mcq', 'How do you add a condition to a list comprehension?', '[x for x in lst if condition]', '[x for x in lst where condition]', '[x if condition for x in lst]', '[x for x in lst when condition]', 'A', 0, 'The if clause comes after the for clause to filter elements. [x for x in lst if x > 0] keeps only positive values.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_85', '85', 'Python', 'Comprehensions', 'Hard', 'mcq', 'What is a nested list comprehension?', 'A comprehension with multiple for clauses to handle nested iterations', 'A list inside a list', 'A comprehension that calls itself', 'A comprehension using recursion', 'A', 0, 'Nested comprehensions have multiple for clauses, e.g., [x*y for x in range(3) for y in range(3)] creates a flat list.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_86', '86', 'Python', 'Exception Handling', 'Easy', 'mcq', 'Which keyword is used to catch exceptions in Python?', 'except', 'catch', 'handle', 'rescue', 'A', 0, 'Python uses try/except blocks. The ''except'' keyword catches specified exceptions.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_87', '87', 'Python', 'Exception Handling', 'Easy', 'mcq', 'What does the finally block do?', 'Executes code regardless of whether an exception occurred', 'Catches all exceptions', 'Raises an exception', 'Terminates the program', 'A', 0, 'The finally block always executes after try/except, making it ideal for cleanup (closing files, connections).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_88', '88', 'Python', 'Exception Handling', 'Medium', 'mcq', 'What does the ''raise'' keyword do?', 'Manually raises an exception', 'Catches an exception', 'Ignores an exception', 'Logs an exception', 'A', 0, '''raise'' is used to explicitly throw an exception. ''raise ValueError(msg)'' creates and raises a ValueError.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_89', '89', 'Python', 'Exception Handling', 'Medium', 'mcq', 'What is the purpose of the ''else'' clause in a try/except block?', 'Executes only if no exception was raised in the try block', 'Catches remaining exceptions', 'Always executes', 'Executes if an exception was raised', 'A', 0, 'The else clause runs only when the try block completes without raising any exception.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_90', '90', 'Python', 'Exception Handling', 'Hard', 'mcq', 'How do you create a custom exception class in Python?', 'By inheriting from Exception or a subclass of Exception', 'By using the error keyword', 'By modifying sys.exceptions', 'By writing a config file', 'A', 0, 'Custom exceptions are created by subclassing Exception: class MyError(Exception): pass.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_91', '91', 'Python', 'Exception Handling', 'Hard', 'mcq', 'What is exception chaining in Python 3?', 'Using ''raise X from Y'' to link a new exception to its cause', 'Catching multiple exceptions in one except', 'Raising exceptions in a loop', 'Using nested try blocks', 'A', 0, '''raise X from Y'' sets Y as the __cause__ of X, preserving the chain of exceptions for debugging.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_92', '92', 'Python', 'File I/O', 'Easy', 'mcq', 'Which built-in function opens a file in Python?', 'open()', 'file()', 'read()', 'load()', 'A', 0, 'open(filename, mode) is the built-in function to open files. It returns a file object.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_93', '93', 'Python', 'File I/O', 'Easy', 'mcq', 'What is the recommended way to handle files in Python?', 'Using a with statement (context manager)', 'Using try/finally', 'Calling close() manually', 'Using global file handles', 'A', 0, 'The ''with'' statement ensures proper resource cleanup by automatically closing the file when the block exits.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_94', '94', 'Python', 'File I/O', 'Medium', 'mcq', 'What mode opens a file for writing, creating it if it does not exist?', '''w''', '''r''', '''x''', '''a''', 'A', 0, '''w'' mode opens for writing, truncating the file if it exists or creating it if it does not.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_95', '95', 'Python', 'File I/O', 'Medium', 'mcq', 'What is the difference between ''r'' and ''rb'' modes?', '''r'' opens in text mode; ''rb'' opens in binary mode', '''r'' is read-only; ''rb'' is read-write', '''rb'' is faster', 'There is no difference', 'A', 0, '''r'' opens in text mode with encoding/decoding. ''rb'' opens in binary mode, returning bytes objects.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_96', '96', 'Python', 'File I/O', 'Hard', 'mcq', 'What does the pathlib module provide over os.path?', 'Object-oriented filesystem paths with methods and operator overloading', 'Faster file operations', 'Network file access', 'Database file storage', 'A', 0, 'pathlib provides Path objects with methods like .read_text(), operator / for joining, and cleaner cross-platform path handling.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_97', '97', 'Python', 'Modules', 'Easy', 'mcq', 'What keyword is used to import a module in Python?', 'import', 'include', 'require', 'using', 'A', 0, 'The ''import'' keyword loads a module. You can also use ''from module import name'' for specific objects.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_98', '98', 'Python', 'Modules', 'Medium', 'mcq', 'What is the purpose of __init__.py in a directory?', 'It marks the directory as a Python package', 'It initializes variables', 'It runs first when Python starts', 'It is required for all directories', 'A', 0, '__init__.py makes a directory a Python package. In Python 3, namespace packages work without it, but it is still common.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_99', '99', 'Python', 'Modules', 'Medium', 'mcq', 'What does ''if __name__ == "__main__":'' guard against?', 'Code running when the module is imported (it only runs when executed directly)', 'Syntax errors', 'Import errors', 'Name collisions', 'A', 0, '__name__ is ''__main__'' only when the script is run directly. When imported, it equals the module name.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_100', '100', 'Python', 'Modules', 'Hard', 'mcq', 'How does Python''s module caching work?', 'Modules are cached in sys.modules after first import', 'Modules are reloaded every import', 'Modules are cached on disk', 'There is no caching', 'A', 0, 'After a module is first imported, Python caches it in sys.modules. Subsequent imports use the cached version.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_101', '101', 'Python', 'Modules', 'Easy', 'mcq', 'What does ''from math import sqrt'' do?', 'Imports only the sqrt function from the math module', 'Imports the entire math module', 'Creates a new sqrt function', 'Renames the math module', 'A', 0, '''from module import name'' imports a specific object from a module directly into the current namespace.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_102', '102', 'Python', 'Regular Expressions', 'Easy', 'mcq', 'Which module provides regular expression support in Python?', 're', 'regex', 'regexp', 'pattern', 'A', 0, 'The ''re'' module is Python''s built-in regular expression library. The third-party ''regex'' module offers extended features.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_103', '103', 'Python', 'Regular Expressions', 'Medium', 'mcq', 'What does re.findall(pattern, string) return?', 'A list of all non-overlapping matches', 'The first match only', 'A boolean', 'A compiled pattern', 'A', 0, 're.findall() returns a list of all non-overlapping matches of the pattern in the string.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_104', '104', 'Python', 'Regular Expressions', 'Medium', 'mcq', 'What does the \d pattern match in a regular expression?', 'Any digit character', 'Any non-digit character', 'Any whitespace', 'The letter d', 'A', 0, '\d matches any Unicode digit (equivalent to [0-9] for ASCII). \D matches non-digits.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_105', '105', 'Python', 'Regular Expressions', 'Hard', 'mcq', 'What is a lookahead assertion in regex?', 'A pattern that matches only if followed by another pattern, without consuming it', 'A way to look at previous matches', 'A method to speed up matching', 'A named group', 'A', 0, 'Lookahead (?=...) asserts that what follows matches the pattern but does not include it in the match result.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_106', '106', 'Python', 'Regular Expressions', 'Hard', 'mcq', 'What is the difference between re.match() and re.search()?', 'match() checks only at the start of the string; search() checks anywhere', 'They are identical', 'search() checks only at the start', 'match() is case-insensitive', 'A', 0, 're.match() anchors to the beginning of the string. re.search() scans through the entire string for a match.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_107', '107', 'Python', 'Multithreading', 'Medium', 'mcq', 'What is the GIL in Python?', 'Global Interpreter Lock - it prevents multiple threads from executing Python bytecode simultaneously', 'Global Import Lock', 'A garbage collection mechanism', 'A file locking system', 'A', 0, 'The GIL is a mutex that protects access to Python objects, limiting true parallelism in CPython threads.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_108', '108', 'Python', 'Multithreading', 'Medium', 'mcq', 'Which module is used for thread-based parallelism in Python?', 'threading', 'multiprocessing', 'asyncio', 'concurrent', 'A', 0, 'The threading module provides Thread and synchronization primitives for thread-based concurrency.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_109', '109', 'Python', 'Multithreading', 'Hard', 'mcq', 'When is multithreading beneficial despite the GIL?', 'For I/O-bound tasks where threads wait for external resources', 'For CPU-bound computation', 'Never, due to the GIL', 'Only with C extensions', 'A', 0, 'The GIL is released during I/O operations, so threads can run concurrently for I/O-bound tasks like network requests.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_110', '110', 'Python', 'Multithreading', 'Hard', 'mcq', 'What is a race condition?', 'When multiple threads access shared data concurrently and the outcome depends on timing', 'When a thread finishes too quickly', 'When threads are created in order', 'A Python exception type', 'A', 0, 'Race conditions occur when threads access shared state without proper synchronization, leading to unpredictable results.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_111', '111', 'Python', 'Multithreading', 'Medium', 'mcq', 'What does threading.Lock() provide?', 'A mutual exclusion lock to prevent concurrent access to shared resources', 'A way to lock files', 'A mechanism to pause threads', 'A thread-safe list', 'A', 0, 'Lock() creates a mutex. Only one thread can acquire it at a time, protecting critical sections.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_112', '112', 'Python', 'Async/Await', 'Medium', 'mcq', 'What does the async keyword do before a function definition?', 'Defines a coroutine function', 'Makes the function run in a separate thread', 'Makes the function faster', 'Creates a daemon process', 'A', 0, 'async def creates a coroutine function. Calling it returns a coroutine object that must be awaited.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_113', '113', 'Python', 'Async/Await', 'Medium', 'mcq', 'What does the await keyword do?', 'Suspends the coroutine until the awaited coroutine completes', 'Creates a new thread', 'Blocks the entire program', 'Deletes a coroutine', 'A', 0, 'await pauses the current coroutine, allowing the event loop to run other tasks until the awaited result is ready.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_114', '114', 'Python', 'Async/Await', 'Hard', 'mcq', 'What is asyncio.gather() used for?', 'Running multiple coroutines concurrently and collecting results', 'Gathering thread outputs', 'Collecting garbage', 'Grouping exceptions', 'A', 0, 'asyncio.gather(*coroutines) schedules multiple coroutines concurrently and returns their results as a list.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_115', '115', 'Python', 'Async/Await', 'Hard', 'mcq', 'What is the event loop in asyncio?', 'The central mechanism that schedules and runs coroutines', 'A loop that handles keyboard events', 'A GUI event handler', 'A file watcher', 'A', 0, 'The event loop is the core of asyncio, managing the execution, scheduling, and I/O multiplexing of coroutines.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_116', '116', 'Python', 'Async/Await', 'Easy', 'mcq', 'Which module provides async/await support in Python''s standard library?', 'asyncio', 'async', 'await', 'concurrent', 'A', 0, 'asyncio is the standard library module for writing asynchronous code using async/await syntax.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_117', '117', 'Python', 'Built-ins', 'Easy', 'mcq', 'What does the map() function do?', 'Applies a function to each item of an iterable', 'Creates a dictionary', 'Sorts a list', 'Maps keys to values', 'A', 0, 'map(func, iterable) returns an iterator that applies func to every item of the iterable.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_118', '118', 'Python', 'Built-ins', 'Easy', 'mcq', 'What does the filter() function do?', 'Returns elements from an iterable where the function returns True', 'Removes None values only', 'Sorts elements', 'Converts data types', 'A', 0, 'filter(func, iterable) returns an iterator yielding elements for which func returns True.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_119', '119', 'Python', 'Built-ins', 'Medium', 'mcq', 'What does zip() do in Python?', 'Creates an iterator of tuples pairing elements from multiple iterables', 'Compresses files', 'Merges dictionaries', 'Concatenates strings', 'A', 0, 'zip() pairs up elements from multiple iterables. It stops at the shortest iterable.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_120', '120', 'Python', 'Built-ins', 'Medium', 'mcq', 'What does enumerate() return?', 'An iterator of (index, value) tuples', 'The length of an iterable', 'A numbered string', 'A range object', 'A', 0, 'enumerate(iterable, start=0) yields (index, element) tuples, useful for getting both index and value in a loop.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_121', '121', 'Python', 'Built-ins', 'Hard', 'mcq', 'What is the purpose of the __slots__ attribute in a class?', 'Restricts instance attributes to a fixed set, saving memory', 'Defines time slots for methods', 'Creates database slots', 'Limits method count', 'A', 0, '__slots__ replaces the per-instance __dict__ with a fixed set of attribute slots, reducing memory overhead.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_122', '122', 'Python', 'Built-ins', 'Easy', 'mcq', 'What does abs() return?', 'The absolute value of a number', 'The abstract class', 'The first element', 'A boolean', 'A', 0, 'abs(x) returns the absolute value of x. For complex numbers, it returns the magnitude.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_123', '123', 'Python', 'Built-ins', 'Medium', 'mcq', 'What does the any() function do?', 'Returns True if any element in the iterable is truthy', 'Returns True if all elements are truthy', 'Picks a random element', 'Checks if the iterable is empty', 'A', 0, 'any(iterable) returns True if at least one element is truthy. It short-circuits on the first True value.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_124', '124', 'Python', 'Built-ins', 'Hard', 'mcq', 'What does the id() function return?', 'The identity (memory address in CPython) of an object', 'A unique string identifier', 'The object''s hash', 'The object''s type', 'A', 0, 'id(obj) returns a unique integer identifier for the object. In CPython, this is the memory address.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_125', '125', 'Python', 'Collections', 'Medium', 'mcq', 'What is collections.defaultdict?', 'A dict subclass that provides default values for missing keys', 'A read-only dictionary', 'A sorted dictionary', 'A dict that limits size', 'A', 0, 'defaultdict takes a factory function (e.g., list, int) and uses it to create default values for missing keys.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_126', '126', 'Python', 'Collections', 'Medium', 'mcq', 'What is collections.Counter used for?', 'Counting hashable objects and returning a dict of counts', 'Counting loop iterations', 'A thread-safe counter', 'Counting lines in a file', 'A', 0, 'Counter is a dict subclass for counting hashable objects. Counter(''abcabc'') gives Counter({''a'':2,''b'':2,''c'':2}).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_127', '127', 'Python', 'Collections', 'Hard', 'mcq', 'What is collections.OrderedDict in Python 3.7+?', 'A dict subclass that remembers order and supports reordering operations', 'Identical to dict with no extra features', 'A dict sorted by keys', 'A deprecated class', 'A', 0, 'While regular dicts maintain insertion order since 3.7, OrderedDict still offers move_to_end() and equality considers order.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_128', '128', 'Python', 'Collections', 'Easy', 'mcq', 'What is a namedtuple?', 'A tuple subclass with named fields accessible by attribute', 'A dictionary with ordered keys', 'A named variable', 'A tuple of names', 'A', 0, 'namedtuple creates tuple subclasses with named fields, e.g., Point = namedtuple(''Point'', [''x'', ''y'']).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_129', '129', 'Python', 'Collections', 'Hard', 'mcq', 'What is collections.ChainMap?', 'A class that groups multiple dicts into a single view for lookups', 'A mapping with chained keys', 'A hash chain implementation', 'A blockchain-style dictionary', 'A', 0, 'ChainMap groups multiple dicts and searches them in order during lookup. It is useful for scoped configurations.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_130', '130', 'Python', 'Scope', 'Easy', 'mcq', 'What is the LEGB rule in Python?', 'Local, Enclosing, Global, Built-in - the order of name lookup', 'Load, Execute, Generate, Build', 'List, Element, Group, Block', 'Lexical, Environmental, General, Base', 'A', 0, 'LEGB describes Python''s variable lookup order: Local scope, Enclosing function scope, Global scope, Built-in scope.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_131', '131', 'Python', 'Scope', 'Medium', 'mcq', 'What does the global keyword do?', 'Declares that a variable inside a function refers to the global scope', 'Creates a global function', 'Exports a variable to other modules', 'Makes a variable constant', 'A', 0, 'The global keyword inside a function indicates that the variable refers to the module-level (global) variable.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_132', '132', 'Python', 'Scope', 'Medium', 'mcq', 'What does the nonlocal keyword do?', 'Refers to a variable in the nearest enclosing scope (not global)', 'Creates a variable outside any function', 'Deletes a local variable', 'Makes a variable thread-local', 'A', 0, 'nonlocal binds a variable to the nearest enclosing function scope, enabling closures to modify outer variables.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_133', '133', 'Python', 'Scope', 'Hard', 'mcq', 'What happens if you assign to a variable name inside a function without global/nonlocal?', 'Python treats it as a local variable for the entire function', 'It modifies the global variable', 'It raises NameError', 'It creates both local and global variables', 'A', 0, 'Any assignment in a function makes the name local to the entire function. Referencing before assignment raises UnboundLocalError.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_134', '134', 'Python', 'Closures', 'Medium', 'mcq', 'What is a closure in Python?', 'A nested function that remembers variables from its enclosing scope', 'A function that closes files', 'A class destructor', 'A locked function', 'A', 0, 'A closure is an inner function that captures and remembers free variables from the enclosing function even after it returns.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_135', '135', 'Python', 'Closures', 'Medium', 'mcq', 'When is a closure created in Python?', 'When a nested function references a variable from its enclosing scope', 'When a function is imported', 'When a class is instantiated', 'When a module is loaded', 'A', 0, 'A closure is formed when a nested function references free variables from the enclosing function scope.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_136', '136', 'Python', 'Closures', 'Hard', 'mcq', 'What attribute of a function object stores its closure variables?', '__closure__', '__vars__', '__scope__', '__env__', 'A', 0, 'func.__closure__ is a tuple of cell objects containing the closed-over variables.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_137', '137', 'Python', 'Closures', 'Hard', 'mcq', 'What is the late binding issue with closures in loops?', 'Closures capture variables by reference, so loop variables share the last value', 'Closures cannot be used in loops', 'Loop closures are always eager', 'It only affects while loops', 'A', 0, 'Closures capture the variable itself (not its value). In a loop, all closures share the same variable, which holds the final iteration value.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_138', '138', 'Python', 'Advanced Python', 'Hard', 'mcq', 'What is a metaclass in Python?', 'A class whose instances are classes (the class of a class)', 'A deprecated feature', 'A mixin class', 'An abstract class', 'A', 0, 'Metaclasses define how classes behave. type is the default metaclass. Custom metaclasses inherit from type.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_139', '139', 'Python', 'Advanced Python', 'Hard', 'mcq', 'What is monkey patching in Python?', 'Dynamically modifying a class or module at runtime', 'A testing framework', 'A code obfuscation technique', 'A packaging tool', 'A', 0, 'Monkey patching replaces attributes/methods of objects at runtime. It is powerful but can make code harder to maintain.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_140', '140', 'Python', 'Advanced Python', 'Medium', 'mcq', 'What is the purpose of __all__ in a module?', 'Defines the public interface for ''from module import *''', 'Lists all classes in the module', 'Imports all submodules', 'Prevents any imports', 'A', 0, '__all__ is a list of names that should be exported when ''from module import *'' is used.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_141', '141', 'Python', 'Advanced Python', 'Hard', 'mcq', 'What does the weakref module provide?', 'References to objects that do not prevent garbage collection', 'Weak encryption', 'Thread-safe references', 'Compressed references', 'A', 0, 'weakref creates references that do not increase the reference count, allowing the referenced object to be garbage collected.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_142', '142', 'Python', 'Advanced Python', 'Medium', 'mcq', 'What is the purpose of the __enter__ and __exit__ methods?', 'They implement the context manager protocol for use with ''with'' statements', 'They control object creation and deletion', 'They manage imports', 'They handle exceptions only', 'A', 0, '__enter__ is called when entering a with block, __exit__ when leaving. Together they form the context manager protocol.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_143', '143', 'Python', 'Data Types', 'Hard', 'mcq', 'What is the difference between is and == in Python?', '''is'' checks identity (same object); ''=='' checks equality (same value)', '''is'' checks value; ''=='' checks identity', 'They are identical', '''is'' only works with strings', 'A', 0, '''is'' compares object identity (id). ''=='' compares values using __eq__. Two objects can be equal but not identical.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_144', '144', 'Python', 'Strings', 'Hard', 'mcq', 'What is the time complexity of string concatenation in a loop using +=?', 'O(n^2) in the worst case because strings are immutable', 'O(n)', 'O(1)', 'O(n log n)', 'A', 0, 'Each += creates a new string and copies existing content. Over n concatenations, this results in O(n^2) total work.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_145', '145', 'Python', 'Lists', 'Hard', 'mcq', 'What is the difference between a shallow copy and a deep copy of a list?', 'Shallow copy copies references to nested objects; deep copy recursively copies all objects', 'They are identical', 'Shallow copy is slower', 'Deep copy only works on flat lists', 'A', 0, 'copy.copy() creates a shallow copy (nested objects are shared). copy.deepcopy() recursively copies all nested objects.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_146', '146', 'Python', 'Dicts', 'Hard', 'mcq', 'What does the | operator do with dictionaries in Python 3.9+?', 'Merges two dictionaries, with the right one taking precedence', 'Performs bitwise OR on values', 'Checks for key overlap', 'Creates a set from dict keys', 'A', 0, 'In Python 3.9+, d1 | d2 merges dictionaries. If keys overlap, values from d2 take precedence.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_147', '147', 'Python', 'Functions', 'Hard', 'mcq', 'What are positional-only parameters in Python 3.8+?', 'Parameters before / in a function signature that must be passed positionally', 'Parameters that must be keywords', 'Parameters with default values', 'Parameters in lambda functions', 'A', 0, 'Parameters before / in def f(a, b, /, c) must be passed as positional arguments, not keyword arguments.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_148', '148', 'Python', 'OOP', 'Hard', 'mcq', 'What is __new__ used for in Python?', 'Creating a new instance before __init__ is called', 'Renewing an existing instance', 'Creating a new module', 'Allocating memory manually', 'A', 0, '__new__ is a static method called before __init__. It actually creates the instance, while __init__ initializes it.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_149', '149', 'Python', 'Decorators', 'Medium', 'mcq', 'Can a class be used as a decorator in Python?', 'Yes, by implementing __call__', 'No, only functions can be decorators', 'Only with @classmethod', 'Only abstract classes', 'A', 0, 'Any callable can be a decorator. A class with __call__ method can decorate functions by returning a callable instance.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_150', '150', 'Python', 'Generators', 'Medium', 'mcq', 'What is the difference between return and yield in a function?', 'return ends the function; yield pauses it and can resume', 'They are identical', 'yield ends the function', 'return pauses the function', 'A', 0, 'return terminates the function and sends a value back. yield suspends the function, preserving state for resumption.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_151', '151', 'Python', 'Comprehensions', 'Hard', 'mcq', 'What is the set comprehension syntax in Python?', '{expr for item in iterable}', '[expr for item in iterable]', '(expr for item in iterable)', '<expr for item in iterable>', 'A', 0, 'Set comprehensions use curly braces like {x**2 for x in range(5)}, creating a set of unique values.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_152', '152', 'Python', 'Exception Handling', 'Medium', 'mcq', 'What is the base class for all built-in exceptions in Python?', 'BaseException', 'Exception', 'Error', 'Throwable', 'A', 0, 'BaseException is the root class. Exception is a subclass that most user-catchable exceptions derive from.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_153', '153', 'Python', 'File I/O', 'Hard', 'mcq', 'What is memory-mapped file I/O in Python?', 'Using mmap to map a file into memory for efficient random access', 'Reading entire files into memory', 'Using virtual memory for files', 'Caching files in RAM', 'A', 0, 'The mmap module maps files into memory, allowing array-like access that is efficient for large files with random access patterns.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_154', '154', 'Python', 'Modules', 'Hard', 'mcq', 'What is a namespace package in Python 3?', 'A package without __init__.py that can span multiple directories', 'A package with named exports', 'A package in a namespace', 'A virtual package', 'A', 0, 'Namespace packages (PEP 420) allow package portions to be split across multiple directories without __init__.py files.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_155', '155', 'Python', 'Regular Expressions', 'Medium', 'mcq', 'What does re.compile() return?', 'A compiled regular expression pattern object', 'A string', 'A boolean', 'A match object', 'A', 0, 're.compile(pattern) pre-compiles a regex for reuse, improving performance when the same pattern is used multiple times.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_156', '156', 'Python', 'Async/Await', 'Medium', 'mcq', 'Can you use await outside of an async function?', 'No, await can only be used inside an async function or at the top level of an async REPL', 'Yes, anywhere in the code', 'Yes, inside regular functions', 'Yes, inside class methods', 'A', 0, 'await is only valid inside async functions (or top-level await in some environments). Using it elsewhere is a SyntaxError.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_157', '157', 'Python', 'Built-ins', 'Medium', 'mcq', 'What does the reversed() function return?', 'A reverse iterator', 'A reversed list', 'A reversed string', 'None', 'A', 0, 'reversed() returns a reverse iterator. To get a list, wrap it: list(reversed(seq)).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_158', '158', 'Python', 'Collections', 'Medium', 'mcq', 'What is collections.deque optimized for?', 'Fast appends and pops from both ends', 'Fast random access', 'Sorting', 'Memory efficiency', 'A', 0, 'deque (double-ended queue) provides O(1) append and pop from both ends, unlike lists which are O(n) for pop(0).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_159', '159', 'Python', 'Scope', 'Hard', 'mcq', 'What is name mangling in Python?', 'Rewriting __attr to _ClassName__attr to avoid accidental overrides in subclasses', 'Encrypting variable names', 'Removing unused variables', 'Renaming modules on import', 'A', 0, 'Names starting with __ (double underscore) in a class are mangled to _ClassName__name to prevent accidental name clashes in inheritance.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_160', '160', 'Python', 'Advanced Python', 'Hard', 'mcq', 'What is the Global Interpreter Lock''s impact on multiprocessing?', 'No impact - multiprocessing uses separate processes, each with its own GIL', 'It prevents multiprocessing entirely', 'It makes multiprocessing slower', 'It shares the GIL across processes', 'A', 0, 'multiprocessing bypasses the GIL by using separate processes, each with its own Python interpreter and GIL.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_161', '161', 'Python', 'Data Types', 'Medium', 'mcq', 'What is the difference between a bytes object and a bytearray?', 'bytes is immutable; bytearray is mutable', 'They are identical', 'bytes is mutable; bytearray is immutable', 'bytearray is faster', 'A', 0, 'bytes objects are immutable sequences of bytes. bytearray is the mutable counterpart, allowing in-place modification.', '');
