INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_220', '220', 'Python', 'OOP', 'Hard', 'output', 'What is printed?', 'Hello from A', 'Hello from B', 'None', 'Error', 'A', 0, 'C inherits from A (not B). C does not override greet(), so A''s greet() is called.', 'class A:
    def greet(self):
        return ''Hello from A''
class B(A):
