INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_221', '221', 'Python', 'Inheritance', 'Medium', 'output', 'What is the output?', '1 2', '2 1', '1 1', 'Error', 'A', 0, 'super().__init__() calls Base.__init__ which sets x=1. Then Child sets y=2.', 'class Base:
    def __init__(self):
        self.x = 1
class Child(Base):
    def __init__(self):
        super().__init__()
        self.y = 2
c = Child()
print(c.x, c.y)');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_222', '222', 'Python', 'Decorators', 'Medium', 'output', 'What does this code print?', '14', '7', '34', 'Error', 'A', 0, 'The decorator doubles the return value. add(3,4) returns 7, multiplied by 2 gives 14.', 'def double(func):
    def wrapper(*args):
        return func(*args) * 2
    return wrapper

@double
def add(a, b):
    return a + b

print(add(3, 4))');
