INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_224', '224', 'Python', 'Generators', 'Hard', 'output', 'What is the output?', '[0, 1, 1, 2, 3, 5]', '[1, 1, 2, 3, 5, 8]', '[0, 1, 2, 3, 5, 8]', 'Error', 'A', 0, 'The generator yields Fibonacci numbers starting from 0. The first 6 values are 0, 1, 1, 2, 3, 5.', 'def fib():
    a, b = 0, 1
    while True:
        yield a
        a, b = b, a + b
