INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_238', '238', 'Python', 'Iterators', 'Hard', 'output', 'What is printed?', '[1, 2, 3]', '[0, 1, 2]', '[0, 1, 2, 3]', 'Error', 'A', 0, 'The iterator increments self.i before returning, yielding 1, 2, 3. StopIteration fires when i >= 3.', 'class Count:
    def __init__(self, n):
        self.n = n
        self.i = 0
    def __iter__(self):
        return self
    def __next__(self):
        if self.i >= self.n:
            raise StopIteration
        self.i += 1
        return self.i
print(list(Count(3)))');
