INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_241', '241', 'Python', 'Multithreading', 'Medium', 'output', 'What is the output?', '[10]', '[]', '[5]', 'Error', 'A', 0, 'The thread calls worker(5), appending 10 to results. join() waits for completion before printing.', 'import threading
