INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_243', '243', 'Python', 'Advanced Python', 'Hard', 'output', 'What is printed?', '1', 'None', 'Error', 'Meta', 'A', 0, 'The metaclass __new__ adds ''version'' to the namespace. MyClass gets version=1 as a class attribute.', 'class Meta(type):
    def __new__(mcs, name, bases, namespace):
        namespace[''version''] = 1
        return super().__new__(mcs, name, bases, namespace)
class MyClass(metaclass=Meta):
    pass
print(MyClass.version)');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_244', '244', 'Python', 'Async/Await', 'Medium', 'output', 'What concept does this code demonstrate?', 'Concurrent coroutine execution - B prints before A', 'Sequential execution - A prints before B', 'Parallel threads', 'Error', 'A', 0, 'asyncio.gather runs coroutines concurrently. B has a shorter delay (0.05s) so it prints before A (0.1s).', 'import asyncio
async def say(msg, delay):
    await asyncio.sleep(delay)
    print(msg)
async def main():
    await asyncio.gather(say(''A'', 0.1), say(''B'', 0.05))
asyncio.run(main())');
