INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_275', '275', 'Python', 'Decorators', 'Hard', 'output', 'What is the output?', '[''hi'', ''hi'', ''hi'']', '''hi''', '(''hi'', ''hi'', ''hi'')', 'Error', 'A', 0, 'The decorator factory repeat(3) creates a decorator that calls greet() 3 times, collecting results in a list.', 'def repeat(n):
    def decorator(func):
        def wrapper(*args):
            return [func(*args) for _ in range(n)]
        return wrapper
    return decorator

@repeat(3)
def greet():
    return ''hi''

print(greet())');
