INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_347', '347', 'Python', 'Strings', 'Hard', 'scenario', 'You need to efficiently build a string from thousands of small pieces. What is the fastest approach?', 'String concatenation with +=', 'f-strings in a loop', 'String multiplication', '''''.join() on a list of parts', 'D', 3, '''''.join(parts) builds the final string in one operation, avoiding O(n^2) cost of repeated concatenation.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_348', '348', 'Python', 'Functions', 'Easy', 'scenario', 'You need to write a function that accepts either a filename or a file object. What feature helps?', 'Overloading', 'Decorators', 'Metaclasses', 'Duck typing - check for read() method', 'D', 3, 'Duck typing: check if the argument has a read() method (file-like object) rather than checking its type.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_349', '349', 'Python', 'OOP', 'Easy', 'scenario', 'You want to track how many instances of a class have been created. Where should you store the count?', 'In __init__', 'In a local variable', 'In a global variable', 'As a class attribute', 'D', 3, 'A class attribute is shared across all instances and persists. Increment it in __init__ to track instance count.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_350', '350', 'Python', 'Generators', 'Easy', 'scenario', 'You need to process items from a list but want to transform each item lazily. What should you use?', 'for loop with list', 'list comprehension', 'sorted()', 'Generator expression', 'D', 3, 'A generator expression (x*2 for x in items) transforms items lazily, one at a time, saving memory.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_351', '351', 'Python', 'Exception Handling', 'Easy', 'scenario', 'You want to ensure a database connection is always closed, even if an exception occurs. What pattern is best?', 'try/except only', 'Manual close() call', 'atexit handler', 'with statement (context manager)', 'D', 3, 'The with statement automatically calls __exit__ which closes the connection, even if an exception occurs.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_352', '352', 'Python', 'File I/O', 'Hard', 'scenario', 'You need to atomically write to a file to prevent corruption if the process crashes mid-write. What approach is best?', 'Direct write with flush()', 'Use a lock file', 'Append mode only', 'Write to a temp file and rename', 'D', 3, 'Writing to a temporary file and atomically renaming it ensures the original file is never in a partial state.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_353', '353', 'Python', 'Modules', 'Easy', 'scenario', 'You want to make your Python script both importable as a module and runnable as a standalone script. What guard should you use?', 'try/except ImportError', 'sys.argv check', 'os.environ check', 'if __name__ == ''__main__'':', 'D', 3, 'The __name__ guard runs code only when the script is executed directly, not when imported.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_354', '354', 'Python', 'Multithreading', 'Hard', 'scenario', 'You need true CPU parallelism for a number-crunching task in Python. What should you use?', 'threading', 'asyncio', 'greenlet', 'multiprocessing', 'D', 3, 'multiprocessing uses separate OS processes, each with its own GIL, enabling true parallel CPU computation.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_355', '355', 'Python', 'Collections', 'Easy', 'scenario', 'You need a FIFO queue with O(1) operations on both ends. What should you use?', 'list', 'tuple', 'set', 'collections.deque', 'D', 3, 'deque (double-ended queue) provides O(1) append and popleft, ideal for FIFO queues.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_356', '356', 'Python', 'Built-ins', 'Hard', 'scenario', 'You need to flatten a list of lists. What is the most Pythonic one-liner using built-ins?', 'reduce()', 'map()', 'filter()', 'sum(lists, []) or itertools.chain.from_iterable()', 'D', 3, 'itertools.chain.from_iterable(lists) efficiently flattens nested iterables. sum(lists, []) works but is O(n^2).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_357', '357', 'Python', 'Advanced Python', 'Hard', 'scenario', 'You want to add type hints and validate data at runtime for API input. What tool is best?', 'Manual isinstance() checks', 'assert statements', 'typing module only', 'pydantic or dataclass with validation', 'D', 3, 'Pydantic provides runtime data validation using type hints, auto-parsing, and clear error messages.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_358', '358', 'Python', 'Async/Await', 'Easy', 'scenario', 'You need to run a blocking synchronous function inside an async application without blocking the event loop. What should you use?', 'Call it directly', 'Use await on it', 'Wrap in a coroutine', 'Use loop.run_in_executor()', 'D', 3, 'run_in_executor() runs blocking code in a thread pool, preventing it from blocking the asyncio event loop.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_359', '359', 'Python', 'Regular Expressions', 'Easy', 'scenario', 'You need to split a string on multiple delimiters (comma, semicolon, pipe). What should you use?', 'str.split()', 'str.partition()', 'str.replace()', 're.split(r''[,;|]'', text)', 'D', 3, 're.split() with a character class [,;|] splits on any of the specified delimiters.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_360', '360', 'Python', 'Dicts', 'Easy', 'scenario', 'You need to iterate over both keys and values of a dictionary simultaneously. What method should you use?', 'keys()', 'values()', 'get()', 'items()', 'D', 3, 'dict.items() returns (key, value) pairs: for k, v in d.items(): ...', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_361', '361', 'Python', 'Scope', 'Easy', 'scenario', 'You want to define a constant used throughout your module. Where should you define it?', 'Inside a function', 'Inside a class', 'In a separate config class', 'At module level with UPPER_CASE name', 'D', 3, 'Module-level constants in UPPER_CASE (e.g., MAX_SIZE = 100) is the Python convention for constants.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_362', '362', 'Python', 'Sets', 'Medium', 'scenario', 'You have two large datasets and need to find items that appear in only one of them. What set operation should you use?', 'Union', 'Intersection', 'Difference', 'Symmetric difference', 'D', 3, 'Symmetric difference (a ^ b) returns elements in either set but not both, finding unique-to-each items.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_363', '363', 'Python', 'Tuples', 'Medium', 'scenario', 'You need to use a pair of coordinates as a dictionary key. Which data type should you use?', 'list', 'set', 'dict', 'tuple', 'D', 3, 'Tuples are immutable and hashable, making them suitable as dictionary keys. Lists are not hashable.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_364', '364', 'Python', 'Inheritance', 'Hard', 'scenario', 'You have a logging mixin, a caching mixin, and a base class. How should you combine them?', 'Nested inheritance chain', 'Composition only', 'Copy methods manually', 'Multiple inheritance: class MyClass(LogMixin, CacheMixin, Base)', 'D', 3, 'Multiple inheritance with mixins cleanly combines orthogonal behaviors without deep inheritance hierarchies.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_365', '365', 'Python', 'Decorators', 'Easy', 'scenario', 'You want to measure the execution time of a function. What is the cleanest approach?', 'Manual time.time() before and after', 'Print statements', 'Profiler module', 'A timing decorator', 'D', 3, 'A decorator wraps the function with timing logic, keeping the function code clean and reusable.', '');
