INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_367', '367', 'Python', 'Comprehensions', 'Medium', 'scenario', 'You need to create a dictionary mapping filenames to their extensions. What is the most Pythonic approach?', 'Manual for loop', 'map() with lambda', 'filter() with lambda', 'Dict comprehension: {f: f.split(''.'')[-1] for f in files}', 'D', 3, 'A dict comprehension is the most concise and Pythonic way to create the mapping.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_368', '368', 'Python', 'Closures', 'Easy', 'scenario', 'You want to create a function that remembers how many times it has been called. What approach uses closures?', 'Global counter variable', 'Class with __call__', 'Static method', 'Nested function with nonlocal counter', 'D', 3, 'A closure with nonlocal counter keeps the count in the enclosing scope, avoiding global state.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_369', '369', 'Python', 'File I/O', 'Hard', 'scenario', 'You need to process a very large CSV file (100GB) row by row. What is the most memory-efficient approach?', 'pandas.read_csv()', 'csv.reader() with readlines()', 'json.load()', 'csv.reader() iterating the file object directly', 'D', 3, 'Iterating the file object with csv.reader reads one row at a time from disk, using constant memory.', '');
