INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_371', '371', 'Python', 'Built-ins', 'Easy', 'scenario', 'You need to remove duplicates from a list while preserving order. What approach works in Python 3.7+?', 'sorted(set(lst))', 'list(set(lst))', 'Using a loop with ''in'' check', 'list(dict.fromkeys(lst))', 'D', 3, 'dict.fromkeys(lst) preserves insertion order (Python 3.7+) and removes duplicates. Converting back to list gives the result.', '');
