INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_373', '373', 'Python', 'Strings', 'Easy', 'scenario', 'You need to check if a user-submitted password contains at least one uppercase letter. What method helps?', 'isupper()', 'islower()', 'any(c.isupper() for c in password)', 'upper()', 'C', 2, 'Using any() with a generator checking each character''s case is the Pythonic way to verify mixed-case requirements.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_374', '374', 'Python', 'Lists', 'Easy', 'scenario', 'You need to check if a list is empty before processing it. What is the most Pythonic way?', 'if len(lst) == 0:', 'if lst == []:', 'if not lst:', 'if lst is None:', 'C', 2, '''if not lst:'' is the most Pythonic idiom. Empty lists are falsy, so ''not []'' evaluates to True.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_375', '375', 'Python', 'Dicts', 'Easy', 'scenario', 'You need to iterate over a dictionary and print each key-value pair. What is the most Pythonic approach?', 'for k in d: print(k, d[k])', 'for i in range(len(d)):', 'for k, v in d.items():', 'while loop with pop()', 'C', 2, 'for k, v in d.items(): unpacks each key-value pair directly, which is the most readable and Pythonic approach.', '');
