INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_379', '379', 'Python', 'Decorators', 'Medium', 'scenario', 'You want to enforce that a function argument is always a positive integer. What approach is cleanest?', 'Add checks at every call site', 'Use global validation', 'A validation decorator', 'String assertions', 'C', 2, 'A decorator can validate arguments before calling the function, keeping the function code clean and the validation reusable.', '');
