INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_383', '383', 'Python', 'Exception Handling', 'Easy', 'scenario', 'Your code might divide by zero. You want to handle it gracefully and return 0 instead. What pattern should you use?', 'Check with assert', 'Use a global flag', 'try/except ZeroDivisionError', 'Ignore the error', 'C', 2, 'try/except ZeroDivisionError catches the specific error and allows returning a default value.', '');
