INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_385', '385', 'Python', 'Modules', 'Medium', 'scenario', 'You need to package your Python project for distribution on PyPI. What tool should you use?', 'pip only', 'conda only', 'setuptools with pyproject.toml', 'manual zip files', 'C', 2, 'setuptools with pyproject.toml is the standard way to package Python projects for distribution.', '');
