INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_387', '387', 'Python', 'Multithreading', 'Easy', 'scenario', 'You need to run a function after a 5-second delay without blocking the main thread. What should you use?', 'time.sleep(5)', 'os.system(''sleep 5'')', 'threading.Timer(5, func)', 'asyncio.sleep(5)', 'C', 2, 'threading.Timer(5, func) creates a timer thread that calls func after 5 seconds without blocking.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_388', '388', 'Python', 'Async/Await', 'Medium', 'scenario', 'You need to rate-limit async API calls to 10 per second. What approach is best?', 'time.sleep() between calls', 'Thread pool', 'asyncio.Semaphore with sleep', 'Multiprocessing', 'C', 2, 'An asyncio.Semaphore combined with asyncio.sleep() provides cooperative rate limiting in async code.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_389', '389', 'Python', 'Built-ins', 'Medium', 'scenario', 'You need to transform a list of strings to integers, filtering out invalid ones. What is the cleanest approach?', 'Manual try/except in a loop', 'regex validation', 'A list comprehension with a helper function and try/except', 'str.isdigit() check', 'C', 2, 'A comprehension with a helper that catches ValueError provides clean filtering: [safe_int(s) for s in items if safe_int(s) is not None].', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_390', '390', 'Python', 'Collections', 'Medium', 'scenario', 'You need an ordered dictionary that also provides fast access to the most and least recently added items. What should you use?', 'dict', 'defaultdict', 'OrderedDict', 'deque', 'C', 2, 'OrderedDict provides move_to_end() and popitem(last=True/False) for manipulating order, beyond what plain dict offers.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_391', '391', 'Python', 'Scope', 'Medium', 'scenario', 'A team member accidentally shadows a built-in name (list = [1,2,3]). How do you still access the built-in?', 'Use List instead', 'Restart Python', 'import builtins; builtins.list', 'Use [] syntax only', 'C', 2, 'The builtins module holds all built-in names. builtins.list still references the original list type.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python_392', '392', 'Python', 'Closures', 'Medium', 'scenario', 'You want to create a configurable logger that remembers its log level. What pattern uses closures?', 'Global log level variable', 'Class with __init__', 'A factory function returning a closure over the level', 'Module-level config', 'C', 2, 'A factory function make_logger(level) returning a closure that captures level provides configurable, stateful loggers.', '');
