INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_83', '83', 'Python Selenium', 'Page Object Model', 'Easy', 'mcq', 'What is the Page Object Model (POM) design pattern?', 'A pattern that creates a class for each web page to encapsulate page elements and interactions', 'A built-in Selenium feature for page management', 'A way to automatically generate page objects from HTML', 'A testing framework for web pages', 'A', 0, 'POM separates page structure/interactions into classes, improving test maintainability.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_84', '84', 'Python Selenium', 'Page Object Model', 'Easy', 'mcq', 'What is the main advantage of the Page Object Model?', 'Reduces code duplication and improves maintainability', 'Makes tests run faster', 'Automatically handles waits', 'Generates test reports', 'A', 0, 'POM centralizes element locators and page interactions, so changes to the UI only require updates in one place.', '');
