INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_86', '86', 'Python Selenium', 'Page Object Model', 'Medium', 'mcq', 'What should a Page Object method return?', 'Either data from the page or a new Page Object for the resulting page', 'Always return True or False', 'Always return self', 'Always return a WebElement', 'A', 0, 'Page methods should return meaningful values or new Page Objects representing page transitions.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_87', '87', 'Python Selenium', 'Page Object Model', 'Medium', 'mcq', 'Which of the following is a best practice in POM?', 'Page classes should not contain assertions', 'Assertions should be in page classes', 'Tests should directly use find_element', 'One page class for the entire application', 'A', 0, 'Assertions belong in test code, not in page objects, to maintain separation of concerns.', '');
