INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_94', '94', 'Python Selenium', 'Page Object Model', 'Easy', 'output', 'What does this page object code structure represent?', 'A login page with methods to enter credentials and click login', 'A data class', 'A test case', 'A fixture', 'A', 0, 'The class encapsulates login page elements and interactions following POM pattern.', 'class LoginPage:
    def __init__(self, driver):
        self.driver = driver
        self.username_input = (By.ID, ''username'')
        self.password_input = (By.ID, ''password'')
        self.login_button = (By.ID, ''login-btn'')
    def login(self, user, pwd):
        self.driver.find_element(*self.username_input).send_keys(user)
        self.driver.find_element(*self.password_input).send_keys(pwd)
        self.driver.find_element(*self.login_button).click()
print(''LoginPage defined'')');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_95', '95', 'Python Selenium', 'Page Object Model', 'Medium', 'output', 'What does the login method return in this POM implementation?', 'A DashboardPage instance', 'None', 'True', 'The driver', 'A', 0, 'The login method returns a new DashboardPage, following POM best practice for page transitions.', 'class LoginPage:
    def __init__(self, driver):
        self.driver = driver
    def login(self, user, pwd):
        self.driver.find_element(By.ID, ''username'').send_keys(user)
        self.driver.find_element(By.ID, ''password'').send_keys(pwd)
        self.driver.find_element(By.ID, ''login-btn'').click()
        return DashboardPage(self.driver)
print(LoginPage.login.__code__.co_names)');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_96', '96', 'Python Selenium', 'Page Object Model', 'Medium', 'output', 'What does this BasePage class provide to subclasses?', 'A common find_element method with explicit wait', 'Nothing useful', 'Automatic test execution', 'Page URL management', 'A', 0, 'The BasePage provides a reusable wait-and-find method that all page classes can inherit.', 'class BasePage:
    def __init__(self, driver):
        self.driver = driver
        self.wait = WebDriverWait(driver, 10)
    def find(self, locator):
        return self.wait.until(EC.presence_of_element_located(locator))
print(''BasePage provides find with wait'')');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_97', '97', 'Python Selenium', 'Page Object Model', 'Hard', 'output', 'What pattern does this code demonstrate?', 'Method chaining in POM (fluent interface)', 'Builder pattern', 'Singleton pattern', 'Observer pattern', 'A', 0, 'Returning self from methods enables method chaining (fluent interface) in page objects.', 'class SearchPage:
    def __init__(self, driver):
        self.driver = driver
    def enter_query(self, text):
        self.driver.find_element(By.NAME, ''q'').send_keys(text)
        return self
    def click_search(self):
        self.driver.find_element(By.NAME, ''btnK'').click()
        return self
print(''Fluent interface pattern'')');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_98', '98', 'Python Selenium', 'Page Object Model', 'Hard', 'output', 'What does this property-based locator pattern provide?', 'Lazy element lookup - element is found each time the property is accessed', 'Caching of elements', 'Automatic retries', 'Static element references', 'A', 0, 'Using @property ensures the element is located fresh each time, avoiding stale references.', 'class ProfilePage:
    def __init__(self, driver):
        self.driver = driver
    @property
    def name_field(self):
        return self.driver.find_element(By.ID, ''name'')
    @property
    def email_field(self):
        return self.driver.find_element(By.ID, ''email'')
print(''Property-based lazy lookup'')');
