INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_121', '121', 'Python Selenium', 'Actions', 'Easy', 'output', 'What does this code do?', 'Moves the mouse to the menu element, triggering a hover effect', 'Clicks the menu element', 'Drags the menu element', 'Scrolls to the menu element', 'A', 0, 'move_to_element followed by perform() moves the mouse to the element, triggering hover events.', 'from selenium.webdriver.common.action_chains import ActionChains
