INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_123', '123', 'Python Selenium', 'Actions', 'Medium', 'output', 'What sequence of actions does this code perform?', 'Holds Ctrl, clicks three elements (selecting multiple), releases Ctrl', 'Clicks three elements sequentially', 'Right-clicks three elements', 'Drags elements together', 'A', 0, 'key_down(Keys.CONTROL) with multiple clicks simulates Ctrl+Click for multi-selection.', 'from selenium.webdriver.common.action_chains import ActionChains
from selenium.webdriver.common.keys import Keys
