print(''Multi-select done'')');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_124', '124', 'Python Selenium', 'Actions', 'Hard', 'output', 'What does this code accomplish?', 'Drags the source element and drops it on the target element', 'Copies source to target', 'Swaps source and target positions', 'Deletes the source element', 'A', 0, 'drag_and_drop clicks-and-holds source, moves to target, and releases.', 'from selenium.webdriver.common.action_chains import ActionChains
