INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_352', '352', 'Python Selenium', 'Test Framework Integration', 'Easy', 'output', 'What does this pytest fixture do?', 'Creates a Chrome driver before each test and quits it after the test completes', 'Creates a permanent browser session', 'Installs Chrome', 'Configures pytest', 'A', 0, 'The yield fixture sets up the driver, yields it for the test, then tears it down.', '@pytest.fixture
def driver():
    d = webdriver.Chrome()
    yield d
    d.quit()
print(''Fixture defined'')');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_353', '353', 'Python Selenium', 'Test Framework Integration', 'Medium', 'output', 'What does this conftest.py fixture configuration achieve?', 'Shares one browser session across all tests in the session, quitting at the end', 'Creates a new browser for each test', 'Runs tests in parallel', 'Configures the browser', 'A', 0, 'scope=''session'' creates the fixture once for the entire test session.', '@pytest.fixture(scope=''session'')
def browser():
    driver = webdriver.Chrome()
    yield driver
    driver.quit()
print(''Session-scoped fixture'')');
