INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_355', '355', 'Python Selenium', 'Test Framework Integration', 'Hard', 'output', 'What does this pytest hook do?', 'Captures and attaches a screenshot to the HTML report when a test fails', 'Takes screenshots before every test', 'Generates a PDF report', 'Logs test results to a file', 'A', 0, 'The hook checks for test failure and adds a base64 screenshot as an extra to the HTML report.', '@pytest.hookimpl(hookwrapper=True)
def pytest_runtest_makereport(item):
    outcome = yield
    report = outcome.get_result()
    if report.when == ''call'' and report.failed:
        driver = item.funcargs.get(''driver'')
        if driver:
            screenshot = driver.get_screenshot_as_base64()
print(''Failure screenshot hook'')');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_356', '356', 'Python Selenium', 'Test Framework Integration', 'Hard', 'output', 'What does this fixture do with the request parameter?', 'Accesses the test name and uses it to create a unique screenshot filename on failure', 'Gets the HTTP request', 'Fetches test data', 'Creates a network request', 'A', 0, 'request.node.name provides the test function name, useful for naming artifacts.', '@pytest.fixture(autouse=True)
def screenshot_on_failure(request, driver):
    yield
    if request.node.rep_call.failed:
        driver.save_screenshot(f''{request.node.name}_failure.png'')
print(''Auto-screenshot fixture'')');
