INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_377', '377', 'Python Selenium', 'Cross-Browser', 'Easy', 'output', 'What does this code demonstrate?', 'Creating different browser drivers based on a browser name parameter', 'Running all browsers simultaneously', 'Installing browsers', 'Browser detection', 'A', 0, 'A factory function creates the appropriate WebDriver based on the browser name string.', 'def get_driver(browser):
