INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_379', '379', 'Python Selenium', 'Cross-Browser', 'Medium', 'output', 'What does this parametrized test achieve?', 'Runs the same test function on Chrome, Firefox, and Edge sequentially', 'Runs on all browsers simultaneously', 'Tests only Chrome', 'Tests browser compatibility', 'A', 0, 'pytest.mark.parametrize runs the test once for each browser value.', '@pytest.mark.parametrize(''browser'', [''chrome'', ''firefox'', ''edge''])
def test_title(browser):
    driver = get_driver(browser)
    driver.get(''https://example.com'')
    assert driver.title == ''Example Domain''
    driver.quit()
print(''Cross-browser test defined'')');
