INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_381', '381', 'Python Selenium', 'Cross-Browser', 'Hard', 'output', 'What does this factory pattern provide?', 'A centralized way to create browsers with common options for any supported browser', 'Automatic browser installation', 'Browser auto-detection', 'Test parallelization', 'A', 0, 'A factory centralizes browser creation logic and common options application.', 'class BrowserFactory:
    @staticmethod
    def create(name, headless=False):
        if name == ''chrome'':
            opts = webdriver.ChromeOptions()
            if headless: opts.add_argument(''--headless'')
            return webdriver.Chrome(options=opts)
        elif name == ''firefox'':
            opts = webdriver.FirefoxOptions()
            if headless: opts.add_argument(''--headless'')
            return webdriver.Firefox(options=opts)
print(''BrowserFactory defined'')');
