INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_444', '444', 'Python Selenium', 'Parallel Execution', 'Medium', 'mcq', 'What is a common challenge with parallel Selenium tests?', 'Tests may interfere with each other if they share state (e.g., same user account, same database records)', 'Selenium does not support parallel execution', 'Browsers cannot run in parallel', 'Tests always fail in parallel', 'A', 0, 'Shared state between tests can cause race conditions and intermittent failures in parallel execution.', '');
