INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Selenium_451', '451', 'Python Selenium', 'Parallel Execution', 'Medium', 'output', 'What does this fixture ensure for parallel execution?', 'Each worker gets its own independent browser instance', 'All workers share one browser', 'Browsers are reused between tests', 'The browser runs in headless mode', 'A', 0, 'A function-scoped fixture creates a new driver for each test, ensuring isolation in parallel execution.', '@pytest.fixture(scope=''function'')
