INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Pytest_331', '331', 'Pytest', 'BDD Integration', 'Medium', 'output', 'What does this step definition return?', 'A Calculator instance as a fixture', 'A string', 'Nothing', 'An error', 'A', 0, 'The @given decorator with target_fixture makes the return value available as a fixture.', 'from pytest_bdd import given

class Calculator:
    def add(self, a, b):
        return a + b

@given(''I have a calculator'', target_fixture=''calculator'')
def get_calculator():
    return Calculator()');
