INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Pytest_336', '336', 'Pytest', 'Parametrize', 'Medium', 'output', 'How many tests will pass? [Parametrize #3]', '2', '3', '1', '0', 'A', 0, 'Only (2,True) and (0,True) satisfy len(s) < 3. ''hello'' has length 5, failing that check.', 'import pytest

@pytest.mark.parametrize(''s,expected'', [(''hi'', True), (''hello'', True), ('''', True)])
