INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_97', '97', 'Manual Testing', 'Test Planning', 'Hard', 'scenario', 'A QA manager is planning testing for a microservices-based e-commerce platform with 20 services, each owned by a different team. How should the test plan be structured?', 'Create a master test plan with service-level test plans and integration test strategy', 'One simple test plan for all services', 'Let each team test independently', 'Skip integration testing', 'A', 0, 'A hierarchical approach with master and service-level plans ensures both unit and integration coverage.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_98', '98', 'Manual Testing', 'Test Planning', 'Hard', 'scenario', 'A test plan for a banking application must meet SOX compliance requirements. What additional considerations apply?', 'Include audit trail verification, access control testing, and data integrity validation', 'Standard functional testing only', 'Performance testing only', 'No additional considerations', 'A', 0, 'SOX compliance requires testing of audit trails, access controls, and data integrity.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_99', '99', 'Manual Testing', 'Test Planning', 'Hard', 'scenario', 'During test planning, the team realizes they have expertise gaps in security testing. The timeline is fixed and hiring is not possible. What should the test plan recommend?', 'Outsource security testing to a specialized firm and include it as a dependency in the plan', 'Skip security testing', 'Have functional testers do security testing without training', 'Delay the project', 'A', 0, 'Outsourcing to specialists addresses the gap; documenting it as a dependency manages expectations.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_100', '100', 'Manual Testing', 'Test Planning', 'Hard', 'scenario', 'A product has both a web app and a mobile app sharing the same backend. The test plan must cover both. How should the test architecture be defined?', 'Shared backend test plan with separate frontend plans for web and mobile, plus integration testing', 'Test only the web app', 'Test only the mobile app', 'Test backend only', 'A', 0, 'A layered test architecture covers shared backend, separate frontends, and integration points.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_101', '101', 'Manual Testing', 'Test Design Techniques', 'Easy', 'mcq', 'What is Equivalence Partitioning?', 'Dividing input data into groups where all values in a group are expected to behave the same', 'Random testing', 'Testing all possible inputs', 'Testing only boundaries', 'A', 0, 'Equivalence Partitioning groups inputs into classes that should produce equivalent behavior.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_102', '102', 'Manual Testing', 'Test Design Techniques', 'Easy', 'mcq', 'What is Boundary Value Analysis (BVA)?', 'Testing at the edges of equivalence partitions', 'Testing random values', 'Testing only the middle values', 'Skipping edge cases', 'A', 0, 'BVA focuses on values at the boundaries of input ranges where defects are most likely.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_103', '103', 'Manual Testing', 'Test Design Techniques', 'Easy', 'mcq', 'Which test design technique uses a decision table?', 'Decision Table Testing', 'Random Testing', 'Exploratory Testing', 'Ad-hoc Testing', 'A', 0, 'Decision Table Testing uses tables to capture combinations of conditions and their actions.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_104', '104', 'Manual Testing', 'Test Design Techniques', 'Easy', 'mcq', 'What is a test case?', 'A set of conditions and expected results used to verify a specific feature', 'A defect report', 'A test plan', 'A code module', 'A', 0, 'A test case defines preconditions, steps, input data, and expected results for verification.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_105', '105', 'Manual Testing', 'Test Design Techniques', 'Easy', 'mcq', 'What does black-box testing focus on?', 'Testing functionality without knowledge of internal code structure', 'Testing source code', 'Testing database schemas', 'Testing hardware', 'A', 0, 'Black-box testing evaluates functionality based on requirements without examining internal code.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_106', '106', 'Manual Testing', 'Test Design Techniques', 'Easy', 'mcq', 'What does white-box testing focus on?', 'Testing internal code structure and logic', 'Testing only the UI', 'Testing without any documentation', 'Testing hardware components', 'A', 0, 'White-box testing examines internal code paths, logic, branches, and data flow.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_107', '107', 'Manual Testing', 'Test Design Techniques', 'Medium', 'mcq', 'What is State Transition Testing?', 'Testing based on changes in state of the system triggered by events', 'Testing only the initial state', 'Random input testing', 'Performance testing', 'A', 0, 'State Transition Testing verifies that the system transitions correctly between states based on events.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_108', '108', 'Manual Testing', 'Test Design Techniques', 'Medium', 'mcq', 'How does pairwise testing reduce the number of test cases?', 'By ensuring every pair of parameter values is tested at least once', 'By testing all combinations', 'By testing only one value per parameter', 'By random selection', 'A', 0, 'Pairwise testing covers all pairs of parameter combinations, dramatically reducing test count.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_109', '109', 'Manual Testing', 'Test Design Techniques', 'Medium', 'mcq', 'What is the purpose of error guessing as a test design technique?', 'To use tester experience to anticipate likely defects', 'To replace systematic techniques', 'To test only happy paths', 'To skip difficult scenarios', 'A', 0, 'Error guessing leverages a tester''s experience to predict where defects are likely to occur.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_110', '110', 'Manual Testing', 'Test Design Techniques', 'Medium', 'mcq', 'In decision table testing, what does each column represent?', 'A unique combination of conditions and corresponding actions', 'A single test step', 'A defect', 'A requirement', 'A', 0, 'Each column in a decision table represents a rule: a combination of conditions and resulting actions.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_111', '111', 'Manual Testing', 'Test Design Techniques', 'Medium', 'mcq', 'What is cause-effect graphing?', 'A technique that maps causes (inputs) to effects (outputs) to derive test cases', 'A debugging tool', 'A code review method', 'A project management technique', 'A', 0, 'Cause-effect graphing creates a visual model of input-output relationships to generate test cases.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_112', '112', 'Manual Testing', 'Test Design Techniques', 'Medium', 'mcq', 'When is Equivalence Partitioning most useful?', 'When there are large input ranges that can be logically divided into groups', 'When there is only one input', 'When testing hardware', 'When no requirements exist', 'A', 0, 'EP is most useful for reducing test cases when input domains are large but can be grouped logically.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_113', '113', 'Manual Testing', 'Test Design Techniques', 'Medium', 'mcq', 'What is the advantage of using a classification tree for test design?', 'It provides a visual hierarchical representation of test input combinations', 'It is faster than all other methods', 'It requires no domain knowledge', 'It eliminates all defects', 'A', 0, 'Classification trees visually organize input parameters hierarchically to derive systematic combinations.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_114', '114', 'Manual Testing', 'Test Design Techniques', 'Medium', 'mcq', 'What is the difference between positive and negative testing?', 'Positive tests verify correct behavior with valid inputs; negative tests verify handling of invalid inputs', 'They are the same', 'Negative tests are run only in production', 'Positive tests use no test data', 'A', 0, 'Positive testing validates expected behavior; negative testing validates error handling and robustness.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_115', '115', 'Manual Testing', 'Test Design Techniques', 'Hard', 'mcq', 'What is Modified Condition/Decision Coverage (MC/DC)?', 'A coverage criterion requiring each condition to independently affect the decision outcome', 'Testing all inputs', 'Testing only boundaries', 'Random testing', 'A', 0, 'MC/DC ensures each condition in a decision independently affects the outcome, used in safety-critical systems.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_116', '116', 'Manual Testing', 'Test Design Techniques', 'Hard', 'mcq', 'How does orthogonal array testing optimize test case design?', 'By selecting a subset of combinations that provides maximum coverage with minimum tests', 'By testing all possible combinations', 'By testing only one input at a time', 'By ignoring interactions', 'A', 0, 'Orthogonal arrays provide balanced coverage of parameter interactions with a minimal set of tests.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_117', '117', 'Manual Testing', 'Test Design Techniques', 'Hard', 'mcq', 'What is the key limitation of Equivalence Partitioning as a standalone technique?', 'It may miss defects at partition boundaries that BVA would catch', 'It generates too many test cases', 'It only works for numeric inputs', 'It requires source code access', 'A', 0, 'EP alone may miss boundary-specific defects, which is why it is often combined with BVA.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_118', '118', 'Manual Testing', 'Test Design Techniques', 'Hard', 'mcq', 'In state transition testing, what is an invalid state transition?', 'A transition that should not occur according to the specification but might due to a defect', 'Any normal transition', 'The initial state', 'The final state', 'A', 0, 'Invalid state transitions are those not permitted by the specification that should be tested as negative cases.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_119', '119', 'Manual Testing', 'Test Design Techniques', 'Hard', 'mcq', 'How does combinatorial explosion affect decision table testing?', 'The number of columns grows exponentially with the number of conditions, making full coverage impractical', 'It has no effect', 'It reduces test cases', 'It speeds up testing', 'A', 0, 'Each additional condition doubles the columns, so techniques like collapsed tables are needed for many conditions.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_120', '120', 'Manual Testing', 'Test Design Techniques', 'Hard', 'mcq', 'What is the relationship between code coverage criteria in terms of strength: Statement, Branch, and MC/DC?', 'MC/DC subsumes Branch which subsumes Statement coverage', 'Statement is strongest', 'They are all equal', 'Branch subsumes MC/DC', 'A', 0, 'MC/DC is the strongest, subsuming Branch coverage, which in turn subsumes Statement coverage.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_121', '121', 'Manual Testing', 'Test Design Techniques', 'Easy', 'scenario', 'A form accepts ages between 18 and 60. A tester needs to design test cases efficiently. Which technique should they use first?', 'Equivalence Partitioning combined with Boundary Value Analysis', 'Random Testing', 'Ad-hoc Testing', 'Only testing age 30', 'A', 0, 'EP divides the range into valid/invalid partitions, and BVA targets the boundaries 17, 18, 60, 61.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_122', '122', 'Manual Testing', 'Test Design Techniques', 'Easy', 'scenario', 'A login page requires a username and password. The tester wants to verify that invalid credentials show an error message. What type of testing is this?', 'Negative Testing', 'Performance Testing', 'Security Testing', 'Load Testing', 'A', 0, 'Negative testing verifies the system handles invalid inputs correctly, such as wrong credentials.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_123', '123', 'Manual Testing', 'Test Design Techniques', 'Easy', 'scenario', 'A tester needs to verify a discount calculation: 10% for orders over $100, 20% for orders over $500. Which technique is best suited?', 'Decision Table Testing', 'Random Testing', 'Exploratory Testing', 'Load Testing', 'A', 0, 'Decision tables effectively capture condition-action rules like discount tiers.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_124', '124', 'Manual Testing', 'Test Design Techniques', 'Easy', 'scenario', 'A QA engineer is told to test a text field that accepts 1-50 characters. Which boundary values should they test?', '0, 1, 50, and 51 characters', 'Only 25 characters', 'Only empty input', 'Only 50 characters', 'A', 0, 'BVA requires testing at boundaries: just below minimum (0), minimum (1), maximum (50), just above (51).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_125', '125', 'Manual Testing', 'Test Design Techniques', 'Medium', 'scenario', 'An e-commerce site has a shipping calculator with 4 inputs each having 3 possible values. Testing all combinations would require 81 test cases. The team has time for only 15. What technique helps?', 'Pairwise Testing', 'Testing all 81 combinations', 'Testing only one combination', 'Skipping testing entirely', 'A', 0, 'Pairwise testing covers all pairs of input values, reducing 81 combinations to approximately 9-15 tests.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_126', '126', 'Manual Testing', 'Test Design Techniques', 'Medium', 'scenario', 'A traffic light system cycles through Red, Green, and Yellow states. A tester needs to verify all valid transitions and that invalid transitions are blocked. Which technique applies?', 'State Transition Testing', 'Equivalence Partitioning', 'Boundary Value Analysis', 'Decision Table Testing', 'A', 0, 'State Transition Testing verifies valid state changes and ensures invalid transitions are rejected.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_127', '127', 'Manual Testing', 'Test Design Techniques', 'Medium', 'scenario', 'A test team finds many defects clustered in the payment module despite using EP and BVA. A senior tester suggests adding another technique. What would complement EP and BVA?', 'Error Guessing based on common payment processing pitfalls', 'Reducing test cases', 'Skipping payment module', 'Testing only the UI', 'A', 0, 'Error Guessing uses experience to target common payment defects not caught by systematic techniques alone.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_128', '128', 'Manual Testing', 'Test Design Techniques', 'Medium', 'scenario', 'An insurance application has a complex premium calculation based on 5 conditions: age range, gender, smoker status, policy type, and coverage amount. The QA lead needs an organized way to identify all rules. What technique is best?', 'Decision Table Testing', 'Random Testing', 'Ad-hoc Testing', 'Only EP', 'A', 0, 'Decision tables systematically capture all combinations of conditions for complex business rules.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_129', '129', 'Manual Testing', 'Test Design Techniques', 'Medium', 'scenario', 'A tester is designing test cases for a function that accepts an email address. They need to cover valid formats, invalid formats, and edge cases. Which combination of techniques would be most thorough?', 'EP for format categories, BVA for length limits, and error guessing for common email mistakes', 'Only random inputs', 'Only valid emails', 'Only blank input', 'A', 0, 'Combining EP, BVA, and error guessing provides comprehensive coverage for email validation testing.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_130', '130', 'Manual Testing', 'Test Design Techniques', 'Medium', 'scenario', 'A mobile app has a form with 3 dropdowns. Dropdown A has 4 options, B has 3 options, and C has 5 options. Full combinatorial testing requires 60 test cases. Time allows for 20. What is the best approach?', 'Pairwise testing to cover all two-way interactions', 'Test only the first option of each', 'Random selection of 20', 'Skip dropdown testing', 'A', 0, 'Pairwise testing ensures every pair of dropdown values appears in at least one test case.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_131', '131', 'Manual Testing', 'Test Design Techniques', 'Hard', 'scenario', 'A medical device firmware has 8 boolean conditions that determine alarm behavior. Full decision table testing requires 256 columns. The team must reduce test cases while maintaining safety coverage. What approach should they use?', 'MC/DC combined with risk-based prioritization of critical condition combinations', 'Random selection of 20 columns', 'Testing only one condition at a time', 'Skipping alarm testing', 'A', 0, 'MC/DC ensures each condition independently affects the outcome, suitable for safety-critical systems.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_132', '132', 'Manual Testing', 'Test Design Techniques', 'Hard', 'scenario', 'A tester is designing test cases for a complex workflow where a user can reach the same screen through 5 different paths. Some paths change the available options on the screen. Which technique best handles this?', 'State Transition Testing combined with path analysis', 'Testing only one path', 'Boundary Value Analysis', 'Equivalence Partitioning', 'A', 0, 'State Transition Testing with path analysis captures how different paths affect system state and available options.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_133', '133', 'Manual Testing', 'Test Design Techniques', 'Hard', 'scenario', 'An API endpoint accepts JSON with 10 optional fields. A tester wants to ensure that all interactions between any 3 fields are tested. What combinatorial technique provides this coverage?', '3-wise combinatorial testing (covering arrays of strength 3)', 'Pairwise testing', 'Testing all 10 fields individually', 'Testing only with all fields present', 'A', 0, '3-wise combinatorial testing covers all interactions between any 3 parameters, stronger than pairwise.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_134', '134', 'Manual Testing', 'Test Design Techniques', 'Hard', 'scenario', 'A financial system calculates tax based on income brackets, filing status, deductions, and state. The business rules are documented in a 50-page specification. How should the test design approach be structured?', 'Decompose rules into decision tables per section, combine with EP/BVA for input ranges, and use RTM for coverage', 'Test with random inputs', 'Test only the first bracket', 'Wait for production issues', 'A', 0, 'Systematic decomposition into decision tables with EP/BVA and traceability ensures comprehensive coverage.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_135', '135', 'Manual Testing', 'Defect Management', 'Easy', 'mcq', 'What is a defect in software testing?', 'A variance between expected and actual results', 'A new feature request', 'A design document', 'A test case', 'A', 0, 'A defect is any deviation from the expected behavior as defined by requirements or specifications.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_136', '136', 'Manual Testing', 'Defect Management', 'Easy', 'mcq', 'What information should a defect report include?', 'Summary, steps to reproduce, expected vs actual result, severity, and priority', 'Only the defect title', 'Only a screenshot', 'Only the tester name', 'A', 0, 'A comprehensive defect report includes all details needed for developers to understand and fix the issue.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_137', '137', 'Manual Testing', 'Defect Management', 'Easy', 'mcq', 'What is the difference between severity and priority of a defect?', 'Severity measures impact on functionality; priority measures urgency of fixing', 'They are the same', 'Severity is set by developers; priority by testers', 'Priority measures functionality impact', 'A', 0, 'Severity reflects technical impact; priority reflects business urgency of the fix.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_138', '138', 'Manual Testing', 'Defect Management', 'Easy', 'mcq', 'What does ''defect life cycle'' refer to?', 'The stages a defect goes through from discovery to closure', 'The product lifecycle', 'The SDLC', 'The test plan duration', 'A', 0, 'The defect life cycle tracks a defect from identification through triage, fixing, verification, and closure.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_139', '139', 'Manual Testing', 'Defect Management', 'Easy', 'mcq', 'Which status indicates a defect has been fixed and awaits verification?', 'Fixed/Ready for Retest', 'New', 'Rejected', 'Deferred', 'A', 0, 'Fixed or Ready for Retest status indicates the developer has applied a fix awaiting QA verification.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_140', '140', 'Manual Testing', 'Defect Management', 'Easy', 'mcq', 'What does it mean when a defect is ''deferred''?', 'The defect is valid but will be addressed in a future release', 'The defect is invalid', 'The defect is fixed', 'The defect is a duplicate', 'A', 0, 'Deferred means the defect is acknowledged but postponed to a later release based on priority.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_141', '141', 'Manual Testing', 'Defect Management', 'Medium', 'mcq', 'What is defect triaging?', 'The process of reviewing, prioritizing, and assigning defects', 'Writing test cases', 'Deploying software', 'Creating user stories', 'A', 0, 'Defect triage involves reviewing reported defects, setting priority, and assigning them to the right team.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_142', '142', 'Manual Testing', 'Defect Management', 'Medium', 'mcq', 'What is the purpose of a defect severity classification system?', 'To categorize defects by their impact on system functionality for appropriate response', 'To rank testers', 'To count lines of code', 'To measure test execution speed', 'A', 0, 'Severity classification ensures appropriate response levels: Critical, Major, Minor, Cosmetic.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_143', '143', 'Manual Testing', 'Defect Management', 'Medium', 'mcq', 'What is a ''showstopper'' defect?', 'A critical defect that blocks further testing or renders the system unusable', 'A minor UI issue', 'A documentation error', 'A feature enhancement', 'A', 0, 'A showstopper is a critical defect that prevents the system from functioning or blocks testing progress.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_144', '144', 'Manual Testing', 'Defect Management', 'Medium', 'mcq', 'What is defect clustering?', 'The tendency of defects to be concentrated in a small number of modules', 'Grouping defects alphabetically', 'Random distribution of defects', 'Having no defects', 'A', 0, 'Defect clustering reflects the Pareto principle: most defects tend to be found in a few modules.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_145', '145', 'Manual Testing', 'Defect Management', 'Medium', 'mcq', 'When should a defect be marked as ''Cannot Reproduce''?', 'When the tester or developer cannot replicate the defect with the given steps', 'When the defect is fixed', 'When a new defect is found', 'When testing is complete', 'A', 0, 'Cannot Reproduce means the defect could not be replicated despite following the reported steps.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_146', '146', 'Manual Testing', 'Defect Management', 'Medium', 'mcq', 'What is the purpose of defect root cause analysis?', 'To identify the underlying reason for defects and prevent recurrence', 'To blame developers', 'To close defects faster', 'To reduce test cases', 'A', 0, 'Root cause analysis identifies why defects occurred to implement preventive measures.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_147', '147', 'Manual Testing', 'Defect Management', 'Medium', 'mcq', 'What happens when a tester reopens a defect?', 'The tester verified the fix and found it inadequate or the defect still exists', 'The defect is deleted', 'A new defect is created', 'Testing is stopped', 'A', 0, 'Reopening indicates the fix did not resolve the issue or the defect persists after the attempted fix.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_148', '148', 'Manual Testing', 'Defect Management', 'Medium', 'mcq', 'What is the difference between a defect and an enhancement request?', 'A defect is a failure to meet requirements; an enhancement is a request for new functionality', 'They are the same', 'Enhancements are always urgent', 'Defects are always low priority', 'A', 0, 'Defects violate existing requirements; enhancements request functionality beyond current requirements.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_149', '149', 'Manual Testing', 'Defect Management', 'Hard', 'mcq', 'What is defect leakage and how is it measured?', 'Defects found in production that escaped testing; measured as production defects divided by total defects', 'Number of test cases', 'Team size', 'Code complexity', 'A', 0, 'Defect leakage measures testing effectiveness by the ratio of escaped defects to total defects found.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_150', '150', 'Manual Testing', 'Defect Management', 'Hard', 'mcq', 'What is the defect removal efficiency (DRE) formula?', 'DRE = (Defects found during testing / Total defects) x 100', 'DRE = Test cases / Defects', 'DRE = Developers / Testers', 'DRE = Time / Cost', 'A', 0, 'DRE measures what percentage of total defects were caught during testing before production release.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_151', '151', 'Manual Testing', 'Defect Management', 'Hard', 'mcq', 'How should defect management be handled in an Agile environment compared to traditional?', 'Real-time triage within sprints with focus on immediate resolution rather than formal workflow', 'Exactly the same as traditional', 'No defect tracking needed', 'Defects are only logged at sprint end', 'A', 0, 'Agile defect management emphasizes rapid triage, immediate resolution within sprints, and lightweight tracking.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_152', '152', 'Manual Testing', 'Defect Management', 'Hard', 'mcq', 'What is a defect cascade?', 'When one defect triggers or masks other defects in dependent functionality', 'A waterfall of test cases', 'A type of test suite', 'A deployment process', 'A', 0, 'A defect cascade occurs when one defect causes failures in related areas, potentially hiding other defects.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_153', '153', 'Manual Testing', 'Defect Management', 'Hard', 'mcq', 'What is the pesticide paradox in relation to defect management?', 'Repeatedly running the same tests eventually stops finding new defects', 'Defects multiply over time', 'New defects appear after deployment', 'Testing tools expire', 'A', 0, 'The pesticide paradox states that repeating the same tests will not find new defects; tests must be revised.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_154', '154', 'Manual Testing', 'Defect Management', 'Hard', 'mcq', 'In a formal defect management process, what role does a Change Control Board (CCB) play?', 'Reviews and approves decisions on defects including deferral, rejection, or priority changes', 'Writes code', 'Executes test cases', 'Deploys software', 'A', 0, 'The CCB makes formal decisions about defect disposition including priority, deferral, and scheduling.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_155', '155', 'Manual Testing', 'Defect Management', 'Easy', 'scenario', 'A tester finds a typo in an error message. How should they classify the severity?', 'Cosmetic/Low', 'Critical', 'Blocker', 'Major', 'A', 0, 'A typo in an error message is a cosmetic issue with minimal impact on functionality.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_156', '156', 'Manual Testing', 'Defect Management', 'Easy', 'scenario', 'A tester reports a defect but the developer says they cannot reproduce it. What should the tester do?', 'Provide more detailed steps, environment info, and screenshots to help reproduce', 'Close the defect', 'Argue with the developer', 'Ignore it', 'A', 0, 'The tester should enhance the report with detailed steps, environment details, and evidence.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_157', '157', 'Manual Testing', 'Defect Management', 'Easy', 'scenario', 'A defect was reported by two different testers independently. What should happen to the second report?', 'Mark it as Duplicate and link it to the original', 'Keep both open', 'Delete it', 'Assign it to a different developer', 'A', 0, 'Duplicate defects should be linked to the original and closed as duplicates to avoid redundant work.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_158', '158', 'Manual Testing', 'Defect Management', 'Easy', 'scenario', 'A developer fixes a login bug. The tester retests and confirms it works correctly. What status should the defect be set to?', 'Closed/Verified', 'Reopened', 'Deferred', 'New', 'A', 0, 'After successful retest verification, the defect should be closed or marked as verified.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_159', '159', 'Manual Testing', 'Defect Management', 'Medium', 'scenario', 'The application crashes when a user uploads a file larger than 10MB. This feature is used daily by all customers. How should severity and priority be assigned?', 'Severity: Critical; Priority: High', 'Severity: Low; Priority: Low', 'Severity: Medium; Priority: Low', 'Severity: Cosmetic; Priority: Medium', 'A', 0, 'A crash affecting all users on a daily feature warrants Critical severity and High priority.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_160', '160', 'Manual Testing', 'Defect Management', 'Medium', 'scenario', 'A QA lead notices that 60% of all defects in the last release were found in the reporting module which has only 10% of the code. What testing principle does this illustrate?', 'Defect Clustering (Pareto principle)', 'Exhaustive Testing', 'Pesticide Paradox', 'Error Guessing', 'A', 0, 'Defect clustering shows that a small number of modules typically contain the majority of defects.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_161', '161', 'Manual Testing', 'Defect Management', 'Medium', 'scenario', 'After a defect is fixed, the tester finds that the fix introduced a new problem in a related feature. What type of defect is this?', 'Regression defect', 'Duplicate defect', 'Enhancement request', 'Design defect', 'A', 0, 'A regression defect is a new issue introduced by a code change intended to fix another problem.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_162', '162', 'Manual Testing', 'Defect Management', 'Medium', 'scenario', 'A critical defect is found two days before release. The fix is complex and risky. What should the team consider?', 'Risk assessment of fixing vs releasing with a known workaround', 'Always fix regardless of risk', 'Ignore the defect', 'Delay release by months', 'A', 0, 'The team should weigh the risk of the fix introducing new issues against releasing with a workaround.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_163', '163', 'Manual Testing', 'Defect Management', 'Medium', 'scenario', 'A defect was marked as ''Not a Defect'' by the developer, but the tester believes it violates the requirements. How should this be resolved?', 'Escalate to the defect triage meeting with requirements documentation as evidence', 'Accept the developer''s decision', 'File a complaint with HR', 'Close the defect permanently', 'A', 0, 'Disagreements should be resolved in triage with evidence from requirements documentation.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_164', '164', 'Manual Testing', 'Defect Management', 'Hard', 'scenario', 'An organization has a defect removal efficiency of only 60%. Production defects are causing significant customer impact. What systematic improvements should be implemented?', 'Improve test coverage, add code reviews, implement shift-left testing, and strengthen entry/exit criteria', 'Hire more support staff', 'Reduce testing', 'Accept the DRE as acceptable', 'A', 0, 'Improving DRE requires better test coverage, early defect detection, code reviews, and stricter quality gates.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_165', '165', 'Manual Testing', 'Defect Management', 'Hard', 'scenario', 'During a triage meeting, there are 200 open defects for a release with limited development capacity. How should the team prioritize?', 'Use a risk-based matrix considering severity, business impact, fix complexity, and customer visibility', 'Fix them in order reported', 'Fix only easy ones', 'Close them all as deferred', 'A', 0, 'A risk-based prioritization matrix ensures the most impactful defects are addressed within constraints.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_166', '166', 'Manual Testing', 'Defect Management', 'Hard', 'scenario', 'A production incident reveals a defect that was actually found during testing but was incorrectly closed as ''Cannot Reproduce.'' What process improvement is needed?', 'Implement stricter criteria for Cannot Reproduce status including minimum reproduction attempts and environment verification', 'No changes needed', 'Stop using the status', 'Blame the tester', 'A', 0, 'Stricter criteria and verification requirements for Cannot Reproduce prevent premature defect closure.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_167', '167', 'Manual Testing', 'Defect Management', 'Hard', 'scenario', 'A defect in a rarely used admin feature allows unauthorized access to user data. It has low impact frequency but high potential damage. How should severity and priority be set?', 'Severity: Critical (security breach); Priority: High (data protection is paramount)', 'Severity: Low; Priority: Low since rarely used', 'Severity: Medium; Priority: Medium', 'Severity: Cosmetic; Priority: Low', 'A', 0, 'Security vulnerabilities are always Critical severity regardless of usage frequency; data protection demands High priority.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_168', '168', 'Manual Testing', 'Test Types', 'Easy', 'mcq', 'What is smoke testing?', 'A quick test to verify the basic functionality of a build before detailed testing', 'Exhaustive testing of all features', 'Performance testing', 'Security testing', 'A', 0, 'Smoke testing is a shallow check to ensure the build is stable enough for further testing.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_169', '169', 'Manual Testing', 'Test Types', 'Easy', 'mcq', 'What is sanity testing?', 'A focused test on specific functionality after a minor change or bug fix', 'Testing all features', 'Load testing', 'Installation testing', 'A', 0, 'Sanity testing verifies that a specific fix or change works without doing broad regression testing.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_170', '170', 'Manual Testing', 'Test Types', 'Easy', 'mcq', 'What is the difference between functional and non-functional testing?', 'Functional tests what the system does; non-functional tests how well it performs', 'They are identical', 'Non-functional is more important', 'Functional testing is done after deployment only', 'A', 0, 'Functional testing verifies features; non-functional testing evaluates quality attributes like performance.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_171', '171', 'Manual Testing', 'Test Types', 'Easy', 'mcq', 'What is integration testing?', 'Testing the interaction between integrated modules or components', 'Testing individual functions', 'Testing the entire system', 'Testing the user interface only', 'A', 0, 'Integration testing verifies that modules work correctly together when combined.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_172', '172', 'Manual Testing', 'Test Types', 'Easy', 'mcq', 'What is system testing?', 'Testing the complete integrated system against requirements', 'Testing a single module', 'Testing in production', 'Testing only the database', 'A', 0, 'System testing validates the entire system as a whole against functional and non-functional requirements.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_173', '173', 'Manual Testing', 'Test Types', 'Easy', 'mcq', 'What is unit testing?', 'Testing individual components or functions in isolation', 'Testing the whole system', 'Testing across browsers', 'Testing user workflows', 'A', 0, 'Unit testing verifies the smallest testable parts of the software in isolation.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_174', '174', 'Manual Testing', 'Test Types', 'Medium', 'mcq', 'What is the difference between smoke testing and sanity testing?', 'Smoke testing is broad and shallow; sanity testing is narrow and deep on specific areas', 'They are the same', 'Sanity is always automated', 'Smoke takes longer than sanity', 'A', 0, 'Smoke tests cover breadth of functionality shallowly; sanity tests focus deeply on specific changes.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_175', '175', 'Manual Testing', 'Test Types', 'Medium', 'mcq', 'What is alpha testing?', 'Testing performed by internal testers at the developer''s site before beta release', 'Testing by end users', 'Automated testing', 'Performance testing', 'A', 0, 'Alpha testing is done by internal staff at the development site to find defects before beta release.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_176', '176', 'Manual Testing', 'Test Types', 'Medium', 'mcq', 'What is beta testing?', 'Testing performed by external users in a real-world environment before general release', 'Internal testing', 'Unit testing', 'Code review', 'A', 0, 'Beta testing involves real users testing in their own environments to find issues missed internally.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_177', '177', 'Manual Testing', 'Test Types', 'Medium', 'mcq', 'What is the purpose of compatibility testing?', 'To verify the application works across different browsers, OS, devices, and configurations', 'To test a single browser', 'To test code quality', 'To test database performance', 'A', 0, 'Compatibility testing ensures the application functions correctly across various environments.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_178', '178', 'Manual Testing', 'Test Types', 'Medium', 'mcq', 'What is end-to-end testing?', 'Testing the complete application flow from start to finish as a user would experience it', 'Testing a single API', 'Testing only the database', 'Testing only the frontend', 'A', 0, 'End-to-end testing validates the entire user journey through the complete system.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_179', '179', 'Manual Testing', 'Test Types', 'Medium', 'mcq', 'What is the difference between top-down and bottom-up integration testing?', 'Top-down starts from higher-level modules using stubs; bottom-up starts from lower-level modules using drivers', 'They are identical', 'Top-down uses drivers', 'Bottom-up uses stubs', 'A', 0, 'Top-down tests from UI down using stubs for lower modules; bottom-up tests from units up using drivers.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_180', '180', 'Manual Testing', 'Test Types', 'Medium', 'mcq', 'What is ad-hoc testing?', 'Unstructured testing without test cases, relying on tester''s intuition', 'Formal testing with detailed test cases', 'Automated testing', 'Performance testing', 'A', 0, 'Ad-hoc testing is informal, unplanned testing aimed at finding defects through random exploration.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_181', '181', 'Manual Testing', 'Test Types', 'Medium', 'mcq', 'What is localization testing?', 'Verifying the application is correctly adapted for a specific locale including language and formats', 'Testing only in English', 'Testing server locations', 'Testing network latency', 'A', 0, 'Localization testing verifies proper adaptation of language, date/number formats, and cultural conventions.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_182', '182', 'Manual Testing', 'Test Types', 'Hard', 'mcq', 'What distinguishes grey-box testing from black-box and white-box testing?', 'Grey-box uses partial knowledge of internal structure to design tests from an external perspective', 'Grey-box is a mix of manual and automated', 'Grey-box is performance testing', 'Grey-box requires no knowledge at all', 'A', 0, 'Grey-box testing combines partial internal knowledge with external testing perspective for better coverage.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_183', '183', 'Manual Testing', 'Test Types', 'Hard', 'mcq', 'When is big-bang integration testing appropriate despite its risks?', 'For small systems with few modules where individual module testing is already thorough', 'For large enterprise systems', 'For safety-critical systems', 'Always', 'A', 0, 'Big-bang integration is viable for small systems where isolation of defects to specific integrations is easier.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_184', '184', 'Manual Testing', 'Test Types', 'Hard', 'mcq', 'What is mutation testing and what does it evaluate?', 'Introducing deliberate faults into code to evaluate the quality of the test suite', 'Testing code mutations from version control', 'Random testing', 'UI testing', 'A', 0, 'Mutation testing seeds small code changes (mutants) to check if existing tests can detect them.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_185', '185', 'Manual Testing', 'Test Types', 'Hard', 'mcq', 'What is the key challenge of testing in a service-oriented architecture (SOA)?', 'Managing dependencies between services and ensuring correct behavior at integration points', 'Writing unit tests', 'UI design', 'Database schema design', 'A', 0, 'SOA testing challenges include service dependencies, contract validation, and integration complexity.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_186', '186', 'Manual Testing', 'Test Types', 'Hard', 'mcq', 'What is the difference between verification and validation in testing?', 'Verification checks if the product is built right; validation checks if the right product is built', 'They are identical', 'Verification is done only in production', 'Validation is done only by developers', 'A', 0, 'Verification ensures correct implementation; validation ensures the product meets user needs.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_187', '187', 'Manual Testing', 'Test Types', 'Hard', 'mcq', 'What is the sandwich (hybrid) integration testing strategy?', 'Combines top-down and bottom-up approaches by testing from both ends toward the middle', 'Testing only the middle layers', 'A specific type of unit test', 'Testing food ordering systems', 'A', 0, 'Sandwich integration tests from top and bottom simultaneously, meeting in the middle for efficiency.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_188', '188', 'Manual Testing', 'Test Types', 'Easy', 'scenario', 'A new build has just been deployed to the test environment. Before the team starts detailed testing, they want to verify the build is stable. What type of testing should they do?', 'Smoke Testing', 'Regression Testing', 'Performance Testing', 'UAT', 'A', 0, 'Smoke testing quickly verifies build stability before investing time in detailed testing.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_189', '189', 'Manual Testing', 'Test Types', 'Easy', 'scenario', 'A developer fixed a specific login bug. The tester wants to quickly verify just that fix works. What type of testing is this?', 'Sanity Testing', 'System Testing', 'Smoke Testing', 'Alpha Testing', 'A', 0, 'Sanity testing focuses on verifying a specific fix or change rather than broad functionality.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_190', '190', 'Manual Testing', 'Test Types', 'Easy', 'scenario', 'A client wants their web application to work on Chrome, Firefox, and Safari. What type of testing is needed?', 'Compatibility/Cross-Browser Testing', 'Unit Testing', 'Smoke Testing', 'Load Testing', 'A', 0, 'Cross-browser compatibility testing verifies the app works correctly across specified browsers.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_191', '191', 'Manual Testing', 'Test Types', 'Easy', 'scenario', 'The development team has completed individual module testing. Now they need to verify that modules work together. What testing level comes next?', 'Integration Testing', 'Unit Testing', 'User Acceptance Testing', 'Smoke Testing', 'A', 0, 'Integration testing follows unit testing to verify correct interaction between modules.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_192', '192', 'Manual Testing', 'Test Types', 'Medium', 'scenario', 'An e-commerce application needs to be tested on iOS and Android with different screen sizes. The QA team has limited devices. What approach should they take?', 'Use a combination of real devices for critical paths and emulators/cloud services for broader coverage', 'Test only on one device', 'Skip mobile testing', 'Test only on emulators', 'A', 0, 'Combining real devices for key scenarios with cloud device farms provides cost-effective coverage.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_193', '193', 'Manual Testing', 'Test Types', 'Medium', 'scenario', 'After a major code refactoring, the team needs to verify that existing functionality still works. What type of testing is most important?', 'Regression Testing', 'Smoke Testing only', 'UAT only', 'Installation Testing', 'A', 0, 'Regression testing verifies that refactoring has not broken existing functionality.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_194', '194', 'Manual Testing', 'Test Types', 'Medium', 'scenario', 'A team wants to test how the system handles 1000 concurrent users. What type of non-functional testing is this?', 'Load Testing', 'Functional Testing', 'Sanity Testing', 'Usability Testing', 'A', 0, 'Load testing evaluates system behavior under expected and peak user concurrency levels.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_195', '195', 'Manual Testing', 'Test Types', 'Medium', 'scenario', 'An internationalized application needs to display prices in local currencies and dates in local formats for 10 countries. What type of testing is required?', 'Localization Testing', 'Unit Testing', 'Smoke Testing', 'Sanity Testing', 'A', 0, 'Localization testing verifies correct adaptation of formats, currencies, and content for each locale.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_196', '196', 'Manual Testing', 'Test Types', 'Medium', 'scenario', 'A healthcare app must verify the complete patient journey from registration through appointment booking to receiving test results. What testing approach covers this?', 'End-to-End Testing', 'Unit Testing', 'Integration Testing of one module', 'Smoke Testing', 'A', 0, 'End-to-end testing validates the complete user journey across all system components.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_197', '197', 'Manual Testing', 'Test Types', 'Medium', 'scenario', 'The team is using bottom-up integration testing but the UI modules are not ready yet. What component is needed to simulate the UI?', 'Test Drivers', 'Stubs', 'Mocks', 'Fixtures', 'A', 0, 'In bottom-up integration, test drivers simulate the calling modules (like the UI) that are not yet available.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_198', '198', 'Manual Testing', 'Test Types', 'Hard', 'scenario', 'A team discovers that their test suite fails to detect intentionally introduced bugs during a quality assessment. What type of testing would evaluate and improve the test suite''s effectiveness?', 'Mutation Testing', 'Regression Testing', 'Smoke Testing', 'Sanity Testing', 'A', 0, 'Mutation testing introduces deliberate code changes to evaluate whether the test suite can detect them.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_199', '199', 'Manual Testing', 'Test Types', 'Hard', 'scenario', 'A banking system has 20 microservices. The team wants to test API contracts between services to prevent integration failures. What testing strategy is most appropriate?', 'Contract Testing / Consumer-Driven Contract Testing', 'Only UI testing', 'Only unit testing', 'Manual integration testing of all services', 'A', 0, 'Contract testing validates API agreements between services, preventing integration failures in microservices.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_200', '200', 'Manual Testing', 'Test Types', 'Hard', 'scenario', 'A system has both real-time and batch processing components. Traditional end-to-end testing takes 8 hours. How can the testing strategy be optimized?', 'Separate real-time and batch testing with parallel execution and targeted integration tests at boundaries', 'Always run full 8-hour tests', 'Skip batch testing', 'Test only real-time features', 'A', 0, 'Separating real-time and batch testing with targeted integration at boundaries reduces cycle time.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_201', '201', 'Manual Testing', 'Test Types', 'Hard', 'scenario', 'A team needs to verify that their application handles graceful degradation when dependent services are down. What type of testing is most appropriate?', 'Failover/Resilience Testing with chaos engineering principles', 'Smoke Testing', 'Unit Testing', 'Usability Testing', 'A', 0, 'Resilience testing with chaos engineering verifies graceful degradation when dependencies fail.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_202', '202', 'Manual Testing', 'Agile Testing', 'Easy', 'mcq', 'In Agile, when does testing begin?', 'From the start of the project, integrated throughout all sprints', 'Only after development is complete', 'Only in the final sprint', 'Only during UAT', 'A', 0, 'In Agile, testing is continuous and starts from the very first sprint.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_203', '203', 'Manual Testing', 'Agile Testing', 'Easy', 'mcq', 'What is a sprint in Agile testing?', 'A fixed time period (usually 2-4 weeks) during which a set of features is developed and tested', 'The entire project timeline', 'A type of test case', 'A defect status', 'A', 0, 'A sprint is a time-boxed iteration where the team delivers a potentially shippable increment.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_204', '204', 'Manual Testing', 'Agile Testing', 'Easy', 'mcq', 'What is the role of a tester in a Scrum team?', 'A team member who collaborates throughout the sprint on quality activities', 'Someone who only tests at the end', 'The person who writes requirements', 'The project sponsor', 'A', 0, 'In Scrum, testers are integral team members participating in all activities including planning and reviews.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_205', '205', 'Manual Testing', 'Agile Testing', 'Easy', 'mcq', 'What is a user story in Agile?', 'A short description of functionality from the user''s perspective', 'A detailed test case', 'A defect report', 'A project charter', 'A', 0, 'A user story describes a feature in the format: As a [user], I want [goal], so that [benefit].', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_206', '206', 'Manual Testing', 'Agile Testing', 'Easy', 'mcq', 'What are acceptance criteria in Agile?', 'Conditions that a user story must satisfy to be considered complete', 'The sprint velocity', 'The team''s skill set', 'The project budget', 'A', 0, 'Acceptance criteria define the specific conditions a user story must meet to be accepted as done.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_207', '207', 'Manual Testing', 'Agile Testing', 'Easy', 'mcq', 'What is the ''Definition of Done'' in Agile?', 'A shared understanding of what it means for a work item to be complete', 'The project end date', 'The first test case', 'A type of requirement', 'A', 0, 'Definition of Done is a checklist of criteria that must be met for an item to be considered complete.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_208', '208', 'Manual Testing', 'Agile Testing', 'Medium', 'mcq', 'What is the Agile testing quadrant model?', 'A framework categorizing tests into four quadrants based on business/technology facing and supporting/critiquing', 'A four-phase test plan', 'A defect classification system', 'A sprint planning tool', 'A', 0, 'The Agile testing quadrants help teams understand different types of tests and when to apply them.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_209', '209', 'Manual Testing', 'Agile Testing', 'Medium', 'mcq', 'What is the purpose of a sprint retrospective from a testing perspective?', 'To reflect on testing process improvements and identify what worked and what needs change', 'To write new test cases', 'To deploy software', 'To estimate story points', 'A', 0, 'Retrospectives help the team continuously improve their testing practices based on sprint experience.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_210', '210', 'Manual Testing', 'Agile Testing', 'Medium', 'mcq', 'How does testing in a Kanban environment differ from Scrum?', 'Kanban has continuous flow with WIP limits instead of fixed sprints', 'There is no difference', 'Kanban has no testing', 'Scrum has no testing', 'A', 0, 'Kanban uses continuous flow with work-in-progress limits rather than time-boxed sprints.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_211', '211', 'Manual Testing', 'Agile Testing', 'Medium', 'mcq', 'What is the role of Behavior-Driven Development (BDD) in Agile testing?', 'It bridges communication between business and technical teams using a shared Given-When-Then format', 'It replaces all testing', 'It is only for developers', 'It is a deployment technique', 'A', 0, 'BDD uses Given-When-Then scenarios to create shared understanding between business and technical teams.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_212', '212', 'Manual Testing', 'Agile Testing', 'Medium', 'mcq', 'What is ''shift-left testing'' in Agile?', 'Moving testing activities earlier in the development process', 'Shifting testers to a different team', 'Delaying testing to the end', 'Moving testing to production', 'A', 0, 'Shift-left testing means performing testing activities earlier to find defects when they are cheaper to fix.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_213', '213', 'Manual Testing', 'Agile Testing', 'Medium', 'mcq', 'How should regression testing be managed in Agile sprints?', 'Through a growing automated regression suite that runs continuously', 'Skip regression testing in Agile', 'Only in the last sprint', 'Manually test everything each sprint', 'A', 0, 'Agile requires a growing automated regression suite to maintain quality across rapid iterations.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_214', '214', 'Manual Testing', 'Agile Testing', 'Medium', 'mcq', 'What is the three amigos meeting in Agile?', 'A discussion between a developer, tester, and business analyst to refine a user story', 'A standup meeting with three people', 'A retrospective with three topics', 'A review with three stakeholders', 'A', 0, 'The three amigos meeting brings different perspectives to ensure shared understanding of requirements.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_215', '215', 'Manual Testing', 'Agile Testing', 'Medium', 'mcq', 'What is Acceptance Test-Driven Development (ATDD)?', 'Writing acceptance tests before development begins, driven by collaboration between team members', 'Testing after development', 'A type of unit test', 'A deployment strategy', 'A', 0, 'ATDD creates acceptance tests first through team collaboration, guiding development to meet those criteria.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_216', '216', 'Manual Testing', 'Agile Testing', 'Hard', 'mcq', 'How does the concept of ''whole team approach'' to quality differ from traditional QA?', 'Everyone on the team is responsible for quality, not just testers', 'Only testers are responsible', 'Only managers are responsible', 'Quality is not important in Agile', 'A', 0, 'The whole team approach means quality is everyone''s responsibility, unlike traditional siloed QA.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_217', '217', 'Manual Testing', 'Agile Testing', 'Hard', 'mcq', 'What is the testing impact when a team transitions from feature teams to component teams?', 'Component teams may optimize locally but increase integration testing complexity', 'No impact on testing', 'Testing becomes unnecessary', 'All testing becomes automated', 'A', 0, 'Component teams can create integration gaps requiring more cross-team integration testing effort.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_218', '218', 'Manual Testing', 'Agile Testing', 'Hard', 'mcq', 'How should technical debt related to testing be managed in Agile?', 'Allocate capacity in each sprint for test automation debt reduction and test maintenance', 'Ignore it', 'Address it only at project end', 'Create a separate testing project', 'A', 0, 'Allocating sprint capacity for testing debt prevents accumulation that degrades quality over time.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_219', '219', 'Manual Testing', 'Agile Testing', 'Hard', 'mcq', 'What is the ''test automation pyramid'' and why is it important in Agile?', 'A strategy with many unit tests, fewer integration tests, and fewest UI tests for fast, stable feedback', 'Equal numbers of all test types', 'Only UI tests', 'Only unit tests', 'A', 0, 'The pyramid ensures fast, reliable feedback with most tests at the unit level and fewer at the UI level.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_220', '220', 'Manual Testing', 'Agile Testing', 'Hard', 'mcq', 'How does continuous integration affect the tester''s role in Agile?', 'Testers focus more on test design, automation, and exploratory testing while CI handles regression', 'Testers are not needed', 'CI replaces all testing', 'Testers only write manual test cases', 'A', 0, 'CI automates regression feedback, allowing testers to focus on higher-value activities like exploration.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_221', '221', 'Manual Testing', 'Agile Testing', 'Hard', 'mcq', 'What challenges arise when scaling Agile testing across multiple teams working on the same product?', 'Test environment contention, integration complexity, and maintaining consistent test standards', 'No challenges', 'Fewer test cases needed', 'Testing becomes simpler', 'A', 0, 'Scaling Agile testing brings environment, integration, and standardization challenges across teams.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_222', '222', 'Manual Testing', 'Agile Testing', 'Easy', 'scenario', 'A Scrum team''s sprint is 2 weeks long. The developer finishes coding a feature on day 10. The tester complains there is not enough time to test. What Agile principle is being violated?', 'Testing should happen throughout the sprint, not just at the end', 'Sprints should be longer', 'Testers should code', 'Developers should test', 'A', 0, 'Agile integrates testing throughout the sprint rather than relegating it to the end.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_223', '223', 'Manual Testing', 'Agile Testing', 'Easy', 'scenario', 'A product owner writes a user story without acceptance criteria. How does this affect the tester?', 'The tester cannot clearly define what constitutes pass or fail for the story', 'No impact', 'Testing is easier', 'The tester writes code instead', 'A', 0, 'Without acceptance criteria, testers lack clear conditions for verifying story completion.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_224', '224', 'Manual Testing', 'Agile Testing', 'Easy', 'scenario', 'During the sprint planning meeting, the team is estimating stories but no tester is present. What risk does this create?', 'Testing effort may be underestimated and testing scenarios may be missed', 'No risk', 'Stories will be overestimated', 'Development will take longer', 'A', 0, 'Without tester input, teams often underestimate testing effort and miss quality considerations.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_225', '225', 'Manual Testing', 'Agile Testing', 'Easy', 'scenario', 'At the end of a sprint, the team demonstrates the completed features to stakeholders. What Agile ceremony is this?', 'Sprint Review/Demo', 'Sprint Retrospective', 'Daily Standup', 'Sprint Planning', 'A', 0, 'The Sprint Review or Demo showcases completed work to stakeholders for feedback.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_226', '226', 'Manual Testing', 'Agile Testing', 'Medium', 'scenario', 'A team''s sprint velocity has been declining because regression testing takes more time each sprint. What solution would address this sustainably?', 'Invest in automated regression testing to reduce manual regression effort', 'Skip regression testing', 'Reduce sprint scope permanently', 'Add more testers', 'A', 0, 'Automating regression tests frees time for new feature testing as the product grows.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_227', '227', 'Manual Testing', 'Agile Testing', 'Medium', 'scenario', 'A QA engineer on an Agile team notices the same types of defects recurring across sprints. What Agile practice would help address this?', 'Use sprint retrospectives to identify root causes and implement preventive actions', 'Ignore the pattern', 'File more defect reports', 'Blame the developers', 'A', 0, 'Retrospectives provide a forum to analyze recurring issues and commit to specific improvements.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_228', '228', 'Manual Testing', 'Agile Testing', 'Medium', 'scenario', 'The business wants to release features to production multiple times per week. What testing strategy enables this cadence?', 'Continuous testing with automated pipelines, feature flags, and canary releases', 'Full manual regression each time', 'No testing', 'Monthly batch testing', 'A', 0, 'Continuous testing with automation, feature flags, and staged rollouts enables frequent safe releases.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_229', '229', 'Manual Testing', 'Agile Testing', 'Medium', 'scenario', 'A tester wants to ensure that a user story is well-understood before development begins. Which Agile practice should they participate in?', 'Three Amigos / Story Refinement session', 'Sprint Retrospective', 'Daily Standup only', 'Test Closure meeting', 'A', 0, 'Three Amigos sessions bring developer, tester, and BA perspectives together for shared understanding.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_230', '230', 'Manual Testing', 'Agile Testing', 'Medium', 'scenario', 'An Agile team is working on a payment feature. The tester proposes writing acceptance tests before the developer starts coding. What practice is this?', 'Acceptance Test-Driven Development (ATDD)', 'Regression Testing', 'Smoke Testing', 'Ad-hoc Testing', 'A', 0, 'ATDD defines acceptance tests upfront to guide development and ensure the feature meets criteria.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_231', '231', 'Manual Testing', 'Agile Testing', 'Hard', 'scenario', 'A large organization with 10 Scrum teams working on one product is struggling with integration quality. Tests pass in individual team environments but fail when code is merged. What testing approach should be adopted?', 'Implement a system-level integration test suite that runs on the merged codebase with shared CI/CD pipelines', 'Let each team test independently', 'Remove integration testing', 'Delay integration to release', 'A', 0, 'Shared CI/CD with system-level integration tests on merged code catches cross-team integration issues.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_232', '232', 'Manual Testing', 'Agile Testing', 'Hard', 'scenario', 'A team is transitioning from Scrum to Kanban. The tester is concerned about how to maintain testing quality without fixed sprint boundaries for regression cycles. What approach should they adopt?', 'Implement continuous testing with automated gates at each stage of the Kanban workflow', 'Stop regression testing', 'Keep sprint boundaries artificially', 'Test only at monthly intervals', 'A', 0, 'In Kanban, continuous testing with quality gates at each workflow stage replaces sprint-based testing cycles.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_233', '233', 'Manual Testing', 'Agile Testing', 'Hard', 'scenario', 'A team practicing BDD finds that their Given-When-Then scenarios become so numerous that maintaining them slows development. How should they optimize?', 'Review and refactor scenarios, remove redundant ones, use scenario outlines, and focus on key behaviors', 'Delete all scenarios', 'Stop using BDD', 'Convert all to unit tests', 'A', 0, 'Scenario maintenance requires periodic review, refactoring, and focusing on key behavioral outcomes.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_234', '234', 'Manual Testing', 'Agile Testing', 'Hard', 'scenario', 'An Agile team''s test automation pyramid is inverted with 80% UI tests and 20% unit tests. Test execution takes hours and is flaky. What is the recommended corrective strategy?', 'Gradually shift tests down the pyramid by converting UI tests to integration/unit tests where possible', 'Add more UI tests', 'Accept the slow feedback', 'Remove all automation', 'A', 0, 'Inverting the pyramid by shifting tests to lower levels improves speed, reliability, and maintainability.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_235', '235', 'Manual Testing', 'Risk-Based Testing', 'Easy', 'mcq', 'What is risk-based testing?', 'A testing approach that prioritizes testing based on the risk of failure and its impact', 'Testing without a plan', 'Testing only high-risk areas', 'Random testing', 'A', 0, 'Risk-based testing uses risk assessment to guide testing priorities and effort allocation.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_236', '236', 'Manual Testing', 'Risk-Based Testing', 'Easy', 'mcq', 'What two factors are typically used to assess risk?', 'Likelihood of failure and impact of failure', 'Cost and schedule', 'Team size and skill', 'Number of test cases and defects', 'A', 0, 'Risk is typically assessed as the product of the likelihood of failure and its potential impact.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_237', '237', 'Manual Testing', 'Risk-Based Testing', 'Easy', 'mcq', 'Why is risk-based testing important when time is limited?', 'It ensures the most critical areas are tested first', 'It eliminates the need for test cases', 'It makes testing faster', 'It reduces the number of testers needed', 'A', 0, 'Risk-based testing prioritizes effort on high-risk areas, maximizing value when time is constrained.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_238', '238', 'Manual Testing', 'Risk-Based Testing', 'Easy', 'mcq', 'Who should be involved in identifying risks for testing?', 'Cross-functional stakeholders including testers, developers, business analysts, and product owners', 'Only testers', 'Only managers', 'Only developers', 'A', 0, 'Risk identification benefits from diverse perspectives across the team and stakeholders.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_239', '239', 'Manual Testing', 'Risk-Based Testing', 'Easy', 'mcq', 'What is a risk matrix in testing?', 'A grid that maps likelihood and impact to categorize risks as high, medium, or low', 'A test case template', 'A defect report format', 'A project schedule', 'A', 0, 'A risk matrix visually categorizes risks by plotting likelihood against impact.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_240', '240', 'Manual Testing', 'Risk-Based Testing', 'Easy', 'mcq', 'What happens to low-risk items in risk-based testing?', 'They receive less testing effort and may use lighter testing techniques', 'They are never tested', 'They get the most testing', 'They are tested first', 'A', 0, 'Low-risk items receive proportionally less effort, possibly using simplified or sampling-based testing.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_241', '241', 'Manual Testing', 'Risk-Based Testing', 'Medium', 'mcq', 'How does risk-based testing influence test case prioritization?', 'High-risk areas are tested first with more thorough test cases', 'All test cases have equal priority', 'Low-risk areas are tested first', 'Priority is random', 'A', 0, 'Risk-based prioritization ensures high-risk functionality is tested first and most thoroughly.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_242', '242', 'Manual Testing', 'Risk-Based Testing', 'Medium', 'mcq', 'What is a product risk versus a project risk?', 'Product risk affects software quality; project risk affects project success (schedule, budget)', 'They are the same', 'Product risk is about hardware', 'Project risk is about testing only', 'A', 0, 'Product risks relate to quality of the deliverable; project risks relate to management of the project.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_243', '243', 'Manual Testing', 'Risk-Based Testing', 'Medium', 'mcq', 'How should risk assessment be maintained throughout the project?', 'Continuously updated as new information, changes, and defect patterns emerge', 'Done once at project start and never revisited', 'Only at project end', 'Only during test planning', 'A', 0, 'Risk assessment is a living activity that should be updated as the project evolves.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_244', '244', 'Manual Testing', 'Risk-Based Testing', 'Medium', 'mcq', 'What is the relationship between risk-based testing and test coverage?', 'Higher-risk areas receive deeper coverage while lower-risk areas get lighter coverage', 'All areas get equal coverage', 'Coverage is not related to risk', 'Only high-risk areas are tested', 'A', 0, 'Risk-based testing allocates coverage proportionally to risk levels across the application.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_245', '245', 'Manual Testing', 'Risk-Based Testing', 'Medium', 'mcq', 'How can historical defect data be used in risk-based testing?', 'Areas with more historical defects are considered higher risk and receive more testing attention', 'Historical data is irrelevant', 'Only new features are risky', 'Data is used only for reporting', 'A', 0, 'Historical defect data helps predict where future defects are likely, guiding risk assessment.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_246', '246', 'Manual Testing', 'Risk-Based Testing', 'Medium', 'mcq', 'What is risk mitigation in the context of testing?', 'Actions taken to reduce the likelihood or impact of identified risks', 'Ignoring risks', 'Accepting all risks', 'Transferring all testing to developers', 'A', 0, 'Risk mitigation involves deliberate actions to reduce either the probability or impact of risks.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_247', '247', 'Manual Testing', 'Risk-Based Testing', 'Medium', 'mcq', 'How does complexity of a module affect its risk assessment?', 'Higher complexity increases the likelihood of defects, raising the risk level', 'Complexity has no impact', 'Simple modules are riskier', 'Complexity only affects performance', 'A', 0, 'Complex modules have more potential for defects, increasing their risk level in assessment.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_248', '248', 'Manual Testing', 'Risk-Based Testing', 'Medium', 'mcq', 'What role does business criticality play in risk-based testing?', 'Features critical to business operations receive higher risk ratings and more testing', 'All features are equally critical', 'Business criticality is not relevant', 'Only technical factors matter', 'A', 0, 'Business-critical features have higher impact potential, warranting more thorough testing.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_249', '249', 'Manual Testing', 'Risk-Based Testing', 'Hard', 'mcq', 'How does PRISMA (Product Risk Management) approach risk-based testing?', 'It uses a systematic process of risk identification, assessment, and mitigation mapped to test activities', 'It only focuses on performance risks', 'It ignores business risks', 'It is a code review technique', 'A', 0, 'PRISMA provides a structured framework linking risk management activities directly to testing efforts.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_250', '250', 'Manual Testing', 'Risk-Based Testing', 'Hard', 'mcq', 'What is residual risk in testing and how should it be communicated?', 'Risk remaining after testing is complete; communicated through test summary reports to stakeholders', 'Risk that does not exist', 'Risk only in production', 'Risk in the test plan', 'A', 0, 'Residual risk represents untested or undertested areas and must be transparently communicated to stakeholders.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_251', '251', 'Manual Testing', 'Risk-Based Testing', 'Hard', 'mcq', 'How should risk-based testing adapt when a critical defect is found in a low-risk area?', 'Re-evaluate the risk assessment for that area and increase testing coverage', 'Ignore it since the area is low risk', 'Keep the same risk level', 'Stop testing other areas', 'A', 0, 'Finding critical defects in low-risk areas signals that the risk assessment needs revision.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_252', '252', 'Manual Testing', 'Risk-Based Testing', 'Hard', 'mcq', 'What is the challenge of quantifying risk in software testing?', 'Risk assessment often involves subjective judgment that can be biased or inconsistent', 'Risk is always perfectly measurable', 'There are no challenges', 'Only developers can assess risk', 'A', 0, 'Risk quantification in testing is inherently subjective and can vary between assessors and contexts.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_253', '253', 'Manual Testing', 'Risk-Based Testing', 'Hard', 'mcq', 'How does the failure mode and effects analysis (FMEA) technique apply to risk-based testing?', 'FMEA systematically identifies potential failure modes, their causes, and effects to prioritize testing', 'FMEA is a coding technique', 'FMEA replaces all test planning', 'FMEA is only for hardware', 'A', 0, 'FMEA evaluates potential failures by severity, occurrence, and detection to compute risk priority numbers.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_254', '254', 'Manual Testing', 'Risk-Based Testing', 'Hard', 'mcq', 'In a risk-based testing approach, how should newly added features in a late sprint be handled?', 'Perform rapid risk assessment and allocate proportional testing effort based on criticality', 'Skip testing for new features', 'Test only existing features', 'Delay the release indefinitely', 'A', 0, 'Late additions need rapid risk assessment to determine appropriate testing depth within time constraints.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_255', '255', 'Manual Testing', 'Risk-Based Testing', 'Easy', 'scenario', 'A project has limited testing time. The payment module is critical to business while the about page is informational. Where should testing effort be focused?', 'Payment module since it has higher business risk and impact', 'About page', 'Equal time on both', 'Neither', 'A', 0, 'The payment module''s critical business impact warrants prioritized testing effort.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_256', '256', 'Manual Testing', 'Risk-Based Testing', 'Easy', 'scenario', 'A QA lead is creating a risk assessment and needs to decide which module to test first: a simple, well-tested module or a complex, newly developed module. Which should be tested first?', 'The complex, newly developed module due to higher risk of defects', 'The simple module', 'Neither', 'Both equally', 'A', 0, 'New, complex modules have higher defect risk and should be prioritized in testing.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_257', '257', 'Manual Testing', 'Risk-Based Testing', 'Easy', 'scenario', 'Stakeholders want to know why certain features received more testing than others. What document justifies this?', 'Risk Assessment document showing the basis for testing prioritization', 'The source code', 'The user manual', 'The deployment guide', 'A', 0, 'The risk assessment documents why certain areas received more testing based on risk analysis.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_258', '258', 'Manual Testing', 'Risk-Based Testing', 'Easy', 'scenario', 'A team identifies that the login module has had 15 defects in the last 3 releases while the dashboard had 2. How does this affect risk-based test planning?', 'The login module should receive higher risk rating and more testing attention', 'Both get equal testing', 'Dashboard gets more testing', 'Stop testing login', 'A', 0, 'Historical defect data indicates higher risk for the login module, warranting increased testing focus.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_259', '259', 'Manual Testing', 'Risk-Based Testing', 'Medium', 'scenario', 'A risk assessment identifies 50 risks. The team can only address 20 with current capacity. How should they decide which 20 to focus on?', 'Rank risks by risk score (likelihood x impact) and address the top 20', 'Randomly select 20', 'Address the easiest 20', 'Address the newest 20', 'A', 0, 'Prioritizing by risk score ensures the highest-impact risks are addressed first.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_260', '260', 'Manual Testing', 'Risk-Based Testing', 'Medium', 'scenario', 'Midway through testing, a new regulatory requirement is discovered that affects the authentication module. How should risk-based testing adapt?', 'Re-assess risk for authentication module, increase its priority, and allocate additional testing effort', 'Ignore the new requirement', 'Continue with the original plan', 'Skip authentication testing', 'A', 0, 'Regulatory requirements increase risk and require re-assessment and additional focused testing.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_261', '261', 'Manual Testing', 'Risk-Based Testing', 'Medium', 'scenario', 'A test manager must present the testing strategy to stakeholders with limited technical knowledge. How should risk-based testing decisions be communicated?', 'Use a visual risk matrix and explain decisions in terms of business impact and likelihood', 'Use technical jargon', 'Show only test case counts', 'Do not communicate testing strategy', 'A', 0, 'Visual risk matrices with business-focused language effectively communicate risk-based decisions to stakeholders.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_262', '262', 'Manual Testing', 'Risk-Based Testing', 'Medium', 'scenario', 'The development team made significant changes to the database layer. The QA team has not updated their risk assessment. What is the potential consequence?', 'Testing may miss critical defects in the changed database layer due to outdated risk priorities', 'No consequence', 'Testing improves automatically', 'The database is not affected', 'A', 0, 'Failing to update risk assessment after major changes can leave high-risk areas undertested.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_263', '263', 'Manual Testing', 'Risk-Based Testing', 'Medium', 'scenario', 'Two modules have the same risk score but only one can be tested thoroughly. Module A is used by all users daily; Module B is used by admins monthly. Which should be prioritized?', 'Module A because its higher usage frequency increases the likelihood and impact of defects affecting users', 'Module B', 'Neither', 'Both equally', 'A', 0, 'Higher usage frequency increases both the likelihood of encountering defects and the number of affected users.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_264', '264', 'Manual Testing', 'Risk-Based Testing', 'Hard', 'scenario', 'An organization is implementing risk-based testing across 5 product lines. Each product has different risk profiles and stakeholders. How should the approach be standardized?', 'Create an organizational risk framework with customizable risk categories while allowing product-specific risk assessments', 'Use the same risk assessment for all products', 'Let each team work independently', 'Skip standardization', 'A', 0, 'A common framework with product-specific customization balances consistency with relevance.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_265', '265', 'Manual Testing', 'Risk-Based Testing', 'Hard', 'scenario', 'During risk-based testing of a trading platform, the QA team discovers that low-risk market data display features have critical timing dependencies with high-risk order execution features. How should the risk assessment change?', 'Increase risk for market data display features due to their coupling with critical order execution', 'Keep risk ratings unchanged', 'Decrease risk for order execution', 'Remove market data from testing', 'A', 0, 'Dependencies with critical features increase the effective risk of seemingly low-risk components.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_266', '266', 'Manual Testing', 'Risk-Based Testing', 'Hard', 'scenario', 'A QA manager needs to justify to the CTO that risk-based testing improved quality. What metrics would demonstrate this?', 'Reduced defect leakage to production in high-risk areas, improved DRE, and correlation of defect finds with risk levels', 'Number of test cases written', 'Team size', 'Testing tool costs', 'A', 0, 'Metrics showing reduced production defects in prioritized areas and improved DRE demonstrate risk-based testing effectiveness.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_267', '267', 'Manual Testing', 'Risk-Based Testing', 'Hard', 'scenario', 'A product has both a web and mobile frontend sharing a common API. The risk assessment was done for web only. Mobile launches next month. How should the risk assessment be extended?', 'Conduct mobile-specific risk assessment including device fragmentation, OS versions, and mobile-specific interactions while inheriting API risk ratings', 'Reuse web assessment as-is', 'Skip mobile risk assessment', 'Test mobile only after production issues', 'A', 0, 'Mobile introduces unique risks that require specific assessment while shared API risks can be inherited.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_268', '268', 'Manual Testing', 'Test Documentation', 'Easy', 'mcq', 'What is a test case document?', 'A document containing test case ID, steps, expected results, and actual results', 'A project charter', 'A code file', 'A deployment script', 'A', 0, 'A test case document details the steps, preconditions, input data, and expected outcomes for each test.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_269', '269', 'Manual Testing', 'Test Documentation', 'Easy', 'mcq', 'What is the purpose of a test summary report?', 'To summarize testing activities, results, and overall quality assessment', 'To write code', 'To deploy software', 'To gather requirements', 'A', 0, 'A test summary report provides an overview of testing outcomes and quality evaluation.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_270', '270', 'Manual Testing', 'Test Documentation', 'Easy', 'mcq', 'What should a well-written test case include?', 'Preconditions, test steps, test data, expected results, and postconditions', 'Only the test name', 'Only the expected result', 'Only the test data', 'A', 0, 'Complete test cases include all information needed for consistent execution by any tester.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_271', '271', 'Manual Testing', 'Test Documentation', 'Easy', 'mcq', 'What is a test log?', 'A chronological record of test execution activities and results', 'A defect report', 'A requirements document', 'A design specification', 'A', 0, 'A test log records when tests were run, by whom, and with what results in chronological order.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_272', '272', 'Manual Testing', 'Test Documentation', 'Easy', 'mcq', 'What is the difference between a test plan and a test case?', 'A test plan describes the testing approach; a test case describes specific steps to test a feature', 'They are identical', 'A test case is more strategic', 'A test plan is more detailed', 'A', 0, 'The test plan is strategic (what/how to test); test cases are tactical (specific steps and expected results).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_273', '273', 'Manual Testing', 'Test Documentation', 'Easy', 'mcq', 'Why is test documentation important?', 'It provides traceability, consistency, and knowledge transfer across the team', 'It slows down testing', 'It is only for auditors', 'It has no value', 'A', 0, 'Documentation ensures tests are repeatable, traceable, and knowledge is preserved for the team.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_274', '274', 'Manual Testing', 'Test Documentation', 'Medium', 'mcq', 'What is the IEEE 829 standard for test documentation?', 'A standard defining formats for test plans, test cases, test logs, and test reports', 'A coding standard', 'A hardware specification', 'A network protocol', 'A', 0, 'IEEE 829 standardizes the format and content of software test documentation artifacts.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_275', '275', 'Manual Testing', 'Test Documentation', 'Medium', 'mcq', 'What is the difference between a test procedure and a test case?', 'A test procedure is a detailed sequence of actions for execution; a test case defines what to verify', 'They are identical', 'A test procedure is less detailed', 'A test case includes execution steps only', 'A', 0, 'Test cases define verification points; test procedures detail the step-by-step execution sequence.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_276', '276', 'Manual Testing', 'Test Documentation', 'Medium', 'mcq', 'What is a test data document?', 'A document specifying the data sets needed for test execution', 'A database schema', 'A deployment log', 'A user guide', 'A', 0, 'Test data documents define the specific data inputs, configurations, and states needed for testing.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_277', '277', 'Manual Testing', 'Test Documentation', 'Medium', 'mcq', 'How should test documentation be maintained in Agile environments?', 'Keep it lightweight, living, and integrated with tools like wikis or test management systems', 'Create extensive documents that are never updated', 'Eliminate all documentation', 'Only use Word documents', 'A', 0, 'Agile favors lightweight, continuously updated documentation integrated with team collaboration tools.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_278', '278', 'Manual Testing', 'Test Documentation', 'Medium', 'mcq', 'What is a test incident report?', 'A document reporting any event during testing that requires investigation', 'A performance report', 'A code review document', 'A sprint burndown chart', 'A', 0, 'A test incident report captures unexpected events during testing that need further investigation.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_279', '279', 'Manual Testing', 'Test Documentation', 'Medium', 'mcq', 'What is the purpose of a requirements traceability matrix (RTM) in test documentation?', 'To ensure every requirement has corresponding test cases and vice versa', 'To track project budget', 'To schedule meetings', 'To monitor server performance', 'A', 0, 'The RTM provides bidirectional traceability between requirements and test cases for coverage assurance.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_280', '280', 'Manual Testing', 'Test Documentation', 'Medium', 'mcq', 'What information should a test execution report contain?', 'Test cases executed, pass/fail status, defects found, and environment details', 'Only pass counts', 'Only defect counts', 'Only test case names', 'A', 0, 'Execution reports provide complete status including pass/fail, defects, and environment context.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_281', '281', 'Manual Testing', 'Test Documentation', 'Medium', 'mcq', 'When should test documentation be reviewed and by whom?', 'Reviewed by peers and leads during test case reviews before execution begins', 'Never reviewed', 'Only after project completion', 'Only by the author', 'A', 0, 'Peer and lead reviews catch issues in test documentation before test execution, improving quality.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_282', '282', 'Manual Testing', 'Test Documentation', 'Hard', 'mcq', 'How should test documentation balance thoroughness with efficiency?', 'Document enough for repeatability and auditability without creating overhead that slows testing', 'Maximum detail always', 'No documentation ever', 'Only screenshots', 'A', 0, 'Effective documentation balances being comprehensive enough for reuse while remaining maintainable.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_283', '283', 'Manual Testing', 'Test Documentation', 'Hard', 'mcq', 'What is the risk of over-documenting in testing?', 'Increased maintenance burden, slower testing cycles, and resistance from the team', 'No risk', 'Better quality always', 'Faster testing', 'A', 0, 'Over-documentation creates maintenance overhead, slows testing, and can lead to outdated artifacts.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_284', '284', 'Manual Testing', 'Test Documentation', 'Hard', 'mcq', 'How does test documentation support regulatory compliance audits?', 'By providing evidence of testing activities, traceability, and adherence to standards', 'It does not support compliance', 'Only code supports compliance', 'Only deployment logs matter', 'A', 0, 'Compliance audits require documented evidence of testing activities and traceability to requirements.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_285', '285', 'Manual Testing', 'Test Documentation', 'Hard', 'mcq', 'What challenges arise when maintaining test documentation for a rapidly evolving product?', 'Documentation becomes outdated quickly, requiring continuous updates and version control', 'No challenges', 'Documentation writes itself', 'Changes do not affect documentation', 'A', 0, 'Rapid changes require disciplined documentation maintenance with versioning to stay current.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_286', '286', 'Manual Testing', 'Test Documentation', 'Hard', 'mcq', 'How should test documentation be structured for a large-scale distributed team?', 'Centralized repository with standardized templates, naming conventions, and access controls', 'Individual documents per person', 'No standardization needed', 'Email attachments only', 'A', 0, 'Distributed teams need centralized, standardized documentation with clear organization and access.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_287', '287', 'Manual Testing', 'Test Documentation', 'Hard', 'mcq', 'What is the relationship between test documentation and knowledge management in an organization?', 'Test documentation captures institutional testing knowledge that enables continuity when team members change', 'No relationship', 'Knowledge management replaces testing', 'Documentation is only for current projects', 'A', 0, 'Test documentation serves as organizational memory, enabling knowledge transfer and continuity.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_288', '288', 'Manual Testing', 'Test Documentation', 'Easy', 'scenario', 'A new tester joins the team and needs to understand what has been tested for the current release. Which document should they refer to?', 'Test Execution Report/Test Summary Report', 'Source Code', 'Deployment Guide', 'Marketing Material', 'A', 0, 'Test execution and summary reports show what has been tested, results, and current quality status.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_289', '289', 'Manual Testing', 'Test Documentation', 'Easy', 'scenario', 'A client asks for proof that their specified requirements have been tested. What document demonstrates this?', 'Requirements Traceability Matrix (RTM)', 'Source Code', 'User Manual', 'Project Budget', 'A', 0, 'The RTM maps each requirement to its test cases, providing traceability evidence.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_290', '290', 'Manual Testing', 'Test Documentation', 'Easy', 'scenario', 'A tester is executing a test case but the steps are too vague to follow. What is wrong with the test documentation?', 'The test case lacks sufficient detail in its steps for consistent execution', 'The tester is inexperienced', 'The application is wrong', 'The test plan is missing', 'A', 0, 'Test cases must have clear, detailed steps that any tester can follow consistently.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_291', '291', 'Manual Testing', 'Test Documentation', 'Easy', 'scenario', 'After a release, the team wants to document what went well and what could be improved in testing. What document captures this?', 'Lessons Learned / Test Closure Report', 'Test Plan', 'RTM', 'Defect Report', 'A', 0, 'The lessons learned or test closure report captures retrospective insights for process improvement.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_292', '292', 'Manual Testing', 'Test Documentation', 'Medium', 'scenario', 'An audit reveals that test cases exist but there is no evidence of execution. What documentation gap needs to be addressed?', 'Test execution logs and evidence (screenshots, results) must be captured and stored', 'Write more test cases', 'Delete existing test cases', 'Ignore the audit', 'A', 0, 'Execution evidence including logs and results must be captured to demonstrate testing was performed.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_293', '293', 'Manual Testing', 'Test Documentation', 'Medium', 'scenario', 'A team uses a wiki for test documentation but different testers use different formats. This causes confusion. What should be implemented?', 'Standardized templates for all test documentation types', 'Let everyone use their own format', 'Stop documenting', 'Use only emails', 'A', 0, 'Standardized templates ensure consistency and usability across the team''s documentation.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_294', '294', 'Manual Testing', 'Test Documentation', 'Medium', 'scenario', 'Test cases written two years ago are still being used but the application has changed significantly. Many test cases fail due to outdated expected results. What maintenance practice is needed?', 'Regular review and update of test cases to align with current application behavior', 'Delete all old test cases', 'Ignore the failures', 'Write entirely new test cases from scratch each time', 'A', 0, 'Test case maintenance through regular reviews ensures documentation stays aligned with the application.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_295', '295', 'Manual Testing', 'Test Documentation', 'Medium', 'scenario', 'A project requires ISO 9001 compliance. The QA lead needs to ensure test documentation meets the standard. What key requirement must be addressed?', 'Document control including version management, review/approval processes, and controlled distribution', 'No special requirements', 'Only verbal approvals', 'Only final reports', 'A', 0, 'ISO 9001 requires formal document control with versioning, approvals, and controlled access.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_296', '296', 'Manual Testing', 'Test Documentation', 'Medium', 'scenario', 'The management wants a weekly status report on testing progress. What key metrics should the test documentation include?', 'Test cases planned vs executed, pass/fail rates, open defects by severity, and risk items', 'Only the number of testers', 'Only the project budget', 'Only meeting notes', 'A', 0, 'Weekly status should include execution progress, pass/fail rates, defect status, and risk highlights.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_297', '297', 'Manual Testing', 'Test Documentation', 'Hard', 'scenario', 'A multinational organization with teams across 5 countries needs a unified test documentation strategy. Teams speak different languages and use different tools. What approach ensures consistency?', 'English as the common documentation language, standardized templates, centralized tool with localized guidelines', 'Each country uses their own language and format', 'No documentation', 'Only the HQ team documents', 'A', 0, 'A common language, standard templates, and centralized tooling with local guidance ensures global consistency.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_298', '298', 'Manual Testing', 'Test Documentation', 'Hard', 'scenario', 'A regulated pharmaceutical company needs to validate its testing documentation process itself. How should this meta-validation be approached?', 'Establish a documentation quality process with periodic audits, peer reviews, and traceability checks of the documentation system', 'No validation of documentation is needed', 'Only validate at project end', 'Only external auditors can validate', 'A', 0, 'Meta-validation requires auditing the documentation process itself for completeness and compliance.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_299', '299', 'Manual Testing', 'Test Documentation', 'Hard', 'scenario', 'A team is transitioning from manual documentation to a test management tool. Legacy data includes 5000 test cases in spreadsheets. What migration strategy is recommended?', 'Prioritize migration of active, high-value test cases first; archive obsolete ones; validate migrated data', 'Migrate everything at once', 'Delete all legacy data', 'Keep using spreadsheets', 'A', 0, 'Phased migration of high-value test cases with validation ensures quality while managing the transition.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_300', '300', 'Manual Testing', 'Test Documentation', 'Hard', 'scenario', 'During a compliance audit, the auditor finds gaps between documented test procedures and actual test execution. The team insists they tested correctly but did not follow the exact documented steps. What is the root cause and solution?', 'Documentation and practice are out of sync; implement periodic alignment reviews and empower testers to update procedures', 'The documentation is wrong', 'The testing is wrong', 'There is no issue', 'A', 0, 'Misalignment between documentation and practice requires regular synchronization and empowered updates.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_301', '301', 'Manual Testing', 'Estimation', 'Easy', 'mcq', 'What is test estimation?', 'The process of predicting the effort, time, and resources needed for testing activities', 'Counting lines of code', 'Measuring server speed', 'Calculating project revenue', 'A', 0, 'Test estimation predicts the resources and time needed to complete testing activities.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_302', '302', 'Manual Testing', 'Estimation', 'Easy', 'mcq', 'Which is a common technique for test effort estimation?', 'Work Breakdown Structure (WBS)', 'Code review', 'Deployment planning', 'Marketing analysis', 'A', 0, 'WBS breaks testing into smaller tasks to estimate effort for each, summing up to total effort.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_303', '303', 'Manual Testing', 'Estimation', 'Easy', 'mcq', 'What factor most affects test effort estimation?', 'Complexity and size of the application under test', 'The color of the UI', 'The company logo', 'The office location', 'A', 0, 'Application complexity and size directly influence the testing effort required.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_304', '304', 'Manual Testing', 'Estimation', 'Easy', 'mcq', 'What is expert judgment in test estimation?', 'Relying on experienced testers'' knowledge to estimate effort', 'Using only mathematical formulas', 'Randomly guessing', 'Copying estimates from other projects', 'A', 0, 'Expert judgment leverages the experience of seasoned testers to predict effort requirements.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_305', '305', 'Manual Testing', 'Estimation', 'Easy', 'mcq', 'Why is accurate test estimation important?', 'It helps plan resources, budget, and schedule realistically', 'It eliminates all defects', 'It speeds up development', 'It reduces team size', 'A', 0, 'Accurate estimation ensures realistic planning of resources, time, and budget for testing.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_306', '306', 'Manual Testing', 'Estimation', 'Easy', 'mcq', 'What is a common unit for measuring test effort?', 'Person-hours or person-days', 'Lines of code', 'Number of servers', 'Number of meetings', 'A', 0, 'Test effort is typically measured in person-hours or person-days of tester time.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_307', '307', 'Manual Testing', 'Estimation', 'Medium', 'mcq', 'What is the three-point estimation technique?', 'Using optimistic, most likely, and pessimistic estimates to calculate expected effort', 'Three people estimate independently', 'Estimating in three minutes', 'Using three test cases', 'A', 0, 'Three-point estimation uses best, expected, and worst case values to compute a weighted average.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_308', '308', 'Manual Testing', 'Estimation', 'Medium', 'mcq', 'How does the Delphi technique work for test estimation?', 'Experts estimate independently, share anonymously, discuss, and iterate until consensus', 'One person decides for all', 'Random number generation', 'Copying from a template', 'A', 0, 'Delphi uses iterative anonymous expert estimates with discussion to reach consensus.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_309', '309', 'Manual Testing', 'Estimation', 'Medium', 'mcq', 'What is analogous estimation in testing?', 'Estimating based on comparison with similar past projects', 'Using only mathematical models', 'Random estimation', 'Doubling the development estimate', 'A', 0, 'Analogous estimation uses data from comparable past projects as a baseline for the current estimate.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_310', '310', 'Manual Testing', 'Estimation', 'Medium', 'mcq', 'What is the testing percentage of overall project effort typically?', 'Varies but commonly ranges from 25% to 50% of total project effort', 'Always 10%', 'Always 90%', 'Testing takes no effort', 'A', 0, 'Testing typically consumes 25-50% of project effort depending on complexity and quality requirements.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_311', '311', 'Manual Testing', 'Estimation', 'Medium', 'mcq', 'How should test estimation account for rework and defect retesting?', 'Include a buffer or factor for expected rework based on historical defect rates', 'Ignore rework', 'Assume no defects will be found', 'Only estimate initial testing', 'A', 0, 'Realistic estimates include rework time based on expected defect rates from similar projects.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_312', '312', 'Manual Testing', 'Estimation', 'Medium', 'mcq', 'What is the Use Case Point method for test estimation?', 'Estimating effort based on the complexity and number of use cases', 'Counting lines of code', 'Measuring screen resolution', 'Counting team members', 'A', 0, 'Use Case Points weight use cases by complexity to estimate the testing effort required.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_313', '313', 'Manual Testing', 'Estimation', 'Medium', 'mcq', 'How does team experience level affect test estimation?', 'Less experienced teams typically need more time; estimates should factor in skill levels', 'Experience has no impact', 'Experienced teams always take longer', 'Skill level is not relevant', 'A', 0, 'Team experience significantly impacts productivity; less experienced teams need adjusted estimates.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_314', '314', 'Manual Testing', 'Estimation', 'Medium', 'mcq', 'What is the role of test estimation in risk management?', 'Identifying when estimates are uncertain helps highlight areas that may need contingency planning', 'No role', 'Risk and estimation are unrelated', 'Estimation eliminates risk', 'A', 0, 'Uncertainty in estimates signals areas needing contingency planning and risk mitigation.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_315', '315', 'Manual Testing', 'Estimation', 'Hard', 'mcq', 'What is function point analysis in the context of test estimation?', 'Measuring software size by counting functional user interactions to derive test effort', 'Counting functions in code', 'Measuring function execution time', 'Counting team functions', 'A', 0, 'Function point analysis measures software size based on user-visible functions to estimate testing effort.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_316', '316', 'Manual Testing', 'Estimation', 'Hard', 'mcq', 'How should test estimation handle the uncertainty of requirements in Agile projects?', 'Use relative estimation with story points and adjust based on velocity and emerging requirements', 'Provide exact estimates upfront', 'Do not estimate in Agile', 'Estimate only at project end', 'A', 0, 'Agile uses relative estimation and velocity to adapt estimates as requirements evolve.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_317', '317', 'Manual Testing', 'Estimation', 'Hard', 'mcq', 'What is estimation bias and how can it be mitigated?', 'Systematic tendency to over/under estimate; mitigated through calibration, historical data, and multiple estimators', 'Bias does not exist in estimation', 'Always overestimate to be safe', 'Use only one estimator', 'A', 0, 'Estimation bias is mitigated through calibration against actuals, data analysis, and multiple perspectives.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_318', '318', 'Manual Testing', 'Estimation', 'Hard', 'mcq', 'How does the cone of uncertainty affect test estimation over the project lifecycle?', 'Estimates are less accurate early and become more precise as the project progresses and unknowns reduce', 'Estimates are always accurate', 'Uncertainty increases over time', 'Estimation accuracy does not change', 'A', 0, 'The cone of uncertainty narrows as project knowledge increases, improving estimate accuracy over time.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_319', '319', 'Manual Testing', 'Estimation', 'Hard', 'mcq', 'What is Monte Carlo simulation in test estimation?', 'A probabilistic method that runs thousands of simulations to estimate likely effort ranges and confidence levels', 'A card game estimation technique', 'A single-point estimate', 'A type of test case', 'A', 0, 'Monte Carlo simulation uses probability distributions to model estimation uncertainty and provide confidence ranges.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_320', '320', 'Manual Testing', 'Estimation', 'Hard', 'mcq', 'How should test estimation account for test environment setup and configuration time?', 'Include explicit line items for environment setup, data preparation, and tool configuration in the estimate', 'Ignore environment time', 'Assume instant setup', 'Environment time is zero', 'A', 0, 'Environment setup can be significant and must be explicitly estimated as part of total testing effort.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_321', '321', 'Manual Testing', 'Estimation', 'Easy', 'scenario', 'A project manager asks the QA lead how long testing will take. The QA lead has no information about the project scope. What should they do first?', 'Request the requirements or scope document before providing an estimate', 'Guess a random number', 'Say two weeks', 'Refuse to estimate', 'A', 0, 'Estimation requires understanding scope; the QA lead needs requirements before estimating.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_322', '322', 'Manual Testing', 'Estimation', 'Easy', 'scenario', 'A test team estimated 100 hours for testing but actual effort was 150 hours. What should they do for future projects?', 'Analyze why the estimate was off and use the actual data to calibrate future estimates', 'Use 100 hours again', 'Never estimate again', 'Double all future estimates', 'A', 0, 'Retrospective analysis of estimation accuracy helps calibrate and improve future estimates.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_323', '323', 'Manual Testing', 'Estimation', 'Easy', 'scenario', 'A QA lead needs to estimate testing for a simple CRUD application with 10 screens. A similar project last year took 80 hours. What estimation technique is being used?', 'Analogous Estimation', 'Delphi Technique', 'Monte Carlo Simulation', 'Function Point Analysis', 'A', 0, 'Using a past similar project as a reference is analogous estimation.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_324', '324', 'Manual Testing', 'Estimation', 'Easy', 'scenario', 'A stakeholder pressures the QA lead to reduce the testing estimate by 50%. What should the QA lead do?', 'Explain the risks of reduced testing and propose a risk-based approach to work within constraints', 'Agree immediately', 'Refuse to negotiate', 'Quit the project', 'A', 0, 'The QA lead should communicate risks transparently and propose alternatives like risk-based prioritization.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_325', '325', 'Manual Testing', 'Estimation', 'Medium', 'scenario', 'A project has 200 test cases. Historical data shows each test case takes an average of 30 minutes to execute including documentation. What is the estimated execution time?', '100 hours (200 x 30 minutes)', '200 hours', '50 hours', '30 hours', 'A', 0, '200 test cases at 30 minutes each equals 100 hours of test execution effort.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_326', '326', 'Manual Testing', 'Estimation', 'Medium', 'scenario', 'Three experts estimate a testing task: Expert A says 40 hours (optimistic), Expert B says 60 hours (most likely), Expert C says 100 hours (pessimistic). Using PERT, what is the estimate?', '63.3 hours using the formula (O + 4M + P) / 6', '40 hours', '100 hours', '200 hours', 'A', 0, 'PERT formula: (40 + 4*60 + 100) / 6 = (40 + 240 + 100) / 6 = 380/6 = 63.3 hours.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_327', '327', 'Manual Testing', 'Estimation', 'Medium', 'scenario', 'A team is estimating for a project with new technology they have never used before. What adjustment should they make to their baseline estimate?', 'Add a learning curve buffer typically 25-50% extra for the first project with new technology', 'No adjustment needed', 'Reduce the estimate', 'Use the same estimate as familiar technology', 'A', 0, 'New technology introduces a learning curve that should be accounted for with an additional buffer.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_328', '328', 'Manual Testing', 'Estimation', 'Medium', 'scenario', 'Midway through the project, 5 new features are added but the testing timeline is not extended. How should the QA lead respond?', 'Re-estimate with new features, communicate the impact, and propose either timeline extension or risk-based scope reduction', 'Absorb the extra work silently', 'Skip testing the new features', 'Reduce testing on all features equally', 'A', 0, 'Scope changes require re-estimation and transparent communication about impacts on timeline or coverage.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_329', '329', 'Manual Testing', 'Estimation', 'Medium', 'scenario', 'A QA manager wants to track estimation accuracy over time. What metric should they use?', 'Estimation Accuracy = (Actual Effort / Estimated Effort) x 100%, tracked over multiple projects', 'Number of test cases', 'Team size', 'Number of defects', 'A', 0, 'Tracking the ratio of actual to estimated effort over time reveals estimation trends and improvement.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_330', '330', 'Manual Testing', 'Estimation', 'Medium', 'scenario', 'A team uses story points for estimation in Agile. Their velocity is 40 points per sprint. The remaining backlog is 120 points of testing-related stories. How many sprints are needed?', '3 sprints (120 / 40)', '1 sprint', '10 sprints', 'Cannot be determined', 'A', 0, 'At a velocity of 40 points per sprint, 120 points requires 3 sprints.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_331', '331', 'Manual Testing', 'Estimation', 'Hard', 'scenario', 'A large enterprise project requires estimating testing effort for 500 requirements across 8 modules. Different modules have different complexity levels. What estimation approach provides the best accuracy?', 'Bottom-up estimation using WBS per module with complexity-weighted effort per requirement type', 'Top-down single estimate', 'Expert guess', 'Fixed percentage of development time', 'A', 0, 'Bottom-up WBS with complexity weighting provides granular, accurate estimates for large diverse projects.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_332', '332', 'Manual Testing', 'Estimation', 'Hard', 'scenario', 'Historical data shows that the team''s estimates are consistently 30% lower than actual effort. The team uses expert judgment exclusively. What process improvement would help?', 'Calibrate estimates using historical actual-vs-estimated data and introduce structured techniques like three-point estimation', 'Continue with expert judgment only', 'Hire new experts', 'Stop estimating', 'A', 0, 'Calibrating with historical data and adding structured techniques corrects systematic underestimation.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_333', '333', 'Manual Testing', 'Estimation', 'Hard', 'scenario', 'A test manager needs to provide a confidence interval for the testing estimate to the steering committee. The optimistic estimate is 400 hours, most likely 600 hours, pessimistic 1000 hours. What should they present?', 'Present PERT estimate of ~633 hours with standard deviation of 100 hours and confidence ranges', 'Present only the optimistic 400 hours', 'Present 1000 hours to be safe', 'Present no estimate', 'A', 0, 'PERT with standard deviation (P-O)/6 = 100 hours provides meaningful confidence ranges for stakeholders.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_334', '334', 'Manual Testing', 'Estimation', 'Hard', 'scenario', 'An organization wants to build an estimation model specific to their testing process. They have 3 years of project data. What approach should they take?', 'Analyze historical data to identify key effort drivers, build a regression model, validate with recent projects, and refine iteratively', 'Use a generic industry model', 'Guess based on team size', 'No model is needed', 'A', 0, 'Custom estimation models built from organizational data and refined iteratively provide the most accurate predictions.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_335', '335', 'Manual Testing', 'Test Metrics', 'Easy', 'mcq', 'What is a test metric?', 'A quantitative measure used to assess the quality and progress of testing activities', 'A type of test case', 'A defect category', 'A project milestone', 'A', 0, 'Test metrics are measurements that quantify testing activities, progress, and quality.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_336', '336', 'Manual Testing', 'Test Metrics', 'Easy', 'mcq', 'What does the ''test execution rate'' metric measure?', 'The number of test cases executed over a given time period', 'The number of defects found', 'The cost of testing', 'The team size', 'A', 0, 'Test execution rate tracks how many test cases have been run in a given timeframe.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_337', '337', 'Manual Testing', 'Test Metrics', 'Easy', 'mcq', 'What is the ''pass rate'' metric?', 'The percentage of test cases that passed out of total executed', 'The number of testers', 'The project budget', 'The code size', 'A', 0, 'Pass rate = (Passed test cases / Total executed test cases) x 100%.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_338', '338', 'Manual Testing', 'Test Metrics', 'Easy', 'mcq', 'What does ''defect density'' measure?', 'The number of defects per unit size of software (e.g., per KLOC or per function point)', 'The total number of defects', 'The speed of testing', 'The team productivity', 'A', 0, 'Defect density normalizes defect counts by software size to enable meaningful comparisons.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_339', '339', 'Manual Testing', 'Test Metrics', 'Easy', 'mcq', 'Why are test metrics important?', 'They provide objective data for decision-making about quality and testing progress', 'They replace testing', 'They are only for management reports', 'They have no practical value', 'A', 0, 'Metrics provide objective evidence for quality decisions, progress tracking, and process improvement.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_340', '340', 'Manual Testing', 'Test Metrics', 'Easy', 'mcq', 'What is ''requirement coverage'' in testing?', 'The percentage of requirements that have at least one associated test case', 'The number of requirements written', 'The number of code lines covered', 'The project completion percentage', 'A', 0, 'Requirement coverage measures what percentage of requirements are addressed by test cases.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_341', '341', 'Manual Testing', 'Test Metrics', 'Medium', 'mcq', 'What is the difference between test metrics and test KPIs?', 'Metrics are measurements; KPIs are key metrics tied to specific goals and targets', 'They are identical', 'KPIs are less important', 'Metrics are not used in reporting', 'A', 0, 'KPIs are a subset of metrics specifically selected to measure performance against goals.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_342', '342', 'Manual Testing', 'Test Metrics', 'Medium', 'mcq', 'What does the ''defect rejection rate'' indicate?', 'The percentage of reported defects that are invalid or rejected after review', 'The number of defects fixed', 'The team velocity', 'The code quality', 'A', 0, 'A high rejection rate may indicate misunderstanding of requirements or poor defect reporting quality.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_343', '343', 'Manual Testing', 'Test Metrics', 'Medium', 'mcq', 'What is the ''defect fix rate'' metric?', 'The number of defects fixed per time period by the development team', 'The number of defects found', 'The testing speed', 'The deployment frequency', 'A', 0, 'Defect fix rate measures development''s throughput in resolving reported defects.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_344', '344', 'Manual Testing', 'Test Metrics', 'Medium', 'mcq', 'How is the ''test case effectiveness'' metric calculated?', 'Number of defects detected divided by the number of test cases executed', 'Number of test cases written', 'Team size multiplied by hours', 'Project cost divided by defects', 'A', 0, 'Test case effectiveness measures the defect-finding yield of the test suite.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_345', '345', 'Manual Testing', 'Test Metrics', 'Medium', 'mcq', 'What does a defect arrival curve show?', 'The rate at which new defects are discovered over time during testing', 'The number of testers over time', 'Server uptime', 'Code commit frequency', 'A', 0, 'A defect arrival curve plots new defect discoveries over time to show testing progress and quality trends.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_346', '346', 'Manual Testing', 'Test Metrics', 'Medium', 'mcq', 'What is the purpose of tracking test case creation progress?', 'To ensure test cases are being developed on schedule to meet execution timelines', 'To count lines of code', 'To measure server load', 'To track deployment frequency', 'A', 0, 'Tracking creation progress ensures the test suite is ready for execution as scheduled.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_347', '347', 'Manual Testing', 'Test Metrics', 'Medium', 'mcq', 'What does the ''defect reopened rate'' metric indicate?', 'The percentage of defects that are reopened after being marked as fixed', 'The number of new defects', 'The team size', 'The project duration', 'A', 0, 'A high reopen rate indicates poor fix quality or inadequate fix verification.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_348', '348', 'Manual Testing', 'Test Metrics', 'Medium', 'mcq', 'How can test metrics be misused?', 'By using them to evaluate individual tester performance or setting targets that incentivize wrong behavior', 'Metrics cannot be misused', 'By collecting too few metrics', 'By sharing them with stakeholders', 'A', 0, 'Using metrics punitively or setting perverse targets can lead to gaming and counterproductive behavior.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_349', '349', 'Manual Testing', 'Test Metrics', 'Hard', 'mcq', 'What is the ''escaped defect rate'' and why is it critical?', 'Defects found in production divided by total defects; it measures testing effectiveness at preventing production issues', 'The rate testers leave the company', 'Server escape velocity', 'Code deployment speed', 'A', 0, 'Escaped defect rate directly measures how effective testing was at catching defects before production.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_350', '350', 'Manual Testing', 'Test Metrics', 'Hard', 'mcq', 'How does measuring ''cost of quality'' help in testing decisions?', 'It quantifies prevention, appraisal, internal and external failure costs to optimize quality investment', 'It only measures testing tool costs', 'It is not relevant to testing', 'It measures only defect costs', 'A', 0, 'Cost of quality analysis helps balance investment in prevention and detection vs failure costs.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_351', '351', 'Manual Testing', 'Test Metrics', 'Hard', 'mcq', 'What is Orthogonal Defect Classification (ODC) and how does it enhance metrics?', 'A scheme classifying defects by attributes like type, trigger, and impact for deeper causal analysis', 'A way to sort defects alphabetically', 'A test execution technique', 'A project management method', 'A', 0, 'ODC provides structured defect classification enabling root cause analysis beyond simple counts.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_352', '352', 'Manual Testing', 'Test Metrics', 'Hard', 'mcq', 'How should metrics be used in a test process improvement initiative?', 'As baseline measurements to identify improvement areas and track progress after changes are implemented', 'Only for annual reports', 'To punish low performers', 'To increase budget', 'A', 0, 'Metrics provide the objective baseline and progress tracking needed for meaningful process improvement.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_353', '353', 'Manual Testing', 'Test Metrics', 'Hard', 'mcq', 'What is the significance of tracking ''test automation ROI'' as a metric?', 'It measures whether the investment in automation is generating positive returns through reduced effort and faster feedback', 'Automation always has positive ROI', 'ROI is not measurable', 'Only manual testing has ROI', 'A', 0, 'Tracking automation ROI ensures the investment is justified by reduced effort, faster cycles, or better coverage.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_354', '354', 'Manual Testing', 'Test Metrics', 'Hard', 'mcq', 'What is a balanced scorecard approach to test metrics?', 'Using a mix of metrics across dimensions like effectiveness, efficiency, coverage, and satisfaction', 'Using only one metric', 'Measuring only pass rates', 'Tracking only defect counts', 'A', 0, 'A balanced scorecard ensures multiple quality dimensions are measured to avoid optimizing one at the expense of others.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_355', '355', 'Manual Testing', 'Test Metrics', 'Easy', 'scenario', 'A manager asks: ''How much of the testing is done?'' What metric provides the best answer?', 'Test execution progress: percentage of planned test cases executed', 'Lines of code written', 'Number of meetings held', 'Team headcount', 'A', 0, 'Test execution progress as a percentage directly answers how much of the planned testing is complete.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_356', '356', 'Manual Testing', 'Test Metrics', 'Easy', 'scenario', 'A team executed 80 test cases and 60 passed. What is the pass rate?', '75% (60/80 x 100)', '80%', '60%', '100%', 'A', 0, 'Pass rate = 60 passed / 80 executed = 75%.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_357', '357', 'Manual Testing', 'Test Metrics', 'Easy', 'scenario', 'The QA lead needs to report how many defects were found per module. What metric is this?', 'Defect distribution by module', 'Test execution rate', 'Pass rate', 'Requirement coverage', 'A', 0, 'Defect distribution by module shows where defects are concentrated across the application.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_358', '358', 'Manual Testing', 'Test Metrics', 'Easy', 'scenario', 'A stakeholder wants to know if all requirements have been tested. Which metric addresses this?', 'Requirement coverage percentage', 'Defect density', 'Pass rate', 'Test execution time', 'A', 0, 'Requirement coverage shows the percentage of requirements that have associated test cases and results.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_359', '359', 'Manual Testing', 'Test Metrics', 'Medium', 'scenario', 'A defect arrival curve shows new defects declining over the last 3 test cycles. What does this trend suggest?', 'The software is stabilizing and most defects have likely been found', 'More defects are hidden', 'Testing is getting worse', 'The team is not finding defects', 'A', 0, 'A declining defect arrival rate typically indicates the software is stabilizing with fewer remaining defects.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_360', '360', 'Manual Testing', 'Test Metrics', 'Medium', 'scenario', 'The defect rejection rate is 40%. What does this high rate indicate and what action should be taken?', 'Many defects are invalid; improve defect reporting quality through training and clearer requirements', 'This is normal', 'Stop reporting defects', 'Increase defect count targets', 'A', 0, 'A 40% rejection rate suggests misunderstanding of requirements or poor defect report quality needing improvement.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_361', '361', 'Manual Testing', 'Test Metrics', 'Medium', 'scenario', 'A project tracks defect density per module. Module X has 5 defects per KLOC while others have 1 per KLOC. What conclusion can be drawn?', 'Module X likely has quality issues and may need code review, more testing, or refactoring', 'Module X is the best module', 'The metric is wrong', 'All modules are equal', 'A', 0, 'Significantly higher defect density signals quality issues requiring investigation and additional attention.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_362', '362', 'Manual Testing', 'Test Metrics', 'Medium', 'scenario', 'A QA team wants to show that investing in test automation has reduced testing time. What metrics should they compare before and after automation?', 'Test execution time, regression cycle time, defect detection rate, and test coverage', 'Only team size', 'Only tool cost', 'Only number of test cases', 'A', 0, 'Comparing execution time, cycle time, detection rate, and coverage before/after shows automation impact.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_363', '363', 'Manual Testing', 'Test Metrics', 'Medium', 'scenario', 'Management wants a single ''quality score'' for the release. The QA lead must combine multiple metrics. What approach is appropriate?', 'Create a weighted composite score using key metrics like pass rate, defect density, requirement coverage, and severity distribution', 'Use only pass rate', 'Use only defect count', 'Refuse to provide a score', 'A', 0, 'A weighted composite score combining key metrics provides a holistic quality assessment.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_364', '364', 'Manual Testing', 'Test Metrics', 'Hard', 'scenario', 'An organization''s testing metrics show 98% pass rate but high production defect rates. What could explain this contradiction and how should it be investigated?', 'Test cases may not cover critical scenarios; investigate test case quality, coverage gaps, and whether tests reflect real usage', 'The metrics are wrong', 'Production defects are acceptable', 'Stop measuring metrics', 'A', 0, 'High pass rates with high production defects indicate test suite quality and coverage gaps needing analysis.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_365', '365', 'Manual Testing', 'Test Metrics', 'Hard', 'scenario', 'A VP of Engineering wants to benchmark the testing organization against industry standards. What metrics framework should the QA director propose?', 'A balanced set including DRE, defect density, cost of quality, test automation coverage, and cycle time compared with TMM/TMMi maturity levels', 'Only defect counts', 'Only team size', 'No benchmarking is possible', 'A', 0, 'Industry benchmarking requires standardized metrics compared against maturity models like TMMi.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_366', '366', 'Manual Testing', 'Test Metrics', 'Hard', 'scenario', 'A team notices that as they add more test cases, the defect detection rate per test case decreases. What does this diminishing return indicate?', 'The most effective test cases have been created first; new test cases are in lower-risk areas or are less targeted', 'More test cases are always better', 'Stop creating test cases', 'The product has no more defects', 'A', 0, 'Diminishing returns suggest test case optimization is needed to target uncovered risk areas rather than adding volume.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_367', '367', 'Manual Testing', 'Test Metrics', 'Hard', 'scenario', 'A testing organization wants to implement predictive analytics using their testing metrics data collected over 5 years. What types of predictions could be valuable?', 'Predicted defect counts for new releases, estimated testing effort based on change size, and likely areas of defect clustering', 'Only weather predictions', 'No predictions are possible from test data', 'Only budget predictions', 'A', 0, 'Historical test metrics can predict defect volumes, effort needs, and risk areas for future releases.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_368', '368', 'Manual Testing', 'Exploratory Testing', 'Easy', 'mcq', 'What is exploratory testing?', 'Simultaneous test design, execution, and learning where the tester actively explores the application', 'Scripted testing with predefined steps', 'Automated testing', 'Performance testing', 'A', 0, 'Exploratory testing combines learning, test design, and execution in a simultaneous cognitive process.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_369', '369', 'Manual Testing', 'Exploratory Testing', 'Easy', 'mcq', 'How does exploratory testing differ from ad-hoc testing?', 'Exploratory testing is structured with charters and time-boxing while ad-hoc has no structure', 'They are identical', 'Ad-hoc is more structured', 'Exploratory uses automation', 'A', 0, 'Exploratory testing uses charters and session-based management, unlike unstructured ad-hoc testing.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_370', '370', 'Manual Testing', 'Exploratory Testing', 'Easy', 'mcq', 'What is a test charter in exploratory testing?', 'A brief document describing the mission and scope of an exploratory testing session', 'A project charter', 'A test plan', 'A defect report', 'A', 0, 'A test charter guides the tester by defining what to explore, what to look for, and potential risks.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_371', '371', 'Manual Testing', 'Exploratory Testing', 'Easy', 'mcq', 'When is exploratory testing most valuable?', 'When requirements are incomplete or the tester needs to quickly learn about the application', 'Only when formal testing is complete', 'Never', 'Only for performance testing', 'A', 0, 'Exploratory testing excels when documentation is sparse or rapid feedback about the application is needed.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_372', '372', 'Manual Testing', 'Exploratory Testing', 'Easy', 'mcq', 'What skills are most important for exploratory testing?', 'Critical thinking, curiosity, domain knowledge, and observation skills', 'Only coding skills', 'Only documentation skills', 'Only management skills', 'A', 0, 'Effective exploratory testers combine analytical thinking, curiosity, and keen observation.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_373', '373', 'Manual Testing', 'Exploratory Testing', 'Easy', 'mcq', 'Should exploratory testing replace scripted testing?', 'No, they complement each other and should be used together', 'Yes, it replaces all scripted testing', 'Yes, scripted testing is obsolete', 'They cannot be used together', 'A', 0, 'Exploratory and scripted testing are complementary; each addresses different testing needs effectively.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_374', '374', 'Manual Testing', 'Exploratory Testing', 'Medium', 'mcq', 'What is session-based test management (SBTM)?', 'A structured approach to managing exploratory testing using time-boxed sessions with charters and debriefs', 'A project management methodology', 'A type of automated testing', 'A defect tracking system', 'A', 0, 'SBTM brings structure to exploratory testing through sessions, charters, session reports, and debriefs.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_375', '375', 'Manual Testing', 'Exploratory Testing', 'Medium', 'mcq', 'What are the three key elements of a session-based exploratory testing session?', 'Charter (mission), time-box (duration), and session report (findings)', 'Code, test, deploy', 'Plan, execute, close', 'Analyze, design, implement', 'A', 0, 'SBTM sessions are defined by their charter, time-box, and the resulting session report.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_376', '376', 'Manual Testing', 'Exploratory Testing', 'Medium', 'mcq', 'How should exploratory testing findings be documented?', 'Through session notes, screenshots, bug reports, and session debrief summaries', 'No documentation needed', 'Only in memory', 'Only verbally', 'A', 0, 'Documenting findings ensures knowledge is captured and defects are formally tracked.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_377', '377', 'Manual Testing', 'Exploratory Testing', 'Medium', 'mcq', 'What is the role of heuristics in exploratory testing?', 'Heuristics guide testers in identifying potential problem areas and testing strategies', 'Heuristics are test scripts', 'Heuristics replace test plans', 'Heuristics are automated tools', 'A', 0, 'Heuristics are experience-based rules of thumb that guide exploration and defect identification.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_378', '378', 'Manual Testing', 'Exploratory Testing', 'Medium', 'mcq', 'What is the ''touring'' approach in exploratory testing?', 'Using different perspectives (like guidebook, money, landmark tours) to explore the application', 'A geographic testing approach', 'Testing while traveling', 'Only testing navigation', 'A', 0, 'Tours provide structured exploration strategies like testing high-value features or less-visited areas.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_379', '379', 'Manual Testing', 'Exploratory Testing', 'Medium', 'mcq', 'How does exploratory testing fit into Agile sprints?', 'It complements scripted testing by uncovering issues that predefined tests might miss during the sprint', 'It is not used in Agile', 'It replaces all sprint testing', 'It is done only in the last sprint', 'A', 0, 'Exploratory testing in Agile catches unexpected issues and provides rapid feedback within sprints.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_380', '380', 'Manual Testing', 'Exploratory Testing', 'Medium', 'mcq', 'What is a debrief session in SBTM?', 'A review meeting where the tester discusses findings, coverage, and next steps with the test lead', 'A sprint planning meeting', 'A code review', 'A deployment meeting', 'A', 0, 'Debriefs allow the tester and lead to discuss findings, assess coverage, and plan further exploration.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_381', '381', 'Manual Testing', 'Exploratory Testing', 'Medium', 'mcq', 'What percentage of time in an exploratory session should be spent on setup versus actual testing?', 'Minimal setup time; the majority should be active testing and exploration', '50% setup, 50% testing', '90% setup, 10% testing', 'Setup time does not matter', 'A', 0, 'Effective exploratory sessions maximize active testing time with minimal setup overhead.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_382', '382', 'Manual Testing', 'Exploratory Testing', 'Hard', 'mcq', 'How can exploratory testing coverage be measured?', 'Through session metrics including areas explored, time spent per area, and findings mapped to the application model', 'It cannot be measured', 'Only by defect count', 'Only by time spent', 'A', 0, 'Coverage is measured by mapping explored areas against an application model and tracking session metrics.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_383', '383', 'Manual Testing', 'Exploratory Testing', 'Hard', 'mcq', 'What is the HTSM (Heuristic Test Strategy Model) by James Bach?', 'A model providing heuristics for test planning covering quality criteria, project environment, product elements, and techniques', 'A programming framework', 'A defect tracking system', 'A project management methodology', 'A', 0, 'HTSM provides structured heuristics to guide test strategy decisions in exploratory testing.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_384', '384', 'Manual Testing', 'Exploratory Testing', 'Hard', 'mcq', 'How does skilled exploratory testing differ from novice exploratory testing in measurable ways?', 'Skilled testers find more critical defects, cover more meaningful scenarios, and document more actionable insights', 'No measurable difference', 'Novices find more bugs', 'Skill does not matter in exploration', 'A', 0, 'Experienced exploratory testers produce higher quality findings through better heuristics and domain knowledge.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_385', '385', 'Manual Testing', 'Exploratory Testing', 'Hard', 'mcq', 'What is the concept of ''testability'' in the context of exploratory testing?', 'The degree to which a system supports efficient exploration through observability and controllability', 'Only the ability to write test cases', 'A code metric', 'A deployment characteristic', 'A', 0, 'Testability encompasses how easily a tester can observe system behavior and control test conditions.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_386', '386', 'Manual Testing', 'Exploratory Testing', 'Hard', 'mcq', 'How can machine learning enhance exploratory testing?', 'By analyzing patterns in previous testing to suggest unexplored areas and potential defect-prone paths', 'ML replaces exploratory testing', 'ML is not relevant to testing', 'By automating all exploration', 'A', 0, 'ML can guide exploration by identifying patterns and suggesting high-value areas to explore.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_387', '387', 'Manual Testing', 'Exploratory Testing', 'Hard', 'mcq', 'What challenges arise when scaling exploratory testing across multiple teams?', 'Ensuring consistency of coverage, avoiding duplication, and maintaining quality of exploration across teams', 'No challenges exist', 'Exploratory testing cannot scale', 'Only one person can do it', 'A', 0, 'Scaling requires coordination mechanisms to ensure comprehensive, non-redundant exploration across teams.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_388', '388', 'Manual Testing', 'Exploratory Testing', 'Easy', 'scenario', 'A new feature has been deployed but no test cases have been written yet. The team needs quick feedback on quality. What approach should be used?', 'Exploratory Testing with a focused charter on the new feature', 'Wait for test cases to be written', 'Skip testing', 'Deploy to production and monitor', 'A', 0, 'Exploratory testing provides immediate quality feedback when formal test cases are not yet available.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_389', '389', 'Manual Testing', 'Exploratory Testing', 'Easy', 'scenario', 'A tester is exploring an application and discovers that clicking a button very rapidly causes a crash. No test case covers this scenario. How should this be handled?', 'Log a defect with steps to reproduce and add the scenario to future test cases', 'Ignore it since no test case exists', 'Close the application', 'Report it verbally only', 'A', 0, 'Unexpected findings during exploration should be documented as defects and added to the test suite.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_390', '390', 'Manual Testing', 'Exploratory Testing', 'Easy', 'scenario', 'A QA lead assigns a junior tester to do exploratory testing for the first time. What guidance should they provide?', 'A test charter defining what to explore, what to look for, and a time-box for the session', 'No guidance; let them figure it out', 'A list of all defects to find', 'Only automated test scripts', 'A', 0, 'A charter and time-box give structure to guide the junior tester''s exploration effectively.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_391', '391', 'Manual Testing', 'Exploratory Testing', 'Easy', 'scenario', 'During an exploratory session, a tester notices that the UI behaves differently on different screen sizes but this is not in scope for their charter. What should they do?', 'Note the observation for a future session and stay focused on the current charter', 'Ignore it completely', 'Stop the current session to investigate', 'Change the charter mid-session', 'A', 0, 'Noting out-of-scope findings for future sessions maintains focus while capturing valuable observations.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_392', '392', 'Manual Testing', 'Exploratory Testing', 'Medium', 'scenario', 'A team has been running the same scripted regression tests for 6 months with no new defects found. The pesticide paradox is suspected. What complementary approach would help?', 'Add exploratory testing sessions targeting areas around the regression suite to find unscripted defects', 'Run the same tests faster', 'Remove regression tests', 'Stop testing', 'A', 0, 'Exploratory testing complements stale regression suites by finding defects outside scripted scenarios.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_393', '393', 'Manual Testing', 'Exploratory Testing', 'Medium', 'scenario', 'A test lead needs to report exploratory testing metrics to management. What should they include?', 'Number of sessions, time spent, charters covered, defects found by severity, and areas explored', 'Only the number of bugs found', 'Only time spent', 'Nothing; exploratory testing is not measurable', 'A', 0, 'Session-based metrics provide quantifiable data on exploratory testing effort and outcomes.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_394', '394', 'Manual Testing', 'Exploratory Testing', 'Medium', 'scenario', 'An exploratory tester wants to understand the payment flow of a complex application they have never used before. Which touring strategy would be most effective initially?', 'The Guidebook Tour: follow the user documentation or help guides to understand basic flows first', 'The Garbage Collector Tour', 'Testing random features', 'Skipping the payment flow', 'A', 0, 'The Guidebook Tour helps testers learn the application through its documented workflows before deeper exploration.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_395', '395', 'Manual Testing', 'Exploratory Testing', 'Medium', 'scenario', 'During a 90-minute exploratory session, a tester spent 60 minutes setting up test data and only 30 minutes actually testing. How should this be addressed?', 'Improve test data availability through pre-prepared datasets or better tooling to maximize actual testing time', 'Accept the ratio', 'Make sessions longer', 'Skip data setup', 'A', 0, 'Reducing setup overhead through prepared data sets maximizes the value of exploratory testing sessions.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_396', '396', 'Manual Testing', 'Exploratory Testing', 'Medium', 'scenario', 'A team wants to divide exploratory testing of a complex application among 4 testers without overlap. How should the work be organized?', 'Create distinct charters for each tester covering different functional areas or perspectives', 'Let everyone explore the same area', 'Only one tester should explore', 'No organization needed', 'A', 0, 'Distinct charters for each tester ensure comprehensive coverage with minimal overlap.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_397', '397', 'Manual Testing', 'Exploratory Testing', 'Hard', 'scenario', 'An organization wants to measure the ROI of exploratory testing compared to scripted testing. What approach should they use?', 'Compare defect detection rates, unique defects found, severity distribution, and time-to-find between both approaches over multiple releases', 'ROI of exploratory testing cannot be measured', 'Only count total bugs', 'Compare team sizes', 'A', 0, 'Comparing detection rates, unique finds, severity, and efficiency metrics between approaches demonstrates relative ROI.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_398', '398', 'Manual Testing', 'Exploratory Testing', 'Hard', 'scenario', 'A mission-critical healthcare system requires both exploratory and scripted testing for regulatory compliance. The regulator questions the rigor of exploratory testing. How should the QA manager justify it?', 'Present SBTM documentation showing charters, session reports, coverage maps, and demonstrate how findings complement scripted testing', 'Abandon exploratory testing', 'Say the regulator is wrong', 'Use only scripted testing', 'A', 0, 'SBTM documentation provides auditable evidence of structured exploratory testing for regulatory compliance.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_399', '399', 'Manual Testing', 'Exploratory Testing', 'Hard', 'scenario', 'A team practices pair exploratory testing where two testers explore together. Some management considers this wasteful. What is the case for continuing this practice?', 'Pair testing combines different perspectives, finds more diverse defects, enables knowledge transfer, and improves session quality', 'It is indeed wasteful', 'Only one tester should explore at a time', 'Pair testing is only for developers', 'A', 0, 'Pair exploratory testing leverages diverse perspectives and knowledge sharing to improve defect discovery.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_400', '400', 'Manual Testing', 'Exploratory Testing', 'Hard', 'scenario', 'A test manager wants to create an exploratory testing competency framework for the organization. What key competencies should it include?', 'Critical thinking, domain knowledge, observation skills, test design ability, tool proficiency, and communication', 'Only coding skills', 'Only management skills', 'Only defect reporting skills', 'A', 0, 'A comprehensive competency framework covers cognitive, technical, domain, and communication skills.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_401', '401', 'Manual Testing', 'Usability Testing', 'Easy', 'mcq', 'What is usability testing?', 'Testing how easy and intuitive a product is for end users to use', 'Testing the code structure', 'Testing server performance', 'Testing database queries', 'A', 0, 'Usability testing evaluates how easily users can accomplish their goals using the product.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_402', '402', 'Manual Testing', 'Usability Testing', 'Easy', 'mcq', 'Who typically participates as subjects in usability testing?', 'Representative end users of the product', 'Only developers', 'Only testers', 'Only managers', 'A', 0, 'Usability testing uses representative end users to get authentic feedback on the user experience.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_403', '403', 'Manual Testing', 'Usability Testing', 'Easy', 'mcq', 'What is a common metric used in usability testing?', 'Task completion rate', 'Lines of code', 'Defect density', 'Server uptime', 'A', 0, 'Task completion rate measures the percentage of users who successfully complete a given task.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_404', '404', 'Manual Testing', 'Usability Testing', 'Easy', 'mcq', 'What is a usability issue?', 'A problem that makes it difficult for users to accomplish their goals', 'A code compilation error', 'A server crash', 'A database lock', 'A', 0, 'Usability issues hinder the user''s ability to efficiently and effectively use the product.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_405', '405', 'Manual Testing', 'Usability Testing', 'Easy', 'mcq', 'When should usability testing ideally begin?', 'Early in the design process, even with prototypes or wireframes', 'Only after full development', 'Only in production', 'Only during maintenance', 'A', 0, 'Starting usability testing early with prototypes catches design issues when they are cheapest to fix.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_406', '406', 'Manual Testing', 'Usability Testing', 'Easy', 'mcq', 'What is a think-aloud protocol in usability testing?', 'Users verbalize their thoughts while performing tasks, revealing their reasoning and confusion', 'A team meeting format', 'A code review technique', 'A testing tool', 'A', 0, 'Think-aloud protocol provides insight into user thought processes and pain points during task execution.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_407', '407', 'Manual Testing', 'Usability Testing', 'Medium', 'mcq', 'What is the difference between usability testing and user experience (UX) testing?', 'Usability focuses on task efficiency; UX encompasses the entire user perception including emotion and satisfaction', 'They are identical', 'Usability is more comprehensive', 'UX is only about visuals', 'A', 0, 'Usability is a component of UX; UX also includes emotional response, satisfaction, and overall perception.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_408', '408', 'Manual Testing', 'Usability Testing', 'Medium', 'mcq', 'What is a heuristic evaluation in usability?', 'Expert review of the interface against established usability principles (like Nielsen''s heuristics)', 'User testing in a lab', 'Automated testing', 'Performance benchmarking', 'A', 0, 'Heuristic evaluation uses expert reviewers assessing against established usability guidelines.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_409', '409', 'Manual Testing', 'Usability Testing', 'Medium', 'mcq', 'What are Nielsen''s 10 usability heuristics primarily used for?', 'Evaluating user interface design against established usability principles', 'Writing code', 'Database design', 'Network configuration', 'A', 0, 'Nielsen''s heuristics are guidelines for evaluating UI design quality and identifying usability issues.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_410', '410', 'Manual Testing', 'Usability Testing', 'Medium', 'mcq', 'How many users are typically needed for usability testing to find most issues?', '5 users can uncover approximately 80% of usability issues according to Nielsen', '100 users minimum', 'Only 1 user', 'At least 50 users', 'A', 0, 'Nielsen''s research suggests 5 users typically reveal about 80% of usability problems.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_411', '411', 'Manual Testing', 'Usability Testing', 'Medium', 'mcq', 'What is an A/B test in the context of usability?', 'Comparing two versions of a design to see which performs better with users', 'Testing version A only', 'Testing alphabetical order', 'A type of unit test', 'A', 0, 'A/B testing compares two design variants to determine which better achieves usability goals.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_412', '412', 'Manual Testing', 'Usability Testing', 'Medium', 'mcq', 'What is the System Usability Scale (SUS)?', 'A standardized questionnaire providing a quick measure of perceived usability', 'A system performance benchmark', 'A code quality metric', 'A deployment checklist', 'A', 0, 'SUS is a 10-item questionnaire that produces a single score representing overall perceived usability.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_413', '413', 'Manual Testing', 'Usability Testing', 'Medium', 'mcq', 'What is moderated vs unmoderated usability testing?', 'Moderated has a facilitator present; unmoderated uses tools for remote self-guided testing', 'They are identical', 'Moderated is always better', 'Unmoderated is always better', 'A', 0, 'Moderated testing allows real-time probing; unmoderated enables larger scale remote testing.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_414', '414', 'Manual Testing', 'Usability Testing', 'Medium', 'mcq', 'What is cognitive walkthrough in usability testing?', 'An evaluation method where experts walk through tasks from the user''s perspective to identify issues', 'A physical walk through the office', 'A code walkthrough', 'A deployment process', 'A', 0, 'Cognitive walkthrough evaluates learnability by simulating a user''s thought process through tasks.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_415', '415', 'Manual Testing', 'Usability Testing', 'Hard', 'mcq', 'How does accessibility testing relate to usability testing?', 'Accessibility ensures usability for people with disabilities; it is a subset of usability for inclusive design', 'They are unrelated', 'Accessibility replaces usability', 'Accessibility is only about screen readers', 'A', 0, 'Accessibility testing ensures the product is usable by people with various disabilities, extending usability to all users.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_416', '416', 'Manual Testing', 'Usability Testing', 'Hard', 'mcq', 'What is the Fitts''s Law and how does it apply to usability testing?', 'It predicts that larger, closer targets are faster to interact with, guiding button sizing and placement', 'It measures code performance', 'It calculates server load', 'It predicts defect rates', 'A', 0, 'Fitts''s Law guides interface design by relating target size and distance to interaction time.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_417', '417', 'Manual Testing', 'Usability Testing', 'Hard', 'mcq', 'What is the role of eye-tracking in advanced usability testing?', 'It reveals where users look, what they notice, and what they miss on the interface', 'It tracks defects', 'It monitors server performance', 'It measures code coverage', 'A', 0, 'Eye-tracking provides objective data about visual attention patterns for UI optimization.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_418', '418', 'Manual Testing', 'Usability Testing', 'Hard', 'mcq', 'How should usability test results be prioritized for development action?', 'By impact on user goals, frequency of occurrence, and severity of the user experience degradation', 'By random order', 'By ease of fix only', 'By developer preference', 'A', 0, 'Prioritizing by impact, frequency, and severity ensures the most impactful usability issues are fixed first.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_419', '419', 'Manual Testing', 'Usability Testing', 'Hard', 'mcq', 'What is the challenge of measuring the ROI of usability testing?', 'Benefits are often indirect (reduced support calls, increased conversion, lower training costs) and hard to attribute directly', 'ROI is always obvious', 'There is no ROI', 'Only direct cost savings count', 'A', 0, 'Usability ROI requires measuring indirect benefits like reduced support costs and increased user satisfaction.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_420', '420', 'Manual Testing', 'Usability Testing', 'Hard', 'mcq', 'How does cultural context affect usability testing?', 'Different cultures have varying expectations for layout, color, navigation, and interaction patterns', 'Culture has no effect', 'Only language matters', 'Usability is universal', 'A', 0, 'Cultural differences affect usability expectations; testing should account for target audience cultural norms.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_421', '421', 'Manual Testing', 'Usability Testing', 'Easy', 'scenario', 'Users of a mobile app complain that buttons are too small to tap. What usability principle is being violated?', 'Adequate touch target size for the input method', 'Database design', 'Server configuration', 'Code structure', 'A', 0, 'Mobile usability requires touch targets large enough for reliable finger interaction.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_422', '422', 'Manual Testing', 'Usability Testing', 'Easy', 'scenario', 'A website has a confusing navigation menu and users cannot find key features. What type of testing would identify this issue?', 'Usability Testing', 'Performance Testing', 'Security Testing', 'Load Testing', 'A', 0, 'Usability testing with real users would reveal navigation confusion and information architecture issues.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_423', '423', 'Manual Testing', 'Usability Testing', 'Easy', 'scenario', 'A product manager wants feedback on a new design before development begins. Only wireframes are available. Can usability testing still be done?', 'Yes, usability testing can be done on wireframes and prototypes', 'No, only finished products can be tested', 'No, only code can be tested', 'No, usability testing requires servers', 'A', 0, 'Usability testing on wireframes provides early feedback and prevents costly design changes later.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_424', '424', 'Manual Testing', 'Usability Testing', 'Easy', 'scenario', 'A user testing a web form gives up because they cannot figure out which fields are required. What usability issue is this?', 'Poor visibility of required field indicators', 'A server error', 'A database problem', 'A code bug', 'A', 0, 'Failing to clearly indicate required fields violates the usability principle of visibility of system status.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_425', '425', 'Manual Testing', 'Usability Testing', 'Medium', 'scenario', 'An e-commerce site has a high cart abandonment rate at the checkout page. The team suspects usability issues. How should they investigate?', 'Conduct usability testing of the checkout flow with task analysis, observe where users struggle, and collect feedback', 'Add more features', 'Reduce prices', 'Change the server', 'A', 0, 'Usability testing of the checkout flow with observation reveals specific pain points causing abandonment.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_426', '426', 'Manual Testing', 'Usability Testing', 'Medium', 'scenario', 'A company wants to compare two versions of their homepage to see which leads to more user sign-ups. What usability test approach is most suitable?', 'A/B Testing with user sign-up as the primary metric', 'Code review', 'Load testing', 'Security audit', 'A', 0, 'A/B testing directly compares two designs measuring the conversion rate for the desired action.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_427', '427', 'Manual Testing', 'Usability Testing', 'Medium', 'scenario', 'A QA team needs to evaluate the usability of an internal tool used by 500 employees across 3 locations. In-person testing is not feasible for all. What approach should they use?', 'Remote unmoderated usability testing using online tools supplemented by moderated sessions for a subset', 'Cancel usability testing', 'Test only at headquarters', 'Use only surveys', 'A', 0, 'Remote unmoderated testing scales across locations while moderated sessions provide deeper insights for a subset.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_428', '428', 'Manual Testing', 'Usability Testing', 'Medium', 'scenario', 'After usability testing, the team identified 30 usability issues. Resources allow fixing only 10 before release. How should they prioritize?', 'Prioritize by impact on primary user workflows, frequency of occurrence, and severity', 'Fix the easiest 10', 'Fix randomly', 'Fix the most recently found', 'A', 0, 'Prioritizing by impact on key workflows and severity ensures the most valuable fixes are made first.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_429', '429', 'Manual Testing', 'Usability Testing', 'Medium', 'scenario', 'A healthcare application is being designed for elderly users who may have limited technical experience. What usability considerations are most critical?', 'Larger fonts, high contrast, simple navigation, clear labels, and error prevention', 'Flashy animations', 'Complex menus', 'Small text for more content', 'A', 0, 'Elderly users benefit from larger text, high contrast, simple workflows, and clear error prevention.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_430', '430', 'Manual Testing', 'Usability Testing', 'Hard', 'scenario', 'A company wants to establish a usability testing practice from scratch. They have no UX team, limited budget, and time-critical releases. What phased approach should they adopt?', 'Start with heuristic evaluations and guerrilla testing, then add structured usability testing as the practice matures', 'Hire a full UX team immediately', 'Skip usability testing entirely', 'Only use automated tools', 'A', 0, 'A phased approach starting with low-cost methods builds capability gradually within constraints.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_431', '431', 'Manual Testing', 'Usability Testing', 'Hard', 'scenario', 'A financial trading platform requires both speed (millisecond responses) and usability (clear interface for complex data). These goals sometimes conflict. How should usability testing balance these?', 'Test with real traders to find the optimal balance between information density and clarity with performance constraints', 'Prioritize speed over all usability', 'Ignore performance in usability tests', 'Test only with non-traders', 'A', 0, 'Testing with actual users under realistic performance conditions reveals the optimal balance point.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_432', '432', 'Manual Testing', 'Usability Testing', 'Hard', 'scenario', 'A product is used by both novice and expert users. Novices need guidance while experts want shortcuts. Usability testing reveals both groups are dissatisfied. How should the design accommodate both?', 'Implement progressive disclosure with default guided paths for novices and discoverable power features for experts', 'Design only for novices', 'Design only for experts', 'Create two separate products', 'A', 0, 'Progressive disclosure serves both audiences by layering complexity and providing multiple interaction paths.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_433', '433', 'Manual Testing', 'Usability Testing', 'Hard', 'scenario', 'A global product must pass usability testing for 8 different markets with varying cultural expectations, languages, and accessibility requirements. How should the usability testing strategy be structured?', 'Core usability testing with universal tasks plus market-specific sessions addressing cultural, linguistic, and accessibility variations', 'One-size-fits-all testing', 'Test only the largest market', 'Skip international usability testing', 'A', 0, 'A layered approach with core universal testing plus market-specific sessions ensures comprehensive cross-cultural usability.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_434', '434', 'Manual Testing', 'Regression Testing', 'Easy', 'mcq', 'What is regression testing?', 'Retesting to verify that changes have not broken existing functionality', 'Testing new features only', 'Testing for the first time', 'Performance testing', 'A', 0, 'Regression testing ensures that code changes (fixes, enhancements) have not adversely affected existing features.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_435', '435', 'Manual Testing', 'Regression Testing', 'Easy', 'mcq', 'When should regression testing be performed?', 'After every code change, bug fix, or new feature addition', 'Only at the end of the project', 'Only before the first release', 'Only once a year', 'A', 0, 'Regression testing should follow every change to ensure existing functionality remains intact.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_436', '436', 'Manual Testing', 'Regression Testing', 'Easy', 'mcq', 'What is a regression test suite?', 'A collection of test cases specifically selected to verify existing functionality after changes', 'All test cases ever written', 'Only new test cases', 'Only failed test cases', 'A', 0, 'A regression suite is a curated set of tests targeting areas likely affected by changes.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_437', '437', 'Manual Testing', 'Regression Testing', 'Easy', 'mcq', 'Why is regression testing important in software development?', 'Code changes can unintentionally break existing features', 'It is not important', 'It only catches new defects', 'It speeds up development', 'A', 0, 'Regression testing catches unintended side effects of code changes that could break existing functionality.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_438', '438', 'Manual Testing', 'Regression Testing', 'Easy', 'mcq', 'Can regression testing be automated?', 'Yes, regression testing is an ideal candidate for automation due to its repetitive nature', 'No, it must always be manual', 'Only partially', 'Only for web applications', 'A', 0, 'The repetitive, predictable nature of regression testing makes it highly suitable for automation.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_439', '439', 'Manual Testing', 'Regression Testing', 'Easy', 'mcq', 'What is the relationship between regression testing and smoke testing?', 'Smoke testing is a subset of regression that provides quick verification; full regression is more comprehensive', 'They are identical', 'Smoke testing replaces regression', 'Regression is faster than smoke', 'A', 0, 'Smoke testing provides quick initial verification while regression testing provides thorough coverage of existing features.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_440', '440', 'Manual Testing', 'Regression Testing', 'Medium', 'mcq', 'What strategies exist for selecting regression test cases?', 'Retest all, selective, prioritized, and risk-based selection approaches', 'Always retest everything', 'Only test new features', 'Random selection only', 'A', 0, 'Multiple strategies balance coverage with efficiency: full retest, selective, prioritized, and risk-based.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_441', '441', 'Manual Testing', 'Regression Testing', 'Medium', 'mcq', 'What is ''selective regression testing''?', 'Running only a subset of regression tests that cover areas affected by the change', 'Running all tests', 'Running no tests', 'Running only new tests', 'A', 0, 'Selective regression identifies and runs only tests relevant to the specific code changes made.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_442', '442', 'Manual Testing', 'Regression Testing', 'Medium', 'mcq', 'How does impact analysis help in regression testing?', 'It identifies which areas of the application are affected by a change to target regression tests', 'It measures test execution speed', 'It counts defects', 'It estimates project cost', 'A', 0, 'Impact analysis maps code changes to affected functionality to guide efficient regression test selection.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_443', '443', 'Manual Testing', 'Regression Testing', 'Medium', 'mcq', 'What is the challenge of maintaining a regression test suite over time?', 'The suite grows continuously, increasing execution time and maintenance effort', 'No challenges exist', 'Suites shrink over time', 'Maintenance is not needed', 'A', 0, 'Growing regression suites require regular pruning, optimization, and maintenance to remain effective.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_444', '444', 'Manual Testing', 'Regression Testing', 'Medium', 'mcq', 'What is test case prioritization in regression testing?', 'Ordering test cases so the most critical or most likely to find defects run first', 'Running tests alphabetically', 'Running the newest tests last', 'Random ordering', 'A', 0, 'Prioritization ensures the most valuable tests run first, providing earlier feedback on critical areas.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_445', '445', 'Manual Testing', 'Regression Testing', 'Medium', 'mcq', 'How does continuous integration (CI) affect regression testing?', 'CI enables automated regression testing on every code commit for immediate feedback', 'CI eliminates regression testing', 'CI makes regression manual', 'CI slows down regression', 'A', 0, 'CI pipelines trigger automated regression tests on each commit, providing rapid quality feedback.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_446', '446', 'Manual Testing', 'Regression Testing', 'Medium', 'mcq', 'What is the difference between partial and full regression testing?', 'Partial tests only affected areas; full tests the entire application', 'They are identical', 'Partial is always better', 'Full regression is never needed', 'A', 0, 'Partial regression focuses on changed areas for efficiency; full regression covers everything for thorough verification.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_447', '447', 'Manual Testing', 'Regression Testing', 'Medium', 'mcq', 'When is full regression testing most necessary?', 'Before major releases, after significant architectural changes, or when risk is high', 'After every minor fix', 'Only once in the project', 'Never', 'A', 0, 'Full regression is warranted for major releases or significant changes where broader impact is possible.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_448', '448', 'Manual Testing', 'Regression Testing', 'Hard', 'mcq', 'What is regression test minimization and how does it differ from prioritization?', 'Minimization reduces the suite size permanently; prioritization reorders without removing tests', 'They are the same', 'Minimization adds tests', 'Prioritization removes tests', 'A', 0, 'Minimization permanently removes redundant tests; prioritization changes execution order to front-load value.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_449', '449', 'Manual Testing', 'Regression Testing', 'Hard', 'mcq', 'How can code coverage data be used to optimize regression testing?', 'By identifying which tests cover changed code and selecting only those for regression', 'Code coverage is not relevant', 'By running all tests regardless', 'By removing covered tests', 'A', 0, 'Coverage data maps tests to code, enabling precise selection of relevant tests for changed areas.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_450', '450', 'Manual Testing', 'Regression Testing', 'Hard', 'mcq', 'What is the regression testing challenge in a microservices architecture?', 'Changes in one service can cascade to dependent services requiring cross-service regression strategies', 'No challenge exists', 'Each service is independent', 'Only UI regression is needed', 'A', 0, 'Microservices interdependencies require regression testing that spans service boundaries.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_451', '451', 'Manual Testing', 'Regression Testing', 'Hard', 'mcq', 'What is the concept of ''test debt'' in relation to regression testing?', 'Accumulated gaps in the regression suite that increase the risk of undetected regressions over time', 'Financial debt from testing tools', 'The time testers owe', 'Budget overruns', 'A', 0, 'Test debt represents missing or outdated regression tests that increase the risk of escaped defects.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_452', '452', 'Manual Testing', 'Regression Testing', 'Hard', 'mcq', 'How does model-based regression testing work?', 'Uses models of the system to automatically generate and select regression test cases based on changes', 'It is a manual technique', 'It does not exist', 'It uses only UI models', 'A', 0, 'Model-based testing generates regression tests from system models, adapting automatically to changes.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_453', '453', 'Manual Testing', 'Regression Testing', 'Hard', 'mcq', 'What is visual regression testing?', 'Automated comparison of UI screenshots before and after changes to detect unintended visual differences', 'Manual visual inspection', 'Testing display resolution', 'Testing color schemes manually', 'A', 0, 'Visual regression testing uses automated screenshot comparison to detect unexpected UI changes.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_454', '454', 'Manual Testing', 'Regression Testing', 'Easy', 'scenario', 'A developer fixed a bug in the login page. The tester wants to make sure the fix did not break the password reset feature. What type of testing should they do?', 'Regression Testing on the password reset and related authentication features', 'Only test the login fix', 'Skip testing password reset', 'Performance testing', 'A', 0, 'Regression testing of related features ensures the fix did not introduce side effects.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_455', '455', 'Manual Testing', 'Regression Testing', 'Easy', 'scenario', 'A QA team has 1000 test cases in their regression suite. Executing all takes 5 days. They need results in 1 day. What should they do?', 'Prioritize and select the most critical test cases based on risk and change impact', 'Skip regression testing', 'Run all 1000 in one day anyway', 'Randomly select 200 tests', 'A', 0, 'Risk-based prioritization ensures the most important tests run within the available time.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_456', '456', 'Manual Testing', 'Regression Testing', 'Easy', 'scenario', 'After a software update, users report that a feature that worked before is now broken. What does this indicate about the regression testing process?', 'The regression test suite did not cover the affected feature or the test was not executed', 'Regression testing is useless', 'The feature was never working', 'Users are confused', 'A', 0, 'The regression gap indicates either missing test coverage or test execution failure for that feature.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_457', '457', 'Manual Testing', 'Regression Testing', 'Easy', 'scenario', 'A team automates their regression suite and can now run it overnight instead of over 3 days manually. What benefit does this provide?', 'Faster feedback on quality, freeing testers for exploratory and new feature testing', 'No benefit', 'Slower testing', 'More defects', 'A', 0, 'Automation speeds regression feedback and frees testers for higher-value manual testing activities.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_458', '458', 'Manual Testing', 'Regression Testing', 'Medium', 'scenario', 'A monolithic application is being refactored into microservices. The existing regression suite is tightly coupled to the monolith. How should the regression strategy evolve?', 'Create service-level regression suites for each microservice plus integration regression tests at boundaries', 'Keep the monolithic regression suite', 'Delete all regression tests', 'Only test the UI', 'A', 0, 'Microservice migration requires decomposed regression suites per service with integration testing between services.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_459', '459', 'Manual Testing', 'Regression Testing', 'Medium', 'scenario', 'A team notices that 40% of their regression test failures are due to test environment issues, not actual defects. How should this be addressed?', 'Stabilize the test environment with better configuration management and add environment health checks before regression runs', 'Ignore false failures', 'Remove flaky tests', 'Stop regression testing', 'A', 0, 'Environment stability and health checks reduce false regression failures and improve test reliability.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_460', '460', 'Manual Testing', 'Regression Testing', 'Medium', 'scenario', 'The regression suite execution time has grown from 2 hours to 12 hours over a year. What optimization strategies should be applied?', 'Parallelize execution, remove redundant tests, optimize slow tests, and implement selective regression', 'Accept the 12-hour runtime', 'Delete half the tests randomly', 'Run regression less frequently', 'A', 0, 'Multiple optimization strategies including parallelization and test minimization reduce execution time.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_461', '461', 'Manual Testing', 'Regression Testing', 'Medium', 'scenario', 'A release contains 50 bug fixes across 10 modules. The QA team needs to decide between full regression and selective regression. What factors should guide the decision?', 'Number of affected modules, interconnections between modules, change complexity, and risk level', 'Only team availability', 'Only the deadline', 'Only defect count', 'A', 0, 'The decision should consider scope of changes, module dependencies, risk, and available time.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_462', '462', 'Manual Testing', 'Regression Testing', 'Medium', 'scenario', 'A CI pipeline runs regression tests on every commit but developers complain the 4-hour suite blocks their work. How should the regression strategy be adjusted?', 'Run a fast critical subset on each commit and full regression nightly or on merge requests', 'Remove regression from CI', 'Let developers skip tests', 'Make the pipeline optional', 'A', 0, 'Tiered regression with fast checks on commits and full suites on nightly/merge provides balanced feedback.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_463', '463', 'Manual Testing', 'Regression Testing', 'Hard', 'scenario', 'A team discovers that their automated regression tests have not been updated in 6 months while the application has changed significantly. Many tests pass but no longer validate meaningful scenarios. What is this problem called and how should it be resolved?', 'Test rot or test decay; resolve by auditing the suite against current requirements and updating or removing stale tests', 'The tests are fine', 'Delete all tests and start over', 'Run them more often', 'A', 0, 'Test rot occurs when tests become outdated; systematic audit and refresh restores suite effectiveness.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_464', '464', 'Manual Testing', 'Regression Testing', 'Hard', 'scenario', 'An organization has 50,000 automated regression tests. Running all takes 24 hours. They need to identify the minimal subset that provides equivalent defect detection. What approach should they use?', 'Test suite minimization using coverage analysis, historical defect detection data, and risk-based filtering', 'Run all 50000 every time', 'Randomly select 10%', 'Delete the oldest tests', 'A', 0, 'Data-driven minimization using coverage and defect detection history identifies the most effective subset.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_465', '465', 'Manual Testing', 'Regression Testing', 'Hard', 'scenario', 'A team uses visual regression testing but gets many false positives due to dynamic content (timestamps, ads, user data). How should this be handled?', 'Implement dynamic content masking, tolerance thresholds, and exclusion zones for known variable areas', 'Stop visual regression testing', 'Ignore all differences', 'Only test static pages', 'A', 0, 'Content masking and tolerance thresholds reduce false positives while maintaining visual regression value.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_466', '466', 'Manual Testing', 'Regression Testing', 'Hard', 'scenario', 'A company wants to implement AI-powered regression test selection that learns from historical test results to predict which tests are most likely to fail. What data would the AI model need?', 'Historical test results, code change patterns, defect data, code coverage mappings, and dependency graphs', 'Only test names', 'Only pass/fail data', 'No data needed', 'A', 0, 'AI-powered test selection needs rich historical data about tests, changes, defects, and code relationships.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_467', '467', 'Manual Testing', 'UAT', 'Easy', 'mcq', 'What does UAT stand for?', 'User Acceptance Testing', 'Universal Application Testing', 'Unified Automation Testing', 'User Automation Test', 'A', 0, 'UAT stands for User Acceptance Testing, where end users validate the system meets their needs.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_468', '468', 'Manual Testing', 'UAT', 'Easy', 'mcq', 'Who typically performs UAT?', 'End users or business stakeholders', 'Developers', 'Database administrators', 'Network engineers', 'A', 0, 'UAT is performed by actual end users or their representatives who will use the system.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_469', '469', 'Manual Testing', 'UAT', 'Easy', 'mcq', 'What is the primary purpose of UAT?', 'To verify the system meets business requirements and is ready for production use', 'To find all bugs', 'To test performance', 'To review code', 'A', 0, 'UAT validates that the system satisfies business needs and is acceptable for production deployment.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_470', '470', 'Manual Testing', 'UAT', 'Easy', 'mcq', 'When in the SDLC does UAT typically occur?', 'After system testing and before production deployment', 'Before development', 'During coding', 'After deployment', 'A', 0, 'UAT occurs after system testing, as the final validation before the system goes to production.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_471', '471', 'Manual Testing', 'UAT', 'Easy', 'mcq', 'What happens if UAT fails?', 'The system is not deployed; issues are documented and sent back for resolution', 'The system is deployed anyway', 'Testing stops permanently', 'The project is cancelled', 'A', 0, 'Failed UAT means the system does not meet user expectations and needs remediation before release.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_472', '472', 'Manual Testing', 'UAT', 'Easy', 'mcq', 'What is a UAT sign-off?', 'Formal approval by business stakeholders that the system is acceptable for production', 'A developer code review', 'A test plan approval', 'A project kickoff', 'A', 0, 'UAT sign-off is the formal business acceptance that authorizes production deployment.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_473', '473', 'Manual Testing', 'UAT', 'Medium', 'mcq', 'What is the difference between alpha testing and UAT?', 'Alpha is internal testing at the developer site; UAT is business user validation against requirements', 'They are identical', 'Alpha is done after UAT', 'UAT is done by developers', 'A', 0, 'Alpha testing is internal; UAT is formal business validation typically done by actual users.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_474', '474', 'Manual Testing', 'UAT', 'Medium', 'mcq', 'What should a UAT test plan include?', 'Business scenarios, acceptance criteria, test data, schedule, participants, and sign-off process', 'Only test cases', 'Only the schedule', 'Only defect reports', 'A', 0, 'A UAT plan covers all aspects needed for structured business validation including acceptance criteria.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_475', '475', 'Manual Testing', 'UAT', 'Medium', 'mcq', 'How should UAT test cases differ from system test cases?', 'UAT test cases focus on business workflows and user scenarios rather than technical specifications', 'They should be identical', 'UAT cases are more technical', 'UAT cases test only the database', 'A', 0, 'UAT tests validate business processes from the user''s perspective, not technical implementation details.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_476', '476', 'Manual Testing', 'UAT', 'Medium', 'mcq', 'What is the role of the QA team during UAT?', 'Supporting users with environment setup, defect logging, and coordination while users drive testing', 'Performing all the testing themselves', 'No role at all', 'Writing code', 'A', 0, 'QA supports UAT by facilitating the process while business users execute the actual validation.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_477', '477', 'Manual Testing', 'UAT', 'Medium', 'mcq', 'What is business acceptance testing (BAT)?', 'Testing that validates the system meets business objectives and regulatory requirements', 'Testing that validates code syntax', 'Testing network performance', 'Testing hardware compatibility', 'A', 0, 'BAT validates business objectives and may include regulatory compliance verification.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_478', '478', 'Manual Testing', 'UAT', 'Medium', 'mcq', 'How should UAT defects be categorized differently from system testing defects?', 'By business impact and user workflow disruption rather than technical severity alone', 'Same categories as system testing', 'No categorization needed', 'Only by priority', 'A', 0, 'UAT defects are categorized by business impact to reflect the user-centric nature of acceptance testing.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_479', '479', 'Manual Testing', 'UAT', 'Medium', 'mcq', 'What is the risk of skipping UAT?', 'The system may not meet actual business needs, leading to user rejection and costly post-deployment fixes', 'No risk', 'Faster deployment', 'Better quality', 'A', 0, 'Skipping UAT risks deploying a system that does not meet business needs, causing user dissatisfaction.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_480', '480', 'Manual Testing', 'UAT', 'Medium', 'mcq', 'What is contract acceptance testing?', 'Verifying that the delivered system meets the contractual agreements and specifications', 'Testing employment contracts', 'Testing network contracts', 'Testing license agreements', 'A', 0, 'Contract acceptance testing validates deliverables against contractual obligations and acceptance criteria.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_481', '481', 'Manual Testing', 'UAT', 'Hard', 'mcq', 'How should UAT be managed when business users have limited availability?', 'Prioritize critical business scenarios, pre-prepare test data, schedule focused sessions, and provide clear documentation', 'Cancel UAT', 'Have testers do it instead', 'Delay indefinitely', 'A', 0, 'Maximizing limited user time requires preparation, prioritization, and efficient session management.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_482', '482', 'Manual Testing', 'UAT', 'Hard', 'mcq', 'What is operational acceptance testing (OAT)?', 'Testing operational readiness including backup/recovery, failover, monitoring, and maintenance procedures', 'Testing user workflows', 'Testing UI design', 'Testing code structure', 'A', 0, 'OAT validates that operational support processes are ready for production deployment.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_483', '483', 'Manual Testing', 'UAT', 'Hard', 'mcq', 'How does UAT differ in Agile versus Waterfall methodologies?', 'In Agile, UAT is continuous with each increment; in Waterfall, it is a single phase near the end', 'No difference', 'Agile does not have UAT', 'Waterfall UAT is continuous', 'A', 0, 'Agile integrates UAT throughout sprints; Waterfall treats it as a distinct final phase.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_484', '484', 'Manual Testing', 'UAT', 'Hard', 'mcq', 'What is the challenge of UAT for enterprise systems with complex integrations?', 'Ensuring realistic end-to-end business scenarios that span multiple integrated systems with consistent test data', 'No challenges', 'Only UI testing matters', 'Integration does not affect UAT', 'A', 0, 'Enterprise UAT must validate business processes that cross system boundaries with realistic integrated scenarios.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_485', '485', 'Manual Testing', 'UAT', 'Hard', 'mcq', 'How should UAT handle conflicting feedback from different user groups?', 'Facilitate prioritization meetings with stakeholders to resolve conflicts based on business objectives and user impact', 'Accept all feedback equally', 'Ignore conflicting feedback', 'Let developers decide', 'A', 0, 'Stakeholder meetings resolve conflicts by aligning decisions with business priorities and user impact.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_486', '486', 'Manual Testing', 'UAT', 'Hard', 'mcq', 'What metrics should be tracked during UAT to assess readiness for go-live?', 'Acceptance criteria pass rate, critical defect count, business scenario completion, and stakeholder satisfaction', 'Only defect count', 'Only time spent', 'Only sign-off status', 'A', 0, 'Multiple UAT metrics provide a holistic view of readiness including criteria, defects, completion, and satisfaction.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_487', '487', 'Manual Testing', 'UAT', 'Easy', 'scenario', 'An HR department is getting a new employee management system. Before deployment, the HR team needs to verify it handles their daily tasks. What type of testing is this?', 'User Acceptance Testing (UAT)', 'Unit Testing', 'Performance Testing', 'Code Review', 'A', 0, 'UAT involves end users (HR team) validating the system meets their operational needs.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_488', '488', 'Manual Testing', 'UAT', 'Easy', 'scenario', 'During UAT, a business user finds that a report shows incorrect totals. They are unsure how to report this issue. What should the QA team do?', 'Provide a simple defect reporting mechanism and assist the user in logging the issue', 'Tell the user to fix it', 'Ignore the issue', 'Close UAT immediately', 'A', 0, 'QA should support users with easy defect reporting tools and assistance during UAT.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_489', '489', 'Manual Testing', 'UAT', 'Easy', 'scenario', 'A UAT participant says the system works correctly but is too slow for their workflow. Should this be logged as a UAT issue?', 'Yes, performance that impacts business workflows is a valid UAT concern', 'No, performance is not UAT scope', 'No, only functional issues count', 'No, users should not complain about speed', 'A', 0, 'Any issue affecting the user''s ability to work effectively is a valid UAT finding.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_490', '490', 'Manual Testing', 'UAT', 'Easy', 'scenario', 'The project deadline is tomorrow but UAT has not been completed. The PM wants to deploy anyway. What should the QA lead advise?', 'Advise against deployment and communicate the risks of releasing without completed UAT', 'Deploy immediately', 'Complete UAT in production', 'Skip UAT permanently', 'A', 0, 'Deploying without completed UAT risks user rejection and post-deployment issues; risks must be communicated.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_491', '491', 'Manual Testing', 'UAT', 'Medium', 'scenario', 'A banking application''s UAT involves validating 200 business scenarios across 5 departments. Each department has only 2 days available. How should UAT be organized?', 'Prioritize critical scenarios per department, pre-prepare test data, and schedule parallel sessions with QA support', 'Test all 200 scenarios in sequence', 'Let only one department test', 'Skip less important departments', 'A', 0, 'Parallel sessions with prioritized scenarios and preparation maximize limited user availability.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_492', '492', 'Manual Testing', 'UAT', 'Medium', 'scenario', 'UAT participants report that the system meets functional requirements but the user interface is confusing. Should this block UAT sign-off?', 'It depends on whether usability is included in the acceptance criteria; if so, it should be addressed', 'No, UI is not important', 'Always block', 'Never block', 'A', 0, 'Whether usability issues block sign-off depends on the defined acceptance criteria for UAT.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_493', '493', 'Manual Testing', 'UAT', 'Medium', 'scenario', 'During UAT of a CRM system, sales managers want additional features not in the original requirements. How should these requests be handled?', 'Log them as enhancement requests separate from UAT defects and evaluate for future releases', 'Add them immediately', 'Ignore them', 'Cancel UAT until they are built', 'A', 0, 'New feature requests during UAT should be tracked separately and evaluated for future release inclusion.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_494', '494', 'Manual Testing', 'UAT', 'Medium', 'scenario', 'A UAT tester reports that data migration from the old system has errors. Some customer records are corrupted. How should this be handled?', 'Halt UAT for affected data areas, investigate the migration issue, fix data, and re-run affected UAT scenarios', 'Continue UAT with corrupted data', 'Ignore data issues', 'Deploy anyway', 'A', 0, 'Data migration errors invalidate UAT results for affected areas and must be resolved before resuming.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_495', '495', 'Manual Testing', 'UAT', 'Medium', 'scenario', 'Multiple UAT participants provide conflicting feedback on the same feature. One says it works correctly while another says it does not. What should the QA coordinator do?', 'Investigate by understanding both users'' scenarios, test data, and steps to determine if it is a legitimate defect', 'Believe the first user', 'Believe the second user', 'Ignore the conflict', 'A', 0, 'Investigating both perspectives reveals whether the discrepancy is a defect or a difference in usage scenarios.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_496', '496', 'Manual Testing', 'UAT', 'Medium', 'scenario', 'A company outsources software development. The contract requires UAT to be completed within 2 weeks. At the end of week 1, only 40% of scenarios are tested due to quality issues. What options should be considered?', 'Request timeline extension, prioritize remaining critical scenarios, and negotiate contract terms based on quality findings', 'Accept the current state', 'Skip remaining scenarios', 'Blame the vendor', 'A', 0, 'Quality issues require transparent communication and negotiation on timeline and acceptance criteria.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_497', '497', 'Manual Testing', 'UAT', 'Hard', 'scenario', 'An organization is deploying an ERP system across 20 countries with different regulatory, language, and business process requirements. How should UAT be structured to cover all variants?', 'Core UAT for shared functionality with country-specific UAT sessions for local regulations, language, and processes', 'One UAT for all countries', 'UAT only in headquarters', 'Skip country-specific testing', 'A', 0, 'A layered UAT approach with core and country-specific testing ensures both global and local requirements are validated.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_498', '498', 'Manual Testing', 'UAT', 'Hard', 'scenario', 'A UAT has been signed off but within the first week of production, critical issues surface that were not caught. Investigation reveals UAT scenarios did not cover real production data volumes. What process improvement is needed?', 'Include production-representative data volumes and edge cases in UAT test data to better simulate real conditions', 'Remove UAT from the process', 'Increase UAT duration only', 'Test only with production data', 'A', 0, 'UAT test data must represent real production volumes and patterns to catch volume-related issues.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_499', '499', 'Manual Testing', 'UAT', 'Hard', 'scenario', 'A SaaS product serves multiple tenants with different configurations. UAT for one tenant''s configuration passes but another''s fails. How should multi-tenant UAT be managed?', 'Implement configuration-specific UAT tracks with shared core validation and tenant-specific scenario sets', 'Test only one tenant', 'Use the same tests for all tenants', 'Skip failing tenant', 'A', 0, 'Multi-tenant SaaS requires both shared and tenant-specific UAT scenarios to cover configuration variations.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Manual Testing_500', '500', 'Manual Testing', 'UAT', 'Hard', 'scenario', 'An organization wants to shift from document-heavy UAT to a more Agile UAT approach. Business users are accustomed to formal sign-off processes. How should the transition be managed?', 'Gradually introduce sprint-level UAT with lightweight acceptance criteria while maintaining formal sign-off for major milestones', 'Eliminate all sign-offs immediately', 'Keep the old process', 'Stop doing UAT', 'A', 0, 'Gradual transition preserves formal governance at key milestones while introducing Agile practices incrementally.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_1', '1', 'API Testing', 'REST Concepts', 'Easy', 'mcq', 'What does REST stand for?', 'Representational State Transfer', 'Remote Execution Service Technology', 'Reliable Endpoint System Transfer', 'Resource Estimation and Status Tracking', 'A', 0, 'REST stands for Representational State Transfer, an architectural style for distributed systems.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_2', '2', 'API Testing', 'REST Concepts', 'Easy', 'mcq', 'Which constraint of REST requires that each request contains all information needed to process it?', 'Statelessness', 'Cacheability', 'Uniform Interface', 'Layered System', 'A', 0, 'Statelessness means the server does not store client context between requests.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_3', '3', 'API Testing', 'REST Concepts', 'Easy', 'mcq', 'What is a resource in REST?', 'Any information that can be named and addressed', 'A database table', 'A server endpoint only', 'An HTTP method', 'A', 0, 'In REST, a resource is any information that can be named, such as a document, image, or collection.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_4', '4', 'API Testing', 'REST Concepts', 'Medium', 'mcq', 'Which of the following is NOT a REST architectural constraint?', 'Stateful sessions', 'Client-Server', 'Cacheability', 'Uniform Interface', 'A', 0, 'REST requires statelessness, not stateful sessions. The server should not store session state.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_5', '5', 'API Testing', 'REST Concepts', 'Medium', 'mcq', 'What does HATEOAS stand for in REST?', 'Hypermedia As The Engine Of Application State', 'HTTP And Transport Encryption Over Application Services', 'Hypertext Application Transfer Engine Over API Services', 'HTTP Access Token Exchange Over Application State', 'A', 0, 'HATEOAS is a REST constraint meaning clients interact with the application through hypermedia provided dynamically by the server.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_6', '6', 'API Testing', 'REST Concepts', 'Hard', 'mcq', 'Which Richardson Maturity Model level involves using hypermedia controls?', 'Level 3', 'Level 2', 'Level 1', 'Level 0', 'A', 0, 'Level 3 of the Richardson Maturity Model introduces HATEOAS (Hypermedia As The Engine Of Application State).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_7', '7', 'API Testing', 'REST Concepts', 'Easy', 'mcq', 'What data format is most commonly used in REST APIs?', 'JSON', 'XML', 'YAML', 'CSV', 'A', 0, 'JSON (JavaScript Object Notation) is the most commonly used data format for REST APIs.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_8', '8', 'API Testing', 'REST Concepts', 'Medium', 'mcq', 'What is idempotency in the context of REST APIs?', 'Making the same request multiple times produces the same result', 'A request that always fails', 'A request that creates a new resource each time', 'A request with no response body', 'A', 0, 'An idempotent operation produces the same result regardless of how many times it is performed.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_9', '9', 'API Testing', 'REST Concepts', 'Hard', 'mcq', 'Which of the following best describes the Uniform Interface constraint in REST?', 'A generalized interface between client and server using standard methods and media types', 'All APIs must use the same URL pattern', 'All resources must return JSON', 'The client and server must use the same programming language', 'A', 0, 'Uniform Interface simplifies the architecture by using standard HTTP methods, URIs, and media types.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_10', '10', 'API Testing', 'REST Concepts', 'Easy', 'mcq', 'What is the purpose of a URI in REST?', 'To uniquely identify a resource', 'To encrypt the payload', 'To define the HTTP method', 'To set the response status code', 'A', 0, 'A URI (Uniform Resource Identifier) uniquely identifies each resource in a REST API.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_11', '11', 'API Testing', 'REST Concepts', 'Medium', 'mcq', 'In REST, what does the term ''representation'' refer to?', 'The format in which a resource is returned to the client', 'The URL of the resource', 'The HTTP method used', 'The server''s internal data model', 'A', 0, 'A representation is the data format (e.g., JSON, XML) returned to the client for a given resource.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_12', '12', 'API Testing', 'REST Concepts', 'Hard', 'mcq', 'What is content negotiation in REST?', 'The process where client and server agree on the response format via Accept headers', 'Negotiating the price of an API subscription', 'Choosing between REST and SOAP', 'Selecting between HTTP and HTTPS', 'A', 0, 'Content negotiation uses headers like Accept and Content-Type to agree on the representation format.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_13', '13', 'API Testing', 'REST Concepts', 'Medium', 'mcq', 'Which of the following is a benefit of the statelessness constraint?', 'Improved scalability since servers do not store session state', 'Faster response times due to caching', 'Better security through encryption', 'Simpler client-side code', 'A', 0, 'Statelessness improves scalability because any server can handle any request without session affinity.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_14', '14', 'API Testing', 'HTTP Methods', 'Easy', 'mcq', 'Which HTTP method is used to retrieve a resource?', 'GET', 'POST', 'PUT', 'DELETE', 'A', 0, 'GET is the standard HTTP method for retrieving resources from a server.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_15', '15', 'API Testing', 'HTTP Methods', 'Easy', 'mcq', 'Which HTTP method is used to create a new resource?', 'POST', 'GET', 'DELETE', 'OPTIONS', 'A', 0, 'POST is typically used to create a new resource on the server.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_16', '16', 'API Testing', 'HTTP Methods', 'Easy', 'mcq', 'Which HTTP method replaces an entire resource?', 'PUT', 'PATCH', 'POST', 'GET', 'A', 0, 'PUT replaces the entire resource at the given URI with the provided representation.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_17', '17', 'API Testing', 'HTTP Methods', 'Easy', 'mcq', 'Which HTTP method is used to delete a resource?', 'DELETE', 'REMOVE', 'DROP', 'PURGE', 'A', 0, 'DELETE is the standard HTTP method to remove a resource from the server.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_18', '18', 'API Testing', 'HTTP Methods', 'Medium', 'mcq', 'Which HTTP method is used for partial updates to a resource?', 'PATCH', 'PUT', 'POST', 'UPDATE', 'A', 0, 'PATCH applies partial modifications to a resource, unlike PUT which replaces the entire resource.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_19', '19', 'API Testing', 'HTTP Methods', 'Medium', 'mcq', 'Which HTTP method is idempotent?', 'PUT', 'POST', 'PATCH', 'CONNECT', 'A', 0, 'PUT is idempotent: making the same PUT request multiple times produces the same result.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_20', '20', 'API Testing', 'HTTP Methods', 'Medium', 'mcq', 'What does the OPTIONS HTTP method do?', 'Describes the communication options for the target resource', 'Retrieves a resource', 'Creates a new resource', 'Deletes a resource', 'A', 0, 'OPTIONS returns the HTTP methods and other options supported by the server for a given URL.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_21', '21', 'API Testing', 'HTTP Methods', 'Hard', 'mcq', 'Which HTTP method is used to check if a resource exists without downloading the body?', 'HEAD', 'OPTIONS', 'TRACE', 'GET', 'A', 0, 'HEAD is identical to GET but returns only headers, not the response body. Useful for checking resource existence.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_22', '22', 'API Testing', 'HTTP Methods', 'Easy', 'mcq', 'Is GET considered a safe HTTP method?', 'Yes, it does not modify server state', 'No, it can modify data', 'Only when used with HTTPS', 'Only for read-only APIs', 'A', 0, 'GET is a safe method because it only retrieves data and does not modify server state.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_23', '23', 'API Testing', 'HTTP Methods', 'Medium', 'mcq', 'Which of the following HTTP methods should NOT have a request body according to common convention?', 'GET', 'POST', 'PUT', 'PATCH', 'A', 0, 'While not strictly forbidden by HTTP spec, GET requests conventionally should not have a request body.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_24', '24', 'API Testing', 'HTTP Methods', 'Hard', 'mcq', 'What is the TRACE HTTP method used for?', 'Performing a loop-back test to see what the server receives', 'Tracing network latency', 'Logging API calls', 'Tracking resource changes', 'A', 0, 'TRACE performs a message loop-back test, returning what the server received, useful for debugging.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_25', '25', 'API Testing', 'HTTP Methods', 'Medium', 'mcq', 'Which HTTP methods are considered idempotent?', 'GET, PUT, DELETE, HEAD, OPTIONS', 'GET, POST, PUT, DELETE', 'Only GET and HEAD', 'All HTTP methods', 'A', 0, 'GET, PUT, DELETE, HEAD, and OPTIONS are idempotent. POST and PATCH are not guaranteed to be idempotent.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_26', '26', 'API Testing', 'HTTP Methods', 'Hard', 'mcq', 'In a RESTful API, what is the difference between PUT and POST for resource creation?', 'PUT creates at a known URI; POST creates at a server-determined URI', 'PUT is faster than POST', 'POST is more secure than PUT', 'There is no difference', 'A', 0, 'PUT creates/replaces a resource at a specific URI. POST lets the server determine the URI of the new resource.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_27', '27', 'API Testing', 'Status Codes', 'Easy', 'mcq', 'What does HTTP status code 200 indicate?', 'OK - The request was successful', 'Created - A new resource was created', 'No Content - The server has no response body', 'Accepted - Request is being processed', 'A', 0, 'HTTP 200 OK indicates the request was successful and the response body contains the result.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_28', '28', 'API Testing', 'Status Codes', 'Easy', 'mcq', 'What does HTTP status code 201 indicate?', 'Created', 'OK', 'Accepted', 'No Content', 'A', 0, 'HTTP 201 Created indicates that a new resource was successfully created.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_29', '29', 'API Testing', 'Status Codes', 'Easy', 'mcq', 'What does HTTP status code 404 indicate?', 'Not Found', 'Unauthorized', 'Forbidden', 'Bad Request', 'A', 0, 'HTTP 404 Not Found means the requested resource could not be found on the server.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_30', '30', 'API Testing', 'Status Codes', 'Easy', 'mcq', 'What does HTTP status code 500 indicate?', 'Internal Server Error', 'Bad Gateway', 'Service Unavailable', 'Gateway Timeout', 'A', 0, 'HTTP 500 Internal Server Error indicates an unexpected condition on the server.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_31', '31', 'API Testing', 'Status Codes', 'Medium', 'mcq', 'What does HTTP status code 204 indicate?', 'No Content - successful but no response body', 'Not Found', 'Bad Request', 'Unauthorized', 'A', 0, 'HTTP 204 No Content indicates success but the server is not returning any content in the body.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_32', '32', 'API Testing', 'Status Codes', 'Medium', 'mcq', 'What does HTTP status code 401 indicate?', 'Unauthorized - authentication is required', 'Forbidden - access denied', 'Not Found', 'Bad Request', 'A', 0, 'HTTP 401 Unauthorized means the request lacks valid authentication credentials.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_33', '33', 'API Testing', 'Status Codes', 'Medium', 'mcq', 'What does HTTP status code 403 indicate?', 'Forbidden - the server refuses to authorize the request', 'Unauthorized - need to login', 'Not Found', 'Method Not Allowed', 'A', 0, 'HTTP 403 Forbidden means the server understood the request but refuses to authorize it.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_34', '34', 'API Testing', 'Status Codes', 'Medium', 'mcq', 'What does HTTP status code 429 indicate?', 'Too Many Requests - rate limit exceeded', 'Internal Server Error', 'Bad Gateway', 'Service Unavailable', 'A', 0, 'HTTP 429 Too Many Requests indicates the user has sent too many requests in a given time (rate limiting).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_35', '35', 'API Testing', 'Status Codes', 'Hard', 'mcq', 'What does HTTP status code 409 indicate?', 'Conflict - the request conflicts with current server state', 'Gone - resource no longer available', 'Precondition Failed', 'Unprocessable Entity', 'A', 0, 'HTTP 409 Conflict indicates the request could not be completed due to a conflict with the current resource state.', '');
