INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_136', '136', 'API Testing', 'WebSocket Testing', 'Easy', 'mcq', 'What is the difference between WebSocket and HTTP?', 'WebSocket provides persistent bidirectional communication; HTTP is request-response based', 'WebSocket uses XML; HTTP uses JSON', 'WebSocket is more secure than HTTP', 'There is no significant difference', 'A', 0, 'WebSocket maintains a persistent connection for real-time bidirectional data flow, unlike HTTP''s request-response model.', '');
