INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_171', '171', 'API Testing', 'Security Testing APIs', 'Easy', 'mcq', 'What is the principle of least privilege in API security?', 'Granting only the minimum permissions necessary for a task', 'Giving all users admin access', 'Using the simplest authentication method', 'Minimizing the number of API endpoints', 'A', 0, 'Least privilege means each user or service should only have access to the resources they need.', '');
