INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_208', '208', 'API Testing', 'Error Handling', 'Medium', 'output', 'What will be printed?', 'Error: 400 Client Error', 'Success', 'None', 'Error: 500 Server Error', 'A', 0, 'The 400 status code triggers raise_for_status() which raises HTTPError caught by the except block.', 'import requests
