INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_211', '211', 'API Testing', 'Status Codes', 'Hard', 'output', 'What will the code print?', 'Rate limited! Retry after 60 seconds', 'Success', 'Server Error', 'Not Found', 'A', 0, 'Status code 429 indicates rate limiting; the Retry-After header specifies when to retry.', 'import requests
