INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_241', '241', 'API Testing', 'Performance Testing APIs', 'Hard', 'output', 'What is this code testing?', 'Concurrent API request handling (throughput)', 'Sequential response times', 'Single request latency', 'Authentication speed', 'A', 0, 'ThreadPoolExecutor sends multiple concurrent requests to measure throughput.', 'import requests
