INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_440', '440', 'API Testing', 'Error Handling', 'Medium', 'output', 'What will the final status be?', '200 after retrying', '500 on all attempts', 'Timeout', 'Connection Error', 'A', 0, 'The first two attempts return 500; the third attempt succeeds with 200.', 'import requests
