INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_441', '441', 'API Testing', 'Status Codes', 'Medium', 'output', 'What status code indicates the resource was created?', '201', '200', '204', '301', 'B', 1, 'The print shows response.status_code which is 200 because the server returned 200, not 201. This is a common API design issue.', 'import requests
