INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_442', '442', 'API Testing', 'Authentication', 'Hard', 'output', 'What will be printed?', 'Token is expired', 'Token is valid', 'Token is invalid', 'Error', 'A', 0, 'The JWT decode raises ExpiredSignatureError because the token''s exp claim is in the past.', 'import jwt
from datetime import datetime, timedelta
# Token was created with exp = now - 1 hour
token = jwt.encode({"user": "alice", "exp": datetime.utcnow() - timedelta(hours=1)}, "secret")
