INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_444', '444', 'API Testing', 'Pagination', 'Hard', 'output', 'What is the total number of items collected?', '100', '50', '10', '1000', 'A', 0, 'Each of the 10 pages returns 10 items, giving a total of 100 items.', 'import requests
