INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_446', '446', 'API Testing', 'Performance Testing APIs', 'Medium', 'output', 'What metrics will this code calculate?', 'Min, max, and average response times', 'Only average response time', 'Only the total time', 'The number of failed requests', 'A', 0, 'The code collects response times and calculates minimum, maximum, and average values.', 'import requests
