INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_452', '452', 'API Testing', 'Versioning', 'Hard', 'output', 'What does the Sunset header indicate?', 'The date after which this API version will no longer be available', 'The creation date of the API', 'The last update date', 'The cache expiry date', 'A', 0, 'The Sunset header specifies when the API version will be retired.', 'import requests
