INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('API Testing_453', '453', 'API Testing', 'Error Handling', 'Hard', 'output', 'What pattern does this implement?', 'Circuit breaker pattern', 'Retry pattern', 'Rate limiter', 'Load balancer', 'A', 0, 'The code tracks failures and stops making requests after 3 consecutive failures (circuit open).', 'import requests
failure_count = 0
circuit_open = False
for _ in range(5):
    if circuit_open:
        print("Circuit OPEN - skipping request")
        continue
    resp = requests.get("https://api.example.com/unstable")
    if resp.status_code >= 500:
        failure_count += 1
        if failure_count >= 3:
            circuit_open = True
    else:
        failure_count = 0');
