INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Postman_154', '154', 'Postman', 'Assertions', 'Medium', 'mcq', 'What does pm.expect([]).to.be.empty check?', 'That the array has no elements', 'That the value is null', 'That the value is undefined', 'That the string is blank', 'A', 0, 'to.be.empty asserts that an array or string has a length of zero.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Postman_155', '155', 'Postman', 'Assertions', 'Hard', 'mcq', 'How do you chain multiple assertions on the same value?', 'pm.expect(val).to.be.a(''string'').and.have.lengthOf(5)', 'pm.expect(val).a(''string'') && pm.expect(val).length(5)', 'pm.multiAssert(val, [''string'', 5])', 'You cannot chain assertions', 'A', 0, 'Chai supports chaining multiple assertions using .and or simply continuing the chain.', '');
