INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Postman_157', '157', 'Postman', 'Chaining Requests', 'Easy', 'mcq', 'How do you store response data for the next request?', 'Set it as a variable in the test script', 'Copy and paste it manually', 'Use the forward button', 'Save it to a file', 'A', 0, 'You store response data as a variable (environment, global, or collection) in the test script.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Postman_158', '158', 'Postman', 'Chaining Requests', 'Medium', 'mcq', 'Which function controls the next request in a collection run?', 'postman.setNextRequest()', 'pm.nextRequest()', 'pm.goto()', 'postman.redirect()', 'A', 0, 'postman.setNextRequest() sets which request to execute next in a collection run.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Postman_159', '159', 'Postman', 'Chaining Requests', 'Medium', 'mcq', 'What happens when postman.setNextRequest(null) is called?', 'The collection run stops after the current request', 'Nothing happens', 'It goes to the first request', 'An error is thrown', 'A', 0, 'Setting the next request to null stops the collection runner after the current request completes.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Postman_160', '160', 'Postman', 'Chaining Requests', 'Hard', 'mcq', 'Can postman.setNextRequest() create loops in a collection run?', 'Yes, by pointing to a previous request', 'No, loops are not possible', 'Only forward references are allowed', 'Only with Newman', 'A', 0, 'You can create loops by setting the next request to a previous request, useful for polling patterns.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Postman_161', '161', 'Postman', 'Chaining Requests', 'Easy', 'mcq', 'What is a typical use case for chaining requests?', 'Using an auth token from login in subsequent requests', 'Sending requests faster', 'Reducing API calls', 'Compressing responses', 'A', 0, 'A common pattern is extracting an auth token from a login response and using it in subsequent requests.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Postman_162', '162', 'Postman', 'Chaining Requests', 'Medium', 'mcq', 'Where should you set variables for chaining: pre-request or test script?', 'Test script, after receiving the response', 'Pre-request script', 'Either works the same', 'In the URL bar', 'A', 0, 'Variables for chaining should be set in the test script where you have access to the response data.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Postman_163', '163', 'Postman', 'Chaining Requests', 'Hard', 'mcq', 'How do you implement conditional branching in a collection run?', 'Use if/else with postman.setNextRequest() in test scripts', 'Use the branch feature in Collection Runner', 'Use environment conditions', 'Conditional branching is not possible', 'A', 0, 'Conditional branching is achieved by using if/else logic with postman.setNextRequest() in test scripts.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Postman_164', '164', 'Postman', 'Chaining Requests', 'Easy', 'mcq', 'Can you chain requests across different folders in a collection?', 'Yes, postman.setNextRequest() works across folders', 'No, only within the same folder', 'Only in the root level', 'Only with Newman', 'A', 0, 'postman.setNextRequest() can reference any request in the collection, regardless of folder structure.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Postman_165', '165', 'Postman', 'Chaining Requests', 'Medium', 'mcq', 'What variable scope is best for short-lived data used in request chaining?', 'Environment or collection variables', 'Global variables', 'Local variables', 'Data variables', 'A', 0, 'Environment or collection variables are suitable for chaining as they persist across requests.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Postman_166', '166', 'Postman', 'Chaining Requests', 'Hard', 'mcq', 'How do you pass an array of IDs from one request to the next?', 'JSON.stringify the array and store as a variable', 'Arrays cannot be passed between requests', 'Use a special array variable type', 'Separate each ID into individual variables', 'A', 0, 'Arrays must be JSON.stringified before storing as variables and parsed back in the next request.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Postman_167', '167', 'Postman', 'Chaining Requests', 'Medium', 'mcq', 'Does postman.setNextRequest() take effect immediately?', 'No, it takes effect after the current request completes', 'Yes, it jumps immediately', 'It queues the next request', 'It depends on the request type', 'A', 0, 'postman.setNextRequest() does not execute immediately; it takes effect after the current request finishes.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Postman_168', '168', 'Postman', 'Chaining Requests', 'Hard', 'mcq', 'What is a retry pattern using request chaining?', 'Set next request to itself with a counter variable', 'Use pm.retry()', 'Use the retry button', 'Retry is not possible with chaining', 'A', 0, 'A retry pattern sets the next request to itself while tracking a counter variable to limit retries.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Postman_169', '169', 'Postman', 'Chaining Requests', 'Easy', 'mcq', 'Can request chaining work in the Collection Runner?', 'Yes, it is designed for the Collection Runner', 'No, only for individual requests', 'Only with Newman', 'Only in monitors', 'A', 0, 'Request chaining via setNextRequest is specifically designed for the Collection Runner and Newman.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Postman_170', '170', 'Postman', 'Chaining Requests', 'Medium', 'mcq', 'What is the difference between chaining with variables vs setNextRequest?', 'Variables pass data; setNextRequest controls flow', 'They are the same thing', 'Variables only work with Newman', 'setNextRequest only works with variables', 'A', 0, 'Variables are for passing data between requests while setNextRequest controls execution order.', '');
