INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_172', '172', 'Python Requests', 'Error Handling', 'Hard', 'mcq', 'What is the relationship between requests.exceptions.ConnectionError and Python''s built-in ConnectionError?', 'requests.exceptions.ConnectionError inherits from both IOError and RequestException, not from built-in ConnectionError', 'They are the same class', 'requests.exceptions.ConnectionError inherits from built-in ConnectionError', 'There is no built-in ConnectionError in Python', 'A', 0, 'Despite the same name, requests'' ConnectionError does not inherit from Python''s built-in ConnectionError.', '');
