INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_214', '214', 'Python Requests', 'Error Handling', 'Medium', 'output', 'What will be printed?', 'HTTPError', 'ConnectionError', 'No error', 'StatusError', 'A', 0, 'A 404 response causes raise_for_status() to raise HTTPError.', 'import requests
