INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_312', '312', 'Python Requests', 'Authentication - Bearer Token', 'Medium', 'scenario', 'An OAuth2 API gives you an access token. How do you use it in subsequent requests?', 'headers={''Authorization'': ''Bearer '' + token}', 'auth=(''Bearer'', token)', 'params={''token'': token}', 'cookies={''auth'': token}', 'A', 0, 'Bearer tokens are sent in the Authorization header with ''Bearer '' prefix.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_313', '313', 'Python Requests', 'Authentication - OAuth', 'Hard', 'scenario', 'You need to implement OAuth1 authentication for a Twitter-like API. What library should you use with requests?', 'requests-oauthlib', 'python-oauth2', 'oauthlib', 'requests-auth', 'A', 0, 'requests-oauthlib provides seamless OAuth1/2 integration with the requests library.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_314', '314', 'Python Requests', 'Session Management', 'Medium', 'scenario', 'You need to make multiple authenticated API calls with the same headers and cookies. What is the best approach?', 'Use a requests.Session() to persist settings across requests', 'Set headers on each individual request', 'Create a new connection for each request', 'Store cookies in a global variable', 'A', 0, 'Sessions persist headers, cookies, and auth across multiple requests efficiently.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_315', '315', 'Python Requests', 'Session Management', 'Hard', 'scenario', 'You need to make hundreds of API calls to the same server efficiently. What approach minimises connection overhead?', 'Use a Session to reuse TCP connections via connection pooling', 'Use multiprocessing with individual requests', 'Set keep-alive headers manually', 'Use async IO with aiohttp only', 'A', 0, 'Sessions reuse TCP connections via urllib3 connection pooling, reducing overhead.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_316', '316', 'Python Requests', 'Timeout Handling', 'Easy', 'scenario', 'Your script hangs when a server is unresponsive. How do you prevent this?', 'Add a timeout parameter to the request', 'Use a separate thread with a timer', 'Set a global socket timeout', 'Close the connection manually', 'A', 0, 'The timeout parameter ensures requests doesn''t wait indefinitely.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_317', '317', 'Python Requests', 'Timeout Handling', 'Medium', 'scenario', 'You need a 5-second connect timeout but a 30-second read timeout for large downloads. How do you configure this?', 'requests.get(url, timeout=(5, 30))', 'requests.get(url, connect_timeout=5, read_timeout=30)', 'requests.get(url, timeout=5, read_limit=30)', 'requests.get(url, timeout={''connect'': 5, ''read'': 30})', 'A', 0, 'A tuple of (connect_timeout, read_timeout) sets them independently.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_318', '318', 'Python Requests', 'Retry Mechanism', 'Medium', 'scenario', 'Your API client needs to retry on 500 and 502 errors up to 3 times. How do you implement this?', 'Use HTTPAdapter with Retry(total=3, status_forcelist=[500, 502])', 'Use a try/except loop with 3 iterations', 'Set requests.max_retries = 3', 'Use session.retry(total=3)', 'A', 0, 'HTTPAdapter with Retry provides configurable automatic retry logic.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_319', '319', 'Python Requests', 'Retry Mechanism', 'Hard', 'scenario', 'You need exponential backoff between retries. How do you configure this?', 'Set backoff_factor in the Retry object', 'Use time.sleep() between manual retries', 'Set retry_delay on HTTPAdapter', 'Use a third-party retry library', 'A', 0, 'Retry(backoff_factor=0.5) adds exponential delays between retry attempts.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_320', '320', 'Python Requests', 'SSL Verification', 'Easy', 'scenario', 'You are testing against a local server with a self-signed certificate. How do you handle the SSL error?', 'Use verify=False (development only) or provide the self-signed cert to verify', 'Remove the https:// from the URL', 'Install a real certificate', 'Downgrade to HTTP', 'A', 0, 'verify=False bypasses SSL verification; for production, provide the custom cert.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_321', '321', 'Python Requests', 'SSL Verification', 'Hard', 'scenario', 'Your company uses a private CA. How do you make requests trust certificates signed by this CA?', 'Pass the CA bundle path to the verify parameter', 'Set verify=False globally', 'Install the CA cert in the system store only', 'Use a custom SSL context', 'A', 0, 'verify=''/path/to/company-ca-bundle.crt'' adds trust for the private CA.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_322', '322', 'Python Requests', 'Streaming Responses', 'Medium', 'scenario', 'You need to download a 2GB file without loading it all into memory. How should you approach this?', 'Use stream=True and iter_content() to write chunks to disk', 'Use response.content and write it all at once', 'Use response.text to save the file', 'Use requests.download(url)', 'A', 0, 'Streaming with chunked iteration prevents loading the entire file into memory.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_323', '323', 'Python Requests', 'Streaming Responses', 'Hard', 'scenario', 'You are consuming a server-sent events (SSE) stream. How do you read events line by line?', 'Use stream=True and response.iter_lines()', 'Use response.text.split(''\n'')', 'Use response.readlines()', 'Use response.events()', 'A', 0, 'iter_lines() yields lines from a streaming response, ideal for SSE.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_324', '324', 'Python Requests', 'File Upload', 'Easy', 'scenario', 'You need to upload a profile picture to an API. How do you send the file?', 'requests.post(url, files={''avatar'': open(''photo.jpg'', ''rb'')})', 'requests.post(url, data=open(''photo.jpg'', ''rb''))', 'requests.upload(url, ''photo.jpg'')', 'requests.post(url, file=''photo.jpg'')', 'A', 0, 'The files parameter handles multipart file uploads correctly.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_325', '325', 'Python Requests', 'File Upload', 'Medium', 'scenario', 'You need to upload a file along with additional form fields. How do you accomplish this?', 'Use both files and data parameters in requests.post()', 'Combine file and form data in the files parameter', 'Send two separate requests', 'Use json parameter for both', 'A', 0, 'files and data can be used together for multipart uploads with additional form fields.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_326', '326', 'Python Requests', 'File Upload', 'Hard', 'scenario', 'You need to upload a large file without loading it all into memory. What approach should you use?', 'Open the file in binary mode and pass it to data for streaming upload', 'Read the entire file into memory first', 'Encode it as base64 in JSON', 'Split it into multiple requests', 'A', 0, 'Passing an open file object to data streams it without loading everything into memory.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_327', '327', 'Python Requests', 'Cookies', 'Easy', 'scenario', 'An API sets a session cookie on login. How do you ensure it is sent with subsequent requests?', 'Use a requests.Session() which automatically manages cookies', 'Manually copy cookies between requests', 'Set cookies in the headers dict', 'Use a cookie file', 'A', 0, 'Sessions automatically store and send cookies across requests.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_328', '328', 'Python Requests', 'Cookies', 'Medium', 'scenario', 'You need to send a specific cookie with a single request without a session. How do you do it?', 'requests.get(url, cookies={''session_id'': ''abc123''})', 'requests.get(url, headers={''cookie'': ''abc123''})', 'requests.get(url, cookie=''session_id=abc123'')', 'requests.get(url, jar={''session_id'': ''abc123''})', 'A', 0, 'The cookies parameter accepts a dict of cookie name-value pairs.', '');
