INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_330', '330', 'Python Requests', 'Redirects', 'Easy', 'scenario', 'You want to know the final URL after an API redirect. How do you find it?', 'Check response.url after the request completes', 'Check response.redirect_url', 'Check response.headers[''Location'']', 'Parse the HTML for the redirect', 'A', 0, 'response.url contains the final URL after all redirects.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_331', '331', 'Python Requests', 'Redirects', 'Medium', 'scenario', 'You need to inspect where a URL redirects without following the redirect. How do you do this?', 'Set allow_redirects=False and check the Location header', 'Parse the HTML response', 'Use response.redirect_url', 'Use requests.head(url)', 'A', 0, 'allow_redirects=False returns the redirect response with the Location header.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_332', '332', 'Python Requests', 'Redirects', 'Hard', 'scenario', 'A login API uses a 302 redirect after authentication, but your POST data is lost. Why?', '302 redirects convert POST to GET, losing the body', 'The server rejected the data', 'Cookies were not sent', 'The timeout expired', 'A', 0, '302 redirect causes a POST-to-GET conversion, which drops the request body.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_333', '333', 'Python Requests', 'Error Handling', 'Easy', 'scenario', 'Your code should handle network errors gracefully. Which exception should you catch?', 'requests.exceptions.ConnectionError', 'ConnectionRefusedError', 'socket.error', 'OSError', 'A', 0, 'ConnectionError covers network-related failures in the requests library.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_334', '334', 'Python Requests', 'Error Handling', 'Medium', 'scenario', 'You want to handle any possible error from the requests library. What exception should you catch?', 'requests.exceptions.RequestException', 'Exception', 'requests.exceptions.HTTPError', 'requests.exceptions.ConnectionError', 'A', 0, 'RequestException is the base class for all requests exceptions.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_335', '335', 'Python Requests', 'Error Handling', 'Hard', 'scenario', 'An API sometimes returns 429 Too Many Requests. How should you handle this with retry logic?', 'Use Retry with status_forcelist=[429] and respect the Retry-After header', 'Catch HTTPError and sleep for a fixed time', 'Ignore the error and retry immediately', 'Switch to a different API', 'A', 0, 'Retry with status_forcelist=[429] and backoff_factor automatically handles rate limiting.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_336', '336', 'Python Requests', 'Mock Testing with responses', 'Easy', 'scenario', 'You need to test code that calls an external API without making real HTTP requests. What approach should you use?', 'Use the responses library to mock the requests', 'Comment out the API calls', 'Use a staging server', 'Mock the entire requests module with unittest.mock', 'A', 0, 'The responses library provides simple and effective mocking for requests calls.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_337', '337', 'Python Requests', 'Mock Testing with responses', 'Medium', 'scenario', 'You need to test that your code properly handles a 500 server error. How do you simulate it?', 'Use responses.add() with status=500', 'Make the real server return 500', 'Raise an exception manually', 'Use unittest.mock to patch the status code', 'A', 0, 'responses.add() can simulate any status code for testing error handling.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_338', '338', 'Python Requests', 'Mock Testing with responses', 'Hard', 'scenario', 'You need to test retry logic by having the first request fail and the second succeed. How do you set this up?', 'Add two responses: first with status=500, second with status=200', 'Use a callback function that counts calls', 'This is not possible with the responses library', 'Use a custom mock server', 'A', 0, 'responses.add() can be called multiple times for the same URL; they are returned in order.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_339', '339', 'Python Requests', 'GET Requests', 'Medium', 'scenario', 'You need to download data from an API that requires both an API key header and query parameters. How do you structure the request?', 'requests.get(url, headers={''X-API-Key'': key}, params={''q'': ''search''})', 'requests.get(url + ''?q=search'', api_key=key)', 'requests.get(url, key=key, query=''search'')', 'requests.get(url, auth=key, params=''q=search'')', 'A', 0, 'Headers and params are separate keyword arguments that can be combined.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_340', '340', 'Python Requests', 'POST Requests', 'Medium', 'scenario', 'An API endpoint accepts both JSON data and file uploads in the same request. What is the best approach?', 'Send files via the files parameter and additional data via the data parameter', 'Use json parameter with base64-encoded file', 'Make two separate requests', 'Combine everything in the json parameter', 'A', 0, 'files and data parameters can be combined for multipart requests with mixed content.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_341', '341', 'Python Requests', 'Response Handling', 'Hard', 'scenario', 'You receive a response with encoding issues - the text shows garbled characters. How do you fix this?', 'Set response.encoding to the correct encoding before accessing response.text', 'Use response.content.decode(''utf-8'')', 'Use response.raw to get unprocessed data', 'Re-send the request with Accept-Charset header', 'A', 0, 'Setting response.encoding before accessing .text fixes encoding issues.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_342', '342', 'Python Requests', 'Headers', 'Hard', 'scenario', 'An API uses ETags for caching. How do you implement conditional requests?', 'Send the ETag in the If-None-Match header and check for 304 status', 'Cache the response locally and check timestamps', 'Use the Expires header only', 'Set Cache-Control: no-cache', 'A', 0, 'Sending If-None-Match with the ETag allows 304 Not Modified responses for caching.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_343', '343', 'Python Requests', 'Session Management', 'Medium', 'scenario', 'You need different authentication for different API hosts in the same application. How do you handle this?', 'Create separate Session objects for each host', 'Use a single session and change auth before each request', 'Set auth in headers instead', 'Use a global auth variable', 'A', 0, 'Separate sessions keep authentication and settings isolated per host.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_344', '344', 'Python Requests', 'Timeout Handling', 'Hard', 'scenario', 'You need to limit the total time spent on a request including retries. How do you implement this?', 'Use a combination of per-request timeout and a total timer with a deadline', 'Set timeout to the total time divided by retry count', 'Use only the timeout parameter', 'Use asyncio timeout', 'A', 0, 'Combine per-request timeout with an external deadline timer to limit total time.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_345', '345', 'Python Requests', 'Retry Mechanism', 'Hard', 'scenario', 'Your retry strategy should only retry on GET and HEAD methods, not POST. How do you configure this?', 'Set allowed_methods=[''GET'', ''HEAD''] in the Retry object', 'Filter methods in a try/except loop', 'Use separate adapters for different methods', 'Use method_whitelist=[''GET'', ''HEAD'']', 'A', 0, 'allowed_methods in the Retry object restricts which HTTP methods are retried.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_346', '346', 'Python Requests', 'SSL Verification', 'Medium', 'scenario', 'You need to verify the server certificate but also send a client certificate. How do you configure both?', 'Use verify=True (or path to CA) and cert=(''/path/client.cert'', ''/path/client.key'')', 'Use verify=''/path/client.cert''', 'Set both in the headers', 'Use SSL context only', 'A', 0, 'verify handles server cert validation; cert provides client certificate authentication.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_347', '347', 'Python Requests', 'Streaming Responses', 'Medium', 'scenario', 'You are processing a large JSON Lines file from an API. How do you efficiently process each line?', 'Use stream=True and response.iter_lines() to process each JSON line', 'Download the entire file then split by newlines', 'Use response.json() which handles JSON Lines', 'Use json.loads(response.text)', 'A', 0, 'iter_lines() with stream=True processes each line without loading the entire response.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_348', '348', 'Python Requests', 'Redirects', 'Hard', 'scenario', 'A POST request to an API returns 307 Temporary Redirect. How does requests handle this differently from 302?', '307 preserves the HTTP method and body; the POST is repeated to the new URL', '307 and 302 are handled the same way', '307 converts POST to GET like 302', '307 is not supported by requests', 'A', 0, '307 preserves the method and body, unlike 302 which converts POST to GET.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_349', '349', 'Python Requests', 'Error Handling', 'Hard', 'scenario', 'You need to distinguish between a server being down (ConnectionError) and the server responding with an error (HTTPError). How do you structure your error handling?', 'Use separate except blocks for ConnectionError and HTTPError', 'Catch RequestException and check the type', 'Check response.status_code only', 'Use response.ok only', 'A', 0, 'Separate except blocks allow different handling for network vs server errors.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_350', '350', 'Python Requests', 'Mock Testing with responses', 'Hard', 'scenario', 'You need to test code that uses a Session with retry logic. How do you mock the responses?', 'The responses library intercepts at the transport level, so sessions and retries work normally with mocked responses', 'You must mock the Session class directly', 'responses does not work with Sessions', 'Use unittest.mock instead', 'A', 0, 'responses intercepts HTTP calls regardless of whether sessions or retries are used.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_351', '351', 'Python Requests', 'Request Body', 'Hard', 'scenario', 'You need to send a binary protobuf payload in a POST request. How do you do this?', 'Pass the serialised bytes to data and set Content-Type header to application/protobuf', 'Use the json parameter with the protobuf', 'Use the files parameter', 'Use the proto parameter', 'A', 0, 'Binary data is sent via data parameter with the appropriate Content-Type header.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_352', '352', 'Python Requests', 'Authentication - Bearer Token', 'Hard', 'scenario', 'Your access token expires after 1 hour. How do you implement automatic token refresh in requests?', 'Create a custom auth class extending AuthBase that refreshes the token when needed', 'Check token expiry before each request manually', 'Use a global variable for the token', 'Set a timeout of 1 hour', 'A', 0, 'A custom AuthBase subclass can intercept requests and refresh tokens automatically.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_353', '353', 'Python Requests', 'Authentication - OAuth', 'Hard', 'scenario', 'You need to implement the OAuth2 client credentials flow for machine-to-machine authentication. What approach works?', 'POST to the token endpoint with client_id and client_secret, then use the returned token', 'Use Basic Auth with client credentials', 'Use requests-oauthlib with user authorization', 'Pass credentials as query parameters', 'A', 0, 'Client credentials flow involves POSTing to the token endpoint to get an access token.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_354', '354', 'Python Requests', 'Session Management', 'Hard', 'scenario', 'You need to log and inspect all HTTP requests and responses made through a session. How do you implement this?', 'Mount a custom adapter or use the built-in logging with urllib3 debug logging', 'Override session.get()', 'Use a global request hook', 'This is not possible with requests', 'A', 0, 'Custom adapters or event hooks can intercept and log all requests and responses.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_355', '355', 'Python Requests', 'File Upload', 'Hard', 'scenario', 'An API requires a multipart upload with a specific boundary string. How do you control this?', 'Prepare the request manually using PreparedRequest and set the Content-Type with the custom boundary', 'Use the boundary parameter in files', 'Set boundary in headers', 'The boundary is always random', 'A', 0, 'PreparedRequest allows full control over the multipart boundary.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_356', '356', 'Python Requests', 'Cookies', 'Hard', 'scenario', 'You need to share cookies between a requests Session and a Selenium WebDriver. How do you transfer cookies?', 'Extract cookies from Selenium and set them on the Session using session.cookies.update()', 'Export to a file and import in the other', 'Cookies are incompatible between the two', 'Use a shared cookie jar', 'A', 0, 'Session cookies can be updated with cookies extracted from Selenium''s driver.get_cookies().', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_357', '357', 'Python Requests', 'GET Requests', 'Hard', 'scenario', 'You need to make a conditional GET request that only downloads data if it has changed since your last request. How do you implement this?', 'Use If-Modified-Since or If-None-Match headers and check for 304 response', 'Compare response.text with cached data', 'Use a hash of the response body', 'Set cache=True in the request', 'A', 0, 'Conditional headers enable efficient caching with 304 Not Modified responses.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_358', '358', 'Python Requests', 'POST Requests', 'Hard', 'scenario', 'You need to send a request with chunked transfer encoding. How do you achieve this?', 'Pass a generator to the data parameter', 'Set headers={''Transfer-Encoding'': ''chunked''}', 'Use stream=True', 'Set chunked=True in the request', 'A', 0, 'Generators passed to data trigger chunked transfer encoding automatically.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_359', '359', 'Python Requests', 'Error Handling', 'Medium', 'scenario', 'Your code needs to retry on ConnectionError but not on HTTPError. How do you structure this?', 'Use separate except clauses and only retry in the ConnectionError handler', 'Catch RequestException and retry for all errors', 'Use raise_for_status() in the retry loop', 'Retry on all exceptions', 'A', 0, 'Separate exception handling allows selective retry logic for specific error types.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_360', '360', 'Python Requests', 'Timeout Handling', 'Medium', 'scenario', 'You are making requests to multiple APIs with different timeout requirements. How do you manage this?', 'Set different timeout values per request or use different Session objects', 'Set a global timeout for all requests', 'Use the longest timeout for all requests', 'Timeouts cannot vary between requests', 'A', 0, 'Each request can have its own timeout parameter for fine-grained control.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_361', '361', 'Python Requests', 'Retry Mechanism', 'Medium', 'scenario', 'You want retries to use exponential backoff starting at 1 second. What backoff_factor should you use?', 'backoff_factor=1', 'backoff_factor=0.5', 'backoff_factor=2', 'backoff_factor=0.1', 'A', 0, 'backoff_factor=1 gives delays of 1s, 2s, 4s... between retries.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_362', '362', 'Python Requests', 'SSL Verification', 'Hard', 'scenario', 'Your application runs in a Docker container and needs to trust the host''s CA certificates. How do you handle this?', 'Mount the host CA bundle into the container and point requests to it via verify or REQUESTS_CA_BUNDLE', 'Set verify=False in all requests', 'Install certifi inside the container only', 'Use the system certificate store automatically', 'A', 0, 'Mounting the host CA bundle and configuring requests to use it is the proper approach.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_363', '363', 'Python Requests', 'Streaming Responses', 'Hard', 'scenario', 'You need to process a streaming response that sends data indefinitely (like a Twitter firehose). How do you handle connection drops?', 'Use iter_lines() in a loop with reconnection logic and timeout', 'Use response.text which buffers everything', 'Set a very large timeout', 'Use WebSockets instead', 'A', 0, 'iter_lines() with reconnection logic handles long-lived streams with potential drops.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_364', '364', 'Python Requests', 'Mock Testing with responses', 'Medium', 'scenario', 'You need to verify that your code sends the correct request headers when calling an API. How do you check this?', 'Use responses.calls[0].request.headers to inspect sent headers', 'Print the headers in the production code', 'Use a proxy to inspect traffic', 'Check response.request.headers', 'A', 0, 'responses.calls records all requests including their headers for inspection.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_365', '365', 'Python Requests', 'Headers', 'Medium', 'scenario', 'You need to send a request that accepts both JSON and XML responses, preferring JSON. How do you set the Accept header?', 'headers={''Accept'': ''application/json, application/xml;q=0.9''}', 'headers={''Accept'': ''json,xml''}', 'headers={''Accept'': ''application/json''} only', 'params={''accept'': ''json,xml''}', 'A', 0, 'Quality values (q=) in Accept header express preference for different content types.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_366', '366', 'Python Requests', 'Query Parameters', 'Medium', 'scenario', 'You need to send a query parameter with special characters like spaces and ampersands. How should you handle this?', 'Use the params dict and requests will URL-encode automatically', 'Manually encode with urllib.parse.quote', 'Replace spaces with + manually', 'Use raw strings in the URL', 'A', 0, 'The params parameter handles URL encoding of special characters automatically.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_367', '367', 'Python Requests', 'Request Body', 'Medium', 'scenario', 'An API accepts both form data and JSON. You need to send nested data. Which approach is better?', 'Use json= for nested data structures', 'Use data= for nested data structures', 'Use data= with manual flattening', 'Send nested data as query parameters', 'A', 0, 'JSON naturally supports nested structures; form encoding does not.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_368', '368', 'Python Requests', 'Response Handling', 'Medium', 'scenario', 'You need to save a binary response (like a PDF) to disk. What is the correct approach?', 'Write response.content to a file opened in binary mode', 'Write response.text to a file', 'Use response.save(''file.pdf'')', 'Use json.dumps(response.content)', 'A', 0, 'response.content provides the raw bytes suitable for binary files.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_369', '369', 'Python Requests', 'Authentication - Basic', 'Hard', 'scenario', 'You need to use Digest authentication instead of Basic. How do you implement this?', 'Use requests.auth.HTTPDigestAuth(user, pass)', 'Use auth=(''user'', ''pass'', ''digest'')', 'Set headers manually with the digest hash', 'Digest auth is not supported', 'A', 0, 'HTTPDigestAuth from requests.auth provides HTTP Digest Authentication.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_370', '370', 'Python Requests', 'Session Management', 'Easy', 'scenario', 'You need to make API calls that require login first. What is the best approach?', 'Use a Session, login first, then make subsequent requests (cookies persist)', 'Login and copy the cookie manually to each request', 'Include credentials in every request', 'Use a global cookie variable', 'A', 0, 'Sessions automatically persist login cookies for subsequent requests.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_371', '371', 'Python Requests', 'File Upload', 'Medium', 'scenario', 'You need to upload a CSV file with specific MIME type ''text/csv''. How do you specify this?', 'files={''file'': (''data.csv'', open(''data.csv'', ''rb''), ''text/csv'')}', 'files={''file'': open(''data.csv'', ''rb''), ''type'': ''text/csv''}', 'files={''file'': open(''data.csv'')}, content_type=''text/csv''', 'headers={''Content-Type'': ''text/csv''}, data=open(''data.csv'')', 'A', 0, 'A tuple with (filename, file_object, content_type) sets the MIME type per file.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_372', '372', 'Python Requests', 'Cookies', 'Medium', 'scenario', 'After login, you want to inspect what cookies the server set. How do you do this?', 'Check response.cookies or session.cookies', 'Check response.headers[''Set-Cookie''] manually', 'Parse the response body for cookies', 'Use browser developer tools', 'A', 0, 'response.cookies provides easy access to cookies set by the server.', '');
