INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_374', '374', 'Python Requests', 'Error Handling', 'Easy', 'scenario', 'Your script crashes when the internet connection drops. How do you make it more robust?', 'Wrap requests calls in try/except for ConnectionError', 'Use a faster internet connection', 'Set verify=False', 'Increase the timeout', 'A', 0, 'Catching ConnectionError prevents crashes due to network issues.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_375', '375', 'Python Requests', 'Mock Testing with responses', 'Easy', 'scenario', 'You want to test your API client without hitting the real API during CI/CD. What do you use?', 'The responses library to mock all HTTP calls', 'A staging environment', 'VCR.py only', 'Manual stubs with unittest.mock.patch', 'A', 0, 'The responses library provides easy mocking specifically designed for the requests library.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_376', '376', 'Python Requests', 'GET Requests', 'Easy', 'scenario', 'You need to check if a resource exists on a server without downloading the full content. Which is more efficient?', 'Use requests.head(url) to send a HEAD request', 'Use requests.get(url) and ignore the body', 'Use requests.options(url)', 'Use requests.get(url, stream=True)', 'A', 0, 'HEAD requests retrieve only headers, not the body, making them efficient for existence checks.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_377', '377', 'Python Requests', 'POST Requests', 'Easy', 'scenario', 'You need to submit a contact form with name, email, and message fields. What is the simplest approach?', 'requests.post(url, data={''name'': ''John'', ''email'': ''j@e.com'', ''message'': ''Hi''})', 'requests.get(url, params={''name'': ''John'', ''email'': ''j@e.com''})', 'requests.post(url, body=''name=John&email=j@e.com'')', 'requests.submit(url, form={''name'': ''John''})', 'A', 0, 'POST with data dict is the standard way to submit form data.', '');
