INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_382', '382', 'Python Requests', 'Query Parameters', 'Hard', 'scenario', 'You need to send a query parameter with the same key multiple times (e.g., for multi-select filters). How do you handle this?', 'Use params={''color'': [''red'', ''blue'']} or params=[(''color'', ''red''), (''color'', ''blue'')]', 'Use params={''color'': ''red,blue''}', 'Send two separate requests', 'Use params={''color[]'': [''red'', ''blue'']}', 'A', 0, 'Lists as values or list of tuples allow duplicate keys in query parameters.', '');
