INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_390', '390', 'Python Requests', 'Error Handling', 'Hard', 'scenario', 'Your application needs to retry on network errors but fail immediately on authentication errors (401). How do you implement this?', 'Catch ConnectionError for retries; catch HTTPError and check status_code for 401 to fail immediately', 'Use status_forcelist to exclude 401', 'Catch all exceptions and retry', 'Use separate Session objects', 'A', 0, 'Differentiated exception handling allows retry on network errors but immediate failure on 401.', '');
