INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_394', '394', 'Python Requests', 'POST Requests', 'Hard', 'scenario', 'You need to send a webhook notification with a JSON payload and HMAC signature header. How do you structure this?', 'Compute HMAC of the body, set it as a header, and use json= for the payload', 'Use the auth parameter with HMAC', 'Send HMAC in the query string', 'Use a special webhook parameter', 'A', 0, 'The HMAC signature is typically sent as a custom header alongside the JSON body.', '');
