INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('Python Requests_398', '398', 'Python Requests', 'Timeout Handling', 'Hard', 'scenario', 'You need to implement a circuit breaker pattern for an unreliable API. What combination of features would you use?', 'Track failures with a counter, use timeout and retry, and stop requests when failure threshold is reached', 'Just set a very long timeout', 'Only use retry with no limit', 'Switch to async requests', 'A', 0, 'A circuit breaker combines failure tracking, timeouts, and retries with a threshold.', '');
