INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_1', '1', 'SQL', 'Aggregate Functions', 'Easy', 'mcq', 'Which function returns the number of rows in a result set in SQL?', 'TOTAL()', 'NUM()', 'SUM()', 'COUNT()', 'D', 3, 'COUNT() returns the number of rows that match the specified criteria.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_2', '2', 'SQL', 'Stored Procedures', 'Hard', 'mcq', 'What is the difference between a stored procedure and a user-defined function (UDF)?', 'There is no difference', 'Procedures must return a value; UDFs do not', 'UDFs cannot accept parameters', 'UDFs must return a value and can be used in SELECT; procedures may not return a value', 'D', 3, 'UDFs are required to return a value and can be used in expressions; stored procedures are more flexible but cannot be called inline in queries.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_3', '3', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Easy', 'mcq', 'What does the IN operator do in a WHERE clause?', 'Checks for NULL values', 'Checks if a value matches any value in a list', 'Checks if a value is between two values', 'Checks for pattern matches', 'B', 1, 'The IN operator allows you to specify multiple values in a WHERE clause, equivalent to multiple OR conditions.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_4', '4', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Hard', 'mcq', 'What is a NATURAL JOIN?', 'A join that returns only unique rows', 'A join that automatically matches columns with the same name in both tables', 'A join on the primary key only', 'A join that uses no condition', 'B', 1, 'NATURAL JOIN automatically joins tables on all columns that share the same name and data type.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_5', '5', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Medium', 'mcq', 'Which JOIN type includes all rows from both tables even if there is no match in SQL?', 'FULL OUTER JOIN', 'LEFT JOIN', 'INNER JOIN', 'CROSS JOIN', 'A', 0, 'FULL OUTER JOIN returns all rows from both tables, placing NULLs where there is no match.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_6', '6', 'SQL', 'NoSQL Concepts', 'Easy', 'mcq', 'What does NoSQL stand for?', 'Non-SQL', 'Not Only SQL', 'New SQL', 'No Structured Query Language', 'B', 1, 'NoSQL stands for ''Not Only SQL'', indicating these databases may support SQL-like queries but are not limited to relational models.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_7', '7', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Medium', 'mcq', 'What is the difference between DROP and TRUNCATE in SQL?', 'DROP is faster than TRUNCATE', 'They are identical', 'TRUNCATE removes the table; DROP removes rows', 'DROP removes the table entirely; TRUNCATE removes all rows but keeps the structure', 'D', 3, 'DROP removes the table definition and data; TRUNCATE keeps the table structure but removes all rows quickly.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_8', '8', 'SQL', 'Views', 'Easy', 'mcq', 'Which statement creates a view in SQL?', 'MAKE VIEW', 'CREATE VIEW', 'ADD VIEW', 'DEFINE VIEW', 'B', 1, 'CREATE VIEW defines a new view based on a SELECT query.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_9', '9', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Medium', 'mcq', 'Which operator is used to search for a specified pattern in a column?', 'MATCH', 'PATTERN', 'SEARCH', 'LIKE', 'D', 3, 'The LIKE operator is used in a WHERE clause to search for a specified pattern using wildcards (% and _).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_10', '10', 'SQL', 'Window Functions', 'Medium', 'mcq', 'What does PARTITION BY do in a window function?', 'Orders the result set', 'Divides the result set into partitions to which the window function is applied independently', 'Limits the number of partitions', 'Filters rows', 'B', 1, 'PARTITION BY divides rows into groups (partitions). The window function is computed separately for each partition.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_11', '11', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Medium', 'mcq', 'What does ALTER TABLE employees ADD COLUMN bonus DECIMAL(10,2); do?', 'Renames the employees table', 'Creates a new table called bonus', 'Deletes the bonus column', 'Adds a new column named bonus to the employees table', 'D', 3, 'ALTER TABLE with ADD COLUMN adds a new column with the specified data type to an existing table.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_12', '12', 'SQL', 'Aggregate Functions', 'Hard', 'mcq', 'Can aggregate functions be nested, such as MAX(AVG(salary)) in SQL?', 'Only with GROUP BY', 'Not directly in standard SQL; you need a subquery or CTE', 'Yes, always', 'Only in PostgreSQL', 'B', 1, 'Standard SQL does not allow nested aggregates directly. You must use a subquery or CTE to first compute the inner aggregate.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_13', '13', 'SQL', 'SELECT basics', 'Hard', 'mcq', 'What is the difference between SELECT DISTINCT and SELECT ALL?', 'DISTINCT is faster than ALL', 'DISTINCT removes duplicates; ALL keeps them (default)', 'ALL removes duplicates; DISTINCT keeps them', 'They are identical', 'B', 1, 'SELECT ALL is the default behavior that returns all rows including duplicates, while DISTINCT removes duplicate rows.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_14', '14', 'SQL', 'SELECT basics', 'Easy', 'mcq', 'Which keyword limits the number of rows returned in MySQL in SQL?', 'TOP', 'FETCH', 'LIMIT', 'ROWNUM', 'C', 2, 'In MySQL and PostgreSQL, LIMIT restricts the number of rows returned by a query.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_15', '15', 'SQL', 'Window Functions', 'Medium', 'mcq', 'What is the difference between RANK() and DENSE_RANK()?', 'DENSE_RANK() leaves gaps; RANK() does not', 'They always produce the same result', 'RANK() only works with numeric columns', 'RANK() leaves gaps after ties; DENSE_RANK() does not', 'D', 3, 'RANK() skips rank numbers after ties (e.g., 1,1,3), while DENSE_RANK() does not skip (1,1,2).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_16', '16', 'SQL', 'Triggers', 'Hard', 'mcq', 'Can a trigger call another trigger (trigger chaining) in SQL?', 'Only in MySQL', 'Yes, a trigger can cause another trigger to fire, leading to nested/cascading triggers', 'Only AFTER triggers can chain', 'No, only one trigger can fire per operation', 'B', 1, 'Triggers can cascade: one trigger''s action can activate another trigger. Most databases allow configuring the maximum nesting depth.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_17', '17', 'SQL', 'Window Functions', 'Easy', 'mcq', 'Which keyword defines a window in a window function?', 'FRAME', 'WINDOW', 'OVER', 'PARTITION', 'C', 2, 'The OVER() clause defines the window (partition and ordering) for a window function.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_18', '18', 'SQL', 'NoSQL Concepts', 'Hard', 'mcq', 'What is eventual consistency in distributed databases?', 'Data is consistent only during transactions', 'All reads always return the latest write', 'Consistency is never achieved', 'All replicas will converge to the same state given enough time without new updates', 'D', 3, 'Eventual consistency guarantees that if no new updates are made, all replicas will eventually return the same value.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_19', '19', 'SQL', 'SELECT basics', 'Medium', 'mcq', 'What is the result of SELECT DISTINCT department FROM employees in SQL?', 'All department values including duplicates', 'Department names sorted alphabetically', 'Unique department values only', 'Count of departments', 'C', 2, 'DISTINCT eliminates duplicate rows from the result set.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_20', '20', 'SQL', 'Window Functions', 'Hard', 'mcq', 'What does NTILE(4) OVER (ORDER BY score DESC) do in SQL?', 'Returns the top 4 scores', 'Divides the result set into 4 roughly equal groups ranked by score descending', 'Returns every 4th row', 'Calculates the 4th percentile', 'B', 1, 'NTILE(n) distributes rows into n approximately equal buckets based on the specified ordering.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_21', '21', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Medium', 'mcq', 'What does IS NULL check for?', 'Whether a value is NULL', 'Whether a value is zero', 'Whether a column exists', 'Whether a value is an empty string', 'A', 0, 'IS NULL tests whether a value is NULL; you cannot use = NULL because NULL is not equal to anything, including itself.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_22', '22', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Hard', 'mcq', 'Can you use a column alias defined in SELECT inside the WHERE clause?', 'Only with numeric aliases', 'Yes, always', 'Only in MySQL', 'No, because WHERE is processed before SELECT', 'D', 3, 'Because WHERE is logically processed before SELECT, column aliases from SELECT are not available in WHERE.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_23', '23', 'SQL', 'Views', 'Hard', 'mcq', 'What is the WITH CHECK OPTION in a view?', 'Validates the view definition', 'Checks for NULL values', 'Adds a constraint to the base table', 'Ensures that INSERT/UPDATE through the view satisfy the view''s WHERE condition', 'D', 3, 'WITH CHECK OPTION prevents data modifications through a view that would make the row disappear from the view.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_24', '24', 'SQL', 'DML (INSERT/UPDATE/DELETE)', 'Medium', 'mcq', 'What does INSERT INTO ... SELECT do in SQL?', 'Inserts rows from a SELECT query result into a table', 'Creates a new table from a query', 'Updates existing rows', 'Copies the table structure only', 'A', 0, 'INSERT INTO ... SELECT copies data from one or more tables into another table using the results of a SELECT query.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_25', '25', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Hard', 'mcq', 'What does CASCADE do in a DROP TABLE statement in SQL?', 'Deletes rows in related tables', 'Creates a backup before dropping', 'Prevents the table from being dropped', 'Automatically drops dependent objects like foreign keys and views', 'D', 3, 'CASCADE automatically drops objects that depend on the table (such as foreign key constraints and views referencing it).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_26', '26', 'SQL', 'Transactions', 'Medium', 'mcq', 'What does ROLLBACK do?', 'Starts a new transaction', 'Undoes all changes made in the current transaction', 'Locks the table', 'Saves the current transaction', 'B', 1, 'ROLLBACK reverses all changes made since the last COMMIT or the start of the transaction.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_27', '27', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Easy', 'mcq', 'Which clause is used to filter rows in a SELECT statement?', 'LIMIT', 'FILTER', 'WHERE', 'HAVING', 'C', 2, 'The WHERE clause filters rows before any grouping takes place.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_28', '28', 'SQL', 'Aggregate Functions', 'Medium', 'mcq', 'What does COUNT(*) vs COUNT(column_name) differ in in SQL?', 'COUNT(column) counts all rows including NULLs', 'COUNT(*) counts all rows; COUNT(column) skips NULLs in that column', 'COUNT(*) is faster', 'They are identical', 'B', 1, 'COUNT(*) counts every row regardless of NULLs; COUNT(column) ignores rows where that column is NULL.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_29', '29', 'SQL', 'Triggers', 'Hard', 'mcq', 'Can a trigger call another trigger (trigger chaining)?', 'No, only one trigger can fire per operation', 'Yes, a trigger can cause another trigger to fire, leading to nested/cascading triggers', 'Only in MySQL', 'Only AFTER triggers can chain', 'B', 1, 'Triggers can cascade: one trigger''s action can activate another trigger. Most databases allow configuring the maximum nesting depth.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_30', '30', 'SQL', 'Views', 'Easy', 'mcq', 'What is a view in SQL?', 'A type of index', 'A virtual table based on a SELECT query', 'A stored procedure', 'A physical copy of a table', 'B', 1, 'A view is a virtual table defined by a query; it does not store data itself but presents data from underlying tables.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_31', '31', 'SQL', 'Window Functions', 'Easy', 'mcq', 'Do window functions reduce the number of rows in the result set?', 'Only RANK() reduces rows', 'No, they add computed values without reducing rows', 'Yes, they group rows like GROUP BY', 'Yes, they filter rows', 'B', 1, 'Unlike aggregate functions with GROUP BY, window functions compute values across a set of rows while retaining all original rows.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_32', '32', 'SQL', 'Triggers', 'Medium', 'mcq', 'What are BEFORE and AFTER triggers?', 'BEFORE works only with INSERT; AFTER works only with DELETE', 'AFTER fires before the operation; BEFORE fires after', 'They are identical', 'BEFORE fires before the DML operation; AFTER fires after it completes', 'D', 3, 'BEFORE triggers execute before the triggering event and can modify the data; AFTER triggers execute after the event.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_33', '33', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Hard', 'mcq', 'Can you use a column alias defined in SELECT inside the WHERE clause in SQL?', 'No, because WHERE is processed before SELECT', 'Only in MySQL', 'Only with numeric aliases', 'Yes, always', 'A', 0, 'Because WHERE is logically processed before SELECT, column aliases from SELECT are not available in WHERE.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_34', '34', 'SQL', 'Indexes', 'Easy', 'mcq', 'What SQL statement creates an index?', 'BUILD INDEX', 'MAKE INDEX', 'CREATE INDEX', 'ADD INDEX', 'C', 2, 'CREATE INDEX is the DDL statement to create an index on one or more columns of a table.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_35', '35', 'SQL', 'SELECT basics', 'Medium', 'mcq', 'What does the CASE expression do in SQL?', 'Sorts results', 'Creates a new table', 'Provides conditional logic similar to IF-THEN-ELSE within a query', 'Converts data types', 'C', 2, 'CASE evaluates conditions and returns a value when the first condition is met, like an IF-ELSE statement.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_36', '36', 'SQL', 'Aggregate Functions', 'Medium', 'mcq', 'What does COUNT(*) vs COUNT(column_name) differ in?', 'COUNT(*) counts all rows; COUNT(column) skips NULLs in that column', 'They are identical', 'COUNT(*) is faster', 'COUNT(column) counts all rows including NULLs', 'A', 0, 'COUNT(*) counts every row regardless of NULLs; COUNT(column) ignores rows where that column is NULL.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_37', '37', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Hard', 'mcq', 'What is the difference between ON and USING in a JOIN clause?', 'USING can reference columns from only one table', 'They are identical', 'USING specifies a common column name; ON allows arbitrary conditions', 'ON works only with INNER JOIN', 'C', 2, 'USING(col) is shorthand when both tables share the same column name; ON allows any boolean expression.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_38', '38', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Medium', 'mcq', 'What is a foreign key?', 'A column that references the primary key of another table', 'A unique identifier for each row', 'A key used for encryption', 'An index on multiple columns', 'A', 0, 'A foreign key establishes a link between two tables by referencing the primary key (or unique key) of another table.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_39', '39', 'SQL', 'Aggregate Functions', 'Hard', 'mcq', 'What does GROUP_CONCAT (MySQL) / STRING_AGG (SQL Server/PostgreSQL) do?', 'Counts strings in a group', 'Splits a string into rows', 'Groups rows by string length', 'Concatenates values from multiple rows into a single string', 'D', 3, 'These functions aggregate string values from multiple rows into one concatenated string per group.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_40', '40', 'SQL', 'Indexes', 'Hard', 'mcq', 'What is a covering index?', 'An index on every column of a table', 'An index that covers multiple tables', 'An index that contains all columns needed by a query, avoiding table lookups', 'An index used only for JOIN operations', 'C', 2, 'A covering index includes all columns referenced in a query, so the database can satisfy the query entirely from the index.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_41', '41', 'SQL', 'Window Functions', 'Easy', 'mcq', 'Which keyword defines a window in a window function in SQL?', 'FRAME', 'WINDOW', 'PARTITION', 'OVER', 'D', 3, 'The OVER() clause defines the window (partition and ordering) for a window function.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_42', '42', 'SQL', 'SELECT basics', 'Hard', 'mcq', 'What is the purpose of the NULLIF function?', 'Counts NULL values', 'Returns NULL if the expression is zero', 'Replaces NULL with a default value', 'Returns NULL if two expressions are equal; otherwise returns the first expression', 'D', 3, 'NULLIF(expr1, expr2) returns NULL if expr1 equals expr2; otherwise it returns expr1. It is useful to avoid division by zero.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_43', '43', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Easy', 'mcq', 'What keyword is used to combine rows from two tables based on a related column in SQL?', 'JOIN', 'COMBINE', 'MERGE', 'UNION', 'A', 0, 'JOIN is used to combine rows from two or more tables based on a related column between them.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_44', '44', 'SQL', 'Triggers', 'Easy', 'mcq', 'What is a trigger in SQL?', 'A type of stored procedure called explicitly', 'A constraint on a column', 'A set of SQL statements that automatically executes when a specified event occurs', 'A manual query execution', 'C', 2, 'A trigger is a database object that is automatically fired in response to certain events like INSERT, UPDATE, or DELETE.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_45', '45', 'SQL', 'SELECT basics', 'Medium', 'mcq', 'What is the result of SELECT DISTINCT department FROM employees?', 'Unique department values only', 'Department names sorted alphabetically', 'Count of departments', 'All department values including duplicates', 'A', 0, 'DISTINCT eliminates duplicate rows from the result set.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_46', '46', 'SQL', 'SELECT basics', 'Medium', 'mcq', 'What is the result of SELECT DISTINCT department FROM employees in SQL?', 'Department names sorted alphabetically', 'Count of departments', 'All department values including duplicates', 'Unique department values only', 'D', 3, 'DISTINCT eliminates duplicate rows from the result set.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_47', '47', 'SQL', 'Transactions', 'Hard', 'mcq', 'Which isolation level allows dirty reads?', 'READ UNCOMMITTED', 'SERIALIZABLE', 'READ COMMITTED', 'REPEATABLE READ', 'A', 0, 'READ UNCOMMITTED is the lowest isolation level and allows reading data that has been modified but not yet committed by other transactions.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_48', '48', 'SQL', 'Normalization', 'Hard', 'mcq', 'What is Boyce-Codd Normal Form (BCNF) in SQL?', 'A stricter version of 3NF where every determinant must be a candidate key', 'A denormalized form', 'A form that allows partial dependencies', 'The same as 3NF', 'A', 0, 'BCNF strengthens 3NF by requiring that for every functional dependency X -> Y, X must be a superkey.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_49', '49', 'SQL', 'Stored Procedures', 'Easy', 'mcq', 'What is a stored procedure in SQL?', 'A database backup method', 'A type of index', 'A temporary query', 'A precompiled collection of SQL statements stored in the database', 'D', 3, 'A stored procedure is a prepared SQL code that is saved and can be reused, often accepting parameters.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_50', '50', 'SQL', 'SELECT basics', 'Medium', 'mcq', 'What does the COALESCE function do?', 'Returns the first non-NULL value from a list of arguments', 'Converts NULL to zero', 'Counts non-NULL values', 'Combines two strings', 'A', 0, 'COALESCE evaluates arguments in order and returns the first non-NULL value.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_51', '51', 'SQL', 'Transactions', 'Easy', 'mcq', 'What SQL command saves all changes made during a transaction in SQL?', 'FINISH', 'APPLY', 'COMMIT', 'SAVE', 'C', 2, 'COMMIT permanently saves all changes made during the current transaction.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_52', '52', 'SQL', 'Indexes', 'Medium', 'mcq', 'What is a composite index?', 'An index on computed columns only', 'An index with a WHERE condition', 'An index that covers all columns', 'An index on two or more columns', 'D', 3, 'A composite (multi-column) index includes two or more columns and is useful when queries filter on multiple columns.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_53', '53', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Easy', 'mcq', 'Which JOIN returns only matching rows from both tables in SQL?', 'INNER JOIN', 'RIGHT JOIN', 'LEFT JOIN', 'FULL OUTER JOIN', 'A', 0, 'INNER JOIN returns only the rows that have matching values in both tables.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_54', '54', 'SQL', 'NoSQL Concepts', 'Medium', 'mcq', 'What type of NoSQL database is Neo4j in SQL?', 'Key-value store', 'Document store', 'Wide-column store', 'Graph database', 'D', 3, 'Neo4j is a graph database that stores data as nodes, relationships, and properties, optimized for traversing connections.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_55', '55', 'SQL', 'SELECT basics', 'Easy', 'mcq', 'What does SELECT * FROM employees; return?', 'Only the first row', 'Only column names', 'All columns and rows from the employees table', 'An error', 'C', 2, 'The asterisk (*) is a wildcard that selects all columns, and without a WHERE clause all rows are returned.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_56', '56', 'SQL', 'Query Optimization', 'Hard', 'mcq', 'What is predicate pushdown in query optimization in SQL?', 'Moving filter conditions closer to the data source to reduce the amount of data processed', 'Adding indexes automatically', 'Rewriting subqueries as joins', 'Removing predicates from the query', 'A', 0, 'Predicate pushdown moves WHERE conditions as early as possible in the query plan to filter data before expensive operations like joins.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_57', '57', 'SQL', 'SELECT basics', 'Medium', 'mcq', 'Which SQL statement is used to return only different values?', 'SELECT DISTINCT', 'SELECT UNIQUE', 'SELECT DIFFERENT', 'SELECT VARIED', 'A', 0, 'SELECT DISTINCT filters out duplicate rows from the result set.', '');
