INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_59', '59', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Medium', 'mcq', 'Which JOIN type includes all rows from both tables even if there is no match?', 'FULL OUTER JOIN', 'INNER JOIN', 'CROSS JOIN', 'LEFT JOIN', 'A', 0, 'FULL OUTER JOIN returns all rows from both tables, placing NULLs where there is no match.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_60', '60', 'SQL', 'Views', 'Easy', 'mcq', 'Which statement creates a view?', 'ADD VIEW', 'MAKE VIEW', 'CREATE VIEW', 'DEFINE VIEW', 'C', 2, 'CREATE VIEW defines a new view based on a SELECT query.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_61', '61', 'SQL', 'Views', 'Medium', 'mcq', 'What is a materialized view in SQL?', 'A regular view with an index', 'A view that stores the result set physically and can be refreshed', 'A view that is always up-to-date', 'A view that cannot be queried', 'B', 1, 'A materialized view physically stores query results and must be refreshed to reflect changes in the underlying data.', '');
