INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_64', '64', 'SQL', 'Window Functions', 'Hard', 'mcq', 'What does NTILE(4) OVER (ORDER BY score DESC) do in SQL?', 'Calculates the 4th percentile', 'Returns the top 4 scores', 'Returns every 4th row', 'Divides the result set into 4 roughly equal groups ranked by score descending', 'D', 3, 'NTILE(n) distributes rows into n approximately equal buckets based on the specified ordering.', '');
