INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_66', '66', 'SQL', 'Triggers', 'Hard', 'mcq', 'What is an INSTEAD OF trigger?', 'A trigger that replaces the original DML operation with custom logic', 'A trigger defined on indexes', 'A trigger that runs after every operation', 'A trigger that prevents all DML operations', 'A', 0, 'INSTEAD OF triggers replace the triggering action entirely; they are commonly used on views to make them updatable.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_67', '67', 'SQL', 'Query Optimization', 'Medium', 'mcq', 'What is an index scan vs an index seek?', 'A scan is always faster', 'A seek goes directly to specific rows; a scan reads the entire index', 'A seek reads the entire table', 'They are the same operation', 'B', 1, 'An index seek efficiently navigates the B-tree to find specific rows; an index scan reads all entries in the index sequentially.', '');
