INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_69', '69', 'SQL', 'Window Functions', 'Hard', 'mcq', 'Which window function returns a value from a preceding row without a self-join?', 'LEAD()', 'LAG()', 'FIRST_VALUE()', 'NTH_VALUE()', 'B', 1, 'LAG() accesses data from a previous row in the same result set without needing a self-join.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_70', '70', 'SQL', 'Triggers', 'Hard', 'mcq', 'Can a trigger call another trigger (trigger chaining) in SQL?', 'Only in MySQL', 'Only AFTER triggers can chain', 'No, only one trigger can fire per operation', 'Yes, a trigger can cause another trigger to fire, leading to nested/cascading triggers', 'D', 3, 'Triggers can cascade: one trigger''s action can activate another trigger. Most databases allow configuring the maximum nesting depth.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_71', '71', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Easy', 'mcq', 'What constraint ensures that a column cannot have NULL values in SQL?', 'CHECK', 'UNIQUE', 'NOT NULL', 'DEFAULT', 'C', 2, 'The NOT NULL constraint prevents a column from accepting NULL values.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_72', '72', 'SQL', 'Query Optimization', 'Medium', 'mcq', 'What is a table scan?', 'Reading every row in a table to find matching rows', 'A method to update statistics', 'Scanning index entries only', 'A type of JOIN operation', 'A', 0, 'A table scan (full table scan) reads every row sequentially, which is inefficient for large tables with selective queries.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_73', '73', 'SQL', 'CTEs', 'Easy', 'mcq', 'What does CTE stand for in SQL?', 'Common Table Expression', 'Cached Temporary Expression', 'Central Table Entity', 'Computed Table Extension', 'A', 0, 'CTE stands for Common Table Expression, introduced with the WITH keyword.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_74', '74', 'SQL', 'Subqueries', 'Easy', 'mcq', 'Where can a subquery be used?', 'Only in SELECT clause', 'In SELECT, FROM, WHERE, and HAVING clauses', 'Only in WHERE clause', 'Only in FROM clause', 'B', 1, 'Subqueries can appear in the SELECT list, FROM clause (as a derived table), WHERE clause, or HAVING clause.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_75', '75', 'SQL', 'Query Optimization', 'Hard', 'mcq', 'What is a query execution plan''s ''cost'' based on?', 'The size of the result set only', 'The number of tables in the database', 'The number of columns selected', 'Estimated I/O and CPU resources needed to execute the query', 'D', 3, 'The optimizer estimates cost based on I/O operations, CPU usage, memory, and statistics about the data distribution.', '');
