INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_77', '77', 'SQL', 'Views', 'Hard', 'mcq', 'Under what condition can you INSERT into a view in SQL?', 'Only if the view has a UNION', 'Never', 'When the view is based on a single table and includes all NOT NULL columns', 'Always', 'C', 2, 'A view is updatable if it maps directly to a single base table and includes all columns that do not have default values.', '');
