INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_79', '79', 'SQL', 'Stored Procedures', 'Hard', 'mcq', 'What is the difference between a stored procedure and a user-defined function (UDF) in SQL?', 'UDFs cannot accept parameters', 'UDFs must return a value and can be used in SELECT; procedures may not return a value', 'There is no difference', 'Procedures must return a value; UDFs do not', 'B', 1, 'UDFs are required to return a value and can be used in expressions; stored procedures are more flexible but cannot be called inline in queries.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_80', '80', 'SQL', 'Indexes', 'Medium', 'mcq', 'What is a composite index in SQL?', 'An index with a WHERE condition', 'An index on two or more columns', 'An index on computed columns only', 'An index that covers all columns', 'B', 1, 'A composite (multi-column) index includes two or more columns and is useful when queries filter on multiple columns.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_81', '81', 'SQL', 'SELECT basics', 'Hard', 'mcq', 'What is the purpose of the NULLIF function in SQL?', 'Replaces NULL with a default value', 'Returns NULL if two expressions are equal; otherwise returns the first expression', 'Returns NULL if the expression is zero', 'Counts NULL values', 'B', 1, 'NULLIF(expr1, expr2) returns NULL if expr1 equals expr2; otherwise it returns expr1. It is useful to avoid division by zero.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_82', '82', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Hard', 'mcq', 'In which order does SQL logically process these clauses?', 'FROM, SELECT, WHERE, GROUP BY, HAVING, ORDER BY', 'SELECT, FROM, GROUP BY, WHERE, HAVING, ORDER BY', 'FROM, WHERE, GROUP BY, HAVING, SELECT, ORDER BY', 'SELECT, FROM, WHERE, GROUP BY, HAVING, ORDER BY', 'C', 2, 'SQL processes clauses in logical order: FROM -> WHERE -> GROUP BY -> HAVING -> SELECT -> ORDER BY.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_83', '83', 'SQL', 'CTEs', 'Medium', 'mcq', 'Can a CTE reference itself?', 'Only with UNION ALL', 'Only in MySQL', 'No, CTEs cannot self-reference', 'Yes, this is called a recursive CTE', 'D', 3, 'A recursive CTE references itself in the recursive member, combined with an anchor member via UNION ALL.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_84', '84', 'SQL', 'Normalization', 'Easy', 'mcq', 'What is First Normal Form (1NF)?', 'All columns are primary keys', 'No partial dependencies', 'Each column contains atomic (indivisible) values and each row is unique', 'No transitive dependencies', 'C', 2, '1NF requires that all column values are atomic (no repeating groups or arrays) and rows are uniquely identifiable.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_85', '85', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Easy', 'mcq', 'What does ORDER BY salary DESC do?', 'Sorts results by salary in descending order', 'Filters salaries', 'Sorts results by salary in ascending order', 'Groups by salary', 'A', 0, 'DESC sorts the result set in descending order; ASC (the default) sorts in ascending order.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_86', '86', 'SQL', 'Aggregate Functions', 'Easy', 'mcq', 'What does AVG(salary) return?', 'The arithmetic mean of all salary values', 'The salary range', 'The most frequent salary', 'The median salary', 'A', 0, 'AVG() calculates the arithmetic mean of a numeric column.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_87', '87', 'SQL', 'SELECT basics', 'Hard', 'mcq', 'What is the difference between SELECT DISTINCT and SELECT ALL in SQL?', 'DISTINCT removes duplicates; ALL keeps them (default)', 'ALL removes duplicates; DISTINCT keeps them', 'They are identical', 'DISTINCT is faster than ALL', 'A', 0, 'SELECT ALL is the default behavior that returns all rows including duplicates, while DISTINCT removes duplicate rows.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_88', '88', 'SQL', 'Stored Procedures', 'Easy', 'mcq', 'What is a stored procedure?', 'A database backup method', 'A type of index', 'A temporary query', 'A precompiled collection of SQL statements stored in the database', 'D', 3, 'A stored procedure is a prepared SQL code that is saved and can be reused, often accepting parameters.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_89', '89', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Hard', 'mcq', 'In which order does SQL logically process these clauses in SQL?', 'FROM, WHERE, GROUP BY, HAVING, SELECT, ORDER BY', 'SELECT, FROM, WHERE, GROUP BY, HAVING, ORDER BY', 'FROM, SELECT, WHERE, GROUP BY, HAVING, ORDER BY', 'SELECT, FROM, GROUP BY, WHERE, HAVING, ORDER BY', 'A', 0, 'SQL processes clauses in logical order: FROM -> WHERE -> GROUP BY -> HAVING -> SELECT -> ORDER BY.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_90', '90', 'SQL', 'Query Optimization', 'Hard', 'mcq', 'What is predicate pushdown in query optimization in SQL?', 'Adding indexes automatically', 'Moving filter conditions closer to the data source to reduce the amount of data processed', 'Removing predicates from the query', 'Rewriting subqueries as joins', 'B', 1, 'Predicate pushdown moves WHERE conditions as early as possible in the query plan to filter data before expensive operations like joins.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_91', '91', 'SQL', 'Triggers', 'Hard', 'mcq', 'Can a trigger call another trigger (trigger chaining) in SQL?', 'Yes, a trigger can cause another trigger to fire, leading to nested/cascading triggers', 'Only AFTER triggers can chain', 'No, only one trigger can fire per operation', 'Only in MySQL', 'A', 0, 'Triggers can cascade: one trigger''s action can activate another trigger. Most databases allow configuring the maximum nesting depth.', '');
