INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_96', '96', 'SQL', 'Indexes', 'Medium', 'mcq', 'What is the downside of having too many indexes on a table in SQL?', 'Slower INSERT, UPDATE, and DELETE operations', 'Increased data integrity', 'Reduced storage usage', 'Faster INSERT operations', 'A', 0, 'Each index must be maintained during data modifications, so excessive indexes slow down write operations and consume additional storage.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_97', '97', 'SQL', 'Normalization', 'Hard', 'mcq', 'What is Second Normal Form (2NF)?', '1NF plus every non-key column is fully dependent on the entire primary key', 'All columns are candidate keys', 'Atomic values only', 'No transitive dependencies', 'A', 0, '2NF requires 1NF and that all non-key attributes are fully functionally dependent on the whole primary key (no partial dependencies).', '');
