INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_131', '131', 'SQL', 'SELECT basics', 'Medium', 'mcq', 'What is the result of SELECT DISTINCT department FROM employees in SQL?', 'Unique department values only', 'Department names sorted alphabetically', 'All department values including duplicates', 'Count of departments', 'A', 0, 'DISTINCT eliminates duplicate rows from the result set.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_132', '132', 'SQL', 'Transactions', 'Medium', 'mcq', 'What does ROLLBACK do in SQL?', 'Saves the current transaction', 'Undoes all changes made in the current transaction', 'Starts a new transaction', 'Locks the table', 'B', 1, 'ROLLBACK reverses all changes made since the last COMMIT or the start of the transaction.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_133', '133', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Hard', 'mcq', 'What does CASCADE do in a DROP TABLE statement?', 'Prevents the table from being dropped', 'Deletes rows in related tables', 'Creates a backup before dropping', 'Automatically drops dependent objects like foreign keys and views', 'D', 3, 'CASCADE automatically drops objects that depend on the table (such as foreign key constraints and views referencing it).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_134', '134', 'SQL', 'Transactions', 'Easy', 'mcq', 'What does ACID stand for in database transactions in SQL?', 'Access, Control, Integrity, Data', 'Atomicity, Concurrency, Integrity, Durability', 'Atomicity, Consistency, Isolation, Durability', 'Access, Consistency, Isolation, Data', 'C', 2, 'ACID properties ensure reliable transaction processing: Atomicity, Consistency, Isolation, and Durability.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_135', '135', 'SQL', 'Indexes', 'Medium', 'mcq', 'What is the downside of having too many indexes on a table?', 'Slower INSERT, UPDATE, and DELETE operations', 'Increased data integrity', 'Reduced storage usage', 'Faster INSERT operations', 'A', 0, 'Each index must be maintained during data modifications, so excessive indexes slow down write operations and consume additional storage.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_136', '136', 'SQL', 'Indexes', 'Easy', 'mcq', 'What is the primary purpose of an index in a database?', 'To enforce uniqueness', 'To encrypt columns', 'To compress data', 'To speed up data retrieval', 'D', 3, 'Indexes create a data structure that allows the database engine to find rows faster without scanning the entire table.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_137', '137', 'SQL', 'DML (INSERT/UPDATE/DELETE)', 'Hard', 'mcq', 'What is the MERGE statement used for?', 'Joining two result sets', 'Combining two tables permanently', 'Merging duplicate rows', 'Performing INSERT, UPDATE, or DELETE in a single statement based on a condition', 'D', 3, 'MERGE (also called UPSERT) conditionally inserts, updates, or deletes rows based on whether a match exists.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_138', '138', 'SQL', 'Window Functions', 'Hard', 'mcq', 'What does NTILE(4) OVER (ORDER BY score DESC) do?', 'Calculates the 4th percentile', 'Returns every 4th row', 'Returns the top 4 scores', 'Divides the result set into 4 roughly equal groups ranked by score descending', 'D', 3, 'NTILE(n) distributes rows into n approximately equal buckets based on the specified ordering.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_139', '139', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Easy', 'mcq', 'Which JOIN returns only matching rows from both tables?', 'INNER JOIN', 'LEFT JOIN', 'FULL OUTER JOIN', 'RIGHT JOIN', 'A', 0, 'INNER JOIN returns only the rows that have matching values in both tables.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_140', '140', 'SQL', 'CTEs', 'Hard', 'mcq', 'What is a recursive CTE used for?', 'Replacing window functions', 'Improving query performance', 'Traversing hierarchical or tree-structured data', 'Defining permanent views', 'C', 2, 'Recursive CTEs contain a self-referencing query and are ideal for hierarchical data like org charts or bill of materials.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_141', '141', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Easy', 'mcq', 'What does a LEFT JOIN return in SQL?', 'A Cartesian product', 'All rows from the left table and matched rows from the right table', 'Only matching rows', 'All rows from the right table and matched rows from the left', 'B', 1, 'LEFT JOIN returns all rows from the left table plus matching rows from the right table; unmatched right-side columns are NULL.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_142', '142', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Medium', 'mcq', 'What is the result of a LEFT JOIN when no matching row exists in the right table in SQL?', 'The right table columns contain NULL', 'An error occurs', 'The row is excluded', 'The right columns contain empty strings', 'A', 0, 'In a LEFT JOIN, when there is no match in the right table, all right-side columns are filled with NULL.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_143', '143', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Medium', 'mcq', 'What does ALTER TABLE employees ADD COLUMN bonus DECIMAL(10,2); do in SQL?', 'Adds a new column named bonus to the employees table', 'Renames the employees table', 'Creates a new table called bonus', 'Deletes the bonus column', 'A', 0, 'ALTER TABLE with ADD COLUMN adds a new column with the specified data type to an existing table.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_144', '144', 'SQL', 'Stored Procedures', 'Hard', 'mcq', 'What is the difference between a stored procedure and a user-defined function (UDF) in SQL?', 'UDFs must return a value and can be used in SELECT; procedures may not return a value', 'Procedures must return a value; UDFs do not', 'There is no difference', 'UDFs cannot accept parameters', 'A', 0, 'UDFs are required to return a value and can be used in expressions; stored procedures are more flexible but cannot be called inline in queries.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_145', '145', 'SQL', 'Indexes', 'Hard', 'mcq', 'What is a filtered index (partial index)?', 'An index on filtered views', 'An index that is automatically updated', 'An index that includes only rows meeting a specified condition', 'An index that filters query results', 'C', 2, 'A filtered (partial) index includes only a subset of rows based on a WHERE predicate, reducing index size and improving performance.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_146', '146', 'SQL', 'SELECT basics', 'Hard', 'mcq', 'What is the difference between UNION and UNION ALL in SQL?', 'They are identical', 'UNION ALL removes duplicates; UNION keeps all', 'UNION removes duplicates; UNION ALL keeps all rows including duplicates', 'UNION ALL only works with two tables', 'C', 2, 'UNION eliminates duplicate rows (with extra overhead); UNION ALL retains all rows from both queries.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_147', '147', 'SQL', 'Transactions', 'Medium', 'mcq', 'What is a deadlock?', 'When a table is locked permanently', 'When two or more transactions are waiting for each other to release locks', 'When a transaction runs for too long', 'When a connection times out', 'B', 1, 'A deadlock occurs when two or more transactions each hold a lock and wait for the other to release theirs, creating a cycle.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_148', '148', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Medium', 'mcq', 'What is the difference between DROP and TRUNCATE in SQL?', 'DROP removes the table entirely; TRUNCATE removes all rows but keeps the structure', 'DROP is faster than TRUNCATE', 'TRUNCATE removes the table; DROP removes rows', 'They are identical', 'A', 0, 'DROP removes the table definition and data; TRUNCATE keeps the table structure but removes all rows quickly.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_149', '149', 'SQL', 'Window Functions', 'Hard', 'mcq', 'Which window function returns a value from a preceding row without a self-join in SQL?', 'NTH_VALUE()', 'LEAD()', 'FIRST_VALUE()', 'LAG()', 'D', 3, 'LAG() accesses data from a previous row in the same result set without needing a self-join.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_150', '150', 'SQL', 'Window Functions', 'Medium', 'mcq', 'What does ROW_NUMBER() do in SQL?', 'Returns the row''s physical position', 'Assigns a unique sequential integer to each row within a partition', 'Numbers only duplicate rows', 'Counts the total rows in the table', 'B', 1, 'ROW_NUMBER() assigns a sequential number starting at 1 for each row in the partition ordered as specified.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_151', '151', 'SQL', 'NoSQL Concepts', 'Hard', 'mcq', 'What does the CAP theorem state?', 'A distributed system can provide at most two of: Consistency, Availability, Partition tolerance', 'Consistency and Availability are the same thing', 'All three of CAP can always be achieved', 'CAP applies only to SQL databases', 'A', 0, 'The CAP theorem states that in a distributed data store, you can guarantee at most two of Consistency, Availability, and Partition tolerance simultaneously.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_152', '152', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Medium', 'mcq', 'What is the difference between DROP and TRUNCATE?', 'DROP removes the table entirely; TRUNCATE removes all rows but keeps the structure', 'TRUNCATE removes the table; DROP removes rows', 'They are identical', 'DROP is faster than TRUNCATE', 'A', 0, 'DROP removes the table definition and data; TRUNCATE keeps the table structure but removes all rows quickly.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_153', '153', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Medium', 'mcq', 'What does the BETWEEN operator include?', 'Neither boundary value', 'Only the start value', 'Only the end value', 'Both the start and end values (inclusive)', 'D', 3, 'BETWEEN is inclusive on both ends: WHERE x BETWEEN 1 AND 10 includes both 1 and 10.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_154', '154', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Hard', 'mcq', 'Which ALTER TABLE command adds a NOT NULL constraint to an existing column?', 'ALTER TABLE t MODIFY col NULL = FALSE', 'ALTER TABLE t CHANGE col NOT NULL', 'ALTER TABLE t ADD NOT NULL ON col', 'ALTER TABLE t ALTER COLUMN col SET NOT NULL', 'D', 3, 'The standard syntax uses ALTER COLUMN ... SET NOT NULL (exact syntax varies by DBMS).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_155', '155', 'SQL', 'Transactions', 'Medium', 'mcq', 'What is a savepoint in SQL?', 'A point within a transaction to which you can later roll back', 'A type of lock', 'A commit point', 'A backup of the database', 'A', 0, 'A savepoint marks a point in a transaction so you can roll back to it without rolling back the entire transaction.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_156', '156', 'SQL', 'Normalization', 'Medium', 'mcq', 'What is denormalization?', 'Deleting unused tables', 'Removing all primary keys', 'Intentionally adding redundancy to improve read performance', 'Converting to NoSQL', 'C', 2, 'Denormalization adds controlled redundancy (e.g., duplicating data) to reduce the number of joins and speed up read queries.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_157', '157', 'SQL', 'Query Optimization', 'Medium', 'mcq', 'What is an index scan vs an index seek in SQL?', 'They are the same operation', 'A scan is always faster', 'A seek goes directly to specific rows; a scan reads the entire index', 'A seek reads the entire table', 'C', 2, 'An index seek efficiently navigates the B-tree to find specific rows; an index scan reads all entries in the index sequentially.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_158', '158', 'SQL', 'Views', 'Hard', 'mcq', 'Under what condition can you INSERT into a view in SQL?', 'Only if the view has a UNION', 'Never', 'When the view is based on a single table and includes all NOT NULL columns', 'Always', 'C', 2, 'A view is updatable if it maps directly to a single base table and includes all columns that do not have default values.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_159', '159', 'SQL', 'Window Functions', 'Hard', 'mcq', 'Which window function returns a value from a preceding row without a self-join in SQL?', 'LEAD()', 'LAG()', 'FIRST_VALUE()', 'NTH_VALUE()', 'B', 1, 'LAG() accesses data from a previous row in the same result set without needing a self-join.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_160', '160', 'SQL', 'Triggers', 'Easy', 'mcq', 'On which DML operations can triggers be defined in SQL?', 'Only UPDATE and DELETE', 'SELECT, INSERT, UPDATE', 'INSERT, UPDATE, DELETE', 'Only INSERT', 'C', 2, 'Triggers can be defined on INSERT, UPDATE, and DELETE operations (not on SELECT, which does not modify data).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_161', '161', 'SQL', 'Views', 'Hard', 'mcq', 'Under what condition can you INSERT into a view?', 'Always', 'When the view is based on a single table and includes all NOT NULL columns', 'Only if the view has a UNION', 'Never', 'B', 1, 'A view is updatable if it maps directly to a single base table and includes all columns that do not have default values.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_162', '162', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Hard', 'mcq', 'What is a self-join and when is it useful?', 'A join that uses no ON clause', 'A join limited to two columns', 'A table joined to itself, useful for hierarchical or comparative queries', 'A join that automatically matches primary keys', 'C', 2, 'A self-join joins a table to itself using aliases, commonly used for hierarchical data like employee-manager relationships.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_163', '163', 'SQL', 'DML (INSERT/UPDATE/DELETE)', 'Easy', 'mcq', 'Which statement adds a new row to a table in SQL?', 'INSERT INTO', 'ADD ROW', 'CREATE ROW', 'APPEND', 'A', 0, 'INSERT INTO is the DML statement to add new rows to a table.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_164', '164', 'SQL', 'Stored Procedures', 'Medium', 'mcq', 'What is the difference between IN, OUT, and INOUT parameters?', 'INOUT is not valid', 'They are all identical', 'IN passes values in; OUT returns values; INOUT does both', 'IN is for integers; OUT is for strings', 'C', 2, 'IN parameters pass values to the procedure, OUT parameters return values, and INOUT parameters serve both purposes.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_165', '165', 'SQL', 'Transactions', 'Easy', 'mcq', 'What SQL command saves all changes made during a transaction?', 'COMMIT', 'APPLY', 'FINISH', 'SAVE', 'A', 0, 'COMMIT permanently saves all changes made during the current transaction.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_166', '166', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Medium', 'mcq', 'What is the difference between WHERE and HAVING?', 'WHERE works only with numbers; HAVING works with strings', 'They are interchangeable', 'WHERE filters rows before grouping; HAVING filters groups after grouping', 'HAVING filters rows before grouping; WHERE filters groups after', 'C', 2, 'WHERE is applied before GROUP BY; HAVING is applied after GROUP BY to filter aggregated results.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_167', '167', 'SQL', 'Query Optimization', 'Easy', 'mcq', 'What SQL command shows the execution plan of a query?', 'ANALYZE', 'DESCRIBE', 'SHOW PLAN', 'EXPLAIN', 'D', 3, 'EXPLAIN (or EXPLAIN PLAN) displays how the database engine will execute a query, showing join methods, index usage, etc.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_168', '168', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Medium', 'mcq', 'What is a CROSS JOIN?', 'A Cartesian product of two tables', 'A join that removes duplicates', 'A self-referencing join', 'A join that matches rows on a condition', 'A', 0, 'A CROSS JOIN produces the Cartesian product, combining every row from the first table with every row from the second.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_169', '169', 'SQL', 'Triggers', 'Easy', 'mcq', 'On which DML operations can triggers be defined?', 'INSERT, UPDATE, DELETE', 'SELECT, INSERT, UPDATE', 'Only UPDATE and DELETE', 'Only INSERT', 'A', 0, 'Triggers can be defined on INSERT, UPDATE, and DELETE operations (not on SELECT, which does not modify data).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_170', '170', 'SQL', 'Normalization', 'Medium', 'mcq', 'What does Third Normal Form (3NF) require?', 'Only atomic values in each column', 'No foreign keys', 'A primary key on every column', '2NF plus no transitive dependencies on the primary key', 'D', 3, '3NF requires that the table is in 2NF and that no non-key column depends on another non-key column (no transitive dependency).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_171', '171', 'SQL', 'Subqueries', 'Hard', 'mcq', 'What is the difference between IN and EXISTS for subqueries in SQL?', 'EXISTS cannot be used with correlated subqueries', 'They are always identical in performance', 'IN is always faster', 'EXISTS checks for row existence and is often faster for large subquery results; IN compares values', 'D', 3, 'EXISTS short-circuits once a match is found and works well with correlated subqueries; IN materializes the subquery result for comparison.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_172', '172', 'SQL', 'Subqueries', 'Medium', 'mcq', 'What is a correlated subquery in SQL?', 'A subquery that references a column from the outer query', 'A subquery inside a HAVING clause', 'A subquery that runs independently', 'A subquery that returns exactly one row', 'A', 0, 'A correlated subquery depends on the outer query for its values and is re-evaluated for each outer row.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_173', '173', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Medium', 'mcq', 'What is the result of a LEFT JOIN when no matching row exists in the right table?', 'The right table columns contain NULL', 'The right columns contain empty strings', 'An error occurs', 'The row is excluded', 'A', 0, 'In a LEFT JOIN, when there is no match in the right table, all right-side columns are filled with NULL.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_174', '174', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Medium', 'mcq', 'What is the difference between WHERE and HAVING in SQL?', 'WHERE works only with numbers; HAVING works with strings', 'They are interchangeable', 'WHERE filters rows before grouping; HAVING filters groups after grouping', 'HAVING filters rows before grouping; WHERE filters groups after', 'C', 2, 'WHERE is applied before GROUP BY; HAVING is applied after GROUP BY to filter aggregated results.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_175', '175', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Medium', 'mcq', 'What is a CROSS JOIN in SQL?', 'A join that removes duplicates', 'A join that matches rows on a condition', 'A Cartesian product of two tables', 'A self-referencing join', 'C', 2, 'A CROSS JOIN produces the Cartesian product, combining every row from the first table with every row from the second.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_176', '176', 'SQL', 'Query Optimization', 'Medium', 'mcq', 'What is a table scan in SQL?', 'Reading every row in a table to find matching rows', 'A method to update statistics', 'A type of JOIN operation', 'Scanning index entries only', 'A', 0, 'A table scan (full table scan) reads every row sequentially, which is inefficient for large tables with selective queries.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_177', '177', 'SQL', 'NoSQL Concepts', 'Medium', 'mcq', 'Which of these is a document-oriented NoSQL database?', 'Cassandra', 'Redis', 'MongoDB', 'Neo4j', 'C', 2, 'MongoDB stores data as flexible JSON-like documents (BSON), making it a document-oriented database.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_178', '178', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Hard', 'mcq', 'Can you use a column alias defined in SELECT inside the WHERE clause in SQL?', 'No, because WHERE is processed before SELECT', 'Yes, always', 'Only with numeric aliases', 'Only in MySQL', 'A', 0, 'Because WHERE is logically processed before SELECT, column aliases from SELECT are not available in WHERE.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_179', '179', 'SQL', 'Transactions', 'Easy', 'mcq', 'What does ACID stand for in database transactions?', 'Access, Control, Integrity, Data', 'Access, Consistency, Isolation, Data', 'Atomicity, Consistency, Isolation, Durability', 'Atomicity, Concurrency, Integrity, Durability', 'C', 2, 'ACID properties ensure reliable transaction processing: Atomicity, Consistency, Isolation, and Durability.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_180', '180', 'SQL', 'Window Functions', 'Easy', 'mcq', 'Do window functions reduce the number of rows in the result set in SQL?', 'Yes, they group rows like GROUP BY', 'No, they add computed values without reducing rows', 'Only RANK() reduces rows', 'Yes, they filter rows', 'B', 1, 'Unlike aggregate functions with GROUP BY, window functions compute values across a set of rows while retaining all original rows.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_181', '181', 'SQL', 'SELECT basics', 'Easy', 'mcq', 'Which SQL keyword is used to retrieve data from a database in SQL?', 'SELECT', 'GET', 'FETCH', 'RETRIEVE', 'A', 0, 'SELECT is the standard SQL keyword used to query and retrieve data from tables.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_182', '182', 'SQL', 'Subqueries', 'Easy', 'mcq', 'What is a subquery?', 'A type of index', 'A temporary table', 'A query nested inside another query', 'A stored procedure', 'C', 2, 'A subquery (or inner query) is a SELECT statement embedded within another SQL statement.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_183', '183', 'SQL', 'Aggregate Functions', 'Hard', 'mcq', 'Can aggregate functions be nested, such as MAX(AVG(salary)) in SQL?', 'Yes, always', 'Only in PostgreSQL', 'Only with GROUP BY', 'Not directly in standard SQL; you need a subquery or CTE', 'D', 3, 'Standard SQL does not allow nested aggregates directly. You must use a subquery or CTE to first compute the inner aggregate.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_184', '184', 'SQL', 'DML (INSERT/UPDATE/DELETE)', 'Medium', 'mcq', 'What does INSERT INTO ... SELECT do in SQL?', 'Inserts rows from a SELECT query result into a table', 'Updates existing rows', 'Creates a new table from a query', 'Copies the table structure only', 'A', 0, 'INSERT INTO ... SELECT copies data from one or more tables into another table using the results of a SELECT query.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_185', '185', 'SQL', 'Query Optimization', 'Easy', 'mcq', 'What SQL command shows the execution plan of a query in SQL?', 'ANALYZE', 'SHOW PLAN', 'DESCRIBE', 'EXPLAIN', 'D', 3, 'EXPLAIN (or EXPLAIN PLAN) displays how the database engine will execute a query, showing join methods, index usage, etc.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_186', '186', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Easy', 'mcq', 'What keyword is used to combine rows from two tables based on a related column?', 'UNION', 'MERGE', 'JOIN', 'COMBINE', 'C', 2, 'JOIN is used to combine rows from two or more tables based on a related column between them.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_187', '187', 'SQL', 'Transactions', 'Hard', 'mcq', 'Which isolation level allows dirty reads in SQL?', 'SERIALIZABLE', 'READ COMMITTED', 'READ UNCOMMITTED', 'REPEATABLE READ', 'C', 2, 'READ UNCOMMITTED is the lowest isolation level and allows reading data that has been modified but not yet committed by other transactions.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_188', '188', 'SQL', 'Views', 'Medium', 'mcq', 'What is a materialized view?', 'A view that cannot be queried', 'A view that stores the result set physically and can be refreshed', 'A view that is always up-to-date', 'A regular view with an index', 'B', 1, 'A materialized view physically stores query results and must be refreshed to reflect changes in the underlying data.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_189', '189', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Hard', 'mcq', 'What does GROUP BY ROLLUP do?', 'Removes duplicate groups', 'Limits the number of groups', 'Orders groups in reverse', 'Creates subtotals for each grouping level and a grand total', 'D', 3, 'ROLLUP generates subtotal rows for the hierarchy of grouped columns plus a grand total row.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_190', '190', 'SQL', 'Query Optimization', 'Hard', 'mcq', 'What is predicate pushdown in query optimization?', 'Removing predicates from the query', 'Rewriting subqueries as joins', 'Moving filter conditions closer to the data source to reduce the amount of data processed', 'Adding indexes automatically', 'C', 2, 'Predicate pushdown moves WHERE conditions as early as possible in the query plan to filter data before expensive operations like joins.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_191', '191', 'SQL', 'Indexes', 'Medium', 'mcq', 'What is a clustered index?', 'An index that allows duplicate values', 'An index that determines the physical order of data in a table', 'An index stored in a separate file', 'An index on multiple columns', 'B', 1, 'A clustered index sorts and stores the data rows of the table based on the index key. A table can have only one clustered index.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_192', '192', 'SQL', 'Transactions', 'Hard', 'mcq', 'What is a phantom read?', 'When a deadlock occurs', 'When a transaction re-reads a query and finds new rows inserted by another transaction', 'When a row is updated during a read', 'When a transaction reads uncommitted data', 'B', 1, 'A phantom read occurs when a transaction re-executes a query and sees rows that were inserted by another committed transaction.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_193', '193', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Medium', 'mcq', 'What is the difference between DROP and TRUNCATE in SQL?', 'DROP removes the table entirely; TRUNCATE removes all rows but keeps the structure', 'DROP is faster than TRUNCATE', 'TRUNCATE removes the table; DROP removes rows', 'They are identical', 'A', 0, 'DROP removes the table definition and data; TRUNCATE keeps the table structure but removes all rows quickly.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_194', '194', 'SQL', 'Query Optimization', 'Easy', 'mcq', 'What does adding an index to a column used in WHERE clauses typically do?', 'Slows down the query', 'Has no effect', 'Removes duplicates', 'Speeds up the query by allowing the database to locate rows faster', 'D', 3, 'An index on a frequently filtered column allows the database to quickly locate relevant rows instead of scanning the entire table.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_195', '195', 'SQL', 'Subqueries', 'Hard', 'mcq', 'What is the difference between IN and EXISTS for subqueries?', 'They are always identical in performance', 'EXISTS cannot be used with correlated subqueries', 'EXISTS checks for row existence and is often faster for large subquery results; IN compares values', 'IN is always faster', 'C', 2, 'EXISTS short-circuits once a match is found and works well with correlated subqueries; IN materializes the subquery result for comparison.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_196', '196', 'SQL', 'Aggregate Functions', 'Hard', 'mcq', 'Can aggregate functions be nested, such as MAX(AVG(salary))?', 'Not directly in standard SQL; you need a subquery or CTE', 'Only with GROUP BY', 'Only in PostgreSQL', 'Yes, always', 'A', 0, 'Standard SQL does not allow nested aggregates directly. You must use a subquery or CTE to first compute the inner aggregate.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_197', '197', 'SQL', 'Window Functions', 'Medium', 'mcq', 'What does ROW_NUMBER() do?', 'Numbers only duplicate rows', 'Returns the row''s physical position', 'Counts the total rows in the table', 'Assigns a unique sequential integer to each row within a partition', 'D', 3, 'ROW_NUMBER() assigns a sequential number starting at 1 for each row in the partition ordered as specified.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_198', '198', 'SQL', 'Query Optimization', 'Medium', 'mcq', 'Why should you avoid SELECT * in production queries?', 'It is not valid SQL', 'It only works with one table', 'It causes syntax errors', 'It retrieves unnecessary columns, increasing I/O and memory usage', 'D', 3, 'SELECT * fetches all columns, which wastes resources and can break applications if the schema changes.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_199', '199', 'SQL', 'Subqueries', 'Hard', 'mcq', 'Which keyword checks for the existence of any rows returned by a subquery?', 'SOME', 'EXISTS', 'IN', 'ANY', 'B', 1, 'EXISTS returns TRUE if the subquery returns one or more rows, regardless of the actual data.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_200', '200', 'SQL', 'Aggregate Functions', 'Medium', 'mcq', 'What does SUM(DISTINCT column) do?', 'Returns the count of distinct values', 'Sums only the unique values in the column', 'Sums all values including duplicates', 'Returns an error', 'B', 1, 'SUM(DISTINCT col) eliminates duplicate values before calculating the sum.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_201', '201', 'SQL', 'SELECT basics', 'Easy', 'output', 'What is the output?', 'result: 1', 'result: 0', 'result: 3', 'result: 3.33', 'A', 0, 'The modulo operator % returns the remainder of 10 divided by 3, which is 1.', 'SELECT 10 % 3 AS result;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_202', '202', 'SQL', 'SELECT basics', 'Medium', 'output', 'What does this query return?', 'val: default', 'Error', 'val: NULL', 'val: empty string', 'A', 0, 'COALESCE returns the first non-NULL argument, which is ''default''.', 'SELECT COALESCE(NULL, NULL, ''default'') AS val;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_203', '203', 'SQL', 'SELECT basics', 'Medium', 'output', 'What is the result?', 'Error', 'answer: NULL', 'answer: No', 'answer: Yes', 'D', 3, '10 > 5 is TRUE, so the CASE expression returns ''Yes''.', 'SELECT CASE WHEN 10 > 5 THEN ''Yes'' ELSE ''No'' END AS answer;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_204', '204', 'SQL', 'DML (INSERT/UPDATE/DELETE)', 'Easy', 'output', 'Given t(id INT, name VARCHAR). What does this produce?', '2', '1', '0', 'Error', 'A', 0, 'Two rows are inserted, so COUNT(*) returns 2.', 'INSERT INTO t VALUES (1, ''Alice''), (2, ''Bob'');
SELECT COUNT(*) FROM t;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_205', '205', 'SQL', 'Window Functions', 'Hard', 'output', 'Given the SQL below, what is the output?', 'A:1, B:2, C:3, D:4', 'A:1, B:2, C:2, D:4', 'A:1, B:2, C:2, D:3', 'A:1, B:1, C:2, D:3', 'B', 1, 'RANK() assigns 1 to A, 2 to B and C (tied), then skips 3 and assigns 4 to D.', 'SELECT name, RANK() OVER (ORDER BY salary) AS rnk FROM emp;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_206', '206', 'SQL', 'Aggregate Functions', 'Medium', 'output', 'Given t(grp, val): (A,10),(A,20),(A,NULL),(B,30). What is the output?', 'A: cnt=3, total=30 and B: cnt=1, total=30', 'Error', 'A: cnt=2, total=30 and B: cnt=1, total=30', 'A: cnt=2, total=30', 'C', 2, 'COUNT(val) skips NULLs: A has 2 non-NULL vals (10,20). SUM also ignores NULL: 10+20=30.', 'SELECT grp, COUNT(val) AS cnt, SUM(val) AS total FROM t GROUP BY grp;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_207', '207', 'SQL', 'Query Optimization', 'Hard', 'output', 'Given the SQL below, what is the output?', 'Query B, because the addition is optimized away', 'Neither can use the index', 'Query A, because Query B''s expression prevents index usage', 'Both are equally efficient', 'C', 2, 'Applying a function or expression to an indexed column (dept_id + 0) prevents the optimizer from using the index (SARGability).', '-- Query A:
SELECT * FROM emp WHERE dept_id = 5;
-- Query B:
SELECT * FROM emp WHERE dept_id + 0 = 5;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_208', '208', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Medium', 'output', 'What does this DDL statement produce?', 'An error because CREATE TABLE AS is not valid', 'A view named test', 'A new table ''test'' with one column containing unique department values', 'An empty table', 'C', 2, 'CREATE TABLE ... AS SELECT creates a new table from the result set of the query.', 'CREATE TABLE test AS SELECT DISTINCT department FROM employees;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_209', '209', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Medium', 'output', 'Given the SQL below, what is the output?', 'X|P and Y|NULL (2 rows)', 'Error', 'Y|NULL (1 row)', 'X|P (1 row)', 'A', 0, 'LEFT JOIN returns all rows from A. X matches B (val=P), Y has no match (val=NULL).', 'SELECT A.name, B.val FROM A LEFT JOIN B ON A.id = B.a_id;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_210', '210', 'SQL', 'SELECT basics', 'Medium', 'output', 'Given the SQL below, what is the output?', 'result: 12', 'result: 210', 'result: 20', 'result: 1024', 'D', 3, 'POWER(2, 10) computes 2^10 = 1024.', 'SELECT POWER(2, 10) AS result;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_211', '211', 'SQL', 'Window Functions', 'Easy', 'output', 'Given t(dept, salary): (A,100),(A,200),(B,150). What does this return?', '(A,100,300),(A,200,300),(B,150,150)', '(A,300,300),(B,150,150)', 'Error', '(A,100,100),(A,200,200),(B,150,150)', 'A', 0, 'SUM with PARTITION BY dept calculates the sum per department while keeping all rows. Dept A total=300, B total=150.', 'SELECT dept, salary, SUM(salary) OVER (PARTITION BY dept) AS dept_total FROM t;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_212', '212', 'SQL', 'Normalization', 'Hard', 'output', 'Given: orders(order_id, customer_name, customer_city, product, quantity). Which normal form is violated and why?', 'Table is fully normalized', '2NF: customer_city depends on customer_name, not the full primary key', '1NF: values are not atomic', '3NF: there are no transitive dependencies', 'B', 1, 'customer_city depends on customer_name (partial dependency if composite PK, transitive if single PK), violating 2NF/3NF.', '-- orders table:
-- order_id | customer_name | customer_city | product | quantity
-- 1        | Alice         | NYC           | Widget  | 5
-- 2        | Alice         | NYC           | Gadget  | 3');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_213', '213', 'SQL', 'Aggregate Functions', 'Easy', 'output', 'Given t(val): (5),(3),(8),(1). What is the output?', 'Error', 'minimum: 3, maximum: 5', 'minimum: 1, maximum: 8', 'minimum: 5, maximum: 3', 'C', 2, 'MIN returns the smallest value (1) and MAX returns the largest (8).', 'SELECT MIN(val) AS minimum, MAX(val) AS maximum FROM t;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_214', '214', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Medium', 'output', 'Given orders(cust_id, amount): (1,100),(1,200),(2,50),(2,150),(3,300). What is the output?', 'cust_id 3: 300 and cust_id 1: 300', 'All 3 customers', 'cust_id 1: 300 and cust_id 3: 300', 'Error', 'C', 2, 'Totals: cust 1=300, cust 2=200, cust 3=300. ORDER BY total DESC with LIMIT 2 returns cust 3 and cust 1 (both 300, order depends on DBMS).', 'SELECT cust_id, SUM(amount) AS total FROM orders GROUP BY cust_id ORDER BY total DESC LIMIT 2;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_215', '215', 'SQL', 'Window Functions', 'Hard', 'output', 'Given t(dt, val): (''2025-01-01'',10),(''2025-01-02'',20),(''2025-01-03'',30). What is the result?', '(''2025-01-01'',10,60),(''2025-01-02'',20,60),(''2025-01-03'',30,60)', '(''2025-01-01'',10,10),(''2025-01-02'',20,30),(''2025-01-03'',30,60)', '(''2025-01-01'',10,10),(''2025-01-02'',20,20),(''2025-01-03'',30,30)', 'Error', 'B', 1, 'This computes a running total: 10, 10+20=30, 10+20+30=60.', 'SELECT dt, val, SUM(val) OVER (ORDER BY dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total FROM t;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_216', '216', 'SQL', 'Transactions', 'Medium', 'output', 'Given the SQL below, what is the output?', 'Error', 'val: 30', 'val: 20', 'val: 10', 'C', 2, 'The update to 30 is rolled back to savepoint sp1, restoring val to 20. Then COMMIT saves val=20.', 'BEGIN;
UPDATE t SET val = 20;
SAVEPOINT sp1;
UPDATE t SET val = 30;
ROLLBACK TO sp1;
COMMIT;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_217', '217', 'SQL', 'DML (INSERT/UPDATE/DELETE)', 'Hard', 'output', 'Given t(id, val): (1,100),(2,200). What does this produce?', '2 rows unchanged', '4 rows: (1,200),(2,400),(11,200),(12,400)', 'Error', '4 rows: (1,100),(2,200),(11,200),(12,400)', 'D', 3, 'INSERT...SELECT adds new rows (11,200) and (12,400) based on existing data. Original rows remain unchanged.', 'INSERT INTO t (id, val) SELECT id + 10, val * 2 FROM t;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_218', '218', 'SQL', 'Subqueries', 'Medium', 'output', 'Given the SQL below, what is the output?', 'No rows', 'A', 'C', 'B, C', 'C', 2, 'AVG(salary) = 50000. Only C has salary (60000) > 50000.', 'SELECT name FROM employees WHERE salary > (SELECT AVG(salary) FROM employees);');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_219', '219', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Easy', 'output', 'Given the SQL below, what is the output?', 'No rows', 'X|P (1 row)', 'X|P and X|Q (2 rows)', 'X|P, X|Q, Y|NULL (3 rows)', 'C', 2, 'INNER JOIN only returns matching rows. A.id=1 matches both B rows, so we get X|P and X|Q. Y has no match.', 'SELECT A.name, B.val FROM A INNER JOIN B ON A.id = B.a_id;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_220', '220', 'SQL', 'SELECT basics', 'Hard', 'output', 'Given the SQL below, what is the output?', 'result: NULL (or unknown)', 'result: FALSE', 'result: TRUE', 'Error', 'A', 0, 'Comparing NULL with = yields NULL (unknown), not TRUE. Use IS NULL to test for NULL.', 'SELECT NULL = NULL AS result;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_221', '221', 'SQL', 'NoSQL Concepts', 'Medium', 'output', 'What does this MongoDB-style query return?', 'An error', 'All fields for users over 25', 'Names of users whose age is greater than 25, without the _id field', 'Only the _id field', 'C', 2, 'The query filters for age > 25 and projects only the name field (excluding _id).', 'db.users.find({ age: { $gt: 25 } }, { name: 1, _id: 0 })');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_222', '222', 'SQL', 'CTEs', 'Medium', 'output', 'Given products(name, price): (A,10),(B,20),(C,30). What does this return?', 'cnt: 2', 'cnt: 3', 'cnt: 1', 'Error', 'A', 0, 'The CTE selects B and C (price > 15). COUNT(*) returns 2.', 'WITH expensive AS (SELECT name FROM products WHERE price > 15)
SELECT COUNT(*) AS cnt FROM expensive;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_223', '223', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Easy', 'output', 'Given t(name): (''Alice''),(''Bob''),(''Anna''). What is the output?', 'Anna, Alice', 'Alice', 'Alice, Anna, Bob', 'Alice, Anna', 'D', 3, 'LIKE ''A%'' matches names starting with A: Alice and Anna. ORDER BY sorts them alphabetically.', 'SELECT name FROM t WHERE name LIKE ''A%'' ORDER BY name;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_224', '224', 'SQL', 'SELECT basics', 'Easy', 'output', 'What is the result of this query?', 'len: 2', 'len: 4', 'len: 3', 'Error', 'C', 2, 'LENGTH returns the number of characters in the string ''SQL'', which is 3.', 'SELECT LENGTH(''SQL'') AS len;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_225', '225', 'SQL', 'SELECT basics', 'Hard', 'output', 'Given the SQL below, what is the output?', 'result: 15.5', 'result: 15.57', 'result: 16', 'result: 15.6', 'D', 3, 'ROUND(15.567, 1) rounds to 1 decimal place: 15.6.', 'SELECT ROUND(15.567, 1) AS result;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_226', '226', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Hard', 'output', 'Tables: emp(id,name,mgr_id): (1,''CEO'',NULL),(2,''VP'',1),(3,''Dev'',2). What does this self-join return?', '(VP,CEO),(Dev,VP)', '(CEO,NULL),(VP,CEO),(Dev,VP)', '(CEO,NULL)', 'Error', 'B', 1, 'The self-join matches each employee to their manager. CEO has no manager (NULL), VP reports to CEO, Dev reports to VP.', 'SELECT e.name AS employee, m.name AS manager FROM emp e LEFT JOIN emp m ON e.mgr_id = m.id;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_227', '227', 'SQL', 'Subqueries', 'Medium', 'output', 'Given employees(name, salary): (A,40000),(B,50000),(C,60000). What does this return?', 'C', 'A', 'No rows', 'B, C', 'A', 0, 'AVG(salary) = 50000. Only C has salary (60000) > 50000.', 'SELECT name FROM employees WHERE salary > (SELECT AVG(salary) FROM employees);');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_228', '228', 'SQL', 'SELECT basics', 'Medium', 'output', 'What is the output?', 'result: 0', 'Error', 'result: 10', 'result: NULL', 'D', 3, 'NULLIF returns NULL when both arguments are equal.', 'SELECT NULLIF(10, 10) AS result;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_229', '229', 'SQL', 'Subqueries', 'Hard', 'output', 'Given emp(id,dept_id,salary): (1,1,50000),(2,1,60000),(3,2,70000),(4,2,80000). What does this return?', 'id:4 salary:80000 only', 'Error', 'All 4 rows', 'id:2 salary:60000 and id:4 salary:80000', 'D', 3, 'The correlated subquery finds the max salary per department. id=2 has the max in dept 1, id=4 in dept 2.', 'SELECT e.id, e.salary FROM emp e WHERE e.salary = (SELECT MAX(salary) FROM emp e2 WHERE e2.dept_id = e.dept_id);');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_230', '230', 'SQL', 'SELECT basics', 'Hard', 'output', 'What is the result?', 'Error', 'future_date: 2025-01-25', 'future_date: 2025-01-15', 'future_date: 2025-02-15', 'B', 1, 'Adding 10 days to January 15 gives January 25.', 'SELECT CAST(''2025-01-15'' AS DATE) + INTERVAL ''10'' DAY AS future_date;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_231', '231', 'SQL', 'SELECT basics', 'Easy', 'output', 'What is the output of the following SQL query?', 'result: 2', 'Error', 'result: 11', 'result: NULL', 'A', 0, '1 + 1 is an arithmetic expression that evaluates to 2.', 'SELECT 1 + 1 AS result;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_232', '232', 'SQL', 'CTEs', 'Hard', 'output', 'Given the SQL below, what is the output?', 'Error', '13', '5', '8', 'D', 3, 'This generates Fibonacci numbers. At n=7: sequence is 0,1,1,2,3,5,8. Column ''a'' at n=7 is 8.', 'WITH RECURSIVE fib(n, a, b) AS (
  SELECT 1, 0, 1
  UNION ALL
  SELECT n+1, b, a+b FROM fib WHERE n < 7
)
SELECT a FROM fib WHERE n = 7;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_233', '233', 'SQL', 'CTEs', 'Hard', 'output', 'What does this recursive CTE produce?', 'Infinite loop', '1, 2, 3, 4', '1', '1, 2, 3, 4, 5', 'D', 3, 'The anchor returns 1, then recursion adds 1 each time until n reaches 5.', 'WITH RECURSIVE nums AS (
  SELECT 1 AS n
  UNION ALL
  SELECT n + 1 FROM nums WHERE n < 5
)
SELECT n FROM nums;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_234', '234', 'SQL', 'SELECT basics', 'Hard', 'output', 'Given the SQL below, what is the output?', 'result: 16', 'result: 15.6', 'result: 15.57', 'result: 15.5', 'B', 1, 'ROUND(15.567, 1) rounds to 1 decimal place: 15.6.', 'SELECT ROUND(15.567, 1) AS result;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_235', '235', 'SQL', 'Transactions', 'Medium', 'output', 'Given t(val): (10). What is the final state of val after these statements?', 'val: 20', 'val: 30', 'Error', 'val: 10', 'A', 0, 'The update to 30 is rolled back to savepoint sp1, restoring val to 20. Then COMMIT saves val=20.', 'BEGIN;
UPDATE t SET val = 20;
SAVEPOINT sp1;
UPDATE t SET val = 30;
ROLLBACK TO sp1;
COMMIT;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_236', '236', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Hard', 'output', 'Given the SQL below, what is the output?', 'c1: 3, c2: 4', 'c1: 4, c2: 4', 'c1: 3, c2: 3', 'c1: 4, c2: 3', 'D', 3, 'COUNT(*) counts all rows (4), COUNT(val) skips the NULL row (3).', 'SELECT COUNT(*) AS c1, COUNT(val) AS c2 FROM data;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_237', '237', 'SQL', 'Normalization', 'Medium', 'output', 'Given the SQL below, what is the output?', 'Cannot determine', 'Yes, it is in 1NF', 'It is in 3NF', 'No, because courses are stored as repeating groups in separate columns', 'D', 3, 'Having course1, course2, course3 as separate columns is a repeating group, violating 1NF. Courses should be in a separate table.', '-- Table: students
-- Columns: id, name, course1, course2, course3
-- Row example: (1, ''Alice'', ''Math'', ''Science'', NULL)');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_238', '238', 'SQL', 'SELECT basics', 'Easy', 'output', 'What is the result?', 'Error', 'result: hello  ', 'result:   hello  ', 'result: hello', 'D', 3, 'TRIM removes leading and trailing whitespace from the string.', 'SELECT TRIM(''  hello  '') AS result;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_239', '239', 'SQL', 'SELECT basics', 'Easy', 'output', 'What is the output?', 'Error', 'result: HELLO', 'result: hello', 'result: Hello', 'B', 1, 'UPPER converts all characters to uppercase.', 'SELECT UPPER(''hello'') AS result;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_240', '240', 'SQL', 'SELECT basics', 'Easy', 'output', 'What does this query return?', 'Error', 'NULL', 'greeting: Hello World', 'greeting: HelloWorld', 'C', 2, 'The || operator concatenates strings in standard SQL.', 'SELECT ''Hello'' || '' '' || ''World'' AS greeting;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_241', '241', 'SQL', 'Indexes', 'Medium', 'output', 'What does this statement create?', 'A check constraint', 'A regular index that allows duplicates', 'A primary key on email', 'A unique index that prevents duplicate email values', 'D', 3, 'CREATE UNIQUE INDEX creates an index that also enforces uniqueness on the email column.', 'CREATE UNIQUE INDEX idx_email ON users(email);');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_242', '242', 'SQL', 'SELECT basics', 'Hard', 'output', 'What is the output?', 'result: 15.5', 'result: 16', 'result: 15.6', 'result: 15.57', 'C', 2, 'ROUND(15.567, 1) rounds to 1 decimal place: 15.6.', 'SELECT ROUND(15.567, 1) AS result;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_243', '243', 'SQL', 'NoSQL Concepts', 'Medium', 'output', 'Given the SQL below, what is the output?', 'Names of users whose age is greater than 25, without the _id field', 'An error', 'Only the _id field', 'All fields for users over 25', 'A', 0, 'The query filters for age > 25 and projects only the name field (excluding _id).', 'db.users.find({ age: { $gt: 25 } }, { name: 1, _id: 0 })');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_244', '244', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Easy', 'output', 'What type of object does this create?', 'A temporary table that is auto-deleted', 'A table with an integer primary key and a decimal column', 'An index', 'A view', 'B', 1, 'CREATE TABLE creates a permanent table. The name ''temp_results'' does not make it temporary; CREATE TEMPORARY TABLE would.', 'CREATE TABLE temp_results (
  id INT PRIMARY KEY,
  score DECIMAL(5,2)
);');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_245', '245', 'SQL', 'CTEs', 'Hard', 'output', 'What does this query return?', '8', '13', 'Error', '5', 'A', 0, 'This generates Fibonacci numbers. At n=7: sequence is 0,1,1,2,3,5,8. Column ''a'' at n=7 is 8.', 'WITH RECURSIVE fib(n, a, b) AS (
  SELECT 1, 0, 1
  UNION ALL
  SELECT n+1, b, a+b FROM fib WHERE n < 7
)
SELECT a FROM fib WHERE n = 7;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_246', '246', 'SQL', 'SELECT basics', 'Hard', 'output', 'What is the result?', 'result: NULL (or unknown)', 'result: FALSE', 'Error', 'result: TRUE', 'A', 0, 'Comparing NULL with = yields NULL (unknown), not TRUE. Use IS NULL to test for NULL.', 'SELECT NULL = NULL AS result;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_247', '247', 'SQL', 'Query Optimization', 'Medium', 'output', 'What does EXPLAIN show for this query on a table with no index on ''name''?', 'A full table scan (Seq Scan / TABLE ACCESS FULL)', 'A hash join', 'An index seek', 'No output', 'A', 0, 'Without an index on ''name'', the database must perform a full table scan to find matching rows.', 'EXPLAIN SELECT * FROM employees WHERE name = ''Alice'';');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_248', '248', 'SQL', 'Aggregate Functions', 'Hard', 'output', 'Given t(dept, emp_name): (A,''X''),(A,''Y''),(B,''Z''). What is the output in PostgreSQL?', 'A: ''Y, X'' and B: ''Z''', 'Error', 'A: ''X, Y'' and B: ''Z''', 'A: ''XY'' and B: ''Z''', 'C', 2, 'STRING_AGG concatenates values with the separator. ORDER BY inside ensures alphabetical order: X, Y.', 'SELECT dept, STRING_AGG(emp_name, '', '' ORDER BY emp_name) AS members FROM t GROUP BY dept;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_249', '249', 'SQL', 'Window Functions', 'Hard', 'output', 'Given emp(name, salary): (A,50000),(B,60000),(C,60000),(D,70000). What does DENSE_RANK() return?', 'A:1, B:1, C:2, D:3', 'A:1, B:2, C:2, D:4', 'A:1, B:2, C:3, D:4', 'A:1, B:2, C:2, D:3', 'D', 3, 'DENSE_RANK() assigns 1 to A, 2 to B and C (tied), and 3 to D without skipping.', 'SELECT name, DENSE_RANK() OVER (ORDER BY salary) AS drnk FROM emp;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_250', '250', 'SQL', 'Aggregate Functions', 'Easy', 'output', 'Given t(val): (10),(20),(30),(40),(50). What is the output?', 'cnt: 2', 'cnt: 4', 'cnt: 5', 'cnt: 3', 'D', 3, 'Values greater than 25 are 30, 40, 50 - that''s 3 rows.', 'SELECT COUNT(*) AS cnt FROM t WHERE val > 25;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_251', '251', 'SQL', 'NoSQL Concepts', 'Hard', 'output', 'What does this Redis-style command sequence return?', '12', '11', 'Error', '10', 'A', 0, 'SET initializes counter to 10. Two INCR commands add 1 each, making it 12.', 'SET counter 10
INCR counter
INCR counter
GET counter');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_252', '252', 'SQL', 'DML (INSERT/UPDATE/DELETE)', 'Medium', 'output', 'Given t(id, val): (1,10),(2,20),(3,30). After this statement, how many rows remain?', '2 rows: (1,10),(2,20)', '3 rows', '1 row: (3,30)', '0 rows', 'C', 2, 'DELETE removes rows where val < 25 (rows with val 10 and 20), leaving only (3,30).', 'DELETE FROM t WHERE val < 25;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_253', '253', 'SQL', 'Subqueries', 'Easy', 'output', 'Given departments(id,name): (1,''HR''),(2,''IT''). employees(dept_id,name): (1,''Alice''),(1,''Bob''). What is the output?', 'IT', 'No rows', 'HR, IT', 'HR', 'D', 3, 'The subquery returns dept_id=1 only. So only ''HR'' (id=1) matches.', 'SELECT name FROM departments WHERE id IN (SELECT DISTINCT dept_id FROM employees);');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_254', '254', 'SQL', 'DML (INSERT/UPDATE/DELETE)', 'Easy', 'output', 'Given t(id, name): (1,''A''),(2,''B''). After this statement, what is in the table?', 'Error', '(1,''A''),(2,''B'')', '(1,''Z''),(2,''B'')', '(1,''Z''),(2,''Z'')', 'C', 2, 'UPDATE changes the name to ''Z'' only where id=1.', 'UPDATE t SET name = ''Z'' WHERE id = 1;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_255', '255', 'SQL', 'Triggers', 'Medium', 'output', 'What happens when a row is inserted into orders with this trigger in place?', 'The orders table is locked', 'Nothing happens', 'A new row is added to audit_log recording the insert action and order id', 'The insert into orders is blocked', 'C', 2, 'The AFTER INSERT trigger fires after each insert on orders, logging the action in the audit_log table.', 'CREATE TRIGGER log_insert
AFTER INSERT ON orders
FOR EACH ROW
BEGIN
  INSERT INTO audit_log(action, order_id) VALUES (''INSERT'', NEW.id);
END;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_256', '256', 'SQL', 'Views', 'Hard', 'output', 'What happens if you INSERT a row with salary=30000 into this view?', 'The row is inserted successfully', 'An error unrelated to CHECK OPTION', 'The INSERT is rejected because salary 30000 does not satisfy the view condition', 'The view is dropped', 'C', 2, 'WITH CHECK OPTION prevents modifications that would create rows not visible through the view.', 'CREATE VIEW high_sal AS
SELECT * FROM employees WHERE salary > 50000
WITH CHECK OPTION;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_257', '257', 'SQL', 'Aggregate Functions', 'Hard', 'output', 'Given sales(region, amount): (N,100),(N,200),(S,150),(S,250),(S,300). What is the output?', 'N | 300 and S | 700', 'S | 700', 'N | 300', 'No rows', 'B', 1, 'N total=300, S total=700. Only S exceeds 500.', 'SELECT region, SUM(amount) AS total FROM sales GROUP BY region HAVING SUM(amount) > 500;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_258', '258', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Medium', 'output', 'Tables: dept(id,name): (1,''HR''),(2,''IT''),(3,''Sales''). emp(id,dept_id,name): (1,1,''Alice''),(2,1,''Bob''),(3,2,''Charlie''). How many rows does this return?', '3 rows', '2 rows', '5 rows', '4 rows (HR-Alice, HR-Bob, IT-Charlie, Sales-NULL)', 'D', 3, 'LEFT JOIN keeps all dept rows. HR matches 2 employees, IT matches 1, Sales matches none (NULL).', 'SELECT d.name, e.name FROM dept d LEFT JOIN emp e ON d.id = e.dept_id;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_259', '259', 'SQL', 'DML (INSERT/UPDATE/DELETE)', 'Medium', 'output', 'Given t(id, val): (1,10),(2,20),(3,30). What is the result after this statement?', '(1,15),(2,20),(3,35)', 'Error', '(1,10),(2,20),(3,30)', '(1,15),(2,25),(3,35)', 'A', 0, 'UPDATE adds 5 to val for id 1 and 3 only. id=2 remains unchanged.', 'UPDATE t SET val = val + 5 WHERE id IN (1, 3);
SELECT * FROM t ORDER BY id;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_260', '260', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Easy', 'output', 'Tables: A(id,name): (1,''X''),(2,''Y''). B(id,a_id,val): (1,1,''P''),(2,1,''Q''). What does this return?', 'No rows', 'X|P, X|Q, Y|NULL (3 rows)', 'X|P and X|Q (2 rows)', 'X|P (1 row)', 'C', 2, 'INNER JOIN only returns matching rows. A.id=1 matches both B rows, so we get X|P and X|Q. Y has no match.', 'SELECT A.name, B.val FROM A INNER JOIN B ON A.id = B.a_id;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_261', '261', 'SQL', 'Window Functions', 'Medium', 'output', 'Given t(id, val): (1,10),(2,20),(3,30). What does LEAD return?', '(1,10,20),(2,20,30),(3,30,0)', '(1,10,NULL),(2,20,10),(3,30,20)', 'Error', '(1,10,0),(2,20,10),(3,30,20)', 'A', 0, 'LEAD gets the next row''s value. The third argument (0) is the default for the last row which has no next row.', 'SELECT id, val, LEAD(val, 1, 0) OVER (ORDER BY id) AS next_val FROM t;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_262', '262', 'SQL', 'Triggers', 'Medium', 'output', 'Given the SQL below, what is the output?', 'The insert into orders is blocked', 'A new row is added to audit_log recording the insert action and order id', 'The orders table is locked', 'Nothing happens', 'B', 1, 'The AFTER INSERT trigger fires after each insert on orders, logging the action in the audit_log table.', 'CREATE TRIGGER log_insert
AFTER INSERT ON orders
FOR EACH ROW
BEGIN
  INSERT INTO audit_log(action, order_id) VALUES (''INSERT'', NEW.id);
END;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_263', '263', 'SQL', 'Stored Procedures', 'Medium', 'output', 'What does this stored procedure do when called with CALL greet(''World'')?', 'Returns NULL', 'Returns ''Hello, World!''', 'Error', 'Returns ''Hello, !''', 'B', 1, 'The procedure concatenates ''Hello, '' with the input parameter ''World'' and ''!'', producing ''Hello, World!''.', 'CREATE PROCEDURE greet(IN msg VARCHAR(100))
BEGIN
  SELECT CONCAT(''Hello, '', msg, ''!'') AS greeting;
END;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_264', '264', 'SQL', 'Aggregate Functions', 'Medium', 'output', 'Given nums(val): (5),(5),(10),(10),(10). What is the output?', 'Error', 'unique_count: 5', 'unique_count: 3', 'unique_count: 2', 'D', 3, 'There are 2 distinct values: 5 and 10.', 'SELECT COUNT(DISTINCT val) AS unique_count FROM nums;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_265', '265', 'SQL', 'SELECT basics', 'Hard', 'output', 'What is the result?', 'result: NULL', 'result: 0', 'An error (division by zero)', 'result: Infinity', 'C', 2, 'Division by zero raises an error in most SQL databases (though some like MySQL may return NULL with a warning).', 'SELECT 1/0 AS result;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_266', '266', 'SQL', 'SELECT basics', 'Easy', 'output', 'What is the output?', 'result: SQL', 'Error', 'result: Sql', 'result: sql', 'D', 3, 'LOWER converts all characters to lowercase.', 'SELECT LOWER(''SQL'') AS result;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_267', '267', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Easy', 'output', 'What happens after executing this statement?', 'An error occurs', 'All existing rows are deleted', 'A new table is created', 'A new email column is added to the employees table with NULL values for existing rows', 'D', 3, 'ALTER TABLE ADD COLUMN adds the new column; existing rows get NULL for the new column unless a DEFAULT is specified.', 'ALTER TABLE employees ADD COLUMN email VARCHAR(255);');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_268', '268', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Easy', 'output', 'Given table: products(id, name, price) with rows (1,''A'',10),(2,''B'',20),(3,''C'',30). What does this return?', 'C, B', 'A', 'A, B, C', 'B, C', 'D', 3, 'Only B (20) and C (30) have price > 15. ORDER BY name sorts them alphabetically: B, C.', 'SELECT name FROM products WHERE price > 15 ORDER BY name;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_269', '269', 'SQL', 'Subqueries', 'Hard', 'output', 'Given the SQL below, what is the output?', 'Error', 'id:4 salary:80000 only', 'All 4 rows', 'id:2 salary:60000 and id:4 salary:80000', 'D', 3, 'The correlated subquery finds the max salary per department. id=2 has the max in dept 1, id=4 in dept 2.', 'SELECT e.id, e.salary FROM emp e WHERE e.salary = (SELECT MAX(salary) FROM emp e2 WHERE e2.dept_id = e.dept_id);');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_270', '270', 'SQL', 'Views', 'Medium', 'output', 'Given employees(name,salary): (A,50000),(B,80000),(C,30000). What does querying this view return?', 'A:50000, B:80000', 'A:50000, B:80000, C:30000', 'Error', 'B:80000', 'A', 0, 'The view filters employees with salary > 40000, returning A and B.', 'CREATE VIEW high_earners AS SELECT name, salary FROM employees WHERE salary > 40000;
SELECT * FROM high_earners;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_271', '271', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Medium', 'output', 'Given the SQL below, what is the output?', 'cust_id 1: 300 and cust_id 3: 300', 'cust_id 3: 300 and cust_id 1: 300', 'All 3 customers', 'Error', 'A', 0, 'Totals: cust 1=300, cust 2=200, cust 3=300. ORDER BY total DESC with LIMIT 2 returns cust 3 and cust 1 (both 300, order depends on DBMS).', 'SELECT cust_id, SUM(amount) AS total FROM orders GROUP BY cust_id ORDER BY total DESC LIMIT 2;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_272', '272', 'SQL', 'Window Functions', 'Medium', 'output', 'Given emp(name, salary): (A,50000),(B,60000),(C,60000),(D,70000). What does this return for ROW_NUMBER?', 'A:1, B:1, C:1, D:1', 'A:1, B:2, C:2, D:3', 'A:1, B:2, C:2, D:4', 'A:1, B:2, C:3, D:4', 'D', 3, 'ROW_NUMBER() assigns unique sequential numbers: 1,2,3,4 regardless of ties.', 'SELECT name, ROW_NUMBER() OVER (ORDER BY salary) AS rn FROM emp;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_273', '273', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Hard', 'output', 'Given t(category, val): (A,1),(A,2),(B,3),(B,4),(C,5). What is the output?', 'Error', '15', 'A:3, B:7, C:5, NULL:15 (grand total row)', 'A:3, B:7, C:5', 'C', 2, 'ROLLUP adds a grand total row (NULL category, sum=15) in addition to the group sums.', 'SELECT category, SUM(val) AS s FROM t GROUP BY ROLLUP(category);');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_274', '274', 'SQL', 'Query Optimization', 'Hard', 'output', 'Which query is likely more efficient on a large table with an index on (dept_id)?', 'Query A, because Query B''s expression prevents index usage', 'Query B, because the addition is optimized away', 'Neither can use the index', 'Both are equally efficient', 'A', 0, 'Applying a function or expression to an indexed column (dept_id + 0) prevents the optimizer from using the index (SARGability).', '-- Query A:
SELECT * FROM emp WHERE dept_id = 5;
-- Query B:
SELECT * FROM emp WHERE dept_id + 0 = 5;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_275', '275', 'SQL', 'Query Optimization', 'Medium', 'output', 'Given the SQL below, what is the output?', 'An index seek', 'No output', 'A hash join', 'A full table scan (Seq Scan / TABLE ACCESS FULL)', 'D', 3, 'Without an index on ''name'', the database must perform a full table scan to find matching rows.', 'EXPLAIN SELECT * FROM employees WHERE name = ''Alice'';');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_276', '276', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Medium', 'output', 'Given employees(dept, salary): (HR,50000),(HR,60000),(IT,70000),(IT,80000). What is the output?', 'No rows', 'HR | 55000 and IT | 75000', 'HR | 55000', 'IT | 75000', 'D', 3, 'HR avg=55000, IT avg=75000. Only IT has AVG(salary) > 60000.', 'SELECT dept, AVG(salary) AS avg_sal FROM employees GROUP BY dept HAVING AVG(salary) > 60000;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_277', '277', 'SQL', 'Transactions', 'Hard', 'output', 'What is the final value after these nested savepoints?', 'val: 2', 'val: original value', 'val: 3', 'val: 1', 'A', 0, 'ROLLBACK TO sp2 undoes the update to 3, restoring val to 2 (the state at sp2). COMMIT saves val=2.', 'BEGIN;
UPDATE t SET val = 1;
SAVEPOINT sp1;
UPDATE t SET val = 2;
SAVEPOINT sp2;
UPDATE t SET val = 3;
ROLLBACK TO sp2;
COMMIT;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_278', '278', 'SQL', 'Window Functions', 'Hard', 'output', 'Given emp(name, salary): (A,50000),(B,60000),(C,60000),(D,70000). What does RANK() return?', 'A:1, B:1, C:2, D:3', 'A:1, B:2, C:3, D:4', 'A:1, B:2, C:2, D:4', 'A:1, B:2, C:2, D:3', 'C', 2, 'RANK() assigns 1 to A, 2 to B and C (tied), then skips 3 and assigns 4 to D.', 'SELECT name, RANK() OVER (ORDER BY salary) AS rnk FROM emp;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_279', '279', 'SQL', 'Aggregate Functions', 'Easy', 'output', 'Given the SQL below, what is the output?', 'cnt: 4', 'cnt: 2', 'cnt: 3', 'cnt: 5', 'C', 2, 'Values greater than 25 are 30, 40, 50 - that''s 3 rows.', 'SELECT COUNT(*) AS cnt FROM t WHERE val > 25;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_280', '280', 'SQL', 'Aggregate Functions', 'Hard', 'output', 'Given the SQL below, what is the output?', 'S | 700', 'No rows', 'N | 300', 'N | 300 and S | 700', 'A', 0, 'N total=300, S total=700. Only S exceeds 500.', 'SELECT region, SUM(amount) AS total FROM sales GROUP BY region HAVING SUM(amount) > 500;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_281', '281', 'SQL', 'Normalization', 'Medium', 'output', 'Consider: students(id, name, course1, course2, course3). Is this in 1NF?', 'Cannot determine', 'It is in 3NF', 'Yes, it is in 1NF', 'No, because courses are stored as repeating groups in separate columns', 'D', 3, 'Having course1, course2, course3 as separate columns is a repeating group, violating 1NF. Courses should be in a separate table.', '-- Table: students
-- Columns: id, name, course1, course2, course3
-- Row example: (1, ''Alice'', ''Math'', ''Science'', NULL)');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_282', '282', 'SQL', 'Subqueries', 'Easy', 'output', 'Given the SQL below, what is the output?', 'IT', 'HR, IT', 'HR', 'No rows', 'C', 2, 'The subquery returns dept_id=1 only. So only ''HR'' (id=1) matches.', 'SELECT name FROM departments WHERE id IN (SELECT DISTINCT dept_id FROM employees);');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_283', '283', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Medium', 'output', 'Tables: A(id,name): (1,''X''),(2,''Y''). B(a_id,val): (1,''P''). What does this return?', 'Error', 'X|P (1 row)', 'Y|NULL (1 row)', 'X|P and Y|NULL (2 rows)', 'D', 3, 'LEFT JOIN returns all rows from A. X matches B (val=P), Y has no match (val=NULL).', 'SELECT A.name, B.val FROM A LEFT JOIN B ON A.id = B.a_id;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_284', '284', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Hard', 'output', 'Tables: t1(id): (1),(2),(3). t2(id): (2),(3),(4). What does FULL OUTER JOIN return?', '(1,NULL),(2,2),(3,3) - 3 rows', '(2,2),(3,3) - 2 rows', '(2,2),(3,3),(NULL,4) - 3 rows', '(1,NULL),(2,2),(3,3),(NULL,4) - 4 rows', 'D', 3, 'FULL OUTER JOIN returns all rows from both tables: matches plus unmatched rows from each side with NULLs.', 'SELECT t1.id AS a, t2.id AS b FROM t1 FULL OUTER JOIN t2 ON t1.id = t2.id;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_285', '285', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Hard', 'output', 'Given data(val): (1),(2),(NULL),(4). What is the result?', 'c1: 3, c2: 4', 'c1: 4, c2: 4', 'c1: 4, c2: 3', 'c1: 3, c2: 3', 'C', 2, 'COUNT(*) counts all rows (4), COUNT(val) skips the NULL row (3).', 'SELECT COUNT(*) AS c1, COUNT(val) AS c2 FROM data;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_286', '286', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Easy', 'output', 'Given t(val): (1),(2),(3),(4),(5). What is the output?', '1, 2, 3, 4, 5', '3', '2, 3, 4', '2, 3', 'C', 2, 'BETWEEN 2 AND 4 is inclusive, returning 2, 3, and 4.', 'SELECT val FROM t WHERE val BETWEEN 2 AND 4 ORDER BY val;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_287', '287', 'SQL', 'Subqueries', 'Hard', 'output', 'Given t(id, val): (1,10),(2,20),(3,30). What does this return?', 'id:2, val:20, total:20', 'id:2, val:20, total:60', 'Error', 'id:2, val:20, total:NULL', 'B', 1, 'The scalar subquery returns the sum of all val (10+20+30=60) for each row. Only id=2 is in the result.', 'SELECT id, val, (SELECT SUM(val) FROM t) AS total FROM t WHERE id = 2;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_288', '288', 'SQL', 'SELECT basics', 'Medium', 'output', 'What is the output?', 'result: 42', 'result: 0', 'result: -42', 'Error', 'A', 0, 'ABS returns the absolute value, converting -42 to 42.', 'SELECT ABS(-42) AS result;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_289', '289', 'SQL', 'Window Functions', 'Medium', 'output', 'Given t(id, val): (1,10),(2,20),(3,30). What does LAG return?', '(1,10,20),(2,20,30),(3,30,NULL)', 'Error', '(1,10,10),(2,20,20),(3,30,30)', '(1,10,NULL),(2,20,10),(3,30,20)', 'D', 3, 'LAG gets the previous row''s value. First row has no previous value (NULL), row 2 gets 10, row 3 gets 20.', 'SELECT id, val, LAG(val) OVER (ORDER BY id) AS prev_val FROM t;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_290', '290', 'SQL', 'CTEs', 'Hard', 'output', 'Given the SQL below, what is the output?', '8', '5', '13', 'Error', 'A', 0, 'This generates Fibonacci numbers. At n=7: sequence is 0,1,1,2,3,5,8. Column ''a'' at n=7 is 8.', 'WITH RECURSIVE fib(n, a, b) AS (
  SELECT 1, 0, 1
  UNION ALL
  SELECT n+1, b, a+b FROM fib WHERE n < 7
)
SELECT a FROM fib WHERE n = 7;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_291', '291', 'SQL', 'Normalization', 'Medium', 'output', 'Given the SQL below, what is the output?', 'Yes, it is in 1NF', 'Cannot determine', 'It is in 3NF', 'No, because courses are stored as repeating groups in separate columns', 'D', 3, 'Having course1, course2, course3 as separate columns is a repeating group, violating 1NF. Courses should be in a separate table.', '-- Table: students
-- Columns: id, name, course1, course2, course3
-- Row example: (1, ''Alice'', ''Math'', ''Science'', NULL)');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_292', '292', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Hard', 'output', 'What does this statement do?', 'Prevents any deletion of customers', 'Adds a foreign key that deletes order rows when the referenced customer is deleted', 'Adds a primary key to orders', 'Creates a new table', 'B', 1, 'ON DELETE CASCADE means that when a customer is deleted, all their related orders are automatically deleted too.', 'ALTER TABLE orders ADD CONSTRAINT fk_customer FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_293', '293', 'SQL', 'SELECT basics', 'Medium', 'output', 'What is the result?', 'result: Data', 'result: base', 'result: D', 'result: Datab', 'A', 0, 'SUBSTRING extracts 4 characters starting at position 1: ''Data''.', 'SELECT SUBSTRING(''Database'' FROM 1 FOR 4) AS result;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_294', '294', 'SQL', 'Aggregate Functions', 'Easy', 'output', 'Given scores(val): (10),(20),(30). What is the output?', 'total: 60, average: 20', 'total: 60, average: 60', 'Error', 'total: 30, average: 10', 'A', 0, 'SUM = 10+20+30 = 60, AVG = 60/3 = 20.', 'SELECT SUM(val) AS total, AVG(val) AS average FROM scores;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_295', '295', 'SQL', 'Aggregate Functions', 'Easy', 'output', 'Given the SQL below, what is the output?', 'total: 30, average: 10', 'Error', 'total: 60, average: 20', 'total: 60, average: 60', 'C', 2, 'SUM = 10+20+30 = 60, AVG = 60/3 = 20.', 'SELECT SUM(val) AS total, AVG(val) AS average FROM scores;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_296', '296', 'SQL', 'Transactions', 'Easy', 'output', 'Given t(val): (100). What value is in t after these statements?', 'Error', 'val: 200', 'val: 100', 'Table is empty', 'C', 2, 'ROLLBACK undoes the UPDATE, so val returns to its original value of 100.', 'BEGIN;
UPDATE t SET val = 200;
ROLLBACK;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_297', '297', 'SQL', 'Subqueries', 'Medium', 'output', 'Given products(name, price): (A,10),(B,20),(C,30),(D,40). What is returned?', 'No rows', 'D', 'A, B, C, D', 'C, D', 'D', 3, 'The subquery returns 10 and 20. > ALL means greater than the maximum (20). C(30) and D(40) qualify.', 'SELECT name FROM products WHERE price > ALL (SELECT price FROM products WHERE name IN (''A'',''B''));');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_298', '298', 'SQL', 'SELECT basics', 'Medium', 'output', 'What is the result?', 'result: 12', 'result: 1024', 'result: 210', 'result: 20', 'B', 1, 'POWER(2, 10) computes 2^10 = 1024.', 'SELECT POWER(2, 10) AS result;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_299', '299', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Easy', 'output', 'Tables: colors(id,name): (1,''Red''),(2,''Blue''). sizes(id,name): (1,''S''),(2,''M''). How many rows does CROSS JOIN return?', '8 rows', '0 rows', '4 rows', '2 rows', 'C', 2, 'CROSS JOIN produces a Cartesian product: 2 colors x 2 sizes = 4 combinations.', 'SELECT c.name, s.name FROM colors c CROSS JOIN sizes s;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_300', '300', 'SQL', 'CTEs', 'Easy', 'output', 'Given t(name, val): (A,10),(B,20),(C,30). What does this CTE query return?', 's: NULL', 's: 60', 's: 30', 'Error', 'B', 1, 'The CTE computes SUM(10+20+30) = 60.', 'WITH total AS (SELECT SUM(val) AS s FROM t)
SELECT s FROM total;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_301', '301', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Easy', 'scenario', 'You need to find all customers who placed orders in the last 30 days. Which WHERE condition is best?', 'WHERE order_date LIKE ''2025%''', 'WHERE order_date = CURRENT_DATE', 'WHERE YEAR(order_date) = 2025', 'WHERE order_date >= CURRENT_DATE - INTERVAL ''30'' DAY', 'D', 3, 'Using date arithmetic with CURRENT_DATE ensures a rolling 30-day window that works regardless of the current date.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_302', '302', 'SQL', 'Normalization', 'Easy', 'scenario', 'Consider this scenario: A table stores customer orders with customer name and address repeated in every order row. What problem does this cause?', 'Better data integrity', 'Data redundancy and update anomalies', 'Faster queries', 'No problem at all', 'B', 1, 'Repeating customer data in every order creates redundancy and risks inconsistency if updated in one place but not another.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_303', '303', 'SQL', 'Query Optimization', 'Hard', 'scenario', 'A report query joins 8 tables and takes 30 seconds. EXPLAIN shows nested loop joins with full table scans. What is the best first step?', 'Analyze the execution plan and add missing indexes on join and filter columns', 'Increase the server timeout', 'Split into 8 separate queries', 'Rewrite the entire query as a stored procedure', 'A', 0, 'The execution plan reveals full table scans, suggesting missing indexes. Adding indexes on join/filter columns is typically the highest-impact fix.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_304', '304', 'SQL', 'DML (INSERT/UPDATE/DELETE)', 'Medium', 'scenario', 'You need to copy all active users from ''users'' to ''active_users'' table. What DML approach is best?', 'UPDATE active_users FROM users WHERE status = ''active'';', 'CREATE TABLE active_users AS SELECT * FROM users;', 'COPY users TO active_users WHERE status = ''active'';', 'INSERT INTO active_users SELECT * FROM users WHERE status = ''active'';', 'D', 3, 'INSERT INTO ... SELECT copies qualifying rows from one table to another existing table.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_305', '305', 'SQL', 'DML (INSERT/UPDATE/DELETE)', 'Easy', 'scenario', 'Consider this scenario: You need to increase all employee salaries by 10%. Which statement is correct?', 'SELECT salary * 1.10 FROM employees;', 'ALTER employees SET salary = salary + 10%;', 'UPDATE employees SET salary = salary * 1.10;', 'INSERT INTO employees salary = salary * 1.10;', 'C', 2, 'UPDATE with SET salary = salary * 1.10 increases every employee''s salary by 10%.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_306', '306', 'SQL', 'Aggregate Functions', 'Easy', 'scenario', 'Management wants to know the total revenue per region. Which approach is correct?', 'SELECT region, revenue FROM sales ORDER BY region;', 'SELECT region, SUM(revenue) FROM sales GROUP BY region;', 'SELECT region, COUNT(revenue) FROM sales;', 'SELECT SUM(region) FROM sales;', 'B', 1, 'SUM(revenue) with GROUP BY region calculates the total revenue for each region.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_307', '307', 'SQL', 'SELECT basics', 'Hard', 'scenario', 'A report requires pivoting rows to columns: showing months as columns and products as rows with sales amounts. Standard SQL doesn''t have PIVOT. What approach works in any DBMS?', 'Use CASE expressions inside aggregate functions: SUM(CASE WHEN month=''Jan'' THEN amount END) AS Jan', 'Use CROSS JOIN with all months', 'Use UNION ALL to combine monthly queries', 'Create separate tables for each month', 'A', 0, 'Conditional aggregation with CASE inside SUM/COUNT is a portable cross-database pivot technique.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_308', '308', 'SQL', 'Views', 'Hard', 'scenario', 'You need to restrict certain columns from some users while allowing full access to others. What is the best approach?', 'Create separate tables for each user group', 'Use row-level security policies only', 'Create a view exposing only allowed columns and grant SELECT on the view (not the base table)', 'Use application-level filtering only', 'C', 2, 'A view can expose a subset of columns and you can grant permissions on the view, providing column-level security.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_309', '309', 'SQL', 'SELECT basics', 'Easy', 'scenario', 'A manager asks you to produce a list of all employee names and their hire dates. Which SQL approach is most appropriate?', 'SELECT * FROM employees;', 'SELECT name FROM employees UNION SELECT hire_date FROM employees;', 'SELECT hire_date FROM employees WHERE name IS NOT NULL;', 'SELECT name, hire_date FROM employees;', 'D', 3, 'Selecting only the needed columns (name, hire_date) is the most efficient and clear approach.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_310', '310', 'SQL', 'Indexes', 'Medium', 'scenario', 'Consider this scenario: After bulk loading 10 million rows, queries are slow despite having indexes. What should you do?', 'Add more indexes', 'Drop all indexes', 'Rebuild/reorganize the indexes and update statistics', 'Restart the database server', 'C', 2, 'Bulk inserts can fragment indexes and make statistics stale. Rebuilding indexes and updating statistics helps the optimizer.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_311', '311', 'SQL', 'Indexes', 'Medium', 'scenario', 'A query filters on (status, created_date) and you want one index to cover both. What do you create?', 'A partial index on created_date', 'Two separate indexes on status and created_date', 'A composite index on (status, created_date)', 'A unique index on status', 'C', 2, 'A composite index on (status, created_date) efficiently covers queries filtering on both columns, especially if status is the leading column.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_312', '312', 'SQL', 'Query Optimization', 'Medium', 'scenario', 'A query uses WHERE YEAR(created_at) = 2025. Why might this perform poorly?', 'Applying a function to an indexed column prevents index usage (not SARGable)', 'YEAR() is slow', '2025 is too far in the future', 'The column is not a date type', 'A', 0, 'Functions on indexed columns prevent the optimizer from using the index. Rewrite as: WHERE created_at >= ''2025-01-01'' AND created_at < ''2026-01-01''.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_313', '313', 'SQL', 'Query Optimization', 'Medium', 'scenario', 'Your query uses SELECT DISTINCT on a 10-million row table and is slow. What should you investigate?', 'Removing all indexes to speed up DISTINCT', 'Replacing DISTINCT with GROUP BY ALL', 'Adding more columns to SELECT DISTINCT', 'Whether DISTINCT is actually needed, and if so, whether an index can support the distinct operation', 'D', 3, 'DISTINCT requires sorting/hashing all rows. Often DISTINCT masks a join issue. If needed, indexes on the selected columns can help.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_314', '314', 'SQL', 'NoSQL Concepts', 'Hard', 'scenario', 'Your system must handle millions of writes per second across multiple data centers with no single point of failure. Which database model is best?', 'A single-node SQL database', 'A distributed wide-column store like Cassandra with tunable consistency', 'An in-memory key-value store', 'A document store on a single server', 'B', 1, 'Cassandra is designed for multi-datacenter, highly available writes with tunable consistency, handling massive write throughput.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_315', '315', 'SQL', 'Stored Procedures', 'Hard', 'scenario', 'You need to generate a dynamic pivot report where column names are not known at design time. What approach works?', 'A CTE with hardcoded columns', 'A stored procedure that builds and executes dynamic SQL based on metadata', 'A simple GROUP BY query', 'A static PIVOT query', 'B', 1, 'Dynamic SQL in a stored procedure can construct the PIVOT columns at runtime based on the actual data values.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_316', '316', 'SQL', 'Normalization', 'Easy', 'scenario', 'A table stores customer orders with customer name and address repeated in every order row. What problem does this cause?', 'Faster queries', 'Better data integrity', 'Data redundancy and update anomalies', 'No problem at all', 'C', 2, 'Repeating customer data in every order creates redundancy and risks inconsistency if updated in one place but not another.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_317', '317', 'SQL', 'Aggregate Functions', 'Hard', 'scenario', 'Consider this scenario: You need to calculate the median salary in a department. SQL has no built-in MEDIAN function. What is the best approach?', 'Use AVG(salary)', 'Use (MAX(salary) + MIN(salary)) / 2', 'Use MODE(salary)', 'Use PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY salary) or a window function approach', 'D', 3, 'PERCENTILE_CONT(0.5) calculates the true median. AVG gives the mean, and (MAX+MIN)/2 gives the midrange, neither of which is the median.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_318', '318', 'SQL', 'Aggregate Functions', 'Medium', 'scenario', 'You need to count orders per customer but only include customers with more than 10 orders. Which approach is correct?', 'SELECT customer_id FROM orders HAVING COUNT(*) > 10;', 'SELECT customer_id, COUNT(*) FROM orders WHERE COUNT(*) > 10 GROUP BY customer_id;', 'SELECT customer_id, COUNT(*) AS cnt FROM orders GROUP BY customer_id HAVING COUNT(*) > 10;', 'SELECT COUNT(*) FROM orders WHERE customer_id > 10;', 'C', 2, 'HAVING filters groups after GROUP BY. You cannot use aggregate functions in WHERE.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_319', '319', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Medium', 'scenario', 'You need to find records that exist in table A but not in table B. What is the most readable approach?', 'SELECT * FROM A CROSS JOIN B WHERE A.id != B.id', 'SELECT a.* FROM A LEFT JOIN B ON A.id = B.id WHERE B.id IS NULL', 'SELECT * FROM A INNER JOIN B ON A.id != B.id', 'SELECT * FROM A WHERE id > (SELECT MAX(id) FROM B)', 'B', 1, 'The LEFT JOIN anti-join pattern is widely understood and performs well: it returns A rows with no match in B.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_320', '320', 'SQL', 'Stored Procedures', 'Medium', 'scenario', 'You need to log the start and end time of a long-running ETL process. Where is the best place to add this logic?', 'Inside a stored procedure that wraps the ETL logic and records timestamps in a log table', 'In a CHECK constraint', 'In a view', 'In a trigger on the target table', 'A', 0, 'A stored procedure can log timestamps before and after the ETL logic, centralizing the monitoring in the database.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_321', '321', 'SQL', 'Transactions', 'Medium', 'scenario', 'Two users simultaneously try to book the last available seat. How do you prevent double-booking?', 'Let both users book and handle it later', 'Use a transaction with SELECT ... FOR UPDATE to lock the seat row before updating', 'Use READ UNCOMMITTED isolation', 'Use a view to prevent concurrent access', 'B', 1, 'SELECT FOR UPDATE acquires a row-level lock, preventing other transactions from modifying the row until the lock is released.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_322', '322', 'SQL', 'NoSQL Concepts', 'Easy', 'scenario', 'Your application needs to cache frequently accessed data with sub-millisecond response times. Which type of database is most suitable?', 'A key-value store like Redis', 'A relational database with indexes', 'A graph database like Neo4j', 'A document database like MongoDB', 'A', 0, 'Key-value stores like Redis operate in-memory and provide sub-millisecond read/write operations, ideal for caching.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_323', '323', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Medium', 'scenario', 'You need to ensure that the ''status'' column in the orders table only accepts values ''pending'', ''shipped'', or ''delivered''. What is the best constraint?', 'CREATE INDEX ON orders(status);', 'ALTER TABLE orders ADD UNIQUE(status);', 'ALTER TABLE orders ADD CONSTRAINT chk_status CHECK (status IN (''pending'', ''shipped'', ''delivered''));', 'Add a trigger that rejects invalid values', 'C', 2, 'A CHECK constraint declaratively enforces the allowed values at the database level.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_324', '324', 'SQL', 'CTEs', 'Medium', 'scenario', 'You need to find all subordinates of a manager in an employee hierarchy. What SQL feature is best?', 'A stored procedure with cursors', 'A simple INNER JOIN', 'A recursive CTE that traverses the employee-manager relationship', 'Multiple UNION ALL queries for each level', 'C', 2, 'A recursive CTE naturally traverses hierarchical data by repeatedly joining the table to itself until no more rows are found.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_325', '325', 'SQL', 'CTEs', 'Medium', 'scenario', 'You need to reuse the same aggregation result in both the SELECT and WHERE of a query. What is the cleanest approach?', 'Define the aggregation as a CTE and reference it in both places', 'Use a global variable', 'Use a temporary table', 'Calculate the aggregation twice with identical subqueries', 'A', 0, 'A CTE computes the result once and allows it to be referenced multiple times in the main query.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_326', '326', 'SQL', 'SELECT basics', 'Medium', 'scenario', 'You need to generate a report showing employee names with NULL phone numbers displayed as ''N/A''. Which approach works?', 'SELECT name, COALESCE(phone, ''N/A'') AS phone FROM employees;', 'SELECT name, phone FROM employees WHERE phone IS NOT NULL;', 'SELECT name, NVL(phone) FROM employees;', 'SELECT name, IFNULL(phone) FROM employees;', 'A', 0, 'COALESCE(phone, ''N/A'') replaces NULL phone values with ''N/A'' while keeping actual phone numbers.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_327', '327', 'SQL', 'NoSQL Concepts', 'Medium', 'scenario', 'Consider this scenario: Your application stores user profiles with varying attributes (some users have social links, some have bio, etc.). Which database model is most flexible?', 'A document database like MongoDB that stores schema-flexible JSON documents', 'A key-value store', 'A relational database with columns for every possible attribute', 'A graph database', 'A', 0, 'Document databases allow each document to have different fields, naturally handling varying attributes without NULL-heavy columns.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_328', '328', 'SQL', 'Window Functions', 'Hard', 'scenario', 'You need to detect consecutive days when a server was down. Which approach is best?', 'Use a simple WHERE clause', 'Use CROSS JOIN all dates', 'Use COUNT(*) GROUP BY date', 'Use ROW_NUMBER() to create groups of consecutive dates (gaps-and-islands technique)', 'D', 3, 'The gaps-and-islands technique uses the difference between ROW_NUMBER and the date to identify consecutive sequences.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_329', '329', 'SQL', 'Transactions', 'Hard', 'scenario', 'Your application requires that once a row is read within a transaction, its value cannot change until the transaction ends. Which isolation level do you need?', 'REPEATABLE READ', 'READ COMMITTED', 'No isolation level is needed', 'READ UNCOMMITTED', 'A', 0, 'REPEATABLE READ ensures that if a row is read twice in the same transaction, the same value is returned both times.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_330', '330', 'SQL', 'Window Functions', 'Easy', 'scenario', 'You need to show each employee''s salary alongside the department average salary. What approach preserves individual rows?', 'Use AVG(salary) OVER (PARTITION BY department) as a window function', 'Use GROUP BY department with AVG(salary)', 'Use DISTINCT with AVG', 'Use a CROSS JOIN with a subquery', 'A', 0, 'A window function computes the department average without collapsing rows, so each employee row is preserved.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_331', '331', 'SQL', 'Views', 'Medium', 'scenario', 'You have a dashboard that queries a complex aggregation. The query is slow. What can you use to pre-compute the results?', 'A trigger that recalculates on every data change', 'An index on every column', 'A materialized view that is refreshed periodically', 'A regular view (which re-runs the query each time)', 'C', 2, 'A materialized view stores the precomputed results, making dashboard queries fast. Periodic refresh keeps data reasonably current.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_332', '332', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Hard', 'scenario', 'You need to produce a report of all possible employee-project combinations (for planning), even if no assignment exists. Which approach works?', 'UNION ALL employees and projects', 'LEFT JOIN employees to assignments only', 'CROSS JOIN employees and projects, then LEFT JOIN assignments to see existing ones', 'INNER JOIN employees, projects, and assignments', 'C', 2, 'CROSS JOIN creates all combinations; LEFT JOINing assignments shows which ones already exist.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_333', '333', 'SQL', 'NoSQL Concepts', 'Medium', 'scenario', 'Your application needs to store and query highly connected data like social network relationships. Which type of database is best?', 'A key-value store like Redis', 'A relational database with self-joins', 'A graph database like Neo4j', 'A document store like MongoDB', 'C', 2, 'Graph databases natively store relationships as edges and nodes, making traversal queries much more efficient than joins in relational databases.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_334', '334', 'SQL', 'Triggers', 'Medium', 'scenario', 'You want to automatically set ''updated_at'' to the current timestamp whenever a row is modified. What is the best approach?', 'A BEFORE UPDATE trigger that sets NEW.updated_at = CURRENT_TIMESTAMP', 'A CHECK constraint on updated_at', 'Application code that always includes updated_at in UPDATE statements', 'An AFTER UPDATE trigger that runs a separate UPDATE', 'A', 0, 'A BEFORE UPDATE trigger modifies the row data before it is written, efficiently setting the timestamp without an extra UPDATE.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_335', '335', 'SQL', 'Normalization', 'Medium', 'scenario', 'When should you denormalize a database?', 'When read performance is critical and joins are a bottleneck', 'When you want to reduce storage', 'Never, normalization is always better', 'Always, for better data integrity', 'A', 0, 'Denormalization trades redundancy for read performance, useful in data warehouses or read-heavy workloads where joins are expensive.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_336', '336', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Medium', 'scenario', 'You need to find employees who do not have a matching record in the departments table. Which approach is most efficient?', 'SELECT * FROM employees WHERE dept_id NOT IN (SELECT id FROM departments);', 'SELECT * FROM employees CROSS JOIN departments WHERE employees.dept_id != departments.id;', 'SELECT * FROM employees MINUS SELECT * FROM departments;', 'SELECT e.* FROM employees e LEFT JOIN departments d ON e.dept_id = d.id WHERE d.id IS NULL;', 'D', 3, 'A LEFT JOIN with a NULL check on the right side is an efficient anti-join pattern to find unmatched rows.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_337', '337', 'SQL', 'Window Functions', 'Hard', 'scenario', 'Consider this scenario: You need to calculate a 7-day moving average of daily revenue. Which window frame is correct?', 'AVG(revenue) OVER (PARTITION BY day)', 'AVG(revenue) OVER (ORDER BY day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)', 'AVG(revenue) OVER (ORDER BY day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)', 'AVG(revenue) GROUP BY day', 'C', 2, 'ROWS BETWEEN 6 PRECEDING AND CURRENT ROW creates a sliding window of 7 days (current + 6 preceding).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_338', '338', 'SQL', 'Window Functions', 'Medium', 'scenario', 'Consider this scenario: You need to calculate a running total of sales by date. Which approach is correct?', 'SUM(amount) OVER (ORDER BY sale_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)', 'TOTAL(amount) OVER (ORDER BY sale_date)', 'SUM(amount) OVER (PARTITION BY sale_date)', 'SUM(amount) GROUP BY sale_date', 'A', 0, 'The window frame ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW creates a cumulative sum from the first row to the current row.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_339', '339', 'SQL', 'DML (INSERT/UPDATE/DELETE)', 'Easy', 'scenario', 'You need to increase all employee salaries by 10%. Which statement is correct?', 'ALTER employees SET salary = salary + 10%;', 'UPDATE employees SET salary = salary * 1.10;', 'SELECT salary * 1.10 FROM employees;', 'INSERT INTO employees salary = salary * 1.10;', 'B', 1, 'UPDATE with SET salary = salary * 1.10 increases every employee''s salary by 10%.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_340', '340', 'SQL', 'Subqueries', 'Easy', 'scenario', 'You need to find employees earning more than the average salary. Which approach is simplest?', 'SELECT * FROM employees WHERE salary > (SELECT AVG(salary) FROM employees);', 'SELECT * FROM employees HAVING salary > AVG(salary);', 'SELECT * FROM employees WHERE salary > AVG(salary);', 'SELECT * FROM employees ORDER BY salary > AVG(salary);', 'A', 0, 'A scalar subquery in WHERE calculates the average once and compares each employee''s salary against it.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_341', '341', 'SQL', 'DML (INSERT/UPDATE/DELETE)', 'Medium', 'scenario', 'You need to delete all orders older than 5 years for GDPR compliance. What is the safest approach?', 'TRUNCATE orders;', 'BEGIN; DELETE FROM orders WHERE order_date < CURRENT_DATE - INTERVAL ''5 YEAR''; -- verify count, then COMMIT;', 'DROP TABLE orders;', 'DELETE FROM orders; -- delete all', 'B', 1, 'Using a transaction allows you to verify the affected rows before committing, preventing accidental mass deletion.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_342', '342', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Hard', 'scenario', 'You need to change a column from VARCHAR(50) to VARCHAR(200) without losing data. What is the safest approach?', 'ALTER TABLE t ALTER COLUMN col TYPE VARCHAR(200);', 'Use UPDATE to truncate values', 'Create a new table and copy data', 'DROP the column and recreate it', 'A', 0, 'Altering the column type to a larger VARCHAR is safe and preserves existing data since all current values fit in the new size.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_343', '343', 'SQL', 'Indexes', 'Medium', 'scenario', 'After bulk loading 10 million rows, queries are slow despite having indexes. What should you do?', 'Drop all indexes', 'Restart the database server', 'Rebuild/reorganize the indexes and update statistics', 'Add more indexes', 'C', 2, 'Bulk inserts can fragment indexes and make statistics stale. Rebuilding indexes and updating statistics helps the optimizer.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_344', '344', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Easy', 'scenario', 'You need to add a new column ''email'' to an existing users table. What DDL command do you use?', 'CREATE COLUMN email ON users;', 'INSERT COLUMN email INTO users;', 'ALTER TABLE users ADD COLUMN email VARCHAR(255);', 'UPDATE TABLE users ADD email;', 'C', 2, 'ALTER TABLE with ADD COLUMN is the DDL statement to add a new column to an existing table.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_345', '345', 'SQL', 'Subqueries', 'Medium', 'scenario', 'You want to find departments that have at least one employee earning over $100,000. Which is most efficient?', 'SELECT * FROM departments WHERE dept_id > 100000;', 'SELECT * FROM departments WHERE id IN (SELECT dept_id FROM employees) AND salary > 100000;', 'SELECT * FROM departments d WHERE EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id AND e.salary > 100000);', 'SELECT DISTINCT d.* FROM departments d JOIN employees e ON d.id = e.dept_id WHERE e.salary > 100000;', 'C', 2, 'EXISTS with a correlated subquery is efficient because it stops searching as soon as it finds one matching employee.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_346', '346', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Medium', 'scenario', 'Consider this scenario: You need to ensure that the ''status'' column in the orders table only accepts values ''pending'', ''shipped'', or ''delivered''. What is the best constraint?', 'ALTER TABLE orders ADD CONSTRAINT chk_status CHECK (status IN (''pending'', ''shipped'', ''delivered''));', 'ALTER TABLE orders ADD UNIQUE(status);', 'Add a trigger that rejects invalid values', 'CREATE INDEX ON orders(status);', 'A', 0, 'A CHECK constraint declaratively enforces the allowed values at the database level.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_347', '347', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Medium', 'scenario', 'Consider this scenario: You need to find records that exist in table A but not in table B. What is the most readable approach?', 'SELECT * FROM A WHERE id > (SELECT MAX(id) FROM B)', 'SELECT a.* FROM A LEFT JOIN B ON A.id = B.id WHERE B.id IS NULL', 'SELECT * FROM A CROSS JOIN B WHERE A.id != B.id', 'SELECT * FROM A INNER JOIN B ON A.id != B.id', 'B', 1, 'The LEFT JOIN anti-join pattern is widely understood and performs well: it returns A rows with no match in B.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_348', '348', 'SQL', 'CTEs', 'Hard', 'scenario', 'You need a bill-of-materials explosion showing all components of a product, including nested sub-components. Which approach is best?', 'A recursive CTE joining the BOM table to itself, accumulating quantities at each level', 'A CROSS JOIN of all components', 'A simple SELECT with GROUP BY', 'Multiple self-joins for each known level', 'A', 0, 'A recursive CTE can traverse the multi-level BOM structure dynamically without knowing the depth in advance.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_349', '349', 'SQL', 'Aggregate Functions', 'Medium', 'scenario', 'You need to find customers whose total purchases this year exceed their total purchases last year. What approach works?', 'Use WHERE amount > last_year_amount (column doesn''t exist)', 'Compare SUM(CASE WHEN year=2025 THEN amount END) vs SUM(CASE WHEN year=2024 THEN amount END) per customer', 'Use MAX(amount) per customer', 'Use GROUP BY year only', 'B', 1, 'Conditional aggregation with CASE computes separate totals for each year within a single GROUP BY query.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_350', '350', 'SQL', 'Transactions', 'Medium', 'scenario', 'Your application processes a batch of 1000 inserts but needs to retry only failed ones. What transaction feature helps?', 'Disabling transactions entirely', 'Individual transactions for each insert', 'A single large transaction for all 1000', 'SAVEPOINTs to mark progress and rollback to the last successful point', 'D', 3, 'SAVEPOINTs allow partial rollback within a transaction, so you can retry failed inserts without losing successful ones.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_351', '351', 'SQL', 'Transactions', 'Hard', 'scenario', 'You need to prevent any new rows from being inserted into a range you are reading during a transaction (prevent phantom reads). Which isolation level is required?', 'REPEATABLE READ', 'SERIALIZABLE', 'READ UNCOMMITTED', 'READ COMMITTED', 'B', 1, 'SERIALIZABLE prevents phantom reads by effectively serializing transactions. REPEATABLE READ prevents non-repeatable reads but not always phantoms.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_352', '352', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Easy', 'scenario', 'Consider this scenario: You need to add a new column ''email'' to an existing users table. What DDL command do you use?', 'INSERT COLUMN email INTO users;', 'CREATE COLUMN email ON users;', 'ALTER TABLE users ADD COLUMN email VARCHAR(255);', 'UPDATE TABLE users ADD email;', 'C', 2, 'ALTER TABLE with ADD COLUMN is the DDL statement to add a new column to an existing table.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_353', '353', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Hard', 'scenario', 'Consider this scenario: You need to add a column with a default value to a table with 100 million rows in production with minimal downtime. What should you consider?', 'In modern DBMS (PostgreSQL 11+, SQL Server), adding a column with a constant default is metadata-only and instant', 'You must always rebuild the entire table', 'It is impossible without downtime', 'You should create a new table and migrate', 'A', 0, 'Modern databases can add a column with a constant default as a metadata-only operation, avoiding a full table rewrite.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_354', '354', 'SQL', 'Query Optimization', 'Hard', 'scenario', 'Your complex query has a subquery in the SELECT list that executes once per row (N+1 problem). How do you fix this?', 'Add an index on the subquery''s table', 'Rewrite the correlated subquery as a JOIN or use a CTE to compute the value once', 'Increase the query timeout', 'Use SELECT * instead of specific columns', 'B', 1, 'Converting a correlated scalar subquery to a JOIN or CTE eliminates per-row execution, drastically improving performance.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_355', '355', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Medium', 'scenario', 'Consider this scenario: You need to enforce that the combination of first_name and last_name is unique across the users table. What constraint do you add?', 'ALTER TABLE users ADD CHECK (first_name != last_name);', 'CREATE INDEX ON users (first_name, last_name);', 'ALTER TABLE users ADD PRIMARY KEY (first_name, last_name);', 'ALTER TABLE users ADD CONSTRAINT uq_name UNIQUE (first_name, last_name);', 'D', 3, 'A UNIQUE constraint on (first_name, last_name) ensures no two rows have the same combination.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_356', '356', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Hard', 'scenario', 'You need to find products whose total sales exceed the overall average total sales per product. Which approach is correct?', 'SELECT product_id FROM sales WHERE SUM(amount) > AVG(amount);', 'SELECT product_id FROM sales HAVING SUM(amount) > AVG(amount);', 'SELECT product_id, SUM(amount) FROM sales GROUP BY product_id HAVING SUM(amount) > (SELECT AVG(total) FROM (SELECT SUM(amount) AS total FROM sales GROUP BY product_id) t);', 'SELECT product_id, SUM(amount) FROM sales GROUP BY product_id WHERE SUM(amount) > AVG(SUM(amount));', 'C', 2, 'You need a subquery to first calculate each product''s total, then average those totals, and compare in HAVING.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_357', '357', 'SQL', 'Transactions', 'Easy', 'scenario', 'You need to transfer money between two bank accounts atomically. What SQL feature ensures both updates succeed or both fail?', 'A stored procedure without a transaction', 'A transaction with BEGIN, UPDATE, UPDATE, COMMIT (and ROLLBACK on error)', 'A single UPDATE statement', 'Two separate UPDATE statements', 'B', 1, 'A transaction groups the two UPDATE statements so that both succeed (COMMIT) or both are undone (ROLLBACK).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_358', '358', 'SQL', 'Query Optimization', 'Easy', 'scenario', 'Consider this scenario: Your query returns 100,000 rows but the user only needs the first 10. What should you add?', 'WHERE ROWNUM < 100000', 'ORDER BY RANDOM()', 'LIMIT 10 (or TOP 10 / FETCH FIRST 10 ROWS depending on DBMS)', 'GROUP BY all columns', 'C', 2, 'LIMIT restricts the result set to 10 rows, reducing data transfer and processing time.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_359', '359', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Hard', 'scenario', 'Consider this scenario: You need to produce a report of all possible employee-project combinations (for planning), even if no assignment exists. Which approach works?', 'LEFT JOIN employees to assignments only', 'INNER JOIN employees, projects, and assignments', 'CROSS JOIN employees and projects, then LEFT JOIN assignments to see existing ones', 'UNION ALL employees and projects', 'C', 2, 'CROSS JOIN creates all combinations; LEFT JOINing assignments shows which ones already exist.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_360', '360', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Medium', 'scenario', 'Consider this scenario: You need to find records that exist in table A but not in table B. What is the most readable approach?', 'SELECT * FROM A INNER JOIN B ON A.id != B.id', 'SELECT a.* FROM A LEFT JOIN B ON A.id = B.id WHERE B.id IS NULL', 'SELECT * FROM A CROSS JOIN B WHERE A.id != B.id', 'SELECT * FROM A WHERE id > (SELECT MAX(id) FROM B)', 'B', 1, 'The LEFT JOIN anti-join pattern is widely understood and performs well: it returns A rows with no match in B.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_361', '361', 'SQL', 'Views', 'Easy', 'scenario', 'Consider this scenario: Analysts need a simplified view of a complex multi-join query they run frequently. What is the best approach?', 'Give them direct access to all tables', 'Create a view that encapsulates the complex query', 'Export the data to a CSV daily', 'Create a stored procedure that returns results', 'B', 1, 'A view provides a simple interface to complex queries, hiding the underlying joins and logic from end users.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_362', '362', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Hard', 'scenario', 'You need to find gaps in a sequential ID column (e.g., missing IDs). Which approach is most efficient?', 'SELECT * WHERE id NOT IN (SELECT id) - circular subquery', 'Use GROUP BY id HAVING COUNT(*) = 0', 'Manually check each ID', 'Use a LEFT JOIN or EXCEPT with a generated sequence, or use LAG/LEAD to find where the difference between consecutive IDs is > 1', 'D', 3, 'Using LAG/LEAD window functions to compare consecutive IDs efficiently identifies gaps without generating a full sequence.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_363', '363', 'SQL', 'Window Functions', 'Medium', 'scenario', 'You need to calculate a running total of sales by date. Which approach is correct?', 'SUM(amount) OVER (PARTITION BY sale_date)', 'SUM(amount) OVER (ORDER BY sale_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)', 'SUM(amount) GROUP BY sale_date', 'TOTAL(amount) OVER (ORDER BY sale_date)', 'B', 1, 'The window frame ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW creates a cumulative sum from the first row to the current row.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_364', '364', 'SQL', 'Stored Procedures', 'Hard', 'scenario', 'You need to implement a retry mechanism for a stored procedure that occasionally fails due to deadlocks. What is the best approach?', 'Use READ UNCOMMITTED to avoid locks', 'Disable locking entirely', 'Wrap the logic in a loop with TRY/CATCH, catching deadlock errors and retrying up to N times with a brief delay', 'Simply re-run the procedure manually when it fails', 'C', 2, 'A retry loop with exception handling catches deadlock errors and retries the operation, a common pattern for handling transient failures.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_365', '365', 'SQL', 'Window Functions', 'Hard', 'scenario', 'Consider this scenario: You need to calculate a 7-day moving average of daily revenue. Which window frame is correct?', 'AVG(revenue) OVER (ORDER BY day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)', 'AVG(revenue) GROUP BY day', 'AVG(revenue) OVER (ORDER BY day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)', 'AVG(revenue) OVER (PARTITION BY day)', 'A', 0, 'ROWS BETWEEN 6 PRECEDING AND CURRENT ROW creates a sliding window of 7 days (current + 6 preceding).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_366', '366', 'SQL', 'Triggers', 'Hard', 'scenario', 'You need to maintain a denormalized total_order_amount in the customers table whenever an order is inserted, updated, or deleted. What is the best approach?', 'Triggers on INSERT, UPDATE, and DELETE on the orders table that update the customer''s total', 'A view that calculates the total on the fly', 'A nightly batch job to recalculate totals', 'Application code that updates the total after every change', 'A', 0, 'Triggers ensure the denormalized total is always up-to-date, regardless of how the data is modified.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_367', '367', 'SQL', 'Views', 'Medium', 'scenario', 'You need to provide different departments with different views of the same employee data (HR sees salary, others don''t). What approach is best?', 'Create separate views for each department showing only allowed columns, and grant appropriate permissions', 'Store data in separate tables per department', 'Use application-level filtering only', 'Create one view for everyone', 'A', 0, 'Separate views with different column selections and targeted permissions enforce column-level security at the database level.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_368', '368', 'SQL', 'SELECT basics', 'Hard', 'scenario', 'Consider this scenario: A report requires pivoting rows to columns: showing months as columns and products as rows with sales amounts. Standard SQL doesn''t have PIVOT. What approach works in any DBMS?', 'Use UNION ALL to combine monthly queries', 'Use CASE expressions inside aggregate functions: SUM(CASE WHEN month=''Jan'' THEN amount END) AS Jan', 'Use CROSS JOIN with all months', 'Create separate tables for each month', 'B', 1, 'Conditional aggregation with CASE inside SUM/COUNT is a portable cross-database pivot technique.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_369', '369', 'SQL', 'Subqueries', 'Medium', 'scenario', 'You need to delete duplicate rows, keeping only the one with the lowest id. Which approach works?', 'DROP duplicates using ALTER TABLE;', 'TRUNCATE TABLE t;', 'DELETE FROM t WHERE ROWNUM > 1;', 'DELETE FROM t WHERE id NOT IN (SELECT MIN(id) FROM t GROUP BY duplicate_columns);', 'D', 3, 'This keeps the row with the minimum id for each group of duplicates and deletes all others.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_370', '370', 'SQL', 'Indexes', 'Easy', 'scenario', 'Your query on a large orders table filtered by customer_id is slow. What is the first optimization to try?', 'Rewrite the query to use a CTE', 'Add more RAM to the server', 'Create an index on the customer_id column', 'Use SELECT * instead of specific columns', 'C', 2, 'An index on customer_id allows the database to quickly locate matching rows instead of scanning the entire table.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_371', '371', 'SQL', 'Stored Procedures', 'Medium', 'scenario', 'You need a database routine that validates input, performs multiple operations, and handles errors. What is the best approach?', 'A trigger on every table involved', 'A stored procedure with input validation, TRY/CATCH or exception handling, and transaction control', 'A view with complex logic', 'Multiple ad-hoc queries from the application', 'B', 1, 'Stored procedures support procedural logic including validation, error handling, and transaction management.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_372', '372', 'SQL', 'Window Functions', 'Hard', 'scenario', 'Consider this scenario: You need to calculate a 7-day moving average of daily revenue. Which window frame is correct?', 'AVG(revenue) OVER (PARTITION BY day)', 'AVG(revenue) OVER (ORDER BY day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)', 'AVG(revenue) OVER (ORDER BY day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)', 'AVG(revenue) GROUP BY day', 'B', 1, 'ROWS BETWEEN 6 PRECEDING AND CURRENT ROW creates a sliding window of 7 days (current + 6 preceding).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_373', '373', 'SQL', 'NoSQL Concepts', 'Medium', 'scenario', 'Consider this scenario: Your application stores user profiles with varying attributes (some users have social links, some have bio, etc.). Which database model is most flexible?', 'A relational database with columns for every possible attribute', 'A key-value store', 'A graph database', 'A document database like MongoDB that stores schema-flexible JSON documents', 'D', 3, 'Document databases allow each document to have different fields, naturally handling varying attributes without NULL-heavy columns.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_374', '374', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Medium', 'scenario', 'A business analyst needs the top 3 departments by average salary, but only departments with more than 5 employees. How do you write this?', 'SELECT TOP 3 dept, AVG(salary) FROM emp WHERE COUNT(*) > 5 GROUP BY dept;', 'SELECT dept, AVG(salary) FROM emp GROUP BY dept WHERE COUNT(*) > 5 LIMIT 3;', 'SELECT dept FROM emp HAVING COUNT(*) > 5 LIMIT 3;', 'SELECT dept, AVG(salary) avg_sal FROM emp GROUP BY dept HAVING COUNT(*) > 5 ORDER BY avg_sal DESC LIMIT 3;', 'D', 3, 'HAVING filters groups (departments with >5 employees), ORDER BY sorts by avg salary, and LIMIT returns top 3.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_375', '375', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Easy', 'scenario', 'You have customers and orders tables. You want a list of all customers with their order details, including customers who have never ordered. Which JOIN is best?', 'RIGHT JOIN with orders on the left', 'LEFT JOIN customers on the left, orders on the right', 'CROSS JOIN', 'INNER JOIN', 'B', 1, 'LEFT JOIN ensures all customers appear, even those with no orders (order columns will be NULL for them).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_376', '376', 'SQL', 'Views', 'Medium', 'scenario', 'Consider this scenario: You have a dashboard that queries a complex aggregation. The query is slow. What can you use to pre-compute the results?', 'A trigger that recalculates on every data change', 'A regular view (which re-runs the query each time)', 'A materialized view that is refreshed periodically', 'An index on every column', 'C', 2, 'A materialized view stores the precomputed results, making dashboard queries fast. Periodic refresh keeps data reasonably current.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_377', '377', 'SQL', 'Normalization', 'Hard', 'scenario', 'A table has columns (student_id, course_id, professor, professor_office). PK is (student_id, course_id). professor_office depends on professor. What normalization issue exists?', 'No issue; the table is in 3NF', '1NF violation: values are not atomic', 'Transitive dependency: professor_office depends on professor, not on the primary key directly. This violates 3NF.', 'Partial dependency: professor depends on student_id only', 'C', 2, 'professor_office depends on professor (a non-key column), which is a transitive dependency violating 3NF.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_378', '378', 'SQL', 'Normalization', 'Medium', 'scenario', 'Consider this scenario: You have a table: orders(order_id, product_name, product_category). product_category depends on product_name, not order_id. What should you do?', 'Keep it as is for simplicity', 'Remove product_category entirely', 'Separate products into their own table with product_name and product_category, and reference it with a foreign key', 'Add product_category to the primary key', 'C', 2, 'Extracting product data into a separate table eliminates the transitive dependency and achieves 3NF.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_379', '379', 'SQL', 'Aggregate Functions', 'Hard', 'scenario', 'You need to calculate the median salary in a department. SQL has no built-in MEDIAN function. What is the best approach?', 'Use (MAX(salary) + MIN(salary)) / 2', 'Use AVG(salary)', 'Use PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY salary) or a window function approach', 'Use MODE(salary)', 'C', 2, 'PERCENTILE_CONT(0.5) calculates the true median. AVG gives the mean, and (MAX+MIN)/2 gives the midrange, neither of which is the median.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_380', '380', 'SQL', 'Stored Procedures', 'Hard', 'scenario', 'Consider this scenario: You need to implement a retry mechanism for a stored procedure that occasionally fails due to deadlocks. What is the best approach?', 'Wrap the logic in a loop with TRY/CATCH, catching deadlock errors and retrying up to N times with a brief delay', 'Disable locking entirely', 'Simply re-run the procedure manually when it fails', 'Use READ UNCOMMITTED to avoid locks', 'A', 0, 'A retry loop with exception handling catches deadlock errors and retries the operation, a common pattern for handling transient failures.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_381', '381', 'SQL', 'Query Optimization', 'Hard', 'scenario', 'Consider this scenario: Your complex query has a subquery in the SELECT list that executes once per row (N+1 problem). How do you fix this?', 'Use SELECT * instead of specific columns', 'Rewrite the correlated subquery as a JOIN or use a CTE to compute the value once', 'Add an index on the subquery''s table', 'Increase the query timeout', 'B', 1, 'Converting a correlated scalar subquery to a JOIN or CTE eliminates per-row execution, drastically improving performance.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_382', '382', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Medium', 'scenario', 'You need to enforce that the combination of first_name and last_name is unique across the users table. What constraint do you add?', 'ALTER TABLE users ADD PRIMARY KEY (first_name, last_name);', 'ALTER TABLE users ADD CONSTRAINT uq_name UNIQUE (first_name, last_name);', 'ALTER TABLE users ADD CHECK (first_name != last_name);', 'CREATE INDEX ON users (first_name, last_name);', 'B', 1, 'A UNIQUE constraint on (first_name, last_name) ensures no two rows have the same combination.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_383', '383', 'SQL', 'Normalization', 'Medium', 'scenario', 'You have a table: orders(order_id, product_name, product_category). product_category depends on product_name, not order_id. What should you do?', 'Add product_category to the primary key', 'Separate products into their own table with product_name and product_category, and reference it with a foreign key', 'Keep it as is for simplicity', 'Remove product_category entirely', 'B', 1, 'Extracting product data into a separate table eliminates the transitive dependency and achieves 3NF.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_384', '384', 'SQL', 'CTEs', 'Easy', 'scenario', 'You have a complex query that is referenced multiple times. What is the best way to improve readability?', 'Use string concatenation to build the query dynamically', 'Copy and paste the subquery wherever needed', 'Use a CTE (WITH clause) to name the subquery and reference it multiple times', 'Create a permanent table', 'C', 2, 'CTEs improve readability by giving a meaningful name to a subquery and allowing it to be referenced multiple times.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_385', '385', 'SQL', 'Indexes', 'Hard', 'scenario', 'Your query SELECT a, b, c FROM t WHERE a = 1 AND b > 10 ORDER BY c benefits from which index?', 'A single index on c', 'No index needed', 'A composite index on (a, b, c) to cover the query entirely', 'A single index on b', 'C', 2, 'A composite index on (a, b, c) supports the equality filter on a, range filter on b, and covers column c for ordering and projection.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_386', '386', 'SQL', 'Subqueries', 'Medium', 'scenario', 'Consider this scenario: You want to find departments that have at least one employee earning over $100,000. Which is most efficient?', 'SELECT * FROM departments WHERE id IN (SELECT dept_id FROM employees) AND salary > 100000;', 'SELECT * FROM departments d WHERE EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id AND e.salary > 100000);', 'SELECT DISTINCT d.* FROM departments d JOIN employees e ON d.id = e.dept_id WHERE e.salary > 100000;', 'SELECT * FROM departments WHERE dept_id > 100000;', 'B', 1, 'EXISTS with a correlated subquery is efficient because it stops searching as soon as it finds one matching employee.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_387', '387', 'SQL', 'Views', 'Easy', 'scenario', 'Analysts need a simplified view of a complex multi-join query they run frequently. What is the best approach?', 'Create a stored procedure that returns results', 'Create a view that encapsulates the complex query', 'Export the data to a CSV daily', 'Give them direct access to all tables', 'B', 1, 'A view provides a simple interface to complex queries, hiding the underlying joins and logic from end users.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_388', '388', 'SQL', 'Views', 'Hard', 'scenario', 'Consider this scenario: You need to restrict certain columns from some users while allowing full access to others. What is the best approach?', 'Use application-level filtering only', 'Create separate tables for each user group', 'Use row-level security policies only', 'Create a view exposing only allowed columns and grant SELECT on the view (not the base table)', 'D', 3, 'A view can expose a subset of columns and you can grant permissions on the view, providing column-level security.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_389', '389', 'SQL', 'Window Functions', 'Hard', 'scenario', 'You need to calculate a 7-day moving average of daily revenue. Which window frame is correct?', 'AVG(revenue) OVER (PARTITION BY day)', 'AVG(revenue) OVER (ORDER BY day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)', 'AVG(revenue) OVER (ORDER BY day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)', 'AVG(revenue) GROUP BY day', 'C', 2, 'ROWS BETWEEN 6 PRECEDING AND CURRENT ROW creates a sliding window of 7 days (current + 6 preceding).', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_390', '390', 'SQL', 'Triggers', 'Easy', 'scenario', 'You need to automatically log every deletion from an important table. What SQL feature is best?', 'An AFTER DELETE trigger that inserts the deleted data into an audit table', 'A view on the table', 'A scheduled job that checks for missing rows', 'A CHECK constraint', 'A', 0, 'An AFTER DELETE trigger fires automatically on each delete, capturing the removed data into an audit log.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_391', '391', 'SQL', 'DDL (CREATE/ALTER/DROP)', 'Hard', 'scenario', 'You need to add a column with a default value to a table with 100 million rows in production with minimal downtime. What should you consider?', 'In modern DBMS (PostgreSQL 11+, SQL Server), adding a column with a constant default is metadata-only and instant', 'You should create a new table and migrate', 'You must always rebuild the entire table', 'It is impossible without downtime', 'A', 0, 'Modern databases can add a column with a constant default as a metadata-only operation, avoiding a full table rewrite.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_392', '392', 'SQL', 'Subqueries', 'Medium', 'scenario', 'Consider this scenario: You want to find departments that have at least one employee earning over $100,000. Which is most efficient?', 'SELECT DISTINCT d.* FROM departments d JOIN employees e ON d.id = e.dept_id WHERE e.salary > 100000;', 'SELECT * FROM departments d WHERE EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id AND e.salary > 100000);', 'SELECT * FROM departments WHERE id IN (SELECT dept_id FROM employees) AND salary > 100000;', 'SELECT * FROM departments WHERE dept_id > 100000;', 'B', 1, 'EXISTS with a correlated subquery is efficient because it stops searching as soon as it finds one matching employee.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_393', '393', 'SQL', 'DML (INSERT/UPDATE/DELETE)', 'Hard', 'scenario', 'You need to update product prices based on a pricing table: if a match exists update the price, if not insert a new row. What is the best approach?', 'Use a trigger on INSERT', 'Use separate INSERT and UPDATE statements in application code', 'Use MERGE (or INSERT ... ON CONFLICT/ON DUPLICATE KEY UPDATE depending on the DBMS)', 'Use DELETE followed by INSERT', 'C', 2, 'MERGE (or UPSERT syntax) handles conditional insert/update in a single atomic statement.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_394', '394', 'SQL', 'Stored Procedures', 'Easy', 'scenario', 'You have a complex query that is run daily by multiple applications. What is the best way to centralize it?', 'Email the query text to all developers', 'Copy the query into each application''s source code', 'Create a view for each application', 'Create a stored procedure that encapsulates the query', 'D', 3, 'A stored procedure centralizes the logic in the database, ensuring consistency and easier maintenance.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_395', '395', 'SQL', 'Subqueries', 'Hard', 'scenario', 'You need the second highest salary in each department. Which approach is correct?', 'Use a correlated subquery or window function to rank salaries per department and pick rank 2', 'SELECT MAX(salary) FROM employees GROUP BY dept_id', 'SELECT AVG(salary) FROM employees GROUP BY dept_id', 'SELECT salary FROM employees ORDER BY salary DESC LIMIT 1 OFFSET 1', 'A', 0, 'A window function like DENSE_RANK() OVER (PARTITION BY dept_id ORDER BY salary DESC) = 2 or an equivalent correlated subquery handles this correctly.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_396', '396', 'SQL', 'Triggers', 'Medium', 'scenario', 'You want to prevent salary updates that decrease an employee''s salary. What is the best approach?', 'A CHECK constraint on salary > 0', 'A BEFORE UPDATE trigger that checks if NEW.salary < OLD.salary and raises an error', 'Application-level validation only', 'An AFTER UPDATE trigger that rolls back the change', 'B', 1, 'A BEFORE UPDATE trigger can compare the new and old values and reject the change before it is applied.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_397', '397', 'SQL', 'NoSQL Concepts', 'Medium', 'scenario', 'Your application stores user profiles with varying attributes (some users have social links, some have bio, etc.). Which database model is most flexible?', 'A document database like MongoDB that stores schema-flexible JSON documents', 'A key-value store', 'A graph database', 'A relational database with columns for every possible attribute', 'A', 0, 'Document databases allow each document to have different fields, naturally handling varying attributes without NULL-heavy columns.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_398', '398', 'SQL', 'Query Optimization', 'Easy', 'scenario', 'Your query returns 100,000 rows but the user only needs the first 10. What should you add?', 'LIMIT 10 (or TOP 10 / FETCH FIRST 10 ROWS depending on DBMS)', 'WHERE ROWNUM < 100000', 'ORDER BY RANDOM()', 'GROUP BY all columns', 'A', 0, 'LIMIT restricts the result set to 10 rows, reducing data transfer and processing time.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_399', '399', 'SQL', 'Indexes', 'Hard', 'scenario', 'A table has millions of rows but queries only ever access rows where status = ''active'' (about 5% of rows). What is the best index strategy?', 'A full index on the status column', 'A clustered index on status', 'A partial (filtered) index WHERE status = ''active''', 'No index needed', 'C', 2, 'A partial index only includes ''active'' rows, making it much smaller and more efficient than a full index.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_400', '400', 'SQL', 'Window Functions', 'Hard', 'scenario', 'Consider this scenario: You need to detect consecutive days when a server was down. Which approach is best?', 'Use COUNT(*) GROUP BY date', 'Use CROSS JOIN all dates', 'Use a simple WHERE clause', 'Use ROW_NUMBER() to create groups of consecutive dates (gaps-and-islands technique)', 'D', 3, 'The gaps-and-islands technique uses the difference between ROW_NUMBER and the date to identify consecutive sequences.', '');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_401', '401', 'SQL', 'SELECT basics', 'Hard', 'code_completion', 'Complete the CASE expression.', 'IF', 'CASE', 'SWITCH', 'WHEN', 'B', 1, 'CASE starts a conditional expression that evaluates WHEN conditions and returns the matching THEN value.', 'SELECT name, salary,
  ___ WHEN salary > 100000 THEN ''High''
       WHEN salary > 50000 THEN ''Medium''
       ELSE ''Low''
  END AS salary_band
FROM employees;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_402', '402', 'SQL', 'Subqueries', 'Hard', 'code_completion', 'Complete the query using a scalar subquery in SELECT.', 'SUM', 'MAX', 'AVG', 'COUNT', 'C', 2, 'AVG(salary) computes the average salary; subtracting it from each salary shows the difference from the mean.', 'SELECT name, salary, salary - (SELECT ___(salary) FROM employees) AS diff_from_avg FROM employees;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_403', '403', 'SQL', 'CTEs', 'Easy', 'code_completion', 'Fill in the blank: Complete the CTE syntax.', 'DECLARE', 'DEFINE', 'CREATE CTE', 'WITH', 'D', 3, 'The WITH keyword introduces a Common Table Expression.', '___ dept_stats AS (
