INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_404', '404', 'SQL', 'SELECT basics', 'Medium', 'code_completion', 'Complete the query to cast a value to integer.', 'CAST', 'TRANSFORM', 'CONVERT', 'CHANGE', 'A', 0, 'CAST converts a value from one data type to another in standard SQL.', 'SELECT ___(price AS INTEGER) AS int_price FROM products;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_405', '405', 'SQL', 'Subqueries', 'Medium', 'code_completion', 'Complete the query to use a derived table.', 'TO', 'AS', 'INTO', 'NAMED', 'B', 1, 'AS provides an alias for the derived table (subquery in FROM clause).', 'SELECT avg_data.dept, avg_data.avg_sal
