INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_407', '407', 'SQL', 'Window Functions', 'Easy', 'code_completion', 'Complete the window function to rank employees by salary.', 'BY', 'OVER', 'USING', 'WITHIN', 'B', 1, 'OVER defines the window specification for the window function.', 'SELECT name, salary, RANK() ___ (ORDER BY salary DESC) AS rnk FROM employees;');
INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_408', '408', 'SQL', 'JOINs (INNER/LEFT/RIGHT/FULL)', 'Easy', 'code_completion', 'Complete the JOIN to include all employees even without a department.', 'INNER JOIN', 'CROSS JOIN', 'LEFT JOIN', 'RIGHT JOIN', 'C', 2, 'LEFT JOIN returns all rows from the left table (employees) and matching rows from the right table.', 'SELECT e.name, d.name FROM employees e ___ departments d ON e.dept_id = d.id;');
