INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_411', '411', 'SQL', 'Normalization', 'Medium', 'code_completion', 'Complete the normalization rule: In 2NF, every non-key attribute must depend on the ___ primary key.', 'first column of the', 'last column of the', 'entire', 'any part of the', 'C', 2, '2NF eliminates partial dependencies: non-key attributes must depend on the entire composite primary key, not just part of it.', '-- 2NF rule: No partial dependencies
