INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_414', '414', 'SQL', 'Stored Procedures', 'Hard', 'code_completion', 'Complete the dynamic SQL execution inside a stored procedure.', 'EXEC IMMEDIATE @sql;', 'PREPARE stmt FROM @sql;', 'CALL @sql;', 'RUN @sql;', 'B', 1, 'PREPARE compiles the dynamic SQL string into a statement that can then be executed.', 'CREATE PROCEDURE run_query(IN tbl VARCHAR(100))
