INSERT OR REPLACE INTO questions (id, csv_id, subject, topic, difficulty, type, question, option_a, option_b, option_c, option_d, correct_answer, answer_index, explanation, code_snippet) VALUES ('SQL_425', '425', 'SQL', 'WHERE/ORDER BY/GROUP BY/HAVING', 'Medium', 'code_completion', 'Complete the query to filter groups with more than 5 employees.', 'WHEN', 'HAVING', 'FILTER', 'WHERE', 'B', 1, 'HAVING filters groups after GROUP BY; WHERE cannot be used with aggregate functions.', 'SELECT department, COUNT(*) AS cnt FROM employees GROUP BY department ___ COUNT(*) > 5;');
