It should print: "func_name took X.XX seconds" and return the original result.', '', '', '', 'import time

def timer(func):
    # Write decorator
    pass

@timer
def slow_function():
    time.sleep(0.5)
    return "done"

result = slow_function()
print("Result:", result)', 'import time
def timer(func):
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        print(f"{func.__name__} took {time.time()-start:.2f} seconds")
        return result
    return wrapper', 'python', '[]', 0, '');
