INSERT OR REPLACE INTO coding_problems (id, test_id, section, title, difficulty, points, time_limit, description, input_format, output_format, constraints_text, starter_code, solution, evaluation_type, required_keywords, required_count, sql_setup) VALUES (224, 'test_wakefit', 'Wakefit Coding', 'POM Login Page Class', 'Medium', 20, 10000, 'Implement a Page Object Model class for a Login Page with: __init__(driver), enter_username(u), enter_password(p), click_login(), get_error_message(), login(u,p).', '', '', '', 'from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC

class LoginPage:
    def __init__(self, driver): pass
    def enter_username(self, u): pass
    def enter_password(self, p): pass
    def click_login(self): pass
    def get_error_message(self): pass
    def login(self, u, p): pass', 'from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
class LoginPage:
    def __init__(self, d): self.d=d; self.w=WebDriverWait(d,10)
    def enter_username(self,u): f=self.w.until(EC.presence_of_element_located((By.ID,"username"))); f.clear(); f.send_keys(u)
    def enter_password(self,p): f=self.d.find_element(By.ID,"password"); f.clear(); f.send_keys(p)
    def click_login(self): self.d.find_element(By.ID,"submit").click()
    def get_error_message(self):
        try: return self.w.until(EC.presence_of_element_located((By.ID,"error"))).text
        except: return None
    def login(self,u,p): self.enter_username(u); self.enter_password(p); self.click_login()', 'python', '[]', 0, '');
