INSERT OR REPLACE INTO coding_problems (id, test_id, section, title, difficulty, points, time_limit, description, input_format, output_format, constraints_text, starter_code, solution, evaluation_type, required_keywords, required_count, sql_setup) VALUES (236, 'test_pycode', 'Python Coding', 'Product Except Self', 'Easy', 10, 10000, 'Given an array of integers, return an array where each element is the product of all other elements in the array (excluding itself). Do not use division.', 'First line: integer n.
Second line: n space-separated integers.', 'Print the result array space-separated.', '2 <= n <= 1000
-100 <= elements <= 100', '# Read input
', 'n = int(input())
nums = list(map(int, input().split()))
prefix = [1] * n
for i in range(1, n):
    prefix[i] = prefix[i - 1] * nums[i - 1]
suffix = [1] * n
for i in range(n - 2, -1, -1):
    suffix[i] = suffix[i + 1] * nums[i + 1]
result = [prefix[i] * suffix[i] for i in range(n)]
print(" ".join(map(str, result)))
