INSERT OR REPLACE INTO coding_problems (id, test_id, section, title, difficulty, points, time_limit, description, input_format, output_format, constraints_text, starter_code, solution, evaluation_type, required_keywords, required_count, sql_setup) VALUES (239, 'test_pycode', 'Python Coding', 'Sliding Window Maximum', 'Easy', 10, 10000, 'Given an array of integers and a window size k, find the maximum value in each sliding window of size k.', 'First line: n and k (space-separated).
Second line: n space-separated integers.', 'Print the maximum of each window, space-separated.', '1 <= k <= n <= 10000', '# Read input
', 'from collections import deque
n, k = map(int, input().split())
nums = list(map(int, input().split()))
dq = deque()
result = []
for i in range(n):
    while dq and dq[0] < i - k + 1:
        dq.popleft()
    while dq and nums[dq[-1]] < nums[i]:
        dq.pop()
    dq.append(i)
    if i >= k - 1:
        result.append(str(nums[dq[0]]))
print(" ".join(result))
', 'python', '[]', 0, '');
