print(max(words, key=count_vowels))
', 'python', '[]', 0, '');
INSERT OR REPLACE INTO coding_problems (id, test_id, section, title, difficulty, points, time_limit, description, input_format, output_format, constraints_text, starter_code, solution, evaluation_type, required_keywords, required_count, sql_setup) VALUES (300, 'test_pycode', 'Python Coding', 'Group Numbers into Even and Odd', 'Easy', 10, 10000, 'Separate a list of numbers into two groups: even and odd, maintaining original order.', 'One line of space-separated integers.', 'Two lines: "Even: ..." and "Odd: ..." (space-separated, empty if none).', '1 <= n <= 1000', '# Read input
', 'nums = list(map(int, input().split()))
evens = [x for x in nums if x % 2 == 0]
odds  = [x for x in nums if x % 2 != 0]
print("Even:" + (" " + " ".join(map(str, evens)) if evens else ""))
print("Odd:" + (" " + " ".join(map(str, odds)) if odds else ""))
', 'python', '[]', 0, '');
INSERT OR REPLACE INTO coding_problems (id, test_id, section, title, difficulty, points, time_limit, description, input_format, output_format, constraints_text, starter_code, solution, evaluation_type, required_keywords, required_count, sql_setup) VALUES (301, 'test_pycode', 'Python Coding', 'Balanced Brackets Check', 'Easy', 10, 10000, 'Check if a string of brackets is balanced. Every opening bracket must have a matching closing bracket in the correct order.', 'A single line string containing brackets: ( ) { } [ ]', 'Print "Balanced" or "Not Balanced".', '1 <= len(s) <= 500', '# Read input
', 's = input()
stack = []
pairs = {")": "(", "}": "{", "]": "["}
for c in s:
    if c in "({[":
        stack.append(c)
    elif c in ")}]":
        if not stack or stack[-1] != pairs[c]:
            print("Not Balanced")
            exit()
        stack.pop()
print("Balanced" if not stack else "Not Balanced")
', 'python', '[]', 0, '');
